    void win_linetabsize_cts(T_chartabsize_T cts, int len) {
        long vcol = 0;
        vcol = (long) cts.cts_vcol;
        for (; (cts.cts_ptr.get() != NUL) && (len == MAXCOL || cts.cts_ptr.lt(cts.cts_line.add(len))); cts.cts_ptr = cts.cts_ptr.add(utfc_ptr2len(cts.cts_ptr))) {
            vcol += (long) win_lbr_chartabsize(cts, null, null);
            if (vcol > MAXCOL) {
                cts.cts_vcol = MAXCOL;
                break;
            } else {
                cts.cts_vcol = (int) vcol;
            }
        }
    }

    boolean vim_isIDc(int c) {
        return c > 0 && c < 256 && (g_chartab[c] & 0xff & CT_ID_CHAR) != 0;
    }

    boolean vim_isNormalIDc(int c) {
        return Integer.compareUnsigned(c - 'A', 26) < 0 || Integer.compareUnsigned(c - 'a', 26) < 0 || Integer.compareUnsigned(c - '0', 10) < 0 || c == '_';
    }

    boolean vim_iswordc(int c) {
        return vim_iswordc_buf(c, curbuf);
    }

    boolean vim_iswordc_buf(int c, S_file_buffer buf) {
        if (c >= 256) {
            return utf_class_buf(c, buf) >= 2;
        }
        return c > 0 && (buf.b_chartab[c >>> 3] & 0xff & (1 << (c & 7))) != 0;
    }

    boolean vim_iswordp(BytePtr p) {
        return vim_iswordp_buf(p, curbuf);
    }

    boolean vim_iswordp_buf(BytePtr p, S_file_buffer buf) {
        int c = 0;
        c = p.get() & 0xff;
        if ((int) mb_bytelen_tab[c] > 1) {
            c = utf_ptr2char(p);
        }
        return vim_iswordc_buf(c, buf);
    }

    boolean vim_isfilec(int c) {
        return c >= 256 || (c > 0 && (g_chartab[c] & 0xff & CT_FNAME_CHAR) != 0);
    }

    boolean vim_isprintc(int c) {
        if (c >= 256) {
            return utf_printable(c);
        }
        return c >= 256 || (c > 0 && (g_chartab[c] & 0xff & CT_PRINT_CHAR) != 0);
    }

    boolean vim_isprintc_strict(int c) {
        if (c >= 256) {
            return utf_printable(c);
        }
        return c >= 256 || (c > 0 && (g_chartab[c] & 0xff & CT_PRINT_CHAR) != 0);
    }

    void init_chartabsize_arg(T_chartabsize_T cts, S_window_S wp, long lnum, int col, BytePtr line, BytePtr ptr) {
        cts.zero();
        cts.cts_win = wp;
        cts.cts_vcol = col;
        cts.cts_line = line;
        cts.cts_ptr = ptr;
    }

    int lbr_chartabsize(T_chartabsize_T cts) {
        int ts = 0;
        if (curwin.w_onebuf_opt.wo_wrap[0] != 0) {
            return win_nolbr_chartabsize(cts, null);
        }
        if (cts.cts_ptr.get() == TAB && (curwin.w_onebuf_opt.wo_list[0] == 0 || curwin.w_lcs_chars.tab1 != 0)) {
            ts = (int) curbuf.b_p_ts[0];
            return ts - cts.cts_vcol % ts;
        } else {
            return ptr2cells(cts.cts_ptr);
        }
    }

    int lbr_chartabsize_adv(T_chartabsize_T cts) {
        int retval = 0;
        retval = lbr_chartabsize(cts);
        cts.cts_ptr = cts.cts_ptr.add(utfc_ptr2len(cts.cts_ptr));
        return retval;
    }

    int win_lbr_chartabsize(T_chartabsize_T cts, IntPtr headp, IntPtr tailp) {
        S_window_S wp = null;
        BytePtr s = null;
        int vcol = 0;
        int ts = 0;
        wp = cts.cts_win;
        s = cts.cts_ptr;
        vcol = cts.cts_vcol;
        if (wp.w_onebuf_opt.wo_wrap[0] != 0) {
            return win_nolbr_chartabsize(cts, headp);
        }
        if (s.get() == TAB && (wp.w_onebuf_opt.wo_list[0] == 0 || wp.w_lcs_chars.tab1 != 0)) {
            ts = (int) wp.w_buffer.b_p_ts[0];
            return ts - vcol % ts;
        } else {
            return ptr2cells(s);
        }
    }

    int win_nolbr_chartabsize(T_chartabsize_T cts, IntPtr headp) {
        S_window_S wp = null;
        BytePtr s = null;
        int col = 0;
        int n = 0;
        wp = cts.cts_win;
        s = cts.cts_ptr;
        col = cts.cts_vcol;
        if (s.get() == TAB && (wp.w_onebuf_opt.wo_list[0] == 0 || wp.w_lcs_chars.tab1 != 0)) {
            n = (int) wp.w_buffer.b_p_ts[0];
            return n - col % n;
        }
        n = ptr2cells(s);
        if (n == 2 && (int) mb_bytelen_tab[s.get() & 0xff] > 1 && in_win_border(wp, col)) {
            if (headp != null) {
                headp.put(1);
            }
            return 3;
        }
        return n;
    }

    boolean in_win_border(S_window_S wp, int vcol) {
        int width1 = 0;
        int width2 = 0;
        if (wp.w_width == 0) {
            return false;
        }
        width1 = wp.w_width - win_col_off(wp);
        if (vcol < width1 - 1) {
            return false;
        }
        if (vcol == width1 - 1) {
            return true;
        }
        width2 = width1 + win_col_off2(wp);
        if (width2 <= 0) {
            return false;
        }
        return (vcol - width1) % width2 == width2 - 1;
    }

    void getvcol(S_window_S wp, T_pos_T pos, IntPtr start, IntPtr cursor, IntPtr end, int flags) {
        int vcol = 0;
        BytePtr ptr = null;
        BytePtr line = null;
        int incr = 0;
        int[] head = new int[1];
        int[] tail = new int[1];
        int ts = 0;
        int c = 0;
        T_chartabsize_T cts = new T_chartabsize_T();
        BytePtr next_ptr = null;
        BytePtr next_ptr_2 = null;
        ts = (int) wp.w_buffer.b_p_ts[0];
        vcol = 0;
        ptr = ml_get_buf(wp.w_buffer, pos.lnum[0], false);
        line = ptr;
        init_chartabsize_arg(cts, wp, pos.lnum[0], 0, line, line);
        cts.cts_max_head_vcol = -1;
        if (wp.w_onebuf_opt.wo_list[0] == 0 || wp.w_lcs_chars.tab1 != NUL) {
            for (;;) {
                head[0] = 0;
                c = ptr.get() & 0xff;
                if (c == NUL) {
                    incr = 1;
                    break;
                }
                if (c == TAB) {
                    incr = ts - vcol % ts;
                } else {
                    if (c >= 128) {
                        incr = utf_ptr2cells(ptr);
                    } else {
                        incr = g_chartab[c] & 0xff & CT_CELL_MASK;
                    }
                    if (incr == 2 && wp.w_onebuf_opt.wo_wrap[0] != 0 && (int) mb_bytelen_tab[ptr.get() & 0xff] > 1 && in_win_border(wp, vcol)) {
                        incr++;
                        head[0] = 1;
                    }
                }
                next_ptr = ptr.add(utfc_ptr2len(ptr));
                if (next_ptr.sub(line) > ((long) pos.col[0])) {
                    break;
                }
                vcol += incr;
                ptr = next_ptr;
            }
            tail[0] = 0;
        } else {
            for (;;) {
                head[0] = 0;
                tail[0] = 0;
                incr = win_lbr_chartabsize(cts, new IntPtr(head, 0), new IntPtr(tail, 0));
                if (cts.cts_ptr.get() == NUL) {
                    incr = 1;
                    break;
                }
                next_ptr_2 = cts.cts_ptr.add(utfc_ptr2len(cts.cts_ptr));
                if (next_ptr_2.sub(line) > ((long) pos.col[0])) {
                    break;
                }
                cts.cts_vcol += incr;
                cts.cts_ptr = next_ptr_2;
            }
            vcol = cts.cts_vcol;
            ptr = cts.cts_ptr;
        }
        if (ptr.get() == NUL && pos.col[0] < MAXCOL && (long) pos.col[0] > ptr.sub(line)) {
            pos.col[0] = (int) ptr.sub(line);
        }
        if (start != null) {
            start.put(vcol + head[0]);
        }
        if (end != null) {
            end.put(vcol + incr - ((flags & GETVCOL_END_EXCL_LBR) != 0 ? tail[0] : 0) - 1);
        }
        if (cursor != null) {
            if (ptr.get() == TAB && (State & MODE_NORMAL) != 0 && wp.w_onebuf_opt.wo_list[0] == 0 && virtual_active() == 0 && !(VIsual_active != 0 && (p_sel[0].get() == 'e' || ((pos.lnum[0] != VIsual.lnum[0] ? pos.lnum[0] < VIsual.lnum[0] : (pos.col[0] != VIsual.col[0] ? pos.col[0] < VIsual.col[0] : pos.coladd < VIsual.coladd)) || (pos.lnum[0] == VIsual.lnum[0] && pos.col[0] == VIsual.col[0] && pos.coladd == VIsual.coladd))))) {
                cursor.put(vcol + incr - 1);
            } else {
                cursor.put(vcol + head[0]);
            }
        }
    }

    int getvcol_nolist(T_pos_T posp) {
        int list_save = 0;
        int[] vcol = new int[1];
        list_save = curwin.w_onebuf_opt.wo_list[0];
        curwin.w_onebuf_opt.wo_list[0] = FALSE;
        if (posp.coladd != 0) {
            getvvcol(curwin, posp, null, new IntPtr(vcol, 0), null, 0);
        } else {
            getvcol(curwin, posp, null, new IntPtr(vcol, 0), null, 0);
        }
        curwin.w_onebuf_opt.wo_list[0] = list_save;
        return vcol[0];
    }

    void getvvcol(S_window_S wp, T_pos_T pos, IntPtr start, IntPtr cursor, IntPtr end, int flags) {
        int[] col = new int[1];
        int coladd = 0;
        int endadd = 0;
        BytePtr ptr = null;
        int c = 0;
        if (virtual_active() != 0) {
            getvcol(wp, pos, new IntPtr(col, 0), null, null, flags);
            coladd = pos.coladd;
            endadd = 0;
            ptr = ml_get_buf(wp.w_buffer, pos.lnum[0], false);
            if (pos.col[0] < ml_get_buf_len(wp.w_buffer, pos.lnum[0])) {
                c = utf_ptr2char(ptr.add(pos.col[0]));
                if (c != TAB && vim_isprintc(c)) {
                    endadd = char2cells(c) - 1;
                    if (coladd > endadd) {
                        endadd = 0;
                    } else {
                        coladd = 0;
                    }
                }
            }
            col[0] += coladd;
            if (start != null) {
                start.put(col[0]);
            }
            if (cursor != null) {
                cursor.put(col[0]);
            }
            if (end != null) {
                end.put(col[0] + endadd);
            }
        } else {
            getvcol(wp, pos, start, cursor, end, flags);
        }
    }

    void getvcols(S_window_S wp, T_pos_T pos1, T_pos_T pos2, IntPtr left, IntPtr right, int flags) {
        int[] from1 = new int[1];
        int[] from2 = new int[1];
        int[] to1 = new int[1];
        int[] to2 = new int[1];
        if (pos1.lnum[0] != pos2.lnum[0] ? pos1.lnum[0] < pos2.lnum[0] : (pos1.col[0] != pos2.col[0] ? pos1.col[0] < pos2.col[0] : pos1.coladd < pos2.coladd)) {
            getvvcol(wp, pos1, new IntPtr(from1, 0), null, new IntPtr(to1, 0), flags);
            getvvcol(wp, pos2, new IntPtr(from2, 0), null, new IntPtr(to2, 0), flags);
        } else {
            getvvcol(wp, pos2, new IntPtr(from1, 0), null, new IntPtr(to1, 0), flags);
            getvvcol(wp, pos1, new IntPtr(from2, 0), null, new IntPtr(to2, 0), flags);
        }
        if (from2[0] < from1[0]) {
            left.put(from2[0]);
        } else {
            left.put(from1[0]);
        }
        if (to2[0] > to1[0]) {
            if (p_sel[0].get() == 'e' && from2[0] - 1 >= to1[0]) {
                right.put(from2[0] - 1);
            } else {
                right.put(to2[0]);
            }
        } else {
            right.put(to1[0]);
        }
    }

    BytePtr skipwhite(BytePtr q) {
        BytePtr p = null;
        p = q;
        while (p.get() == ' ' || p.get() == '\t') {
            p = p.add(1);
        }
        return p;
    }

