        top_end = 0;
        mid_start = 999;
        mid_end = 0;
        bot_start = 999;
        scrolled_down = false;
        scrolled_for_mod = false;
        top_to_mod = false;
        eof = false;
        didline = false;
        old_botline = wp.w_botline;
        mod_top = 0L;
        mod_bot = 0L;
