    void dealloc_cmdbuff() {
        ccline.cmdbuff = null;
        ccline.cmdbufflen = 0;
        ccline.cmdlen = ccline.cmdbufflen;
    }

    void alloc_cmdbuff(long len) {
        if (Long.compareUnsigned(len, 80L) < 0) {
            len = 100L;
        } else {
            len += 20L;
        }
        ccline.cmdbuff = BytePtr.alloc(len);
        ccline.cmdbufflen = (int) len;
    }

    boolean realloc_cmdbuff(int len) {
        BytePtr p = null;
        int plen = 0;
        int i = 0;
        if (len < ccline.cmdbufflen) {
            return true;
        }
        p = ccline.cmdbuff;
        plen = ccline.cmdbufflen;
        alloc_cmdbuff((long) len);
        if (ccline.cmdbuff == null) {
            ccline.cmdbuff = p;
            ccline.cmdbufflen = plen;
            return false;
        }
        Rt.memmove(ccline.cmdbuff, p, (long) ccline.cmdlen);
        ccline.cmdbuff.set(ccline.cmdlen, (byte) NUL);
        if (ccline.xpc != null && ccline.xpc.xp_pattern != null && ccline.xpc.xp_context != EXPAND_NOTHING && ccline.xpc.xp_context != -2) {
            i = (int) ccline.xpc.xp_pattern.sub(p);
            if (i >= 0 && i <= ccline.cmdlen) {
                ccline.xpc.xp_pattern = ccline.cmdbuff.add(i);
            }
        }
        return true;
    }

    void draw_cmdline(int start, int len) {
        msg_outtrans_len(ccline.cmdbuff.add(start), len);
    }

    void putcmdline(int c, int shift) {
        if (cmd_silent != 0) {
            return;
        }
        msg_no_more = TRUE;
        msg_putchar(c);
        if (shift != 0) {
            draw_cmdline(ccline.cmdpos, ccline.cmdlen - ccline.cmdpos);
        }
        msg_no_more = FALSE;
        cursorcmd();
        extra_char = c;
        extra_char_shift = shift;
    }

    void unputcmdline() {
        if (cmd_silent != 0) {
            return;
        }
        msg_no_more = TRUE;
        if (ccline.cmdlen == ccline.cmdpos) {
            msg_putchar(' ');
        } else {
            draw_cmdline(ccline.cmdpos, utfc_ptr2len(ccline.cmdbuff.add(ccline.cmdpos)));
        }
        msg_no_more = FALSE;
        cursorcmd();
        extra_char = NUL;
    }

    boolean put_on_cmdline(BytePtr str, int len, boolean redraw) {
        boolean retval = false;
        int i = 0;
        int m = 0;
        int c = 0;
        if (len < 0) {
            len = (int) musl_strlen(str);
        }
        if (ccline.cmdlen + len + 1 >= ccline.cmdbufflen) {
            retval = realloc_cmdbuff(ccline.cmdlen + len + 1);
        } else {
            retval = true;
        }
        if ((retval ? 1 : 0) == OK) {
            if (!ccline.overstrike) {
                Rt.memmove(ccline.cmdbuff.add(ccline.cmdpos).add(len), ccline.cmdbuff.add(ccline.cmdpos), (long) (ccline.cmdlen - ccline.cmdpos));
                ccline.cmdlen += len;
            } else {
                m = 0;
                i = 0;
                for (; i < len; i += utfc_ptr2len(str.add(i))) {
                    m++;
                }
                i = ccline.cmdpos;
                for (; (i < ccline.cmdlen) && m > 0; i += utfc_ptr2len(ccline.cmdbuff.add(i))) {
                    m--;
                }
                if (i < ccline.cmdlen) {
                    Rt.memmove(ccline.cmdbuff.add(ccline.cmdpos).add(len), ccline.cmdbuff.add(i), (long) (ccline.cmdlen - i));
                    ccline.cmdlen += ccline.cmdpos + len - i;
                } else {
                    ccline.cmdlen = ccline.cmdpos + len;
                }
            }
            Rt.memmove(ccline.cmdbuff.add(ccline.cmdpos), str, (long) len);
            ccline.cmdbuff.set(ccline.cmdlen, (byte) NUL);
            i = 0;
            c = utf_ptr2char(ccline.cmdbuff.add(ccline.cmdpos));
            while (ccline.cmdpos > 0 && utf_iscomposing(c)) {
                i = utf_head_off(ccline.cmdbuff, ccline.cmdbuff.add(ccline.cmdpos).add(-1)) + 1;
                ccline.cmdpos -= i;
                len += i;
                c = utf_ptr2char(ccline.cmdbuff.add(ccline.cmdpos));
            }
            if (i != 0) {
                i = ptr2cells(ccline.cmdbuff.add(ccline.cmdpos));
                ccline.cmdspos -= i;
                msg_col -= i;
                if (msg_col < 0) {
                    msg_col += cmdline_width;
                    msg_row--;
                }
            }
            if (redraw && cmd_silent == 0) {
                msg_no_more = TRUE;
                i = cmdline_row;
                cursorcmd();
                draw_cmdline(ccline.cmdpos, ccline.cmdlen - ccline.cmdpos);
                if (cmdline_row != i || ccline.overstrike) {
                    msg_clr_eos();
                }
                msg_no_more = FALSE;
            }
            if (KeyTyped != 0) {
                m = (int) ((long) cmdline_width * Rows[0]);
                if (m < 0) {
                    m = MAXCOL;
                }
            } else {
                m = MAXCOL;
            }
            i = 0;
            for (; i < len; i++) {
                c = cmdline_charsize(ccline.cmdpos);
                correct_cmdspos(ccline.cmdpos, c);
                if (ccline.cmdspos + c < m) {
                    ccline.cmdspos += c;
                }
                c = utfc_ptr2len(ccline.cmdbuff.add(ccline.cmdpos)) - 1;
                if (c > (len - i - 1)) {
                    c = len - i - 1;
                }
                ccline.cmdpos += c;
                i += c;
                ccline.cmdpos++;
            }
        }
        if (redraw) {
            msg_check();
        }
        return retval;
    }

    void save_cmdline(T_cmdline_info_T ccp) {
        if (prev_ccline_used == 0) {
            prev_ccline.zero();
            prev_ccline_used = TRUE;
        }
        ccp.set(prev_ccline);
        prev_ccline.set(ccline);
        ccline.cmdbuff = null;
    }

    void restore_cmdline(T_cmdline_info_T ccp) {
        ccline.set(prev_ccline);
        prev_ccline.set(ccp);
    }

    boolean cmdline_paste(int regname, boolean literally, boolean remcr) {
        long i = 0;
        BytePtr[] arg = new BytePtr[1];
        BytePtr p = null;
        int[] allocated = new int[1];
        BytePtr w = null;
        int len = 0;
        if (regname != Ctrl_F && regname != Ctrl_P && regname != Ctrl_W && regname != Ctrl_A && regname != Ctrl_L && !valid_yank_reg(regname, false)) {
            return false;
        }
        line_breakcheck();
        if (got_int != 0) {
            return false;
        }
        textlock++;
        i = (long) (get_spec_reg(regname, new Ptr<BytePtr>(arg, 0), new IntPtr(allocated, 0), true) ? 1 : 0);
        textlock--;
        if (i != 0) {
            if (arg[0] == null) {
                return false;
            }
            p = arg[0];
            if (p_is[0] != 0 && regname == Ctrl_W) {
                w = ccline.cmdbuff.add(ccline.cmdpos);
                for (; w.gt(ccline.cmdbuff); ) {
                    len = utf_head_off(ccline.cmdbuff, w.add(-1)) + 1;
                    if (!vim_iswordc(utf_ptr2char(w.add(-len)))) {
                        break;
                    }
                    w = w.add(-len);
                }
                len = (int) ccline.cmdbuff.add(ccline.cmdpos).sub(w);
                if (p_ic[0] != 0 ? musl_strncasecmp(w, arg[0], (long) len) == 0 : musl_strncmp(w, arg[0], (long) len) == 0) {
                    p = p.add(len);
                }
            }
            cmdline_paste_str(p, literally);
            return true;
        }
        return cmdline_paste_reg(regname, literally, remcr);
    }

    void cmdline_paste_str(BytePtr s_arg, boolean literally) {
        BytePtr[] s = new BytePtr[] {s_arg};
        int c = 0;
        int cv = 0;
        if (literally) {
            put_on_cmdline(s[0], -1, true);
        } else {
            while (s[0].get() != NUL) {
                cv = s[0].get() & 0xff;
                if (cv == Ctrl_V && s[0].at(1) != 0) {
                    s[0] = s[0].add(1);
                }
                c = mb_cptr2char_adv(new Ptr<BytePtr>(s, 0));
                if (cv == Ctrl_V || c == ESC || c == Ctrl_C || c == CAR || c == NL || c == Ctrl_L || c == intr_char || (c == Ctrl_BSL && s[0].get() == Ctrl_N)) {
                    stuffcharReadbuff(Ctrl_V);
                }
                stuffcharReadbuff(c);
            }
        }
    }

