    void add_buff(S_buffheader buf, BytePtr s, long slen) {
        long len = 0;
        S_buffblock p = null;
        if (slen < 0L) {
            slen = musl_strlen(s);
        }
        if (slen == 0L) {
            return;
        }
        if (buf.bh_first.b_next == null) {
            buf.bh_curr = buf.bh_first;
            buf.bh_create_newblock = TRUE;
        } else if (buf.bh_curr == null) {
            iemsg(new BytePtr(e_add_to_internal_buffer_that_was_already_read_from, 0));
            return;
        } else if (buf.bh_index != 0) {
            Rt.memmove(buf.bh_first.b_next.b_str, buf.bh_first.b_next.b_str.add(buf.bh_index), buf.bh_first.b_next.b_strlen - (long) buf.bh_index + 1L);
            buf.bh_first.b_next.b_strlen -= (long) buf.bh_index;
            buf.bh_space += buf.bh_index;
        }
        buf.bh_index = 0;
        if (buf.bh_create_newblock == 0 && buf.bh_space >= (int) slen) {
            vim_strncpy(buf.bh_curr.b_str.add((int) buf.bh_curr.b_strlen), s, slen);
            buf.bh_curr.b_strlen += slen;
            buf.bh_space -= slen;
        } else {
            if (slen < MINIMAL_SIZE) {
                len = MINIMAL_SIZE;
            } else {
                len = slen;
            }
            p = new S_buffblock();
            p.b_str = BytePtr.alloc(len + 1L);
            vim_strncpy(p.b_str, s, slen);
            p.b_strlen = slen;
            buf.bh_space = (int) (len - slen);
            buf.bh_create_newblock = FALSE;
            p.b_next = buf.bh_curr.b_next;
            buf.bh_curr.b_next = p;
            buf.bh_curr = p;
        }
    }

    void delete_buff_tail(S_buffheader buf, int slen) {
        if (buf.bh_curr == null) {
            return;
        }
        if (Long.compareUnsigned(buf.bh_curr.b_strlen, (long) slen) < 0) {
            return;
        }
        buf.bh_curr.b_str.set((int) (buf.bh_curr.b_strlen - (long) slen), (byte) NUL);
        buf.bh_curr.b_strlen -= (long) slen;
        buf.bh_space += slen;
    }

    void add_num_buff(S_buffheader buf, long n) {
        byte[] number = new byte[32];
        int numberlen = 0;
        numberlen = vim_snprintf(new BytePtr(number, 0), 32L, BytePtr.lit("%ld"), n);
        add_buff(buf, new BytePtr(number, 0), (long) numberlen);
    }

    void add_char_buff(S_buffheader buf, int c) {
        byte[] bytes = new byte[22];
        int len = 0;
        int i = 0;
        byte[] temp = new byte[4];
        long templen = 0;
        if (c < 0) {
            len = 1;
        } else {
            len = utf_char2bytes(c, new BytePtr(bytes, 0));
        }
        i = 0;
        for (; i < len; i++) {
            if (!(c < 0)) {
                c = bytes[i] & 0xff;
            }
            if (c < 0 || c == 128 || c == NUL) {
                temp[0] = (byte) -128;
                temp[1] = (byte) (c == 128 ? KS_SPECIAL : (c == NUL ? KS_ZERO : -c & 255));
                temp[2] = (byte) (c == 128 || c == NUL ? 'X' : (-c >>> 8) & 255);
                temp[3] = (byte) NUL;
                templen = 3L;
            } else {
                temp[0] = (byte) c;
                temp[1] = (byte) NUL;
                templen = 1L;
            }
            add_buff(buf, new BytePtr(temp, 0), templen);
        }
    }

    int read_readbuffers(boolean advance) {
        int c = 0;
        c = read_readbuf(readbuf1, advance);
        if (c == NUL) {
            c = read_readbuf(readbuf2, advance);
        }
        return c;
    }

    int read_readbuf(S_buffheader buf, boolean advance) {
        byte c = 0;
        S_buffblock curr = null;
        if (buf.bh_first.b_next == null) {
            return NUL;
        }
        curr = buf.bh_first.b_next;
        c = curr.b_str.at(buf.bh_index);
        if (advance) {
            buf.bh_index++;
            if (curr.b_str.at(buf.bh_index) == NUL) {
                buf.bh_first.b_next = curr.b_next;
                buf.bh_index = 0;
            }
        }
        return c & 0xff;
    }

    void start_stuff() {
        if (readbuf1.bh_first.b_next != null) {
            readbuf1.bh_curr = readbuf1.bh_first;
            readbuf1.bh_create_newblock = TRUE;
        }
        if (readbuf2.bh_first.b_next != null) {
            readbuf2.bh_curr = readbuf2.bh_first;
            readbuf2.bh_create_newblock = TRUE;
        }
    }

    boolean stuff_empty() {
        return readbuf1.bh_first.b_next == null && readbuf2.bh_first.b_next == null;
    }

    void typeahead_noflush(int c) {
        typeahead_char = c;
    }

    void flush_buffers(int flush_typeahead) {
        init_typebuf();
        start_stuff();
        while (read_readbuffers(true) != NUL) {
        }
        if (flush_typeahead == FLUSH_MINIMAL) {
            if (typebuf.tb_off + typebuf.tb_maplen >= typebuf.tb_buflen) {
                typebuf.tb_off = MAXMAPLEN;
                typebuf.tb_len = 0;
            } else {
                typebuf.tb_off += typebuf.tb_maplen;
                typebuf.tb_len -= typebuf.tb_maplen;
            }
        } else {
            if (flush_typeahead == FLUSH_INPUT) {
                while (inchar(typebuf.tb_buf, typebuf.tb_buflen - 1, 10L) != 0) {
                }
            }
            typebuf.tb_off = MAXMAPLEN;
            typebuf.tb_len = 0;
        }
        typebuf.tb_maplen = 0;
        typebuf.tb_silent = 0;
        cmd_silent = FALSE;
        typebuf.tb_no_abbr_cnt = 0;
        typebuf.tb_change_cnt++;
        if (typebuf.tb_change_cnt == 0) {
            typebuf.tb_change_cnt = 1;
        }
    }

    void ResetRedobuff() {
        if (block_redo != 0) {
            return;
        }
        free_buff(old_redobuff);
        old_redobuff.set(redobuff);
        redobuff.bh_first.b_next = null;
    }

    void CancelRedo() {
        if (block_redo != 0) {
            return;
        }
        free_buff(redobuff);
        redobuff.set(old_redobuff);
        old_redobuff.bh_first.b_next = null;
        start_stuff();
        while (read_readbuffers(true) != NUL) {
        }
    }

    void AppendToRedobuff(BytePtr s) {
        if (block_redo == 0) {
            add_buff(redobuff, s, -1L);
        }
    }

    void AppendToRedobuffLit(BytePtr str, int len) {
        BytePtr[] s = new BytePtr[1];
        int c = 0;
        BytePtr start = null;
        s[0] = str;
        if (block_redo != 0) {
            return;
        }
        while (len < 0 ? s[0].get() != NUL : s[0].sub(str) < (long) len) {
            start = s[0];
            while ((s[0].get() & 0xff) >= ' ' && (s[0].get() & 0xff) < DEL && (len < 0 || s[0].sub(str) < (long) len)) {
                s[0] = s[0].add(1);
            }
            if (s[0].get() == NUL && (s[0].at(-1) == '0' || s[0].at(-1) == '^')) {
                s[0] = s[0].add(-1);
            }
            if (s[0].gt(start)) {
                add_buff(redobuff, start, s[0].sub(start));
            }
            if (s[0].get() == NUL || (len >= 0 && s[0].sub(str) >= (long) len)) {
                break;
            }
            c = mb_cptr2char_adv(new Ptr<BytePtr>(s, 0));
            if (c < ' ' || c == DEL || (s[0].get() == NUL && (c == '0' || c == '^'))) {
                add_char_buff(redobuff, Ctrl_V);
            }
            if (s[0].get() == NUL && c == '0') {
                add_buff(redobuff, BytePtr.lit("048"), 3L);
            } else {
                add_char_buff(redobuff, c);
            }
        }
    }

    void AppendToRedobuffSpec(BytePtr s_arg) {
        BytePtr[] s = new BytePtr[] {s_arg};
        if (block_redo != 0) {
            return;
        }
        while (s[0].get() != NUL) {
            if ((s[0].get() & 0xff) == 128 && s[0].at(1) != NUL && s[0].at(2) != NUL) {
                add_buff(redobuff, s[0], 3L);
                s[0] = s[0].add(3);
            } else {
                add_char_buff(redobuff, mb_cptr2char_adv(new Ptr<BytePtr>(s, 0)));
            }
        }
    }

    void AppendCharToRedobuff(int c) {
        if (block_redo == 0) {
            add_char_buff(redobuff, c);
        }
    }

    void AppendNumberToRedobuff(long n) {
        if (block_redo == 0) {
            add_num_buff(redobuff, n);
        }
    }

    void stuffReadbuff(BytePtr s) {
        add_buff(readbuf1, s, -1L);
    }

    void stuffRedoReadbuff(BytePtr s) {
        add_buff(readbuf2, s, -1L);
    }

    void stuffReadbuffLen(BytePtr s, long len) {
        add_buff(readbuf1, s, len);
    }

    void stuffcharReadbuff(int c) {
        add_char_buff(readbuf1, c);
    }

    void stuffnumReadbuff(long n) {
        add_num_buff(readbuf1, n);
    }

    void stuffescaped(BytePtr arg_arg, int literally) {
        BytePtr[] arg = new BytePtr[] {arg_arg};
        int c = 0;
        BytePtr start = null;
        while (arg[0].get() != NUL) {
            start = arg[0];
            while (((arg[0].get() & 0xff) >= ' ' && (arg[0].get() & 0xff) < DEL) || ((arg[0].get() & 0xff) == 128 && literally == 0)) {
                arg[0] = arg[0].add(1);
            }
            if (arg[0].gt(start)) {
                stuffReadbuffLen(start, arg[0].sub(start));
            }
            if (arg[0].get() != NUL) {
                c = mb_cptr2char_adv(new Ptr<BytePtr>(arg, 0));
                if (literally != 0 && ((c < ' ' && c != TAB) || c == DEL)) {
                    stuffcharReadbuff(Ctrl_V);
                }
                stuffcharReadbuff(c);
            }
        }
    }

    int read_redo(boolean init, boolean old_redo) {
        int c = 0;
        int n = 0;
        byte[] buf = new byte[22];
        int i = 0;
        if (init) {
            if (old_redo) {
                read_redo_bp = old_redobuff.bh_first.b_next;
            } else {
                read_redo_bp = redobuff.bh_first.b_next;
            }
            if (read_redo_bp == null) {
                return FAIL;
            }
            read_redo_p = read_redo_bp.b_str;
            return OK;
        }
        c = read_redo_p.get() & 0xff;
        if (c != NUL) {
            if (c != 128 || (read_redo_p.at(1) & 0xff) == KS_SPECIAL) {
                n = c < 0 || c > 255 ? 1 : (int) mb_bytelen_tab[c];
            } else {
                n = 1;
            }
            i = 0;
            for (; ; i++) {
                if (c == 128) {
                    c = (read_redo_p.at(1) & 0xff) == KS_SPECIAL ? 128 : ((read_redo_p.at(1) & 0xff) == KS_ZERO ? -(KS_ZERO + ('X' << 8)) : -((read_redo_p.at(1) & 0xff) + ((read_redo_p.at(2) & 0xff) << 8)));
                    read_redo_p = read_redo_p.add(2);
                }
                read_redo_p = read_redo_p.add(1);
                if (read_redo_p.get() == NUL && read_redo_bp.b_next != null) {
                    read_redo_bp = read_redo_bp.b_next;
                    read_redo_p = read_redo_bp.b_str;
                }
                buf[i] = (byte) c;
                if (i == n - 1) {
                    if (n != 1) {
                        c = utf_ptr2char(new BytePtr(buf, 0));
                    }
                    break;
                }
                c = read_redo_p.get() & 0xff;
                if (c == NUL) {
                    break;
                }
            }
        }
        return c;
    }

    void copy_redo(boolean old_redo) {
        int c = 0;
        while (true) {
            c = read_redo(false, old_redo);
            if (!(c != NUL)) {
                break;
            }
            add_char_buff(readbuf2, c);
        }
    }

    boolean start_redo(long count, boolean old_redo) {
        int c = 0;
        if (read_redo(true, old_redo) == FAIL) {
            return false;
        }
        c = read_redo(false, old_redo);
        if (c == '"') {
            add_buff(readbuf2, BytePtr.lit("\""), 1L);
            c = read_redo(false, old_redo);
            if (c >= '1' && c < '9') {
                c++;
            }
            add_char_buff(readbuf2, c);
            if (c == '=') {
                add_char_buff(readbuf2, CAR);
                cmd_silent = TRUE;
            }
            c = read_redo(false, old_redo);
        }
        if (c == 'v') {
            VIsual.set(curwin.w_cursor);
            VIsual_active = TRUE;
            VIsual_select = FALSE;
            VIsual_reselect = TRUE;
            redo_VIsual_busy = TRUE;
            c = read_redo(false, old_redo);
        }
        if (count != 0) {
            while (Integer.compareUnsigned(c - '0', 10) < 0) {
                c = read_redo(false, old_redo);
            }
            add_num_buff(readbuf2, count);
        }
        add_char_buff(readbuf2, c);
        copy_redo(old_redo);
        return true;
    }

    boolean start_redo_ins() {
        int c = 0;
        if (read_redo(true, false) == FAIL) {
            return false;
        }
        start_stuff();
        while (true) {
            c = read_redo(false, false);
            if (!(c != NUL)) {
                break;
            }
            if (vim_strchr(BytePtr.lit("AaIiRrOo"), c) != null) {
                if (c == 'O' || c == 'o') {
                    add_buff(readbuf2, BytePtr.lit("\n"), -1L);
                }
                break;
            }
        }
        copy_redo(false);
        block_redo = TRUE;
        return true;
    }

    void stop_redo_ins() {
        block_redo = FALSE;
    }

    void init_typebuf() {
        if (typebuf.tb_buf != null) {
            return;
        }
        typebuf.tb_buf = new BytePtr(typebuf_init, 0);
        typebuf.tb_noremap = new BytePtr(noremapbuf_init, 0);
        typebuf.tb_buflen = 5 * (MAXMAPLEN + 3);
        typebuf.tb_len = 0;
        typebuf.tb_off = MAXMAPLEN + 4;
        typebuf.tb_change_cnt = 1;
    }

    boolean ins_typebuf(BytePtr str, int noremap, int offset, boolean nottyped, int silent) {
        BytePtr s1 = null;
        BytePtr s2 = null;
        int newlen = 0;
        int addlen = 0;
        int i = 0;
        int newoff = 0;
        int val = 0;
        int nrm = 0;
        int extra = 0;
        init_typebuf();
        typebuf.tb_change_cnt++;
        if (typebuf.tb_change_cnt == 0) {
            typebuf.tb_change_cnt = 1;
        }
        addlen = (int) musl_strlen(str);
        if (offset == 0 && addlen <= typebuf.tb_off) {
            typebuf.tb_off -= addlen;
            Rt.memmove(typebuf.tb_buf.add(typebuf.tb_off), str, (long) addlen);
        } else if (typebuf.tb_len == 0 && typebuf.tb_buflen >= addlen + 3 * (MAXMAPLEN + 4)) {
            typebuf.tb_off = (typebuf.tb_buflen - addlen - 3 * (MAXMAPLEN + 4)) / 2;
            Rt.memmove(typebuf.tb_buf.add(typebuf.tb_off), str, (long) addlen);
        } else {
            newoff = MAXMAPLEN + 4;
            extra = addlen + newoff + 4 * (MAXMAPLEN + 4);
            if (typebuf.tb_len > (2147483647 - extra)) {
                emsg(gettext_(new BytePtr(e_command_too_complex, 0)));
                setcursor();
                return false;
            }
            newlen = typebuf.tb_len + extra;
            s1 = BytePtr.alloc((long) newlen);
            s2 = BytePtr.alloc((long) newlen);
            typebuf.tb_buflen = newlen;
            Rt.memmove(s1.add(newoff), typebuf.tb_buf.add(typebuf.tb_off), (long) offset);
            Rt.memmove(s1.add(newoff).add(offset), str, (long) addlen);
            Rt.memmove(s1.add(newoff).add(offset).add(addlen), typebuf.tb_buf.add(typebuf.tb_off).add(offset), (long) (typebuf.tb_len - offset + 1));
            typebuf.tb_buf = s1;
            Rt.memmove(s2.add(newoff), typebuf.tb_noremap.add(typebuf.tb_off), (long) offset);
            Rt.memmove(s2.add(newoff).add(offset).add(addlen), typebuf.tb_noremap.add(typebuf.tb_off).add(offset), (long) (typebuf.tb_len - offset));
            typebuf.tb_noremap = s2;
            typebuf.tb_off = newoff;
        }
        typebuf.tb_len += addlen;
        if (noremap == -2) {
            val = RM_SCRIPT;
        } else if (noremap == -3) {
            val = RM_ABBR;
        } else {
            val = RM_NONE;
        }
        if (noremap == -3) {
            nrm = 1;
        } else if (noremap < 0) {
            nrm = addlen;
        } else {
            nrm = noremap;
        }
        i = 0;
        for (; i < addlen; i++) {
            nrm--;
            typebuf.tb_noremap.set(typebuf.tb_off + i + offset, (byte) (nrm >= 0 ? val : RM_YES));
        }
        if (nottyped || typebuf.tb_maplen > offset) {
            typebuf.tb_maplen += addlen;
        }
        if (silent != 0 || typebuf.tb_silent > offset) {
            typebuf.tb_silent += addlen;
            cmd_silent = TRUE;
        }
        if (typebuf.tb_no_abbr_cnt != 0 && offset == 0) {
            typebuf.tb_no_abbr_cnt += addlen;
        }
        return true;
    }

    int ins_char_typebuf(int c, int modifiers) {
        byte[] buf = new byte[67];
        int len = 0;
        len = special_to_buf(c, modifiers, true, new BytePtr(buf, 0));
        buf[len] = (byte) NUL;
        ins_typebuf(new BytePtr(buf, 0), KeyNoremap, 0, KeyTyped == 0, cmd_silent);
        return len;
    }

    boolean typebuf_changed(int tb_change_cnt) {
        return tb_change_cnt != 0 && typebuf.tb_change_cnt != tb_change_cnt;
    }

    boolean typebuf_typed() {
        return typebuf.tb_maplen == 0;
    }

    int typebuf_maplen() {
        return typebuf.tb_maplen;
    }

    void del_typebuf(int len, int offset) {
        int i = 0;
        if (len == 0) {
            return;
        }
        typebuf.tb_len -= len;
        if (offset == 0 && typebuf.tb_buflen - (typebuf.tb_off + len) >= 3 * MAXMAPLEN + 3) {
            typebuf.tb_off += len;
        } else {
            i = typebuf.tb_off + offset;
            if (typebuf.tb_off > MAXMAPLEN) {
                Rt.memmove(typebuf.tb_buf.add(MAXMAPLEN), typebuf.tb_buf.add(typebuf.tb_off), (long) offset);
                Rt.memmove(typebuf.tb_noremap.add(MAXMAPLEN), typebuf.tb_noremap.add(typebuf.tb_off), (long) offset);
                typebuf.tb_off = MAXMAPLEN;
            }
            Rt.memmove(typebuf.tb_buf.add(typebuf.tb_off).add(offset), typebuf.tb_buf.add(i).add(len), (long) (typebuf.tb_len - offset + 1));
            Rt.memmove(typebuf.tb_noremap.add(typebuf.tb_off).add(offset), typebuf.tb_noremap.add(i).add(len), (long) (typebuf.tb_len - offset));
        }
        if (typebuf.tb_maplen > offset) {
            if (typebuf.tb_maplen < offset + len) {
                typebuf.tb_maplen = offset;
            } else {
                typebuf.tb_maplen -= len;
            }
        }
        if (typebuf.tb_silent > offset) {
            if (typebuf.tb_silent < offset + len) {
                typebuf.tb_silent = offset;
            } else {
                typebuf.tb_silent -= len;
            }
        }
        if (typebuf.tb_no_abbr_cnt > offset) {
            if (typebuf.tb_no_abbr_cnt < offset + len) {
                typebuf.tb_no_abbr_cnt = offset;
            } else {
                typebuf.tb_no_abbr_cnt -= len;
            }
        }
        typebuf.tb_change_cnt++;
        if (typebuf.tb_change_cnt == 0) {
            typebuf.tb_change_cnt = 1;
        }
    }

    boolean gotchars_add_byte(T_gotchars_state_T state, byte byte_) {
        int c = 0;
        long t1 = 0;
        boolean retval = false;
        boolean in_special = false;
        boolean in_mbyte = false;
        t1 = state.buflen;
        state.buflen++;
        state.buf[(int) t1] = byte_;
        c = state.buf[(int) t1] & 0xff;
        retval = false;
        in_special = Integer.compareUnsigned(state.pending_special, 0) > 0;
        in_mbyte = Integer.compareUnsigned(state.pending_mbyte, 0) > 0;
        if (in_special) {
            state.pending_special--;
        } else if (c == 128) {
            state.pending_special = 2;
        }
        if (Integer.compareUnsigned(state.pending_special, 0) > 0) {
            state.prev_c = c;
            return retval;
        }
        if (in_mbyte) {
            state.pending_mbyte--;
        } else {
            if (in_special) {
                if (state.prev_c == KS_MODIFIER) {
                    state.prev_c = c;
                    return retval;
                }
                c = state.prev_c == KS_SPECIAL ? 128 : (state.prev_c == KS_ZERO ? -(KS_ZERO + ('X' << 8)) : -(state.prev_c + (c << 8)));
                if (c == K_FOCUSGAINED || c == K_FOCUSLOST || c == K_COMPLETE_DELAY) {
                    state.buflen = 0L;
                }
            }
            state.pending_mbyte = (c < 0 || c > 255 ? 1 : (int) mb_bytelen_tab[c]) - 1;
        }
        if (Integer.compareUnsigned(state.pending_mbyte, 0) > 0) {
            state.prev_c = c;
            return retval;
        }
        retval = true;
        state.prev_c = c;
        return retval;
    }

    void gotchars(BytePtr chars, int len) {
        BytePtr s = null;
        int todo = 0;
        int t1 = 0;
        BytePtr t2 = null;
        s = chars;
        todo = len;
        while (true) {
            t1 = todo;
            todo--;
            if (!(t1 > 0)) {
                break;
            }
            t2 = s;
            s = s.add(1);
            if (!gotchars_add_byte(gotchars_state, t2.get())) {
                continue;
            }
            if (reg_recording != 0) {
                gotchars_state.buf[(int) gotchars_state.buflen] = (byte) NUL;
                add_buff(recordbuff, new BytePtr(gotchars_state.buf, 0), gotchars_state.buflen);
                last_recorded_len += gotchars_state.buflen;
            }
            gotchars_state.buflen = 0L;
        }
        may_sync_undo();
        maptick++;
    }

    void gotchars_ignore() {
        byte[] nop_buf = new byte[3];
        nop_buf = new byte[3];
        nop_buf[0] = (byte) -128;
        nop_buf[1] = (byte) KS_EXTRA;
        nop_buf[2] = (byte) KE_IGNORE;
        gotchars(new BytePtr(nop_buf, 0), 3);
    }

    void ungetchars(int len) {
        if (reg_recording == 0) {
            return;
        }
        delete_buff_tail(recordbuff, len);
        last_recorded_len -= (long) len;
    }

    void may_sync_undo() {
        if ((State & (MODE_INSERT | MODE_CMDLINE)) == 0 || arrow_used != 0) {
            u_sync(false);
        }
    }

    boolean alloc_typebuf() {
        typebuf.tb_buf = BytePtr.alloc(5 * (MAXMAPLEN + 3));
        typebuf.tb_noremap = BytePtr.alloc(5 * (MAXMAPLEN + 3));
        if (typebuf.tb_buf == null || typebuf.tb_noremap == null) {
            free_typebuf();
            return false;
        }
        typebuf.tb_buflen = 5 * (MAXMAPLEN + 3);
        typebuf.tb_off = MAXMAPLEN + 4;
        typebuf.tb_len = 0;
        typebuf.tb_maplen = 0;
        typebuf.tb_silent = 0;
        typebuf.tb_no_abbr_cnt = 0;
        typebuf.tb_change_cnt++;
        if (typebuf.tb_change_cnt == 0) {
            typebuf.tb_change_cnt = 1;
        }
        return true;
    }

    void free_typebuf() {
        if (BytePtr.eq(typebuf.tb_buf, new BytePtr(typebuf_init, 0))) {
            internal_error(BytePtr.lit("Free typebuf 1"));
        } else {
            typebuf.tb_buf = null;
        }
        if (BytePtr.eq(typebuf.tb_noremap, new BytePtr(noremapbuf_init, 0))) {
            internal_error(BytePtr.lit("Free typebuf 2"));
        } else {
            typebuf.tb_noremap = null;
        }
    }

    boolean can_get_old_char() {
        return old_char != -1 && (old_KeyStuffed != 0 || stuff_empty());
    }

    void save_typeahead(T_tasave_T tp) {
        tp.save_typebuf.set(typebuf);
        tp.typebuf_valid = alloc_typebuf();
        if (!tp.typebuf_valid) {
            typebuf.set(tp.save_typebuf);
        }
        tp.old_char = old_char;
        tp.old_mod_mask = old_mod_mask;
        old_char = -1;
        tp.save_readbuf1.set(readbuf1);
        readbuf1.bh_first.b_next = null;
        tp.save_readbuf2.set(readbuf2);
        readbuf2.bh_first.b_next = null;
        tp.save_inputbuf = get_input_buf();
    }

    void restore_typeahead(T_tasave_T tp, boolean overwrite) {
        if (tp.typebuf_valid) {
            free_typebuf();
            typebuf.set(tp.save_typebuf);
        }
        old_char = tp.old_char;
        old_mod_mask = tp.old_mod_mask;
        free_buff(readbuf1);
        readbuf1.set(tp.save_readbuf1);
        free_buff(readbuf2);
        readbuf2.set(tp.save_readbuf2);
        set_input_buf(tp.save_inputbuf, overwrite);
    }

    int merge_modifyOtherKeys(int c_arg, IntPtr modifiers) {
        int c = 0;
        c = c_arg;
        if ((modifiers.get() & MOD_MASK_CTRL) != 0) {
            if ((c >= '`' && c <= 127) || (c >= '@' && c <= '_')) {
                c &= 31;
                if (c == NUL) {
                    c = -(KS_ZERO + ('X' << 8));
                }
            } else if (c == '6') {
                c = 30;
            }
            if (c != c_arg) {
                modifiers.put(modifiers.get() & ~MOD_MASK_CTRL);
            }
        }
        if ((modifiers.get() & (MOD_MASK_META | MOD_MASK_ALT)) != 0 && c >= 0 && c <= 127) {
            if ((modifiers.get() & MOD_MASK_SHIFT) != 0 && c >= 'a' && c <= 'z') {
                c += 'a' - 'A';
                modifiers.put(modifiers.get() & ~MOD_MASK_SHIFT);
            }
            c += 128;
            modifiers.put(modifiers.get() & ~(MOD_MASK_META | MOD_MASK_ALT));
        }
        return c;
    }

    void add_byte_to_showcmd(byte byte_) {
        BytePtr[] ptr = new BytePtr[1];
        int modifiers = 0;
        int c = 0;
        BytePtr mb_ptr = null;
        BytePtr t1 = null;
        int t2 = 0;
        int[] modifiers_after = new int[1];
        int mod_c = 0;
        BytePtr t3 = null;
        modifiers = 0;
        c = NUL;
        if (p_sc[0] == 0 || msg_silent != 0) {
            return;
        }
        if (!gotchars_add_byte(add_byte_to_showcmd_state, byte_)) {
            return;
        }
        add_byte_to_showcmd_state.buf[(int) add_byte_to_showcmd_state.buflen] = (byte) NUL;
        add_byte_to_showcmd_state.buflen = 0L;
        ptr[0] = new BytePtr(add_byte_to_showcmd_state.buf, 0);
        if ((ptr[0].at(0) & 0xff) == 128 && (ptr[0].at(1) & 0xff) == KS_MODIFIER && ptr[0].at(2) != NUL) {
            modifiers = ptr[0].at(2) & 0xff;
            ptr[0] = ptr[0].add(3);
        }
        if (ptr[0].get() != NUL) {
            mb_ptr = mb_unescape(new Ptr<BytePtr>(ptr, 0));
            if (mb_ptr != null) {
                t2 = utf_ptr2char(mb_ptr);
            } else {
                t1 = ptr[0];
                ptr[0] = ptr[0].add(1);
                t2 = t1.get() & 0xff;
            }
            c = t2;
            if (c <= 127) {
                modifiers_after[0] = modifiers;
                mod_c = merge_modifyOtherKeys(c, new IntPtr(modifiers_after, 0));
                if (modifiers_after[0] == 0) {
                    modifiers = 0;
                    c = mod_c;
                }
            }
        }
        if (modifiers != 0) {
            add_to_showcmd(128);
            add_to_showcmd(KS_MODIFIER);
            add_to_showcmd(modifiers);
        }
        if (c != NUL) {
            add_to_showcmd(c);
        }
        while (ptr[0].get() != NUL) {
            t3 = ptr[0];
            ptr[0] = ptr[0].add(1);
            add_to_showcmd(t3.get() & 0xff);
        }
    }

    int vgetc() {
        int c = 0;
        int c2 = 0;
        int n = 0;
        byte[] buf = new byte[22];
        int i = 0;
        boolean did_inc = false;
        int save_allow_keys = 0;
        if (can_get_old_char()) {
            c = old_char;
            old_char = -1;
            mod_mask[0] = old_mod_mask;
        } else {
            mod_mask[0] = 0;
            vgetc_mod_mask = 0;
            vgetc_char = 0;
            last_recorded_len -= vgetc_last_vgetc_recorded_len;
            for (;;) {
                did_inc = false;
                if (mod_mask[0] != 0) {
                    no_mapping++;
                    allow_keys++;
                    did_inc = true;
                }
                c = vgetorpeek(true);
                if (did_inc) {
                    no_mapping--;
                    allow_keys--;
                }
                if (c == 128) {
                    save_allow_keys = allow_keys;
                    no_mapping++;
                    allow_keys = 0;
                    c2 = vgetorpeek(true);
                    c = vgetorpeek(true);
                    no_mapping--;
                    allow_keys = save_allow_keys;
                    if (c2 == KS_MODIFIER) {
                        mod_mask[0] = c;
                        continue;
                    }
                    c = c2 == KS_SPECIAL ? 128 : (c2 == KS_ZERO ? -(KS_ZERO + ('X' << 8)) : -(c2 + (c << 8)));
                    if (allow_osc_key == 0 && c == K_OSC) {
                        continue;
                    }
                    if (c == K_ESC) {
                        c = ESC;
                    }
                }
                n = c < 0 || c > 255 ? 1 : (int) mb_bytelen_tab[c];
                if (n > 1) {
                    no_mapping++;
                    buf[0] = (byte) c;
                    i = 1;
                    for (; i < n; i++) {
                        buf[i] = (byte) vgetorpeek(true);
                        if ((buf[i] & 0xff) == 128) {
                            c = vgetorpeek(true);
                            if (vgetorpeek(true) == KE_CSI && c == KS_EXTRA) {
                                buf[i] = (byte) CSI;
                            }
                        }
                    }
                    no_mapping--;
                    c = utf_ptr2char(new BytePtr(buf, 0));
                }
                if (vgetc_char == 0) {
                    vgetc_mod_mask = mod_mask[0];
                    vgetc_char = c;
                }
                switch (c) {
                    case K_KPLUS:
                        c = '+';
                        break;
                    case K_KMINUS:
                        c = '-';
                        break;
                    case K_KDIVIDE:
                        c = '/';
                        break;
                    case K_KMULTIPLY:
                        c = '*';
                        break;
                    case K_KENTER:
                        c = CAR;
                        break;
                    case K_KPOINT:
                        c = '.';
                        break;
                    case K_K0:
                        c = '0';
                        break;
                    case K_K1:
                        c = '1';
                        break;
                    case K_K2:
                        c = '2';
                        break;
                    case K_K3:
                        c = '3';
                        break;
                    case K_K4:
                        c = '4';
                        break;
                    case K_K5:
                        c = '5';
                        break;
                    case K_K6:
                        c = '6';
                        break;
                    case K_K7:
                        c = '7';
                        break;
                    case K_K8:
                        c = '8';
                        break;
                    case K_K9:
                        c = '9';
                        break;
                    case K_XHOME:
                    case K_ZHOME:
                        if (mod_mask[0] == MOD_MASK_SHIFT) {
                            c = K_TC_HASH_2;
                            mod_mask[0] = 0;
                        } else if (mod_mask[0] == MOD_MASK_CTRL) {
                            c = K_C_HOME;
                            mod_mask[0] = 0;
                        } else {
                            c = K_HOME;
                        }
                        break;
                    case K_XEND:
                    case K_ZEND:
                        if (mod_mask[0] == MOD_MASK_SHIFT) {
                            c = K_TC_STAR_7;
                            mod_mask[0] = 0;
                        } else if (mod_mask[0] == MOD_MASK_CTRL) {
                            c = K_C_END;
                            mod_mask[0] = 0;
                        } else {
                            c = K_END;
                        }
                        break;
                    case K_XUP:
                        c = K_UP;
                        break;
                    case K_XDOWN:
                        c = K_DOWN;
                        break;
                    case K_XLEFT:
                        c = K_LEFT;
                        break;
                    case K_XRIGHT:
                        c = K_RIGHT;
                        break;
                }
                break;
            }
            vgetc_last_vgetc_recorded_len = last_recorded_len;
        }
        return c;
    }

    int safe_vgetc() {
        int c = 0;
        c = vgetc();
        if (c == NUL) {
            c = get_keystroke();
        }
        return c;
    }

    int plain_vgetc_nopaste() {
        int c = 0;
        do {
            c = safe_vgetc();
        } while (c == K_IGNORE || c == -(KS_VER_SCROLLBAR + ('X' << 8)) || c == -(KS_HOR_SCROLLBAR + ('X' << 8)) || c == K_MOUSEMOVE);
        return c;
    }

    int plain_vgetc() {
        int c = 0;
        c = plain_vgetc_nopaste();
        if (c == K_PASTESTART) {
            c = bracketed_paste(PASTE_ONE_CHAR, false, null);
        }
        return c;
    }

    int vpeekc() {
        if (can_get_old_char()) {
            return old_char;
        }
        return vgetorpeek(false);
    }

    boolean char_avail() {
        int retval = 0;
        no_mapping++;
        retval = vpeekc();
        no_mapping--;
        return retval != NUL;
    }

    int check_simplify_modifier(int max_offset) {
        int offset = 0;
        BytePtr tp = null;
        int[] modifier = new int[1];
        int c = 0;
        int new_c = 0;
        byte[] new_string = new byte[21];
        int len = 0;
        int key_offset = 0;
        int i = 0;
        offset = 0;
        for (; offset < max_offset; offset++) {
            if (offset + 3 >= typebuf.tb_len) {
                break;
            }
            tp = typebuf.tb_buf.add(typebuf.tb_off).add(offset);
            if (((tp.at(0) & 0xff) == 128 || (tp.at(0) & 0xff) == CSI) && (tp.at(1) & 0xff) == KS_MODIFIER) {
                modifier[0] = tp.at(2) & 0xff;
                c = tp.at(3) & 0xff;
                new_c = merge_modifyOtherKeys(c, new IntPtr(modifier, 0));
                if (new_c != c) {
                    key_offset = offset;
                    if (offset == 0) {
                        vgetc_char = c;
                        vgetc_mod_mask = tp.at(2) & 0xff;
                    }
                    if (new_c < 0) {
                        new_string[0] = (byte) -128;
                        new_string[1] = (byte) (new_c == 128 ? KS_SPECIAL : (new_c == NUL ? KS_ZERO : -new_c & 255));
                        new_string[2] = (byte) (new_c == 128 || new_c == NUL ? 'X' : (-new_c >>> 8) & 255);
                        len = 3;
                    } else {
                        len = utf_char2bytes(new_c, new BytePtr(new_string, 0));
                    }
                    if (modifier[0] == 0) {
                        if (!put_string_in_typebuf(offset, 4, new BytePtr(new_string, 0), len, null, 0, null)) {
                            return -1;
                        }
                    } else {
                        tp.set(2, (byte) modifier[0]);
                        key_offset = offset + 3;
                        if (!put_string_in_typebuf(key_offset, 1, new BytePtr(new_string, 0), len, null, 0, null)) {
                            return -1;
                        }
                    }
                    i = 0;
                    for (; i < len; i++) {
                        typebuf.tb_noremap.set(typebuf.tb_off + key_offset + i, (byte) ((typebuf.tb_noremap.at(typebuf.tb_off + key_offset + i) & 0xff) | RM_SIMPLIFIED));
                    }
                    return len;
                }
            }
        }
        return 0;
    }

    boolean key_protocol_enabled() {
        int using_mok = 0;
        using_mok = modify_otherkeys_state != MOKS_INITIAL ? (modify_otherkeys_state == MOKS_ENABLED ? 1 : 0) : seenModifyOtherKeys;
        return using_mok != 0 || kitty_protocol_state == KKPS_ENABLED;
    }

    int handle_mapping(IntPtr keylenp, IntPtr timedout, IntPtr mapdepth) {
        S_mapblock mp = null;
        S_mapblock mp2 = null;
        S_mapblock mp_match = null;
        int mp_match_len = 0;
        int max_mlen = 0;
        int want_termcode = 0;
        int tb_c1 = 0;
        int mlen = 0;
        int keylen = 0;
        boolean i = false;
        int local_State = 0;
        boolean is_plug_map = false;
        boolean in_osc = false;
        int c2 = 0;
        BytePtr[] p1 = new BytePtr[1];
        BytePtr p2 = null;
        BytePtr s = null;
        int n = 0;
        BytePtr t2 = null;
        int save_keylen = 0;
        BytePtr map_str = null;
        int noremap = 0;
        mp = null;
        mp_match_len = 0;
        max_mlen = 0;
        want_termcode = 0;
        keylen = keylenp.get();
        local_State = get_real_state();
        is_plug_map = false;
        in_osc = in_osc_sequence();
        if (!in_osc && typebuf.tb_len >= 3 && (typebuf.tb_buf.at(typebuf.tb_off) & 0xff) == 128 && (typebuf.tb_buf.at(typebuf.tb_off + 1) & 0xff) == KS_EXTRA && typebuf.tb_buf.at(typebuf.tb_off + 2) == KE_PLUG) {
            is_plug_map = true;
        }
        tb_c1 = typebuf.tb_buf.at(typebuf.tb_off) & 0xff;
        if (!in_osc && no_mapping == 0 && is_maphash_valid() != 0 && (no_zero_mapping == 0 || tb_c1 != '0') && (typebuf.tb_maplen == 0 || is_plug_map || (p_remap[0] != 0 && (typebuf.tb_noremap.at(typebuf.tb_off) & 0xff & (RM_NONE | RM_ABBR)) == 0)) && !(p_paste[0] != 0 && (State & (MODE_INSERT | MODE_CMDLINE)) != 0) && !(State == (8192 | MODE_NORMAL) && (tb_c1 == CAR || tb_c1 == ' ')) && State != MODE_ASKMORE && State != MODE_CONFIRM) {
            mp = get_buf_maphash_list(local_State, tb_c1);
            mp2 = get_maphash_list(local_State, tb_c1);
            if (mp == null) {
                mp = mp2;
                mp2 = null;
            }
            mp_match = null;
            mp_match_len = 0;
            for (;;) {
                if (!(mp != null)) {
                    break;
                }
                c1: {
                    if ((mp.m_keys.at(0) & 0xff) == tb_c1 && (mp.m_mode & local_State) != 0 && !(mp.m_simplified && key_protocol_enabled() && typebuf.tb_maplen == 0 && (typebuf.tb_noremap.at(typebuf.tb_off) & 0xff & RM_SIMPLIFIED) == 0)) {
                        mlen = 1;
                        for (; mlen < typebuf.tb_len; mlen++) {
                            c2 = typebuf.tb_buf.at(typebuf.tb_off + mlen) & 0xff;
                            if ((mp.m_keys.at(mlen) & 0xff) != c2) {
                                break;
                            }
                        }
                        p1[0] = mp.m_keys;
                        p2 = mb_unescape(new Ptr<BytePtr>(p1, 0));
                        if (p2 != null && (int) mb_bytelen_tab[tb_c1] > utfc_ptr2len(p2)) {
                            mlen = 0;
                        }
                        keylen = mp.m_keylen;
                        if (mlen == keylen || (mlen == typebuf.tb_len && typebuf.tb_len < keylen)) {
                            s = typebuf.tb_noremap.add(typebuf.tb_off);
                            if ((s.get() & 0xff & ~RM_SIMPLIFIED) == RM_SCRIPT && ((mp.m_keys.at(0) & 0xff) != 128 || (mp.m_keys.at(1) & 0xff) != KS_EXTRA || mp.m_keys.at(2) != KE_SNR)) {
                                break c1;
                            }
                            n = mlen;
                            for (;;) {
                                n--;
                                if (!(n >= 0)) {
                                    break;
                                }
                                t2 = s;
                                s = s.add(1);
                                if ((t2.get() & 0xff & (RM_NONE | RM_ABBR)) != 0) {
                                    break;
                                }
                            }
                            if (!is_plug_map && n >= 0) {
                                break c1;
                            }
                            if (keylen > typebuf.tb_len) {
                                if (timedout.get() == 0 && !(mp_match != null && mp_match.m_nowait != 0)) {
                                    keylen = -2;
                                    break;
                                }
                            } else if (keylen > mp_match_len) {
                                mp_match = mp;
                                mp_match_len = keylen;
                            }
                        } else {
                            if (max_mlen < mlen) {
                                max_mlen = mlen;
                                want_termcode = (mp.m_keys.at(mlen) & 0xff) == 128 ? 1 : 0;
                            } else if (max_mlen == mlen && (mp.m_keys.at(mlen) & 0xff) == 128) {
                                want_termcode = 1;
                            }
                            if (Integer.compareUnsigned((mp.m_keys.at(mlen) & 0xff) - 'A', 26) < 0) {
                                want_termcode = 1;
                            }
                        }
                    }
                }
                if (mp.m_next[0] == null) {
                    mp = mp2;
                    mp2 = null;
                } else {
                    mp = mp.m_next[0];
                }
            }
            if (keylen != -2 && mp_match != null) {
                mp = mp_match;
                keylen = mp_match_len;
            }
        }
        if (!in_osc && p_pt[0].get() != NUL && mp == null && (State & (MODE_INSERT | MODE_NORMAL)) != 0) {
            mlen = 0;
            for (; (mlen < typebuf.tb_len) && p_pt[0].at(mlen) != 0; mlen++) {
                if ((p_pt[0].at(mlen) & 0xff) != (typebuf.tb_buf.at(typebuf.tb_off + mlen) & 0xff)) {
                    break;
                }
            }
            if (p_pt[0].at(mlen) == NUL) {
                if (mlen > typebuf.tb_maplen) {
                    gotchars(typebuf.tb_buf.add(typebuf.tb_off).add(typebuf.tb_maplen), mlen - typebuf.tb_maplen);
                }
                del_typebuf(mlen, 0);
                set_option_value_give_err(BytePtr.lit("paste"), (long) (p_paste[0] == 0 ? 1 : 0), null, 0);
                if ((State & MODE_INSERT) == 0) {
                    msg_col = 0;
                    msg_row = (int) (Rows[0] - 1L);
                    msg_clr_eos();
                }
                status_redraw_all();
                redraw_statuslines();
                showmode();
                setcursor();
                keylenp.put(keylen);
                return map_result_retry;
            }
            if (mlen == typebuf.tb_len) {
                keylen = -1;
            } else if (max_mlen < mlen) {
                max_mlen = mlen + 1;
            }
        }
        if (in_osc || ((mp == null || max_mlen + want_termcode > mp_match_len || (mp_match_len == 1 && mp.m_keys.get() == ESC && timedout.get() == 0)) && keylen != -2)) {
            save_keylen = keylen;
            if (in_osc || no_mapping == 0 || allow_keys != 0) {
                if (in_osc || ((typebuf.tb_maplen == 0 || (p_remap[0] != 0 && (typebuf.tb_noremap.at(typebuf.tb_off) & 0xff & ~RM_SIMPLIFIED) == RM_YES)) && timedout.get() == 0)) {
                    keylen = check_termcode(max_mlen + 1, null, 0, null);
                } else {
                    keylen = 0;
                }
                if (keylen == 0 && save_keylen == -1 && timedout.get() == 0) {
                    keylen = -1;
                }
                if (keylen == 0 && no_reduce_keys == 0) {
                    keylen = check_simplify_modifier(max_mlen + 1);
                    if (keylen < 0) {
                        return map_result_fail;
                    }
                }
                if (keylen < 0 && typebuf.tb_len == typebuf.tb_maplen) {
                    keylen = 0;
                }
            } else {
                keylen = 0;
            }
            if (keylen == 0) {
                if (mp == null) {
                    keylenp.put(keylen);
                    return map_result_get;
                }
            }
            if (keylen > 0) {
                keylenp.put(keylen);
                return map_result_retry;
            }
            if (mp == null || keylen < 0) {
                keylen = -1;
            } else {
                keylen = mp_match_len;
            }
        }
        if (keylen >= 0 && keylen <= typebuf.tb_len) {
            if (keylen > typebuf.tb_maplen) {
                gotchars(typebuf.tb_buf.add(typebuf.tb_off).add(typebuf.tb_maplen), keylen - typebuf.tb_maplen);
            }
            cmd_silent = typebuf.tb_silent > 0 ? 1 : 0;
            del_typebuf(keylen, 0);
            mapdepth.put(mapdepth.get() + 1);
            if ((long) mapdepth.get() >= p_mmd[0]) {
                emsg(gettext_(new BytePtr(e_recursive_mapping, 0)));
                if ((State & MODE_CMDLINE) != 0) {
                    redrawcmdline();
                } else {
                    setcursor();
                }
                flush_buffers(FLUSH_MINIMAL);
                mapdepth.put(0);
                keylenp.put(keylen);
                return map_result_fail;
            }
            if (VIsual_active != 0 && VIsual_select != 0 && (mp.m_mode & MODE_VISUAL) != 0) {
                VIsual_select = FALSE;
                ins_typebuf(BytePtr.lit("\200\365X"), -1, 0, true, FALSE);
            }
            map_str = mp.m_str;
            if (map_str == null) {
                i = false;
            } else {
                if (mp.m_noremap != REMAP_YES) {
                    noremap = mp.m_noremap;
                } else if (musl_strncmp(map_str, mp.m_keys, (long) keylen) == 0 || (mp.m_alt != null && musl_strncmp(map_str, mp.m_alt.m_keys, (long) mp.m_alt.m_keylen) == 0)) {
                    noremap = -3;
                } else {
                    noremap = REMAP_YES;
                }
                i = ins_typebuf(map_str, noremap, 0, true, cmd_silent != 0 || mp.m_silent != 0 ? 1 : 0);
            }
            keylenp.put(keylen);
            if ((i ? 1 : 0) == FAIL) {
                return map_result_fail;
            }
            return map_result_retry;
        }
        keylenp.put(keylen);
        return map_result_nomatch;
    }

    void vungetc(int c) {
        old_char = c;
        old_mod_mask = mod_mask[0];
        old_KeyStuffed = KeyStuffed;
    }

    void check_end_reg_executing(boolean advance) {
        if (reg_executing != 0 && (typebuf.tb_maplen == 0 || pending_end_reg_executing != 0)) {
            if (advance) {
                reg_executing = 0;
                pending_end_reg_executing = FALSE;
            } else {
                pending_end_reg_executing = TRUE;
            }
        }
    }

    int vgetorpeek(boolean advance) {
        int c = 0;
        int[] timedout = new int[1];
        int[] mapdepth = new int[1];
        boolean mode_deleted = false;
        int new_wcol = 0;
        int new_wrow = 0;
        int n = 0;
        int old_wcol = 0;
        int old_wrow = 0;
        int wait_tb_len = 0;
        long wait_time = 0;
        int[] keylen = new int[1];
        int showcmd_idx = 0;
        int result = 0;
        boolean t1 = false;
        int col = 0;
        BytePtr ptr = null;
        T_chartabsize_T cts = new T_chartabsize_T();
        boolean showing_partial = false;
        int t2 = 0;
        int t3 = 0;
        timedout[0] = FALSE;
        mapdepth[0] = 0;
        mode_deleted = false;
        if (vgetc_busy > 0 && ex_normal_busy == 0) {
            return NUL;
        }
        vgetc_busy++;
        if (advance) {
            KeyStuffed = FALSE;
        }
        init_typebuf();
        start_stuff();
        check_end_reg_executing(advance);
        do {
            if (typeahead_char != 0) {
                c = typeahead_char;
                if (advance) {
                    typeahead_char = 0;
                }
            } else {
                c = read_readbuffers(advance);
            }
            if (c != NUL && got_int == 0) {
                if (advance) {
                    KeyStuffed = TRUE;
                }
                if (typebuf.tb_no_abbr_cnt == 0) {
                    typebuf.tb_no_abbr_cnt = 1;
                }
            } else {
                for (;;) {
                    keylen[0] = 0;
                    check_end_reg_executing(advance);
                    if (typebuf.tb_maplen != 0) {
                        line_breakcheck();
                    } else {
                        ui_breakcheck();
                    }
                    if (got_int != 0) {
                        c = inchar(typebuf.tb_buf, typebuf.tb_buflen - 1, 0L);
                        if ((c != 0 || typebuf.tb_maplen != 0) && (State & (MODE_INSERT | MODE_CMDLINE)) != 0) {
                            c = ESC;
                        } else {
                            c = Ctrl_C;
                        }
                        flush_buffers(FLUSH_INPUT);
                        if (advance) {
                            typebuf.tb_buf.put((byte) c);
                            gotchars(typebuf.tb_buf, 1);
                        }
                        cmd_silent = FALSE;
                        break;
                    } else if (typebuf.tb_len > 0) {
                        result = handle_mapping(new IntPtr(keylen, 0), new IntPtr(timedout, 0), new IntPtr(mapdepth, 0));
                        if (result == map_result_retry) {
                            continue;
                        }
                        if (result == map_result_fail) {
                            c = -1;
                            break;
                        }
                        if (result == map_result_get) {
                            c = typebuf.tb_buf.at(typebuf.tb_off) & 0xff;
                            if (advance) {
                                cmd_silent = typebuf.tb_silent > 0 ? 1 : 0;
                                if (typebuf.tb_maplen > 0) {
                                    KeyTyped = FALSE;
                                } else {
                                    KeyTyped = TRUE;
                                    gotchars(typebuf.tb_buf.add(typebuf.tb_off), 1);
                                }
                                KeyNoremap = typebuf.tb_noremap.at(typebuf.tb_off) & 0xff & ~RM_SIMPLIFIED;
                                del_typebuf(1, 0);
                            }
                            break;
                        }
                    }
                    c = 0;
                    new_wcol = curwin.w_wcol;
                    new_wrow = curwin.w_wrow;
                    t1 = advance && typebuf.tb_len == 1 && typebuf.tb_buf.at(typebuf.tb_off) == ESC && no_mapping == 0 && kitty_protocol_state != KKPS_ENABLED && ex_normal_busy == 0 && typebuf.tb_maplen == 0 && (State & MODE_INSERT) != 0 && (p_timeout[0] != 0 || (keylen[0] == -1 && p_ttimeout[0] != 0));
                    if (t1) {
                        c = inchar(typebuf.tb_buf.add(typebuf.tb_off).add(typebuf.tb_len), 3, 25L);
                        t1 = c == 0;
                    }
                    if (t1) {
                        col = 0;
                        if (mode_displayed != 0) {
                            unshowmode(true);
                            mode_deleted = true;
                        }
                        validate_cursor();
                        old_wcol = curwin.w_wcol;
                        old_wrow = curwin.w_wrow;
                        if (curwin.w_cursor.col[0] != 0) {
                            if (curwin.w_wcol > 0) {
                                if (did_ai != 0 && skipwhite(ml_get_curline().add(curwin.w_cursor.col[0])).get() == NUL) {
                                    curwin.w_wcol = 0;
                                    ptr = ml_get_curline();
                                    init_chartabsize_arg(cts, curwin, curwin.w_cursor.lnum[0], 0, ptr, ptr);
                                    while (cts.cts_ptr.lt(ptr.add(curwin.w_cursor.col[0]))) {
                                        if (!(cts.cts_ptr.get() == ' ' || cts.cts_ptr.get() == '\t')) {
                                            curwin.w_wcol = cts.cts_vcol;
                                        }
                                        cts.cts_vcol += lbr_chartabsize(cts);
                                        cts.cts_ptr = cts.cts_ptr.add(utfc_ptr2len(cts.cts_ptr));
                                    }
                                    curwin.w_wrow = curwin.w_cline_row + curwin.w_wcol / curwin.w_width;
                                    curwin.w_wcol %= curwin.w_width;
                                    curwin.w_wcol += curwin_col_off();
                                    col = 0;
                                } else {
                                    curwin.w_wcol--;
                                    col = curwin.w_cursor.col[0] - 1;
                                }
                            } else if (curwin.w_onebuf_opt.wo_wrap[0] != 0 && curwin.w_wrow != 0) {
                                curwin.w_wrow--;
                                curwin.w_wcol = curwin.w_width - 1;
                                col = curwin.w_cursor.col[0] - 1;
                            }
                            if (col > 0 && curwin.w_wcol > 0) {
                                ptr = ml_get_curline();
                                col -= utf_head_off(ptr, ptr.add(col));
                                if (utf_ptr2cells(ptr.add(col)) > 1) {
                                    curwin.w_wcol--;
                                }
                            }
                        }
                        setcursor();
                        out_flush();
                        new_wcol = curwin.w_wcol;
                        new_wrow = curwin.w_wrow;
                        curwin.w_wcol = old_wcol;
                        curwin.w_wrow = old_wrow;
                    }
                    if (c < 0) {
                        continue;
                    }
                    n = 1;
                    for (; n <= c; n++) {
                        typebuf.tb_noremap.set(typebuf.tb_off + n, (byte) RM_YES);
                    }
                    typebuf.tb_len += c;
                    if (typebuf.tb_len >= typebuf.tb_maplen + MAXMAPLEN) {
                        timedout[0] = TRUE;
                        continue;
                    }
                    if (ex_normal_busy > 0) {
                        if (typebuf.tb_len > 0) {
                            timedout[0] = TRUE;
                            continue;
                        }
                        if (p_im[0] != 0 && (State & MODE_INSERT) != 0) {
                            c = Ctrl_L;
                        } else if ((State & MODE_CMDLINE) != 0) {
                            c = Ctrl_C;
                        } else {
                            c = ESC;
                        }
                        typebuf.tb_no_abbr_cnt = 0;
                        break;
                    }
                    if (((State & MODE_INSERT) != 0 || p_lz[0] != 0) && (State & MODE_CMDLINE) == 0 && advance && must_redraw != 0 && need_wait_return == 0) {
                        update_screen(0);
                        setcursor();
                    }
                    showcmd_idx = 0;
                    showing_partial = false;
                    if (typebuf.tb_len > 0 && advance) {
                        if ((State & (MODE_NORMAL | MODE_INSERT)) != 0 && State != (8192 | MODE_NORMAL)) {
                            if ((State & MODE_INSERT) != 0 && ptr2cells(typebuf.tb_buf.add(typebuf.tb_off).add(typebuf.tb_len).add(-1)) == 1) {
                                edit_putchar(typebuf.tb_buf.at(typebuf.tb_off + typebuf.tb_len - 1) & 0xff, false);
                                setcursor();
                                showing_partial = true;
                            }
                            old_wcol = curwin.w_wcol;
                            old_wrow = curwin.w_wrow;
                            curwin.w_wcol = new_wcol;
                            curwin.w_wrow = new_wrow;
                            push_showcmd();
                            if (typebuf.tb_len > SHOWCMD_COLS) {
                                showcmd_idx = typebuf.tb_len - SHOWCMD_COLS;
                            }
                            while (showcmd_idx < typebuf.tb_len) {
                                t2 = showcmd_idx;
                                showcmd_idx++;
                                add_byte_to_showcmd(typebuf.tb_buf.at(typebuf.tb_off + t2));
                            }
                            curwin.w_wcol = old_wcol;
                            curwin.w_wrow = old_wrow;
                        }
                        if ((State & MODE_CMDLINE) != 0 && get_cmdline_info().cmdbuff != null && ptr2cells(typebuf.tb_buf.add(typebuf.tb_off).add(typebuf.tb_len).add(-1)) == 1) {
                            putcmdline(typebuf.tb_buf.at(typebuf.tb_off + typebuf.tb_len - 1) & 0xff, FALSE);
                            showing_partial = true;
                        }
                    }
                    if (typebuf.tb_len == 0) {
                        timedout[0] = FALSE;
                    }
                    if (advance) {
                        if (typebuf.tb_len == 0 || !(p_timeout[0] != 0 || (p_ttimeout[0] != 0 && keylen[0] == -1))) {
                            wait_time = -1L;
                        } else if (keylen[0] == -1 && p_ttm[0] >= 0L) {
                            wait_time = p_ttm[0];
                        } else {
                            wait_time = p_tm[0];
                        }
                    } else {
                        wait_time = 0L;
                    }
                    wait_tb_len = typebuf.tb_len;
                    c = inchar(typebuf.tb_buf.add(typebuf.tb_off).add(typebuf.tb_len), typebuf.tb_buflen - typebuf.tb_off - typebuf.tb_len - 1, wait_time);
                    if (showcmd_idx != 0) {
                        pop_showcmd();
                    }
                    if (showing_partial) {
                        if ((State & MODE_INSERT) != 0) {
                            edit_unputchar();
                        }
                        if ((State & MODE_CMDLINE) != 0 && get_cmdline_info().cmdbuff != null) {
                            unputcmdline();
                        } else {
                            setcursor();
                        }
                    }
                    if (c < 0) {
                        continue;
                    }
                    if (c == NUL) {
                        if (!advance) {
                            break;
                        }
                        if (wait_tb_len > 0) {
                            timedout[0] = TRUE;
                            continue;
                        }
                    } else {
                        while (typebuf.tb_buf.at(typebuf.tb_off + typebuf.tb_len) != NUL) {
                            t3 = typebuf.tb_len;
                            typebuf.tb_len++;
                            typebuf.tb_noremap.set(typebuf.tb_off + t3, (byte) RM_YES);
                        }
                    }
                }
            }
        } while ((c < 0 && c != K_CANCEL) || (advance && c == NUL));
        if (advance && p_smd[0] != 0 && msg_silent == 0 && (State & MODE_INSERT) != 0) {
            if (c == ESC && !mode_deleted && no_mapping == 0 && mode_displayed != 0) {
                if (typebuf.tb_len != 0 && KeyTyped == 0) {
                    redraw_cmdline = TRUE;
                } else {
                    unshowmode(false);
                }
            } else if (c != ESC && mode_deleted) {
                if (typebuf.tb_len != 0 && KeyTyped == 0) {
                    redraw_cmdline = TRUE;
                } else {
                    showmode();
                }
            }
        }
        if (timedout[0] != 0 && c == ESC) {
            gotchars_ignore();
        }
        vgetc_busy--;
        return c;
    }

    int inchar(BytePtr buf, int maxlen, long wait_time) {
        int len = 0;
        int tb_change_cnt = 0;
        byte[] dum = new byte[154];
        boolean t1 = false;
        len = 0;
        tb_change_cnt = typebuf.tb_change_cnt;
        if (wait_time == -1L || wait_time > 100L) {
            cursor_on();
            out_flush_cursor(false, false);
        }
        if (State != (8192 | MODE_NORMAL)) {
            did_outofmem_msg = FALSE;
        }
        undo_off = FALSE;
        if (got_int != 0) {
            for (;;) {
                len = ui_inchar(new BytePtr(dum, 0), MAXMAPLEN * 3 + 3, 0L, 0);
                if (len == 0 || (len == 1 && dum[0] == Ctrl_C)) {
                    break;
                }
            }
            return FALSE;
        }
        if (wait_time == -1L || wait_time > 10L) {
            out_flush();
        }
        len = ui_inchar(buf, maxlen / 3, wait_time, tb_change_cnt);
        if (typebuf_changed(tb_change_cnt)) {
            return 0;
        }
        t1 = len > 0;
        if (t1) {
            typebuf.tb_change_cnt++;
            t1 = typebuf.tb_change_cnt == 0;
        }
        if (t1) {
            typebuf.tb_change_cnt = 1;
        }
        return fix_input_buffer(buf, len);
    }

    int fix_input_buffer(BytePtr buf, int len) {
        int i = 0;
        BytePtr p = null;
        p = buf;
        i = len;
        for (;;) {
            i--;
            if (!(i >= 0)) {
                break;
            }
            if (p.at(0) == NUL || ((p.at(0) & 0xff) == 128 && (i < 2 || (p.at(1) & 0xff) != KS_EXTRA || (p.at(2) != KE_CURSORHOLD && p.at(2) != KE_COMPLETE_DELAY)))) {
                Rt.memmove(p.add(3), p.add(1), (long) i);
                p.set(2, (byte) ((p.at(0) & 0xff) == 128 || p.at(0) == NUL ? 'X' : (-(p.at(0) & 0xff) >>> 8) & 255));
                p.set(1, (byte) ((p.at(0) & 0xff) == 128 ? KS_SPECIAL : (p.at(0) == NUL ? KS_ZERO : -(p.at(0) & 0xff) & 255)));
                p.set(0, (byte) -128);
                p = p.add(2);
                len += 2;
            }
            p = p.add(1);
        }
        p.put((byte) NUL);
        return len;
    }

    boolean input_available() {
        return !vim_is_input_buf_empty();
    }

    BytePtr getcmdkeycmd(int promptc, int indent, int do_concat) {
        S_growarray line_ga = new S_growarray();
        int c1 = 0;
        int c2 = 0;
        int cmod = 0;
        boolean aborted = false;
        c1 = -1;
        cmod = 0;
        aborted = false;
        ga_init2(line_ga, 1L, 32);
        no_mapping++;
        got_int = FALSE;
        while (c1 != NUL && !aborted) {
            if (!ga_grow(line_ga, 32)) {
                aborted = true;
                break;
            }
            if (vgetorpeek(false) == NUL) {
                emsg(gettext_(new BytePtr(e_cmd_mapping_must_end_with_cr, 0)));
                aborted = true;
                break;
            }
            c1 = vgetorpeek(true);
            if (c1 == 128) {
                c1 = vgetorpeek(true);
                c2 = vgetorpeek(true);
                if (c1 == KS_MODIFIER) {
                    cmod = c2;
                    continue;
                }
                c1 = c1 == KS_SPECIAL ? 128 : (c1 == KS_ZERO ? -(KS_ZERO + ('X' << 8)) : -(c1 + (c2 << 8)));
                if (c1 == K_ESC) {
                    c1 = ESC;
                }
            }
            if (got_int != 0) {
                aborted = true;
            } else if (c1 == '\r' || c1 == '\n') {
                c1 = NUL;
            } else if (c1 == ESC) {
                aborted = true;
            } else if (c1 == K_COMMAND || c1 == K_SCRIPT_COMMAND) {
                emsg(gettext_(new BytePtr(e_cmd_mapping_must_end_with_cr_before_second_cmd, 0)));
                aborted = true;
            } else if (c1 == K_SNR) {
                ga_concat_len(line_ga, BytePtr.lit("<SNR>"), 5L);
            } else {
                if (cmod != 0) {
                    ga_append(line_ga, 128);
                    ga_append(line_ga, KS_MODIFIER);
                    ga_append(line_ga, cmod);
                }
                if (c1 < 0) {
                    ga_append(line_ga, 128);
                    ga_append(line_ga, c1 == 128 ? KS_SPECIAL : (c1 == NUL ? KS_ZERO : -c1 & 255));
                    ga_append(line_ga, c1 == 128 || c1 == NUL ? 'X' : (-c1 >>> 8) & 255);
                } else {
                    ga_append(line_ga, c1);
                }
            }
            cmod = 0;
        }
        no_mapping--;
        if (aborted) {
            ga_clear(line_ga);
        }
        return GA_BytePtr(line_ga);
    }

    boolean do_cmdkey_command(int key, int flags) {
        boolean res = false;
        res = do_cmdline(null, fp_getcmdkeycmd, flags);
        return res;
    }

    void init_highlight(boolean both, boolean reset) {
        int i = 0;
        Ptr<BytePtr> pp = null;
        if (both) {
            init_highlight_had_both = true;
            pp = new Ptr<BytePtr>(highlight_init_both, 0);
            i = 0;
            for (; pp.at(i) != null; i++) {
                do_highlight(pp.at(i), reset, true);
            }
        } else if (!init_highlight_had_both) {
            return;
        }
        if (p_bg[0].get() == 'l') {
            pp = new Ptr<BytePtr>(highlight_init_light, 0);
        } else {
            pp = new Ptr<BytePtr>(highlight_init_dark, 0);
        }
        i = 0;
        for (; pp.at(i) != null; i++) {
            do_highlight(pp.at(i), reset, true);
        }
        if (t_colors < 8) {
            do_highlight(BytePtr.lit("Visual term=reverse cterm=reverse ctermbg=NONE ctermfg=NONE"), false, true);
        }
        if (t_colors <= 8) {
            if (p_bg[0].get() == 'l') {
                do_highlight(BytePtr.lit("Search ctermfg=black"), false, true);
            }
        }
        resolve_fallback_fg_to_rgb();
        resolve_fallback_bg_to_rgb();
    }

    int lookup_color(int idx, boolean foreground, IntPtr boldp) {
        int color = 0;
        BytePtr p = null;
        color = color_numbers_16[idx];
        if (color < 0) {
            return -1;
        }
        if (t_colors == 8) {
            color = color_numbers_8[idx];
            if (foreground) {
                if ((color & 8) != 0) {
                    boldp.put(TRUE);
                } else {
                    boldp.put(FALSE);
                }
            }
            color &= 7;
        } else if (t_colors == 16 || t_colors == 88 || t_colors >= 256) {
            if (term_strings[KS_CAF].get() != NUL) {
                p = term_strings[KS_CAF];
            } else {
                p = term_strings[KS_CSF];
            }
            if (p.get() != NUL && (t_colors > 256 || p.add((int) musl_strlen(p)).add(-1).get() == 'm')) {
                if (t_colors == 88) {
                    color = color_numbers_88[idx];
                } else if (t_colors >= 256) {
                    color = color_numbers_256[idx];
                } else {
                    color = color_numbers_8[idx];
                }
            }
        }
        return color;
    }

    void highlight_group_link(BytePtr from_hg, int from_len, BytePtr to_hg, int to_len, boolean dodefault, boolean forceit, boolean init) {
        int from_id = 0;
        int to_id = 0;
        T_hl_group_T hlgroup = null;
        hlgroup = null;
        from_id = syn_check_group(from_hg, from_len);
        if (musl_strncmp(to_hg, BytePtr.lit("NONE"), 4L) == 0) {
            to_id = 0;
        } else {
            to_id = syn_check_group(to_hg, to_len);
        }
        if (from_id > 0) {
            hlgroup = GA_Ptr_T_hl_group_T(highlight_ga).at(from_id - 1);
            if (dodefault && (forceit || hlgroup.sg_deflink == 0)) {
                hlgroup.sg_deflink = to_id;
            }
        }
        if (from_id > 0 && (!init || hlgroup.sg_set == 0)) {
            if (to_id > 0 && !forceit && !init && hl_has_settings(from_id - 1, dodefault)) {
                if (GA_Ptr_T_estack_T(exestack).at(exestack.ga_len - 1).es_name == null && !dodefault) {
                    emsg(gettext_(new BytePtr(e_group_has_settings_highlight_link_ignored, 0)));
                }
            } else if (hlgroup.sg_link != to_id || hlgroup.sg_cleared) {
                if (!init) {
                    hlgroup.sg_set |= SG_LINK;
                }
                hlgroup.sg_link = to_id;
                hlgroup.sg_cleared = false;
                redraw_all_later(UPD_SOME_VALID);
                need_highlight_changed = TRUE;
            }
        }
    }

    void highlight_reset_all() {
        int idx = 0;
        restore_cterm_colors();
        idx = 0;
        for (; idx < highlight_ga.ga_len; idx++) {
            highlight_clear(idx);
        }
        init_highlight(true, true);
        highlight_changed();
        redraw_later_clear();
    }

    boolean highlight_set_termgui_attr(int idx, BytePtr key, BytePtr arg, boolean init) {
        int attr = 0;
        long off = 0;
        T_keyvalue_T target = new T_keyvalue_T();
        Ptr<T_keyvalue_T> entry = null;
        attr = 0;
        off = 0L;
        target.key = 0;
        target.value.length = 0L;
        while (arg.at((int) off) != NUL) {
            target.value.string[0] = arg.add((int) off);
            entry = keyvalue_bsearch(target, new Ptr<T_keyvalue_T>(highlight_tab, 0), 13L, fp_cmp_keyvalue_value_ni);
            if (entry == null) {
                vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(new BytePtr(e_illegal_value_str, 0)), arg);
                emsg(iobuff_or(gettext_(new BytePtr(e_illegal_value_str, 0))));
                return false;
            }
            attr |= entry.get().key;
            off += entry.get().value.length;
            if (arg.at((int) off) == ',') {
                off++;
            }
        }
        if (key.get() == 'T') {
            if (!init || (GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_set & SG_TERM) == 0) {
                if (!init) {
                    GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_set |= SG_TERM;
                }
                GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_term = attr;
            }
        } else if (key.get() == 'C') {
            if (!init || (GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_set & SG_CTERM) == 0) {
                if (!init) {
                    GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_set |= SG_CTERM;
                }
                GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_cterm = attr;
                GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_cterm_bold = false;
            }
        }
        return true;
    }

    void hl_set_ctermfg_normal_group(int color, int bold) {
        cterm_normal_fg_color = color + 1;
        cterm_normal_fg_bold = bold;
        set_must_redraw(UPD_CLEAR);
        if (termcap_active != 0 && color >= 0) {
            term_fg_color(color);
        }
    }

    void highlight_set_ctermfg(int idx, int color, boolean is_normal_group) {
        GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_cterm_fg = color + 1;
        if (is_normal_group) {
            hl_set_ctermfg_normal_group(color, GA_Ptr_T_hl_group_T(highlight_ga).at(idx).sg_cterm & HL_BOLD);
        }
    }

    void hl_set_ctermbg_normal_group(int color) {
        int dark = 0;
        cterm_normal_bg_color = color + 1;
        set_must_redraw(UPD_CLEAR);
        if (color >= 0) {
            dark = -1;
            if (termcap_active != 0) {
                term_bg_color(color);
            }
            if (t_colors < 16) {
                dark = color == 0 || color == 4 ? 1 : 0;
            } else if (color < 16) {
                dark = color < 7 || color == 8 ? 1 : 0;
            }
            if (dark != -1 && dark != (p_bg[0].get() == 'd' ? 1 : 0) && !option_was_set(BytePtr.lit("bg"))) {
                set_option_value_give_err(BytePtr.lit("bg"), 0L, dark != 0 ? BytePtr.lit("dark") : BytePtr.lit("light"), 0);
                reset_option_was_set(BytePtr.lit("bg"));
            }
        }
    }

