    int hl_combine_attr(int char_attr, int prim_attr) {
        S_attr_entry char_aep = null;
        S_attr_entry prim_aep = null;
        S_attr_entry new_en = new S_attr_entry();
        char_aep = null;
        if (char_attr == 0) {
            return prim_attr;
        }
        if (char_attr <= HL_ALL && prim_attr <= HL_ALL) {
            return ((prim_attr & HL_NOCOMBINE) != 0 ? prim_attr : char_attr) | prim_attr;
        }
        if (t_colors > 1) {
            if (char_attr > HL_ALL) {
                char_aep = syn_cterm_attr2entry(char_attr);
            }
            if (char_aep != null) {
                new_en.set(char_aep);
            } else {
                new_en.zero();
                if (char_attr <= HL_ALL) {
                    new_en.ae_attr = (short) char_attr;
                }
            }
            if (prim_attr <= HL_ALL) {
                new_en.ae_attr = (short) (((prim_attr & HL_NOCOMBINE) != 0 ? prim_attr : (int) new_en.ae_attr) | prim_attr);
            } else {
                prim_aep = syn_cterm_attr2entry(prim_attr);
                if (prim_aep != null) {
                    new_en.ae_attr = (short) ((((int) prim_aep.ae_attr & HL_NOCOMBINE) != 0 ? (int) prim_aep.ae_attr : (int) new_en.ae_attr) | (int) prim_aep.ae_attr);
                    if ((prim_aep.ae_u.cterm.fg_color & 0xffff) > 0) {
                        new_en.ae_u.cterm.fg_color = prim_aep.ae_u.cterm.fg_color;
                    }
                    if ((prim_aep.ae_u.cterm.bg_color & 0xffff) > 0) {
                        new_en.ae_u.cterm.bg_color = prim_aep.ae_u.cterm.bg_color;
                    }
                    if ((prim_aep.ae_u.cterm.ul_color & 0xffff) > 0) {
                        new_en.ae_u.cterm.ul_color = prim_aep.ae_u.cterm.ul_color;
                    }
                    if ((prim_aep.ae_u.cterm.font & 0xffff) > 0) {
                        new_en.ae_u.cterm.font = prim_aep.ae_u.cterm.font;
                    }
                }
            }
            return get_attr_entry(cterm_attr_table, new_en);
        }
        if (char_attr > HL_ALL) {
            char_aep = syn_term_attr2entry(char_attr);
        }
        if (char_aep != null) {
            new_en.set(char_aep);
        } else {
            new_en.zero();
            if (char_attr <= HL_ALL) {
                new_en.ae_attr = (short) char_attr;
            }
        }
        if (prim_attr <= HL_ALL) {
            new_en.ae_attr = (short) (((prim_attr & HL_NOCOMBINE) != 0 ? prim_attr : (int) new_en.ae_attr) | prim_attr);
        } else {
            prim_aep = syn_term_attr2entry(prim_attr);
            if (prim_aep != null) {
                new_en.ae_attr = (short) ((((int) prim_aep.ae_attr & HL_NOCOMBINE) != 0 ? (int) prim_aep.ae_attr : (int) new_en.ae_attr) | (int) prim_aep.ae_attr);
                if (prim_aep.ae_u.term.start != null) {
                    new_en.ae_u.term.start = prim_aep.ae_u.term.start;
                    new_en.ae_u.term.stop = prim_aep.ae_u.term.stop;
                }
            }
        }
        return get_attr_entry(term_attr_table, new_en);
    }

    void cterm_idx_to_rgb(int idx, IntPtr r, IntPtr g, IntPtr b) {
        long rgb = 0;
        int n = 0;
        int v = 0;
        if (idx < 0 || idx > 255) {
            b.put(0);
            g.put(b.get());
            r.put(g.get());
            return;
        }
        if (idx < 16) {
            rgb = cterm_color_16[idx];
            r.put((int) ((rgb >>> 16) & 255L));
            g.put((int) ((rgb >>> 8) & 255L));
            b.put((int) (rgb & 255L));
        } else if (idx < 232) {
            n = idx - 16;
            r.put(cterm_idx_to_rgb_cube[n / 36 % 6]);
            g.put(cterm_idx_to_rgb_cube[n / 6 % 6]);
            b.put(cterm_idx_to_rgb_cube[n % 6]);
        } else {
            v = 8 + (idx - 232) * 10;
            b.put(v);
            g.put(b.get());
            r.put(g.get());
        }
    }

    int rgb_to_cterm_idx(int r, int g, int b) {
        int best = 0;
        long best_d = 0;
        int i = 0;
        int n = 0;
        int cr = 0;
        int cg = 0;
        int cb = 0;
        long d = 0;
        int v = 0;
        long d_2 = 0;
        best = 0;
        best_d = -1L;
        i = 16;
        for (; i < 232; i++) {
            n = i - 16;
            cr = rgb_to_cterm_idx_cube[n / 36 % 6];
            cg = rgb_to_cterm_idx_cube[n / 6 % 6];
            cb = rgb_to_cterm_idx_cube[n % 6];
            d = (long) ((cr - r) * (cr - r) + (cg - g) * (cg - g) + (cb - b) * (cb - b));
            if (best_d < 0L || d < best_d) {
                best_d = d;
                best = i;
            }
        }
        i = 232;
        for (; i < 256; i++) {
            v = 8 + (i - 232) * 10;
            d_2 = (long) ((v - r) * (v - r) + (v - g) * (v - g) + (v - b) * (v - b));
            if (d_2 < best_d) {
                best_d = d_2;
                best = i;
            }
        }
        return best;
    }

    boolean resolve_color_to_rgb(int cterm_c, long rgb, IntPtr r, IntPtr g, IntPtr b) {
        if (cterm_c > 0) {
            cterm_idx_to_rgb(cterm_c - 1, r, g, b);
            return true;
        }
        return false;
    }

    long resolve_fallback_color(int cterm_c, long rgb, long default_rgb) {
        int[] red = new int[1];
        int[] green = new int[1];
        int[] blue = new int[1];
        if (!resolve_color_to_rgb(cterm_c, rgb, new IntPtr(red, 0), new IntPtr(green, 0), new IntPtr(blue, 0))) {
            return default_rgb;
        } else {
            return (long) ((red[0] << 16) | (green[0] << 8) | blue[0]);
        }
    }

    void resolve_fallback_fg_to_rgb() {
        long fgcolor_or_gui_fgcolor = 0;
        fgcolor_or_gui_fgcolor = 33554431L;
        fallback_fg_rgb = resolve_fallback_color(cterm_normal_fg_color, fgcolor_or_gui_fgcolor, (long) (p_bg[0].get() == 'l' ? 0 : 16777215));
    }

    void resolve_fallback_bg_to_rgb() {
        long bgcolor_or_gui_bgcolor = 0;
        bgcolor_or_gui_bgcolor = 33554431L;
        fallback_bg_rgb = resolve_fallback_color(cterm_normal_bg_color, bgcolor_or_gui_bgcolor, (long) (p_bg[0].get() == 'l' ? 16777215 : 0));
    }

    int blend_cterm_colors(int popup_c, long popup_rgb, int under_c, long under_rgb, int default_rgb, int blend_val) {
        int[] pr = new int[1];
        int[] pg = new int[1];
        int[] pb = new int[1];
        int[] ur = new int[1];
        int[] ug = new int[1];
        int[] ub = new int[1];
        int r = 0;
        int g = 0;
        int b = 0;
        if (t_colors < 256) {
            return popup_c;
        }
        if (!resolve_color_to_rgb(popup_c, popup_rgb, new IntPtr(pr, 0), new IntPtr(pg, 0), new IntPtr(pb, 0))) {
            return under_c;
        }
        if (blend_val <= 0) {
            return rgb_to_cterm_idx(pr[0], pg[0], pb[0]) + 1;
        }
        if (!resolve_color_to_rgb(under_c, under_rgb, new IntPtr(ur, 0), new IntPtr(ug, 0), new IntPtr(ub, 0))) {
            ur[0] = (default_rgb >> 16) & 255;
            ug[0] = (default_rgb >> 8) & 255;
            ub[0] = default_rgb & 255;
        }
        if (blend_val >= 100) {
            return rgb_to_cterm_idx(ur[0], ug[0], ub[0]) + 1;
        }
        r = pr[0] + (ur[0] - pr[0]) * blend_val / 100;
        g = pg[0] + (ug[0] - pg[0]) * blend_val / 100;
        b = pb[0] + (ub[0] - pb[0]) * blend_val / 100;
        return rgb_to_cterm_idx(r, g, b) + 1;
    }

    int hl_blend_attr_common(int char_attr, int popup_attr, int blend, boolean blend_fg) {
        S_attr_entry char_aep = null;
        S_attr_entry popup_aep = null;
        S_attr_entry new_en = new S_attr_entry();
        S_attr_entry tmp_en = new S_attr_entry();
        long popup_bg_rgb = 0;
        int under_fg = 0;
        long under_fg_rgb = 0;
        int under_bg = 0;
        long under_bg_rgb = 0;
        char_aep = null;
        if (t_colors > 1) {
            if (char_attr > HL_ALL) {
                char_aep = syn_cterm_attr2entry(char_attr);
            }
            if (char_aep != null) {
                new_en.set(char_aep);
            } else {
                new_en.zero();
                if (char_attr <= HL_ALL) {
                    new_en.ae_attr = (short) char_attr;
                }
            }
            if (popup_attr <= HL_ALL) {
                tmp_en.zero();
                tmp_en.ae_attr = (short) popup_attr;
                popup_aep = tmp_en;
                popup_aep.ae_u.cterm.bg_color = (short) cterm_normal_bg_color;
            } else {
                popup_aep = syn_cterm_attr2entry(popup_attr);
            }
            if (popup_aep != null) {
                popup_bg_rgb = 33554431L;
                if ((popup_bg_rgb == 33554431L || popup_bg_rgb == 33554430L) && popup_aep.ae_u.cterm.bg_color == 0) {
                    popup_bg_rgb = fallback_bg_rgb;
                }
                if (!blend_fg) {
                    new_en.ae_attr = popup_aep.ae_attr;
                    if ((popup_aep.ae_u.cterm.fg_color & 0xffff) > 0) {
                        new_en.ae_u.cterm.fg_color = popup_aep.ae_u.cterm.fg_color;
                    } else if (cterm_normal_fg_color > 0) {
                        new_en.ae_u.cterm.fg_color = (short) cterm_normal_fg_color;
                    } else {
                        new_en.ae_u.cterm.fg_color = (short) (p_bg[0].get() == 'l' ? 1 : 16);
                    }
                    new_en.ae_u.cterm.ul_color = popup_aep.ae_u.cterm.ul_color;
                    new_en.ae_u.cterm.font = popup_aep.ae_u.cterm.font;
                } else {
                    under_fg = char_aep != null ? char_aep.ae_u.cterm.fg_color & 0xffff : 0;
                    under_fg_rgb = 33554431L;
                    new_en.ae_u.cterm.fg_color = (short) blend_cterm_colors(popup_aep.ae_u.cterm.bg_color & 0xffff, popup_bg_rgb, under_fg, under_fg_rgb, (int) fallback_fg_rgb, blend);
                }
                under_bg = char_aep != null ? char_aep.ae_u.cterm.bg_color & 0xffff : 0;
                under_bg_rgb = 33554431L;
                new_en.ae_u.cterm.bg_color = (short) blend_cterm_colors(popup_aep.ae_u.cterm.bg_color & 0xffff, popup_bg_rgb, under_bg, under_bg_rgb, (int) fallback_bg_rgb, blend);
            }
            return get_attr_entry(cterm_attr_table, new_en);
        }
        if (char_attr > HL_ALL) {
            char_aep = syn_term_attr2entry(char_attr);
        }
        if (char_aep != null) {
            new_en.set(char_aep);
        } else {
            new_en.zero();
            if (char_attr <= HL_ALL) {
                new_en.ae_attr = (short) char_attr;
            }
        }
        return get_attr_entry(term_attr_table, new_en);
    }

    int hl_blend_attr(int char_attr, int popup_attr, int blend, boolean blend_fg) {
        if (blend >= 100 && blend_fg) {
            return char_attr;
        }
        return hl_blend_attr_common(char_attr, popup_attr, blend, blend_fg);
    }

    int hl_pum_blend_attr(int char_attr, int popup_attr, int blend) {
        return hl_blend_attr_common(char_attr, popup_attr, blend, true);
    }

    int syn_attr2attr(int attr) {
        S_attr_entry aep = null;
        if (t_colors > 1) {
            aep = syn_cterm_attr2entry(attr);
        } else {
            aep = syn_term_attr2entry(attr);
        }
        if (aep == null) {
            return 0;
        }
        return (int) aep.ae_attr;
    }

    S_attr_entry syn_term_attr2entry(int attr) {
        attr -= HL_ALL + 1;
        if (attr >= term_attr_table.ga_len) {
            return null;
        }
        return GA_Ptr_S_attr_entry(term_attr_table).at(attr);
    }

    S_attr_entry syn_cterm_attr2entry(int attr) {
        attr -= HL_ALL + 1;
        if (attr >= cterm_attr_table.ga_len) {
            return null;
        }
        return GA_Ptr_S_attr_entry(cterm_attr_table).at(attr);
    }

    void highlight_list_one(int id) {
        T_hl_group_T sgp = null;
        int didh = 0;
        didh = FALSE;
        sgp = GA_Ptr_T_hl_group_T(highlight_ga).at(id - 1);
        if (message_filtered(sgp.sg_name)) {
            return;
        }
        didh = highlight_list_arg(id, didh, LIST_ATTR, sgp.sg_term, null, BytePtr.lit("term"));
        didh = highlight_list_arg(id, didh, LIST_STRING, 0, sgp.sg_start, BytePtr.lit("start"));
        didh = highlight_list_arg(id, didh, LIST_STRING, 0, sgp.sg_stop, BytePtr.lit("stop"));
        didh = highlight_list_arg(id, didh, LIST_ATTR, sgp.sg_cterm, null, BytePtr.lit("cterm"));
        didh = highlight_list_arg(id, didh, LIST_INT, sgp.sg_cterm_fg, null, BytePtr.lit("ctermfg"));
        didh = highlight_list_arg(id, didh, LIST_INT, sgp.sg_cterm_bg, null, BytePtr.lit("ctermbg"));
        didh = highlight_list_arg(id, didh, LIST_INT, sgp.sg_cterm_ul, null, BytePtr.lit("ctermul"));
        didh = highlight_list_arg(id, didh, LIST_INT, sgp.sg_cterm_font, null, BytePtr.lit("ctermfont"));
        if (sgp.sg_link != 0 && got_int == 0) {
            syn_list_header(didh, 9999, id);
            didh = TRUE;
            msg_puts_attr(BytePtr.lit("links to"), highlight_attr[HLF_D]);
            msg_putchar(' ');
            msg_outtrans(GA_Ptr_T_hl_group_T(highlight_ga).at(GA_Ptr_T_hl_group_T(highlight_ga).at(id - 1).sg_link - 1).sg_name);
        }
        if (didh == 0) {
            highlight_list_arg(id, didh, LIST_STRING, 0, BytePtr.lit("cleared"), BytePtr.lit(""));
        }
    }

    BytePtr highlight_arg_to_string(int type, int iarg, BytePtr sarg, BytePtr buf) {
        long buflen = 0;
        int i = 0;
        if (type == LIST_INT) {
            vim_snprintf(buf, MAX_ATTR_LEN, BytePtr.lit("%d"), iarg - 1);
        } else if (type == LIST_STRING) {
            return sarg;
        } else {
            buf.set(0, (byte) NUL);
            buflen = 0L;
            i = 0;
            for (; i < 13; i++) {
                if ((iarg & highlight_index_tab[i].key) != 0) {
                    if (Long.compareUnsigned(buflen, 0L) > 0) {
                        musl_strcpy(buf.add((int) buflen), BytePtr.lit(","));
                        buflen++;
                    }
                    musl_strcpy(buf.add((int) buflen), highlight_index_tab[i].value.string[0]);
                    buflen += highlight_index_tab[i].value.length;
                    iarg &= ~highlight_index_tab[i].key;
                }
            }
        }
        return buf;
    }

    int highlight_list_arg(int id, int didh, int type, int iarg, BytePtr sarg, BytePtr name) {
        byte[] buf = new byte[120];
        BytePtr ts = null;
        if (got_int != 0) {
            return FALSE;
        }
        if (type == LIST_STRING ? sarg == null : iarg == 0) {
            return didh;
        }
        ts = highlight_arg_to_string(type, iarg, sarg, new BytePtr(buf, 0));
        syn_list_header(didh, (int) ((long) vim_strsize(ts) + musl_strlen(name) + 1L), id);
        didh = TRUE;
        if (got_int == 0) {
            if ((int) name.get() != NUL) {
                msg_puts_attr(name, highlight_attr[HLF_D]);
                msg_puts_attr(BytePtr.lit("="), highlight_attr[HLF_D]);
            }
            msg_outtrans(ts);
        }
        return didh;
    }

    boolean syn_list_header(int did_header, int outlen, int id) {
        int endcol = 0;
        boolean newline = false;
        int name_col = 0;
        endcol = 19;
        newline = true;
        name_col = 0;
        if (did_header == 0) {
            msg_putchar('\n');
            if (got_int != 0) {
                return true;
            }
            msg_outtrans(GA_Ptr_T_hl_group_T(highlight_ga).at(id - 1).sg_name);
            name_col = msg_col;
            endcol = 15;
        } else if (msg_col + outlen + 1 >= cmdline_width) {
            msg_putchar('\n');
            if (got_int != 0) {
                return true;
            }
        } else {
            if (msg_col >= endcol) {
                newline = false;
            }
        }
        if (msg_col >= endcol) {
            endcol = msg_col + 1;
        }
        if (cmdline_width <= endcol) {
            endcol = cmdline_width - 1;
        }
        msg_advance(endcol);
        if (did_header == 0) {
            if (endcol == cmdline_width - 1 && endcol <= name_col) {
                msg_putchar(' ');
            }
            msg_puts_attr(BytePtr.lit("xxx"), syn_id2attr(id));
            msg_putchar(' ');
        }
        return newline;
    }

    void set_hl_attr(int idx) {
        S_attr_entry at_en = new S_attr_entry();
        T_hl_group_T sgp = null;
        sgp = GA_Ptr_T_hl_group_T(highlight_ga).at(idx);
        if (sgp.sg_name_u != null && musl_strcmp(sgp.sg_name_u, BytePtr.lit("NORMAL")) == 0) {
            return;
        }
        if (sgp.sg_start == null && sgp.sg_stop == null) {
            sgp.sg_term_attr = sgp.sg_term;
        } else {
            at_en.ae_attr = (short) sgp.sg_term;
            at_en.ae_u.term.start = sgp.sg_start;
            at_en.ae_u.term.stop = sgp.sg_stop;
            sgp.sg_term_attr = get_attr_entry(term_attr_table, at_en);
        }
        if (sgp.sg_cterm_fg == 0 && sgp.sg_cterm_bg == 0 && sgp.sg_cterm_ul == 0 && sgp.sg_cterm_font == 0) {
            sgp.sg_cterm_attr = sgp.sg_cterm;
        } else {
            at_en.ae_attr = (short) sgp.sg_cterm;
            at_en.ae_u.cterm.fg_color = (short) sgp.sg_cterm_fg;
            at_en.ae_u.cterm.bg_color = (short) sgp.sg_cterm_bg;
            at_en.ae_u.cterm.ul_color = (short) sgp.sg_cterm_ul;
            at_en.ae_u.cterm.font = (short) sgp.sg_cterm_font;
            sgp.sg_cterm_attr = get_attr_entry(cterm_attr_table, at_en);
        }
    }

    int syn_override(int id) {
        int k = 0;
        if (overrides != null && overrides.arr != null) {
            k = 0;
            for (; k < overrides.len; k++) {
                if (overrides.arr.at(k).from == id) {
                    return overrides.arr.at(k).to_;
                }
            }
        }
        return id;
    }

    int syn_name2id_len(BytePtr name, int len) {
        byte[] name_u = new byte[201];
        int i = 0;
        if (len > MAX_SYN_NAME) {
            len = MAX_SYN_NAME;
        }
        Rt.memmove(new BytePtr(name_u, 0), name, (long) len);
        name_u[len] = (byte) NUL;
        vim_strup(new BytePtr(name_u, 0));
        i = 0;
        for (; i < highlight_ga.ga_len; i++) {
            if (musl_strcmp(GA_Ptr_T_hl_group_T(highlight_ga).at(i).sg_name_u, new BytePtr(name_u, 0)) == 0) {
                return i + 1;
            }
        }
        return 0;
    }

    int syn_namen2id(BytePtr linep, int len) {
        return syn_name2id_len(linep, len);
    }

    int syn_check_group(BytePtr pp, int len) {
        int id = 0;
        BytePtr name = null;
        if (len > MAX_SYN_NAME) {
            emsg(gettext_(new BytePtr(e_highlight_group_name_too_long, 0)));
            return 0;
        }
        id = syn_name2id_len(pp, len);
        if (id == 0) {
            name = vim_strnsave(pp, (long) len);
            id = syn_add_group(name);
        }
        return id;
    }

    int syn_add_group(BytePtr name) {
        BytePtr p = null;
        BytePtr name_up = null;
        p = name;
        for (; p.get() != NUL; p = p.add(1)) {
            if (!vim_isprintc(p.get() & 0xff)) {
                emsg(gettext_(new BytePtr(e_unprintable_character_in_group_name, 0)));
                return 0;
            } else if (!(Integer.compareUnsigned((p.get() & 0xff) - 'A', 26) < 0 || Integer.compareUnsigned((p.get() & 0xff) - 'a', 26) < 0 || Integer.compareUnsigned((p.get() & 0xff) - '0', 10) < 0) && p.get() != '_' && p.get() != '.' && p.get() != '-') {
                msg_source(highlight_attr[HLF_W]);
                msg(gettext_(BytePtr.lit("W18: Invalid character in group name")));
                break;
            }
        }
        if (highlight_ga.ga_data == null) {
            highlight_ga.ga_itemsize = 88;
            highlight_ga.ga_growsize = 10;
        }
        if (highlight_ga.ga_len >= MAX_HL_ID) {
            emsg(gettext_(new BytePtr(e_too_many_highlight_and_syntax_groups, 0)));
            return 0;
        }
        if (!ga_grow(highlight_ga, 1)) {
            return 0;
        }
        name_up = vim_strsave(name);
        vim_strup(name_up);
        Rt.zeroStructs(GA_Ptr_T_hl_group_T(highlight_ga).add(highlight_ga.ga_len), 1);
        GA_Ptr_T_hl_group_T(highlight_ga).at(highlight_ga.ga_len).sg_name = name;
        GA_Ptr_T_hl_group_T(highlight_ga).at(highlight_ga.ga_len).sg_name_u = name_up;
        highlight_ga.ga_len++;
        return highlight_ga.ga_len;
    }

    void syn_unadd_group() {
        highlight_ga.ga_len--;
    }

    int syn_id2attr(int hl_id) {
        int attr = 0;
        T_hl_group_T sgp = null;
        hl_id = syn_get_final_id(hl_id);
        sgp = GA_Ptr_T_hl_group_T(highlight_ga).at(hl_id - 1);
        if (t_colors > 1) {
            attr = sgp.sg_cterm_attr;
        } else {
            attr = sgp.sg_term_attr;
        }
        return attr;
    }

    int syn_get_final_id(int hl_id) {
        int count = 0;
        T_hl_group_T sgp = null;
        int tmp = 0;
        if (hl_id > highlight_ga.ga_len || hl_id < 1) {
            return 0;
        }
        count = 100;
        for (;;) {
            count--;
            if (!(count >= 0)) {
                break;
            }
            c1: {
                tmp = hl_id;
                sgp = GA_Ptr_T_hl_group_T(highlight_ga).at(hl_id - 1);
                if (sgp.sg_link == 0 || sgp.sg_link > highlight_ga.ga_len) {
                    break;
                }
                hl_id = syn_override(hl_id);
                if (tmp != hl_id) {
                    break c1;
                }
                hl_id = sgp.sg_link;
            }
        }
        return syn_override(hl_id);
    }

    boolean highlight_changed() {
        int hlf = 0;
        int i = 0;
        BytePtr p = null;
        BytePtr default_hl = null;
        int attr = 0;
        BytePtr end = null;
        int id = 0;
        S_window_S wp = null;
        BytePtr errmsg = null;
        need_highlight_changed = FALSE;
        hlf = 0;
        for (; hlf < HLF_COUNT; hlf++) {
            highlight_attr[hlf] = 0;
            highlight_attr_raw[hlf] = 0;
            highlight_ids[hlf] = 0;
        }
        default_hl = get_highlight_default();
        i = 0;
        for (; i < 2; i++) {
            if (i != 0) {
                if (default_hl != null && p_hl[0] != null && musl_strcmp(default_hl, p_hl[0]) == 0) {
                    continue;
                }
                p = p_hl[0];
            } else {
                p = default_hl;
            }
            if (p == null) {
                continue;
            }
            while (p.get() != 0) {
                hlf = 0;
                for (; hlf < HLF_COUNT; hlf++) {
                    if (hl_flags[hlf] == (p.get() & 0xff)) {
                        break;
                    }
                }
                p = p.add(1);
                if (hlf == HLF_COUNT || p.get() == NUL) {
                    return false;
                }
                attr = 0;
                id = 0;
                for (; (p.get() != 0) && p.get() != ','; p = p.add(1)) {
                    if (p.get() == ' ' || p.get() == '\t') {
                        continue;
                    }
                    if (attr > HL_ALL) {
                        return false;
                    }
                    switch (p.get() & 0xff) {
                        case 'b':
                            attr |= HL_BOLD;
                            break;
                        case 'i':
                            attr |= HL_ITALIC;
                            break;
                        case '-':
                        case 'n':
                            break;
                        case 'r':
                            attr |= HL_INVERSE;
                            break;
                        case 's':
                            attr |= HL_STANDOUT;
                            break;
                        case 'u':
                            attr |= HL_UNDERLINE;
                            break;
                        case 'c':
                            attr |= HL_UNDERCURL;
                            break;
                        case '2':
                            attr |= HL_UNDERDOUBLE;
                            break;
                        case 'd':
                            attr |= HL_UNDERDOTTED;
                            break;
                        case '=':
                            attr |= HL_UNDERDASHED;
                            break;
                        case 't':
                            attr |= HL_STRIKETHROUGH;
                            break;
                        case ':':
                            p = p.add(1);
                            if (attr != 0 || p.get() == NUL) {
                                return false;
                            }
                            end = vim_strchr(p, ',');
                            if (end == null) {
                                end = p.add((int) musl_strlen(p));
                            }
                            id = syn_check_group(p, (int) end.sub(p));
                            if (id == 0) {
                                return false;
                            }
                            attr = syn_id2attr(id);
                            p = end.add(-1);
                            break;
                        default:
                            return false;
                    }
                }
                highlight_attr[hlf] = attr;
                highlight_attr_raw[hlf] = attr;
                highlight_ids[hlf] = id;
                p = skip_to_option_part(p);
            }
        }
        wp = curwin;
        errmsg = update_winhighlight(wp, wp.w_onebuf_opt.wo_whl[0]);
        if (errmsg != null) {
            emsg(gettext_(errmsg));
        }
        return true;
    }

    void update_highlight_overrides(Ptr<T_hl_override_T> old, Ptr<T_hl_override_T> hl_new, int newlen) {
        S_hl_overrides_S set = null;
        if (old == null) {
            return;
        }
        set = overrides;
        for (; set != null; set = set.next) {
            if (Ptr.eq(set.arr, old)) {
                set.arr = hl_new;
                set.len = newlen;
            }
        }
    }

    void set_highlight_attr(Ptr<T_hl_override_T> arr, int len, boolean update_ids) {
        int i = 0;
        T_hl_override_T override = null;
        int hlf = 0;
        int attr = 0;
        int k = 0;
        i = 0;
        for (; i < len; i++) {
            override = arr.at(i);
            hlf = -1;
            if (override.from <= 0) {
                hlf = -override.from;
            } else {
                k = 0;
                for (; k < HLF_COUNT; k++) {
                    if (override.from == highlight_ids[k]) {
                        hlf = k;
                        break;
                    }
                }
                if (hlf == -1) {
                    continue;
                }
            }
            if (update_ids) {
                if (override.to_ <= 0) {
                    if (hlf == -override.to_) {
                        highlight_ids[hlf] = -1;
                    } else {
                        highlight_ids[hlf] = highlight_ids[-override.to_];
                    }
                } else {
                    highlight_ids[hlf] = override.to_;
                }
            } else {
                if (override.to_ <= 0) {
                    attr = highlight_attr[-override.to_];
                } else {
                    attr = syn_id2attr(override.to_);
                }
                highlight_attr[hlf] = attr;
            }
        }
    }

    boolean push_highlight_overrides(Ptr<T_hl_override_T> arr, int len) {
        S_hl_overrides_S set = null;
        if (overrides != null && Ptr.eq(overrides.arr, arr)) {
            return false;
        }
        set = new S_hl_overrides_S();
        set.arr = arr;
        set.len = len;
        set.next = overrides;
        overrides = set;
        Rt.memmove(new IntPtr(set.attr, 0), new IntPtr(highlight_attr, 0), 70);
        Rt.memmove(new IntPtr(highlight_attr, 0), new IntPtr(highlight_attr_raw, 0), 70);
        if (arr != null) {
            set_highlight_attr(arr, len, false);
        }
        return true;
    }

    void pop_highlight_overrides() {
        S_hl_overrides_S set = null;
        set = overrides;
        if (overrides == null) {
            return;
        }
        overrides = set.next;
        Rt.memmove(new IntPtr(highlight_attr, 0), new IntPtr(set.attr, 0), 70);
    }

    Ptr<T_hl_override_T> parse_winhighlight(BytePtr opt, IntPtr len, Ptr<BytePtr> errmsg) {
        BytePtr p = null;
        Ptr<T_hl_override_T> arr = null;
        int i = 0;
        int num = 0;
        int n_colons = 0;
        T_hl_override_T override = null;
        int t1 = 0;
        BytePtr[] fromname = new BytePtr[1];
        BytePtr[] toname = new BytePtr[1];
        BytePtr tmp = null;
        Ptr<BytePtr>[] names = new Ptr[2];
        int[] fromlen = new int[1];
        int[] tolen = new int[1];
        IntPtr[] lens = new IntPtr[2];
        int[] fromid = new int[1];
        int[] toid = new int[1];
        IntPtr[] ids = new IntPtr[2];
        int k = 0;
        BytePtr name = null;
        int nlen = 0;
        int hlf = 0;
        p = opt;
        i = 0;
        num = 1;
        n_colons = 0;
        if (p.get() == NUL) {
            return null;
        }
        while (true) {
            p = vim_strchr(p, ',');
            if (!(p != null)) {
                break;
            }
            p = p.add(1);
            num++;
        }
        p = opt;
        while (true) {
            p = vim_strchr(p, ':');
            if (!(p != null)) {
                break;
            }
            p = p.add(1);
            n_colons++;
        }
        if (num != n_colons) {
            errmsg.put(new BytePtr(e_invalid_argument, 0));
            return null;
        }
        arr = new Ptr<T_hl_override_T>(T_hl_override_T.array(num), 0);
        p = opt;
        while (true) {
            t1 = i;
            i++;
            override = arr.at(t1);
            fromname[0] = p;
            names = new Ptr[2];
            names[0] = new Ptr<BytePtr>(fromname, 0);
            names[1] = new Ptr<BytePtr>(toname, 0);
            lens = new IntPtr[2];
            lens[0] = new IntPtr(fromlen, 0);
            lens[1] = new IntPtr(tolen, 0);
            ids = new IntPtr[2];
            ids[0] = new IntPtr(fromid, 0);
            ids[1] = new IntPtr(toid, 0);
            p = vim_strchr(p, ':');
            if (p == null) {
                errmsg.put(new BytePtr(e_invalid_argument, 0));
                return null;
            }
            fromlen[0] = (int) p.sub(fromname[0]);
            if (fromlen[0] == 0) {
                errmsg.put(new BytePtr(e_invalid_argument, 0));
                return null;
            }
            p = p.add(1);
            if (p.get() == NUL) {
                errmsg.put(new BytePtr(e_invalid_argument, 0));
                return null;
            }
            toname[0] = p;
            tmp = vim_strchr(p, ',');
            if (tmp == null) {
                tolen[0] = (int) musl_strlen(p);
            } else {
                tolen[0] = (int) tmp.sub(toname[0]);
                tmp = tmp.add(1);
                p = tmp;
            }
            if (tolen[0] == 0) {
                errmsg.put(new BytePtr(e_invalid_argument, 0));
                return null;
            }
            k = 0;
            for (; k < 2; k++) {
                name = names[k].get();
                nlen = lens[k].get();
                if (name.get() == '!') {
                    if (nlen != 2) {
                        errmsg.put(new BytePtr(e_invalid_argument, 0));
                        return null;
                    }
                    hlf = 0;
                    for (; hlf < HLF_COUNT; hlf++) {
                        if (hl_flags[hlf] == (name.at(1) & 0xff)) {
                            break;
                        }
                    }
                    if (hlf >= HLF_COUNT) {
                        errmsg.put(new BytePtr(e_invalid_argument, 0));
                        return null;
                    }
                    ids[k].put(-hlf);
                } else {
                    if (syn_check_group(name, nlen) == 0) {
                        errmsg.put(new BytePtr(e_invalid_argument, 0));
                        return null;
                    }
                    ids[k].put(syn_namen2id(name, nlen));
                    if (ids[k].get() == 0) {
                        errmsg.put(new BytePtr(e_invalid_argument, 0));
                        return null;
                    }
                    if (IntPtr.eq(ids[k], new IntPtr(fromid, 0)) && musl_strcmp(GA_Ptr_T_hl_group_T(highlight_ga).at(ids[k].get() - 1).sg_name_u, BytePtr.lit("NORMAL")) == 0) {
                        ids[k].put(-HLF_WIN);
                    }
                }
            }
            override.from = fromid[0];
            override.to_ = toid[0];
            if (tmp == null) {
                break;
            }
        }
        len.put(num);
        return arr;
    }

    BytePtr update_winhighlight(S_window_S wp, BytePtr opt) {
        BytePtr[] err = new BytePtr[1];
        Ptr<T_hl_override_T> arr = null;
        int[] num = new int[1];
        err[0] = null;
        num[0] = 1;
        arr = parse_winhighlight(opt, new IntPtr(num, 0), new Ptr<BytePtr>(err, 0));
        if (arr == null && err[0] != null) {
            return err[0];
        }
        if (arr == null && wp.w_hl == null) {
            return null;
        }
        update_highlight_overrides(wp.w_hl, arr, num[0]);
        wp.w_hl = arr;
        wp.w_hl_len = num[0];
        wp.w_hlfwin_id = hlf_get_id(wp, HLF_WIN);
        return null;
    }

    int hlf_get_id(S_window_S wp, int hlf) {
        int id = 0;
        if (wp.w_hl == null) {
            return highlight_ids[hlf];
        }
        Rt.memmove(new IntPtr(hlf_get_id_prev, 0), new IntPtr(highlight_ids, 0), 70);
        set_highlight_attr(wp.w_hl, wp.w_hl_len, true);
        id = highlight_ids[hlf];
        Rt.memmove(new IntPtr(highlight_ids, 0), new IntPtr(hlf_get_id_prev, 0), 70);
        return id;
    }

    BytePtr update_wincolor(S_window_S wp, BytePtr opt) {
        BytePtr str = null;
        BytePtr errmsg = null;
        str = opt.get() == NUL ? BytePtr.lit("") : BytePtr.alloc(4L + musl_strlen(opt));
        if (str == null) {
            return new BytePtr(e_out_of_memory, 0);
        }
        if (opt.get() != NUL) {
            vim_snprintf(str, 4L + musl_strlen(opt), BytePtr.lit("!(:%s"), opt);
        }
        errmsg = update_winhighlight(wp, str);
        if (errmsg == null) {
            set_string_option_direct_in_win(wp, BytePtr.lit("winhighlight"), -1, str, OPT_FREE | OPT_LOCAL, 0);
        }
        return errmsg;
    }

