    int get_indent_str(BytePtr ptr, int ts, boolean no_ts) {
        int count = 0;
        count = 0;
        for (; ptr.get() != 0; ptr = ptr.add(1)) {
            if (ptr.get() == TAB) {
                if (!no_ts) {
                    count += ts - count % ts;
                } else {
                    count += ptr2cells(ptr);
                }
            } else if (ptr.get() == ' ') {
                count++;
            } else {
                break;
            }
        }
        return count;
    }

    boolean set_indent(int size, int flags) {
        BytePtr p = null;
        BytePtr newline = null;
        BytePtr oldline = null;
        BytePtr s = null;
        int todo = 0;
        int ind_len = 0;
        int line_len = 0;
        boolean doit = false;
        int ind_done = 0;
        int tab_pad = 0;
        boolean retval = false;
        int orig_char_len = 0;
        BytePtr t1 = null;
        BytePtr t2 = null;
        BytePtr t3 = null;
        BytePtr t4 = null;
        BytePtr t5 = null;
        BytePtr t6 = null;
        BytePtr t7 = null;
        int old_offset = 0;
        int new_offset = 0;
        doit = false;
        ind_done = 0;
        retval = false;
        orig_char_len = -1;
        todo = size;
        ind_len = 0;
        oldline = ml_get_curline();
        p = oldline;
        line_len = ml_get_curline_len() + 1;
        if (curbuf.b_p_et[0] == 0 || ((flags & SIN_INSERT) == 0 && curbuf.b_p_pi[0] != 0)) {
            if ((flags & SIN_INSERT) == 0 && curbuf.b_p_pi[0] != 0) {
                ind_done = 0;
                while (todo > 0 && (p.get() == ' ' || p.get() == '\t')) {
                    if (p.get() == TAB) {
                        tab_pad = (int) curbuf.b_p_ts[0] - ind_done % (int) curbuf.b_p_ts[0];
                        if (todo < tab_pad) {
                            break;
                        }
                        todo -= tab_pad;
                        ind_len++;
                        ind_done += tab_pad;
                    } else {
                        todo--;
                        ind_len++;
                        ind_done++;
                    }
                    p = p.add(1);
                }
                if (curbuf.b_p_et[0] != 0) {
                    orig_char_len = ind_len;
                }
                tab_pad = (int) curbuf.b_p_ts[0] - ind_done % (int) curbuf.b_p_ts[0];
                if (todo >= tab_pad && orig_char_len == -1) {
                    doit = true;
                    todo -= tab_pad;
                    ind_len++;
                }
            }
            while (todo >= (int) curbuf.b_p_ts[0]) {
                if (p.get() != TAB) {
                    doit = true;
                } else {
                    p = p.add(1);
                }
                todo -= (int) curbuf.b_p_ts[0];
                ind_len++;
            }
        }
        while (todo > 0) {
            if (p.get() != ' ') {
                doit = true;
            } else {
                p = p.add(1);
            }
            todo--;
            ind_len++;
        }
        if (!doit && !(p.get() == ' ' || p.get() == '\t') && (flags & SIN_INSERT) == 0) {
            return false;
        }
        if ((flags & SIN_INSERT) != 0) {
            p = oldline;
        } else {
            p = skipwhite(p);
            line_len -= (int) p.sub(oldline);
        }
        if (orig_char_len != -1) {
            newline = BytePtr.alloc((long) (orig_char_len + size - ind_done + line_len));
            todo = size - ind_done;
            ind_len = orig_char_len + todo;
            p = oldline;
            s = newline;
            while (orig_char_len > 0) {
                t1 = s;
                s = s.add(1);
                t2 = p;
                p = p.add(1);
                t1.put(t2.get());
                orig_char_len--;
            }
            while (p.get() == ' ' || p.get() == '\t') {
                p = p.add(1);
            }
        } else {
            todo = size;
            newline = BytePtr.alloc((long) (ind_len + line_len));
            s = newline;
        }
        if (curbuf.b_p_et[0] == 0) {
            if ((flags & SIN_INSERT) == 0 && curbuf.b_p_pi[0] != 0) {
                p = oldline;
                ind_done = 0;
                while (todo > 0 && (p.get() == ' ' || p.get() == '\t')) {
                    if (p.get() == TAB) {
                        tab_pad = (int) curbuf.b_p_ts[0] - ind_done % (int) curbuf.b_p_ts[0];
                        if (todo < tab_pad) {
                            break;
                        }
                        todo -= tab_pad;
                        ind_done += tab_pad;
                    } else {
                        todo--;
                        ind_done++;
                    }
                    t3 = s;
                    s = s.add(1);
                    t4 = p;
                    p = p.add(1);
                    t3.put(t4.get());
                }
                tab_pad = (int) curbuf.b_p_ts[0] - ind_done % (int) curbuf.b_p_ts[0];
                if (todo >= tab_pad) {
                    t5 = s;
                    s = s.add(1);
                    t5.put((byte) TAB);
                    todo -= tab_pad;
                }
                p = skipwhite(p);
            }
            while (todo >= (int) curbuf.b_p_ts[0]) {
                t6 = s;
                s = s.add(1);
                t6.put((byte) TAB);
                todo -= (int) curbuf.b_p_ts[0];
            }
        }
        while (todo > 0) {
            t7 = s;
            s = s.add(1);
            t7.put((byte) ' ');
            todo--;
        }
        Rt.memmove(s, p, (long) line_len);
        if ((flags & SIN_UNDO) == 0 || u_savesub(curwin.w_cursor.lnum[0])) {
            old_offset = (int) p.sub(oldline);
            new_offset = (int) s.sub(newline);
            ml_replace(curwin.w_cursor.lnum[0], newline, false);
            if ((flags & SIN_CHANGED) != 0) {
                changed_bytes(curwin.w_cursor.lnum[0], 0);
            }
            if (saved_cursor.lnum[0] == curwin.w_cursor.lnum[0]) {
                if (saved_cursor.col[0] >= old_offset) {
                    saved_cursor.col[0] += ind_len - old_offset;
                } else if (saved_cursor.col[0] >= new_offset) {
                    saved_cursor.col[0] = new_offset;
                }
            }
            retval = true;
        }
        curwin.w_cursor.col[0] = ind_len;
        return retval;
    }

    boolean inindent(int extra) {
        BytePtr ptr = null;
        int col = 0;
        col = 0;
        ptr = ml_get_curline();
        for (; (ptr.get() == ' ' || ptr.get() == '\t'); col++) {
            ptr = ptr.add(1);
        }
        if (col >= curwin.w_cursor.col[0] + extra) {
            return true;
        } else {
            return false;
        }
    }

