    void ins_try_si(int c) {
        T_pos_T pos = null;
        T_pos_T old_pos = new T_pos_T();
        BytePtr ptr = null;
        int i = 0;
        boolean temp = false;
        boolean t1 = false;
        boolean t2 = false;
        if (((did_si != 0 || can_si_back != 0) && c == '{') || (can_si != 0 && c == '}' && inindent(0))) {
            t1 = c == '}';
            if (t1) {
                pos = findmatch(null, '{');
                t1 = pos != null;
            }
            if (t1) {
                old_pos.set(curwin.w_cursor);
                ptr = ml_get(pos.lnum[0]);
                i = pos.col[0];
                if (i > 0) {
                    while (true) {
                        i--;
                        if (!(i > 0 && (ptr.at(i) == ' ' || ptr.at(i) == '\t'))) {
                            break;
                        }
                    }
                }
                curwin.w_cursor.lnum[0] = pos.lnum[0];
                curwin.w_cursor.col[0] = i;
                t2 = ptr.at(i) == ')';
                if (t2) {
                    pos = findmatch(null, '(');
                    t2 = pos != null;
                }
                if (t2) {
                    curwin.w_cursor.set(pos);
                }
                i = get_indent();
                curwin.w_cursor.set(old_pos);
                if ((State & VREPLACE_FLAG) != 0) {
                    change_indent(INDENT_SET, i, false, NUL, TRUE);
                } else {
                    set_indent(i, SIN_CHANGED);
                }
            } else if (curwin.w_cursor.col[0] > 0) {
                temp = true;
                if (c == '{' && can_si_back != 0 && curwin.w_cursor.lnum[0] > 1L) {
                    old_pos.set(curwin.w_cursor);
                    i = get_indent();
                    while (curwin.w_cursor.lnum[0] > 1L) {
                        curwin.w_cursor.lnum[0]--;
                        ptr = skipwhite(ml_get(curwin.w_cursor.lnum[0]));
                        if (ptr.get() != '#' && ptr.get() != NUL) {
                            break;
                        }
                    }
                    if (get_indent() >= i) {
                        temp = false;
                    }
                    curwin.w_cursor.set(old_pos);
                }
                if (temp) {
                    shift_line(true, FALSE, 1, TRUE);
                }
            }
        }
        if (curwin.w_cursor.col[0] > 0 && can_si != 0 && c == '#' && inindent(0)) {
            old_indent = get_indent();
            set_indent(0, SIN_CHANGED);
        }
        if (ai_col > curwin.w_cursor.col[0]) {
            ai_col = curwin.w_cursor.col[0];
        }
    }

    void change_indent(int type, int amount, boolean round, int replaced, int call_changed_bytes) {
        int vcol = 0;
        int last_vcol = 0;
        int insstart_less = 0;
        int new_cursor_col = 0;
        int i = 0;
        BytePtr ptr = null;
        int save_p_list = 0;
        int start_col = 0;
        int vc = 0;
        int orig_col = 0;
        BytePtr new_line = null;
        BytePtr orig_line = null;
        int len = 0;
        int save_State = 0;
        T_chartabsize_T cts = new T_chartabsize_T();
        long ptrlen = 0;
        int len_2 = 0;
        orig_col = 0;
        orig_line = null;
        if ((State & VREPLACE_FLAG) != 0) {
            len = ml_get_curline_len();
            orig_line = vim_strnsave(ml_get_curline(), (long) len);
            orig_col = curwin.w_cursor.col[0];
        }
        save_p_list = curwin.w_onebuf_opt.wo_list[0];
        curwin.w_onebuf_opt.wo_list[0] = FALSE;
        vc = getvcol_nolist(curwin.w_cursor);
        vcol = vc;
        start_col = curwin.w_cursor.col[0];
        new_cursor_col = curwin.w_cursor.col[0];
        beginline(BL_WHITE);
        new_cursor_col -= curwin.w_cursor.col[0];
        insstart_less = curwin.w_cursor.col[0];
        if (new_cursor_col < 0) {
            vcol = get_indent() - vcol;
        }
        if (new_cursor_col > 0) {
            start_col = -1;
        }
        if (type == INDENT_SET) {
            set_indent(amount, call_changed_bytes != 0 ? SIN_CHANGED : 0);
        } else {
            save_State = State;
            if ((State & VREPLACE_FLAG) != 0) {
                State = MODE_INSERT;
            }
            shift_line(type == INDENT_DEC, round ? 1 : 0, 1, call_changed_bytes);
            State = save_State;
        }
        insstart_less -= curwin.w_cursor.col[0];
        if (new_cursor_col >= 0) {
            if (new_cursor_col == 0) {
                insstart_less = MAXCOL;
            }
            new_cursor_col += curwin.w_cursor.col[0];
        } else if ((State & MODE_INSERT) == 0) {
            new_cursor_col = curwin.w_cursor.col[0];
        } else {
            vcol = get_indent() - vcol;
            curwin.w_virtcol[0] = vcol < 0 ? 0 : vcol;
            last_vcol = 0;
            ptr = ml_get_curline();
            init_chartabsize_arg(cts, curwin, 0L, 0, ptr, ptr);
            while (cts.cts_vcol <= curwin.w_virtcol[0]) {
                last_vcol = cts.cts_vcol;
                if (cts.cts_vcol > 0) {
                    cts.cts_ptr = cts.cts_ptr.add(utfc_ptr2len(cts.cts_ptr));
                }
                if (cts.cts_ptr.get() == NUL) {
                    break;
                }
                cts.cts_vcol += lbr_chartabsize(cts);
            }
            vcol = last_vcol;
            new_cursor_col = (int) cts.cts_ptr.sub(cts.cts_line);
            if (vcol != curwin.w_virtcol[0]) {
                curwin.w_cursor.col[0] = new_cursor_col;
                i = curwin.w_virtcol[0] - vcol;
                ptr = BytePtr.alloc((long) (i + 1));
                new_cursor_col += i;
                ptr.set(i, (byte) NUL);
                ptrlen = (long) i;
                while (true) {
                    i--;
                    if (!(i >= 0)) {
                        break;
                    }
                    ptr.set(i, (byte) ' ');
                }
                ins_str(ptr, ptrlen);
            }
            insstart_less = MAXCOL;
        }
        curwin.w_onebuf_opt.wo_list[0] = save_p_list;
        if (new_cursor_col <= 0) {
            curwin.w_cursor.col[0] = 0;
        } else {
            curwin.w_cursor.col[0] = new_cursor_col;
        }
        curwin.w_set_curswant = true;
        changed_cline_bef_curs();
        if ((State & MODE_INSERT) != 0) {
            if (curwin.w_cursor.lnum[0] == Insstart.lnum[0] && Insstart.col[0] != 0) {
                if (Insstart.col[0] <= insstart_less) {
                    Insstart.col[0] = 0;
                } else {
                    Insstart.col[0] -= insstart_less;
                }
            }
            if (ai_col <= insstart_less) {
                ai_col = 0;
            } else {
                ai_col -= insstart_less;
            }
        }
        if ((State & REPLACE_FLAG) != 0 && (State & VREPLACE_FLAG) == 0 && start_col >= 0) {
            while (start_col > curwin.w_cursor.col[0]) {
                replace_join(0);
                start_col--;
            }
            while (start_col < curwin.w_cursor.col[0] || replaced != 0) {
                replace_push(NUL);
                if (replaced != 0) {
                    replace_push(replaced);
                    replaced = NUL;
                }
                start_col++;
            }
        }
        if ((State & VREPLACE_FLAG) != 0) {
            if (orig_line == null) {
                return;
            }
            len_2 = ml_get_curline_len();
            new_line = vim_strnsave(ml_get_curline(), (long) len_2);
            new_line.set(curwin.w_cursor.col[0], (byte) NUL);
            ml_replace(curwin.w_cursor.lnum[0], orig_line, false);
            curwin.w_cursor.col[0] = orig_col;
            backspace_until_column(0);
            ins_bytes(new_line);
        }
    }

    boolean copy_indent(int size, BytePtr src) {
        BytePtr p = null;
        BytePtr line = null;
        BytePtr s = null;
        int todo = 0;
        int ind_len = 0;
        int line_len = 0;
        int tab_pad = 0;
        int ind_done = 0;
        int round = 0;
        BytePtr t1 = null;
        BytePtr t2 = null;
        BytePtr t3 = null;
        BytePtr t4 = null;
        p = null;
        line = null;
        line_len = 0;
        round = 1;
        for (; round <= 2; round++) {
            todo = size;
            ind_len = 0;
            ind_done = 0;
            s = src;
            while (todo > 0 && (s.get() == ' ' || s.get() == '\t')) {
                if (s.get() == TAB) {
                    tab_pad = (int) curbuf.b_p_ts[0] - ind_done % (int) curbuf.b_p_ts[0];
                    if (todo < tab_pad) {
                        break;
                    }
                    todo -= tab_pad;
                    ind_done += tab_pad;
                } else {
                    todo--;
                    ind_done++;
                }
                ind_len++;
                if (p != null) {
                    t1 = p;
                    p = p.add(1);
                    t1.put(s.get());
                }
                s = s.add(1);
            }
            tab_pad = (int) curbuf.b_p_ts[0] - ind_done % (int) curbuf.b_p_ts[0];
            if (todo >= tab_pad && curbuf.b_p_et[0] == 0) {
                todo -= tab_pad;
                ind_len++;
                if (p != null) {
                    t2 = p;
                    p = p.add(1);
                    t2.put((byte) TAB);
                }
            }
            if (curbuf.b_p_et[0] == 0) {
                while (todo >= (int) curbuf.b_p_ts[0]) {
                    todo -= (int) curbuf.b_p_ts[0];
                    ind_len++;
                    if (p != null) {
                        t3 = p;
                        p = p.add(1);
                        t3.put((byte) TAB);
                    }
                }
            }
            while (todo > 0) {
                todo--;
                ind_len++;
                if (p != null) {
                    t4 = p;
                    p = p.add(1);
                    t4.put((byte) ' ');
                }
            }
            if (p == null) {
                line_len = ml_get_curline_len() + 1;
                line = BytePtr.alloc((long) (ind_len + line_len));
                p = line;
            }
        }
        Rt.memmove(p, ml_get_curline(), (long) line_len);
        ml_replace(curwin.w_cursor.lnum[0], line, false);
        curwin.w_cursor.col[0] = ind_len;
        return true;
    }

