    int plines(long lnum) {
        return plines_win(curwin, lnum, true);
    }

    int plines_win(S_window_S wp, long lnum, boolean limit_winheight) {
        int lines = 0;
        if (wp.w_width == 0) {
            return 1;
        }
        if (wp.w_onebuf_opt.wo_wrap[0] == 0) {
            lines = 1;
        } else {
            lines = plines_win_nofold(wp, lnum);
        }
        if (limit_winheight && lines > wp.w_height) {
            return wp.w_height;
        }
        return lines;
    }

    int plines_win_nofold(S_window_S wp, long lnum) {
        BytePtr s = null;
        long col = 0;
        int width = 0;
        T_chartabsize_T cts = new T_chartabsize_T();
        s = ml_get_buf(wp.w_buffer, lnum, false);
        init_chartabsize_arg(cts, wp, lnum, 0, s, s);
        if (s.get() == NUL) {
            return 1;
        }
        win_linetabsize_cts(cts, MAXCOL);
        col = (long) cts.cts_vcol;
        if (wp.w_onebuf_opt.wo_list[0] != 0 && wp.w_lcs_chars.eol[0] != NUL) {
            col += 1L;
        }
        width = wp.w_width - win_col_off(wp);
        if (width <= 0) {
            return 32000;
        }
        if (col <= (long) width) {
            return 1;
        }
        col -= (long) width;
        width += win_col_off2(wp);
        return (int) ((col + (long) (width - 1)) / (long) width + 1L);
    }

    int plines_win_col(S_window_S wp, long lnum, long column) {
        long col = 0;
        int lines = 0;
        int width = 0;
        BytePtr line = null;
        T_chartabsize_T cts = new T_chartabsize_T();
        lines = 0;
        if (wp.w_onebuf_opt.wo_wrap[0] == 0) {
            return lines + 1;
        }
        if (wp.w_width == 0) {
            return lines + 1;
        }
        line = ml_get_buf(wp.w_buffer, lnum, false);
        init_chartabsize_arg(cts, wp, lnum, 0, line, line);
        while (cts.cts_ptr.get() != NUL && cts.cts_ptr.lt(line.add((int) column))) {
            cts.cts_vcol += win_lbr_chartabsize(cts, null, null);
            cts.cts_ptr = cts.cts_ptr.add(utfc_ptr2len(cts.cts_ptr));
        }
        col = (long) cts.cts_vcol;
        if (cts.cts_ptr.get() == TAB && (State & MODE_NORMAL) != 0 && (wp.w_onebuf_opt.wo_list[0] == 0 || wp.w_lcs_chars.tab1 != 0)) {
            col += (long) (win_lbr_chartabsize(cts, null, null) - 1);
        }
        width = wp.w_width - win_col_off(wp);
        if (width <= 0) {
            return 9999;
        }
        lines += 1;
        if (col > ((long) width)) {
            lines += (col - (long) width) / (long) (width + win_col_off2(wp)) + 1L;
        }
        return lines;
    }

    int plines_m_win(S_window_S wp, long first, long last, int max) {
        int count = 0;
        count = 0;
        while (first <= last && count < max) {
            count += plines_win(wp, first, false);
            first++;
        }
        return max < count ? max : count;
    }

    int gchar_pos(T_pos_T pos) {
        BytePtr ptr = null;
        int ptrlen = 0;
        if (pos.col[0] == MAXCOL) {
            return NUL;
        }
        ptrlen = ml_get_len(pos.lnum[0]);
        ptr = ml_get_pos(pos);
        if (pos.col[0] > ptrlen) {
            return NUL;
        }
        return utf_ptr2char(ptr);
    }

