    boolean find_is_eval_item(BytePtr ptr, IntPtr colp, IntPtr bnp, int dir) {
        if ((ptr.get() == ']' && dir == -1) || (ptr.get() == '[' && dir == FORWARD)) {
            bnp.put(bnp.get() + 1);
        }
        if (bnp.get() > 0) {
            if ((ptr.get() == '[' && dir == -1) || (ptr.get() == ']' && dir == FORWARD)) {
                bnp.put(bnp.get() - 1);
            }
            return true;
        }
        if (ptr.get() == '.') {
            return true;
        }
        if (ptr.at(dir == -1 ? 0 : 1) == '>' && ptr.at(dir == -1 ? -1 : 0) == '-') {
            colp.put(colp.get() + dir);
            return true;
        }
        return false;
    }

    int find_ident_under_cursor(Ptr<BytePtr> text, int find_type) {
        return find_ident_at_pos(curwin, curwin.w_cursor.lnum[0], curwin.w_cursor.col[0], text, null, find_type);
    }

    int find_ident_at_pos(S_window_S wp, long lnum, int startcol, Ptr<BytePtr> text, IntPtr textcol, int find_type) {
        BytePtr ptr = null;
        int[] col = new int[1];
        int i = 0;
        int this_class = 0;
        int prev_class = 0;
        int[] prevcol = new int[1];
        int[] bn = new int[1];
        col[0] = 0;
        this_class = 0;
        bn[0] = 0;
        ptr = ml_get_buf(wp.w_buffer, lnum, false);
        i = (find_type & FIND_IDENT) != 0 ? 0 : 1;
        for (; i < 2; i++) {
            col[0] = startcol;
            while (ptr.at(col[0]) != NUL) {
                if ((find_type & FIND_EVAL) != 0 && ptr.at(col[0]) == ']') {
                    break;
                }
                this_class = mb_get_class(ptr.add(col[0]));
                if (this_class != 0 && (i == 1 || this_class != 1)) {
                    break;
                }
                col[0] += utfc_ptr2len(ptr.add(col[0]));
            }
            bn[0] = ptr.at(col[0]) == ']' ? 1 : 0;
            if ((find_type & FIND_EVAL) != 0 && ptr.at(col[0]) == ']') {
                this_class = mb_get_class(BytePtr.lit("a"));
            } else {
                this_class = mb_get_class(ptr.add(col[0]));
            }
            while (col[0] > 0 && this_class != 0) {
                prevcol[0] = col[0] - 1 - utf_head_off(ptr, ptr.add(col[0]).add(-1));
                prev_class = mb_get_class(ptr.add(prevcol[0]));
                if (this_class != prev_class && (i == 0 || prev_class == 0 || (find_type & FIND_IDENT) != 0) && ((find_type & FIND_EVAL) == 0 || prevcol[0] == 0 || !find_is_eval_item(ptr.add(prevcol[0]), new IntPtr(prevcol, 0), new IntPtr(bn, 0), -1))) {
                    break;
                }
                col[0] = prevcol[0];
            }
            if (this_class > 2) {
                this_class = 2;
            }
            if ((find_type & FIND_STRING) == 0 || this_class == 2) {
                break;
            }
        }
        if (ptr.at(col[0]) == NUL || (i == 0 && this_class != 2)) {
            if ((find_type & FIND_NOERROR) == 0) {
                if ((find_type & FIND_STRING) != 0) {
                    emsg(gettext_(new BytePtr(e_no_string_under_cursor, 0)));
                } else {
                    emsg(gettext_(new BytePtr(e_no_identifier_under_cursor, 0)));
                }
            }
            return 0;
        }
        ptr = ptr.add(col[0]);
        text.put(ptr);
        if (textcol != null) {
            textcol.put(col[0]);
        }
        bn[0] = 0;
        startcol -= col[0];
        col[0] = 0;
        this_class = mb_get_class(ptr);
        while (ptr.at(col[0]) != NUL && ((i == 0 ? mb_get_class(ptr.add(col[0])) == this_class : mb_get_class(ptr.add(col[0])) != 0) || ((find_type & FIND_EVAL) != 0 && col[0] <= startcol && find_is_eval_item(ptr.add(col[0]), new IntPtr(col, 0), new IntPtr(bn, 0), FORWARD)))) {
            col[0] += utfc_ptr2len(ptr.add(col[0]));
        }
        return col[0];
    }

    void prep_redo_cmd(S_cmdarg_S cap) {
        prep_redo(cap.oap.regname, cap.count0, NUL, cap.cmdchar, NUL, NUL, cap.nchar[0]);
    }

    void prep_redo(int regname, long num, int cmd1, int cmd2, int cmd3, int cmd4, int cmd5) {
        prep_redo_num2(regname, num, cmd1, cmd2, 0L, cmd3, cmd4, cmd5);
    }

    void prep_redo_num2(int regname, long num1, int cmd1, int cmd2, long num2, int cmd3, int cmd4, int cmd5) {
        ResetRedobuff();
        if (regname != 0) {
            AppendCharToRedobuff('"');
            AppendCharToRedobuff(regname);
        }
        if (num1 != 0L) {
            AppendNumberToRedobuff(num1);
        }
        if (cmd1 != NUL) {
            AppendCharToRedobuff(cmd1);
        }
        if (cmd2 != NUL) {
            AppendCharToRedobuff(cmd2);
        }
        if (num2 != 0L) {
            AppendNumberToRedobuff(num2);
        }
        if (cmd3 != NUL) {
            AppendCharToRedobuff(cmd3);
        }
        if (cmd4 != NUL) {
            AppendCharToRedobuff(cmd4);
        }
        if (cmd5 != NUL) {
            AppendCharToRedobuff(cmd5);
        }
    }

    boolean checkclearop(S_oparg_S oap) {
        if (oap.op_type == OP_NOP) {
            return false;
        }
        clearopbeep(oap);
        return true;
    }

    boolean checkclearopq(S_oparg_S oap) {
        if (oap.op_type == OP_NOP && VIsual_active == 0) {
            return false;
        }
        clearopbeep(oap);
        return true;
    }

    void clearop(S_oparg_S oap) {
        oap.op_type = OP_NOP;
        oap.regname = 0;
        oap.motion_force = NUL;
        oap.use_reg_one = FALSE;
        motion_force = NUL;
    }

    void clearopbeep(S_oparg_S oap) {
        clearop(oap);
        beep_flush();
    }

    void unshift_special(S_cmdarg_S cap) {
        switch (cap.cmdchar) {
            case K_TC_PCT_i:
                cap.cmdchar = K_RIGHT;
                break;
            case K_TC_HASH_4:
                cap.cmdchar = K_LEFT;
                break;
            case K_S_UP:
                cap.cmdchar = K_UP;
                break;
            case K_S_DOWN:
                cap.cmdchar = K_DOWN;
                break;
            case K_TC_HASH_2:
                cap.cmdchar = K_HOME;
                break;
            case K_TC_STAR_7:
                cap.cmdchar = K_END;
                break;
        }
        cap.cmdchar = simplify_key(cap.cmdchar, new IntPtr(mod_mask, 0));
    }

    void may_clear_cmdline() {
        if (mode_displayed != 0) {
            clear_cmdline = TRUE;
        } else {
            clear_showcmd();
        }
    }

    void clear_showcmd() {
        boolean cursor_bot = false;
        long lines = 0;
        int[] leftcol = new int[1];
        int[] rightcol = new int[1];
        long top = 0;
        long bot = 0;
        BytePtr s = null;
        BytePtr e = null;
        int l = 0;
        int bytes = 0;
        int chars = 0;
        if (p_sc[0] == 0) {
            return;
        }
        if (VIsual_active != 0 && stuff_empty() && typebuf.tb_len == 0) {
            cursor_bot = VIsual.lnum[0] != curwin.w_cursor.lnum[0] ? VIsual.lnum[0] < curwin.w_cursor.lnum[0] : (VIsual.col[0] != curwin.w_cursor.col[0] ? VIsual.col[0] < curwin.w_cursor.col[0] : VIsual.coladd < curwin.w_cursor.coladd);
            if (cursor_bot) {
                top = VIsual.lnum[0];
                bot = curwin.w_cursor.lnum[0];
            } else {
                top = curwin.w_cursor.lnum[0];
                bot = VIsual.lnum[0];
            }
            lines = bot - top + 1L;
            if (VIsual_mode == Ctrl_V) {
                getvcols(curwin, curwin.w_cursor, VIsual, new IntPtr(leftcol, 0), new IntPtr(rightcol, 0), GETVCOL_END_EXCL_LBR);
                vim_snprintf(new BytePtr(showcmd_buf, 0), SHOWCMD_COLS + 1 + 30, BytePtr.lit("%ldx%ld"), lines, (long) (rightcol[0] - leftcol[0] + 1));
            } else if (VIsual_mode == 'V' || VIsual.lnum[0] != curwin.w_cursor.lnum[0]) {
                vim_snprintf(new BytePtr(showcmd_buf, 0), SHOWCMD_COLS + 1 + 30, BytePtr.lit("%ld"), lines);
            } else {
                bytes = 0;
                chars = 0;
                if (cursor_bot) {
                    s = ml_get_pos(VIsual);
                    e = ml_get_cursor();
                } else {
                    s = ml_get_cursor();
                    e = ml_get_pos(VIsual);
                }
                while (p_sel[0].get() != 'e' ? s.le(e) : s.lt(e)) {
                    l = utfc_ptr2len(s);
                    if (l == 0) {
                        bytes++;
                        chars++;
                        break;
                    }
                    bytes += l;
                    chars++;
                    s = s.add(l);
                }
                if (bytes == chars) {
                    vim_snprintf(new BytePtr(showcmd_buf, 0), SHOWCMD_COLS + 1 + 30, BytePtr.lit("%d"), chars);
                } else {
                    vim_snprintf(new BytePtr(showcmd_buf, 0), SHOWCMD_COLS + 1 + 30, BytePtr.lit("%d-%d"), chars, bytes);
                }
            }
            showcmd_buf[SHOWCMD_COLS] = (byte) NUL;
            showcmd_visual = TRUE;
        } else {
            showcmd_buf[0] = (byte) NUL;
            showcmd_visual = FALSE;
            if (showcmd_is_clear != 0) {
                return;
            }
        }
        display_showcmd();
    }

    boolean add_to_showcmd(int c) {
        BytePtr p = null;
        int old_len = 0;
        int extra_len = 0;
        int overflow = 0;
        int i = 0;
        byte[] mbyte_buf = new byte[21];
        int t1 = 0;
        if (p_sc[0] == 0 || msg_silent != 0) {
            return false;
        }
        if (showcmd_visual != 0) {
            showcmd_buf[0] = (byte) NUL;
            showcmd_visual = FALSE;
        }
        if (c < 0) {
            i = 0;
            for (; add_to_showcmd_ignore[i] != 0; i++) {
                if (add_to_showcmd_ignore[i] == c) {
                    return false;
                }
            }
        }
        if (c <= 127 || !vim_isprintc(c)) {
            p = transchar(c);
            if (p.get() == ' ') {
                musl_strcpy(p, BytePtr.lit("<20>"));
            }
        } else {
            t1 = utf_char2bytes(c, new BytePtr(mbyte_buf, 0));
            mbyte_buf[t1] = (byte) NUL;
            p = new BytePtr(mbyte_buf, 0);
        }
        old_len = (int) musl_strlen(new BytePtr(showcmd_buf, 0));
        extra_len = (int) musl_strlen(p);
        overflow = old_len + extra_len - SHOWCMD_COLS;
        if (overflow > 0) {
            Rt.memmove(new BytePtr(showcmd_buf, 0), new BytePtr(showcmd_buf, 0).add(overflow), (long) (old_len - overflow + 1));
        }
        musl_strcat(new BytePtr(showcmd_buf, 0), p);
        if (char_avail()) {
            return false;
        }
        display_showcmd();
        return true;
    }

    void add_to_showcmd_c(int c) {
        if (!add_to_showcmd(c)) {
            setcursor();
        }
    }

    void del_from_showcmd(int len) {
        int old_len = 0;
        if (p_sc[0] == 0) {
            return;
        }
        old_len = (int) musl_strlen(new BytePtr(showcmd_buf, 0));
        if (len > old_len) {
            len = old_len;
        }
        showcmd_buf[old_len - len] = (byte) NUL;
        if (!char_avail()) {
            display_showcmd();
        }
    }

    void push_showcmd() {
        if (p_sc[0] != 0) {
            musl_strcpy(new BytePtr(old_showcmd_buf, 0), new BytePtr(showcmd_buf, 0));
        }
    }

    void pop_showcmd() {
        if (p_sc[0] == 0) {
            return;
        }
        musl_strcpy(new BytePtr(showcmd_buf, 0), new BytePtr(old_showcmd_buf, 0));
        display_showcmd();
    }

    void showcmd_update_clear_state() {
        showcmd_is_clear = showcmd_buf[0] == NUL ? 1 : 0;
    }

    void display_showcmd() {
        int len = 0;
        len = vim_strsize(new BytePtr(showcmd_buf, 0));
        showcmd_update_clear_state();
        cursor_off();
        if (p_sloc[0].get() == 's') {
            if (showcmd_is_clear != 0 && vgetc_busy == 0) {
                curwin.w_redr_status = true;
            } else {
                win_redr_status(curwin, false);
            }
        } else if (p_sloc[0].get() == 't') {
            if (showcmd_is_clear != 0 && vgetc_busy == 0) {
                redraw_tabline = TRUE;
            } else {
                draw_tabline();
            }
        } else {
            if (showcmd_is_clear == 0) {
                screen_puts(new BytePtr(showcmd_buf, 0), (int) Rows[0] - 1, cmdline_col_off + sc_col, 0);
            }
            screen_puts(BytePtr.lit("          ").add(len), (int) Rows[0] - 1, cmdline_col_off + sc_col + len, 0);
        }
        setcursor();
    }

