    void op_tilde(S_oparg_S oap) {
        T_pos_T pos = new T_pos_T();
        S_block_def bd = new S_block_def();
        int did_change = 0;
        int one_change = 0;
        did_change = FALSE;
        if (!u_save(oap.start.lnum[0] - 1L, oap.end.lnum[0] + 1L)) {
            return;
        }
        pos.set(oap.start);
        if (oap.block_mode != 0) {
            for (; pos.lnum[0] <= oap.end.lnum[0]; pos.lnum[0]++) {
                block_prep(oap, bd, pos.lnum[0], FALSE);
                pos.col[0] = bd.textcol;
                one_change = swapchars(oap.op_type, pos, bd.textlen);
                did_change |= one_change;
            }
            if (did_change != 0) {
                changed_lines(oap.start.lnum[0], 0, oap.end.lnum[0] + 1L, 0L);
            }
        } else {
            if (oap.motion_type == MLINE) {
                oap.start.col[0] = 0;
                pos.col[0] = 0;
                oap.end.col[0] = ml_get_len(oap.end.lnum[0]);
                if (oap.end.col[0] != 0) {
                    oap.end.col[0]--;
                }
            } else if (oap.inclusive == 0) {
                dec(oap.end);
            }
            if (pos.lnum[0] == oap.end.lnum[0]) {
                did_change = swapchars(oap.op_type, pos, oap.end.col[0] - pos.col[0] + 1);
            } else {
                for (;;) {
                    did_change |= swapchars(oap.op_type, pos, pos.lnum[0] == oap.end.lnum[0] ? oap.end.col[0] + 1 : ml_get_pos_len(pos));
                    if ((oap.end.lnum[0] != pos.lnum[0] ? oap.end.lnum[0] < pos.lnum[0] : (oap.end.col[0] != pos.col[0] ? oap.end.col[0] < pos.col[0] : oap.end.coladd < pos.coladd)) || (oap.end.lnum[0] == pos.lnum[0] && oap.end.col[0] == pos.col[0] && oap.end.coladd == pos.coladd) || inc(pos) == -1) {
                        break;
                    }
                }
            }
            if (did_change != 0) {
                changed_lines(oap.start.lnum[0], oap.start.col[0], oap.end.lnum[0] + 1L, 0L);
            }
        }
        if (did_change == 0 && oap.is_VIsual != 0) {
            redraw_curbuf_later(UPD_INVERTED);
        }
        if ((cmdmod.cmod_flags & CMOD_LOCKMARKS) == 0) {
            curbuf.b_op_start.set(oap.start);
            curbuf.b_op_end.set(oap.end);
        }
        if (oap.line_count > p_report[0]) {
            vim_snprintf(IObuff, iobuff_room(), NGETTEXT(BytePtr.lit("%ld line changed"), BytePtr.lit("%ld lines changed"), oap.line_count), oap.line_count);
            msg(iobuff_or(NGETTEXT(BytePtr.lit("%ld line changed"), BytePtr.lit("%ld lines changed"), oap.line_count)));
        }
    }

    int swapchars(int op_type, T_pos_T pos, int length) {
        int todo = 0;
        int did_change = 0;
        int len = 0;
        did_change = 0;
        todo = length;
        for (; todo > 0; todo--) {
            len = utfc_ptr2len(ml_get_pos(pos));
            if (len > 0) {
                todo -= len - 1;
            }
            did_change |= swapchar(op_type, pos) ? 1 : 0;
            if (inc(pos) == -1) {
                break;
            }
        }
        return did_change;
    }

    boolean swapchar(int op_type, T_pos_T pos) {
        int c = 0;
        int nc = 0;
        T_pos_T sp = new T_pos_T();
        T_pos_T sp_2 = new T_pos_T();
        c = gchar_pos(pos);
        if ((op_type == OP_UPPER || op_type == OP_NOP || op_type == OP_TILDE) && c == 223) {
            sp.set(curwin.w_cursor);
            curwin.w_cursor.set(pos);
            del_char(false);
            ins_char(7838);
            curwin.w_cursor.set(sp);
            return true;
        }
        nc = c;
        if (vim_islower(c)) {
            if (op_type != OP_LOWER) {
                nc = vim_toupper(c);
            }
        } else if (vim_isupper(c)) {
            if (op_type != OP_UPPER) {
                nc = vim_tolower(c);
            }
        }
        if (nc != c) {
            if (c >= 128 || nc >= 128) {
                sp_2.set(curwin.w_cursor);
                curwin.w_cursor.set(pos);
                del_bytes((long) utf_ptr2len(ml_get_cursor()), false, false);
                ins_char(nc);
                curwin.w_cursor.set(sp_2);
            } else {
                pbyte(pos.copy(), nc);
            }
            return true;
        }
        return false;
    }

