    void set_string_option_global(int opt_idx, Ptr<BytePtr> varp) {
        Ptr<BytePtr> p = null;
        BytePtr s = null;
        boolean t1 = false;
        if (is_window_local_option(opt_idx) != 0) {
            p = get_varp_allbuf(new Ptr<S_vimoption>(options, opt_idx)).ov_str;
        } else {
            p = get_option_var(opt_idx);
        }
        t1 = !is_global_option(opt_idx) && !Ptr.eq(p, varp);
        if (t1) {
            s = vim_strsave(varp.get());
            t1 = s != null;
        }
        if (t1) {
            free_string_option(p.get());
            p.put(s);
        }
    }

    void set_string_option_direct(BytePtr name, int opt_idx, BytePtr val, int opt_flags, int set_sid) {
        BytePtr s = null;
        Ptr<BytePtr> varp = null;
        boolean both = false;
        int idx = 0;
        both = (opt_flags & (OPT_LOCAL | OPT_GLOBAL)) == 0;
        idx = opt_idx;
        if (idx == -1) {
            idx = findoption(name);
            if (idx < 0) {
                vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(new BytePtr(e_internal_error_str, 0)), BytePtr.lit("set_string_option_direct()"));
                emsg(iobuff_or(gettext_(new BytePtr(e_internal_error_str, 0))));
                vim_snprintf(IObuff, emsg_iobuff_room(), BytePtr.lit("For option %s"), name);
                iemsg(iobuff_or(BytePtr.lit("For option %s")));
                return;
            }
        }
        if (is_hidden_option(idx)) {
            return;
        }
        s = vim_strsave(val);
        varp = get_option_varp_scope(idx, both ? OPT_LOCAL : opt_flags).ov_str;
        if ((opt_flags & OPT_FREE) != 0 && (get_option_flags(idx) & P_ALLOCED) != 0) {
            free_string_option(varp.get());
        }
        varp.put(s);
        if (both) {
            set_string_option_global(idx, varp);
        }
        set_option_flag(idx, P_ALLOCED);
        if (is_global_local_option(idx) != 0 && both) {
            free_string_option(varp.get());
            varp.put(empty_option);
        }
    }

