    BytePtr did_set_matchpairs(T_optset_T args) {
        Ptr<BytePtr> varp = null;
        BytePtr p = null;
        int x2 = 0;
        int x3 = 0;
        BytePtr t1 = null;
        varp = args.os_varp.ov_str;
        p = varp.get();
        for (; p.get() != NUL; p = p.add(1)) {
            x2 = -1;
            x3 = -1;
            p = p.add(utfc_ptr2len(p));
            if (p.get() != NUL) {
                t1 = p;
                p = p.add(1);
                x2 = t1.get() & 0xff;
            }
            if (p.get() != NUL) {
                x3 = utf_ptr2char(p);
                p = p.add(utfc_ptr2len(p));
            }
            if (x2 != ':' || x3 == -1 || (p.get() != NUL && p.get() != ',')) {
                return new BytePtr(e_invalid_argument, 0);
            }
            if (p.get() == NUL) {
                break;
            }
        }
        return null;
    }

