    BytePtr did_set_string_option(int opt_idx, Ptr<BytePtr> varp, BytePtr oldval, BytePtr value, BytePtr errbuf, long errbuflen, int opt_flags, int op, IntPtr value_checked) {
        BytePtr errmsg = null;
        long free_oldval = 0;
        Fn6 did_set_cb = null;
        T_optset_T args = new T_optset_T();
        Ptr<BytePtr> p = null;
        errmsg = null;
        free_oldval = get_option_flags(opt_idx) & P_ALLOCED;
        did_set_cb = get_option_did_set_cb(opt_idx);
        if (Ptr.eq(varp, new Ptr<BytePtr>(term_strings, KS_NAME))) {
            opt_idx = findoption(BytePtr.lit("term"));
            if (opt_idx >= 0) {
                free_oldval = get_option_flags(opt_idx) & P_ALLOCED;
                did_set_cb = get_option_did_set_cb(opt_idx);
            }
        }
        args.zero();
        if (secure != 0 && (get_option_flags(opt_idx) & P_SECURE) != 0) {
            errmsg = new BytePtr(e_not_allowed_here, 0);
        } else if (check_illegal_path_names(opt_idx, varp)) {
            errmsg = new BytePtr(e_invalid_argument, 0);
        } else if (did_set_cb != null) {
            args.os_varp.set(optvar_str(varp));
            args.os_idx = opt_idx;
            args.os_flags = opt_flags;
            args.os_op = op;
            args.os_oldval.string = oldval;
            args.os_newval.string = value;
            args.os_errbuf = errbuf;
            args.os_errbuflen = errbuflen;
            errmsg = did_set_cb.call(args);
            value_checked.put(args.os_value_checked);
        }
        if (errmsg != null) {
            free_string_option(varp.get());
            varp.put(oldval);
            if (args.os_restore_chartab) {
                init_chartab();
            }
            if (Ptr.eq(varp, new Ptr<BytePtr>(p_hl, 0))) {
                highlight_changed();
            }
        } else {
            if (free_oldval != 0) {
                free_string_option(oldval);
            }
            set_option_flag(opt_idx, P_ALLOCED);
            if ((opt_flags & (OPT_LOCAL | OPT_GLOBAL)) == 0 && is_global_local_option(opt_idx) != 0) {
                p = get_option_varp_scope(opt_idx, OPT_LOCAL).ov_str;
                free_string_option(p.get());
                p.put(empty_option);
            } else if ((opt_flags & OPT_LOCAL) == 0 && opt_flags != OPT_GLOBAL) {
                set_string_option_global(opt_idx, varp);
            }
        }
        if (curwin.w_curswant != MAXCOL && (get_option_flags(opt_idx) & (P_CURSWANT | P_RALL)) != 0L && (get_option_flags(opt_idx) & P_HLONLY) == 0L) {
            curwin.w_set_curswant = true;
        }
        if ((opt_flags & OPT_NO_REDRAW) == 0) {
            check_redraw(get_option_flags(opt_idx));
        }
        return errmsg;
    }

    boolean check_opt_strings(BytePtr val, Ptr<BytePtr> values, boolean list) {
        return opt_strings_flags(val, values, null, list);
    }

    boolean opt_strings_flags(BytePtr val, Ptr<BytePtr> values, IntPtr flagp, boolean list) {
        int i = 0;
        int len = 0;
        int new_flags = 0;
        new_flags = 0;
        while (val.get() != 0) {
            i = 0;
            for (; ; i++) {
                if (values.at(i) == null) {
                    return false;
                }
                len = (int) musl_strlen(values.at(i));
                if (musl_strncmp(values.at(i), val, (long) len) == 0 && ((list && val.at(len) == ',') || val.at(len) == NUL)) {
                    val = val.add(len + (val.at(len) == ',' ? 1 : 0));
                    new_flags |= 1 << i;
                    break;
                }
            }
        }
        if (flagp != null) {
            flagp.put(new_flags);
        }
        return true;
    }

    void mch_write(BytePtr s, int len) {
        vim_ignored = host_write(s, len);
        if (p_wd[0] != 0) {
            RealWaitForChar(read_cmd_fd, p_wd[0], null, null);
        }
    }

    int mch_inchar(BytePtr buf, int maxlen, long wtime, int tb_change_cnt) {
        return inchar_loop(buf, maxlen, wtime, tb_change_cnt, fp_WaitForChar, null);
    }

    void mch_delay(long msec, int flags) {
        if ((flags & MCH_DELAY_IGNOREINPUT) != 0) {
            out_flush();
            musl_delay(msec, TRUE);
        } else {
            WaitForChar(msec, null, FALSE);
        }
    }

    void deathtrap(int sigarg) {
        int i = 0;
        if (deathtrap_entered == 0 && (sigarg == SIGHUP || sigarg == SIGTERM) && !vim_handle_signal(sigarg)) {
            return;
        }
        deathtrap_entered++;
        block_autocmds();
        v_dying = deathtrap_entered;
        i = 0;
        for (; signal_info[i].sig != -1; i++) {
            if (sigarg == signal_info[i].sig) {
                break;
            }
        }
        full_screen = FALSE;
        if (deathtrap_entered == 2) {
            out_str(BytePtr.lit("Vim: Double signal, exiting\n"));
            out_flush();
            getout(1);
        }
        vim_snprintf(IObuff, 1025L, BytePtr.lit("Vim: Caught deadly signal %s\015\n"), signal_info[i].name);
        preserve_exit();
    }

    void mch_suspend() {
        out_flush();
        term_leave();
        out_flush();
        musl_suspend();
        term_enter();
    }

    void mch_init() {
        Columns[0] = 80L;
        Rows[0] = 24L;
        out_flush();
        musl_host_init();
    }

    boolean vim_handle_signal(int sig) {
        switch (sig) {
            case -1:
                vim_handle_signal_blocked = true;
                break;
            case -2:
                vim_handle_signal_blocked = false;
                if (vim_handle_signal_got_signal != 0) {
                    host_raise(vim_handle_signal_got_signal);
                    vim_handle_signal_got_signal = 0;
                }
                break;
            default:
                if (!vim_handle_signal_blocked) {
                    return true;
                }
                vim_handle_signal_got_signal = sig;
                got_int = TRUE;
                break;
        }
        return false;
    }

    boolean vim_is_xterm(BytePtr name) {
        if (name == null) {
            return false;
        }
        return (musl_strncasecmp(name, BytePtr.lit("xterm"), 5L) == 0 && musl_strncasecmp(name, BytePtr.lit("xterm-kitty"), 11L) != 0) || musl_strncasecmp(name, BytePtr.lit("nxterm"), 6L) == 0 || musl_strncasecmp(name, BytePtr.lit("kterm"), 5L) == 0 || musl_strncasecmp(name, BytePtr.lit("mlterm"), 6L) == 0 || musl_strncasecmp(name, BytePtr.lit("rxvt"), 4L) == 0 || musl_strncasecmp(name, BytePtr.lit("screen.xterm"), 12L) == 0 || musl_strcmp(name, BytePtr.lit("builtin_xterm")) == 0;
    }

    void exit_scroll() {
        if (newline_on_exit != 0 || msg_didout != 0) {
            if (msg_use_printf()) {
                if (info_message != 0) {
                    host_message(BytePtr.lit("\n"), -1, FALSE);
                } else {
                    host_message(BytePtr.lit("\015\n"), -1, TRUE);
                }
            } else {
                out_char('\n');
            }
        } else {
            restore_cterm_colors();
            msg_clr_eos_force();
            windgoto((int) Rows[0] - 1, cmdline_col_off);
        }
    }

    void mch_exit(int r) {
        exiting = TRUE;
        term_leave();
        if (swapping_screen() && newline_on_exit == 0) {
            exit_scroll();
        }
        stoptermcap();
        if (!swapping_screen() || newline_on_exit != 0) {
            exit_scroll();
        }
        if (full_screen != 0) {
            cursor_on();
        }
        out_flush();
        ml_close_all(true);
        host_exit(r);
    }

    void get_stty() {
        T_ttyinfo_T info = new T_ttyinfo_T();
        byte[] buf = new byte[2];
        BytePtr p = null;
        if (!get_tty_info(read_cmd_fd, info)) {
            return;
        }
        intr_char = info.interrupt;
        buf[0] = (byte) info.backspace;
        buf[1] = (byte) NUL;
        add_termcode(BytePtr.lit("kb"), new BytePtr(buf, 0), FALSE);
        p = find_termcode(BytePtr.lit("kD"));
        if (p != null && (p.at(0) & 0xff) == (buf[0] & 0xff) && (p.at(1) & 0xff) == (buf[1] & 0xff)) {
            do_fixdel(null);
        }
    }

    boolean get_tty_info(int fd, T_ttyinfo_T info) {
        int[] bs = new int[1];
        int[] intr = new int[1];
        int[] cr = new int[1];
        int[] nlcr = new int[1];
        bs[0] = 0;
        intr[0] = 0;
        cr[0] = 0;
        nlcr[0] = 0;
        if (musl_tty_keys(fd, new IntPtr(bs, 0), new IntPtr(intr, 0), new IntPtr(cr, 0), new IntPtr(nlcr, 0)) == OK) {
            info.backspace = (byte) bs[0] & 0xff;
            info.interrupt = (byte) intr[0] & 0xff;
            info.enter = cr[0] != 0 ? NL : CAR;
            info.nl_does_cr = (nlcr[0] != 0 ? TRUE : FALSE) != 0;
            return true;
        }
        return false;
    }

    void mch_set_shellsize() {
        if (term_strings[KS_CWS].get() != 0) {
            term_set_winsize((int) Rows[0], (int) Columns[0]);
            out_flush();
            screen_start();
        }
    }

    void mch_breakcheck(boolean force) {
        if ((term_entered != 0 || force) && RealWaitForChar(read_cmd_fd, 0L, null, null) != 0) {
            fill_input_buf(false);
        }
    }

    int WaitForChar(long msec, IntPtr interrupted, int ignore_input) {
        int avail = 0;
        if (ignore_input == 0 && input_available()) {
            return 1;
        }
        avail = RealWaitForChar(read_cmd_fd, msec, null, interrupted);
        return avail;
    }

    int RealWaitForChar(int fd, long msec, IntPtr check_for_gpm, IntPtr interrupted) {
        return musl_wait_for_input(msec);
    }

    int no_Magic(int x) {
        if (x < 0) {
            return x + 256;
        }
        return x;
    }

    int toggle_Magic(int x) {
        if (x < 0) {
            return x + 256;
        }
        return x - 256;
    }

    int re_multi_type(int c) {
        if (c == '@' - 256 || c == '=' - 256 || c == '?' - 256) {
            return MULTI_ONE;
        }
        if (c == '*' - 256 || c == '+' - 256 || c == '{' - 256) {
            return MULTI_MULT;
        }
        return NOT_MULTI;
    }

    int backslash_trans(int c) {
        switch (c) {
            case 'r':
                return CAR;
            case 't':
                return TAB;
            case 'e':
                return ESC;
            case 'b':
                return BS;
        }
        return c;
    }

    int get_char_class(Ptr<BytePtr> pp) {
        T_keyvalue_T target = new T_keyvalue_T();
        Ptr<T_keyvalue_T> entry = null;
        if (pp.get().at(1) == ':' && Integer.compareUnsigned((pp.get().at(2) & 0xff) - 'a', 26) < 0 && Integer.compareUnsigned((pp.get().at(3) & 0xff) - 'a', 26) < 0 && Integer.compareUnsigned((pp.get().at(4) & 0xff) - 'a', 26) < 0) {
            target.key = 0;
            target.value.string[0] = pp.get().add(2);
            target.value.length = 0L;
            if (get_char_class_last_entry != null && cmp_keyvalue_value_n(target, get_char_class_last_entry) == 0) {
                entry = get_char_class_last_entry;
            } else {
                entry = keyvalue_bsearch(target, new Ptr<T_keyvalue_T>(get_char_class_char_class_tab, 0), 19L, fp_cmp_keyvalue_value_n_Fn3);
            }
            if (entry != null) {
                get_char_class_last_entry = entry;
                pp.put(pp.get().add((int) (entry.get().value.length + 2L)));
                return entry.get().key;
            }
        }
        return CLASS_NONE;
    }

    void init_class_tab() {
        int i = 0;
        if (init_class_tab_done) {
            return;
        }
        i = 0;
        for (; i < 256; i++) {
            if (i >= '0' && i <= '7') {
                class_tab[i] = (short) (RI_DIGIT + RI_HEX + RI_OCTAL + RI_WORD);
            } else if (i >= '8' && i <= '9') {
                class_tab[i] = (short) (RI_DIGIT + RI_HEX + RI_WORD);
            } else if (i >= 'a' && i <= 'f') {
                class_tab[i] = (short) (RI_HEX + RI_WORD + RI_HEAD + RI_ALPHA + RI_LOWER);
            } else if (i >= 'g' && i <= 'z') {
                class_tab[i] = (short) (RI_WORD + RI_HEAD + RI_ALPHA + RI_LOWER);
            } else if (i >= 'A' && i <= 'F') {
                class_tab[i] = (short) (RI_HEX + RI_WORD + RI_HEAD + RI_ALPHA + RI_UPPER);
            } else if (i >= 'G' && i <= 'Z') {
                class_tab[i] = (short) (RI_WORD + RI_HEAD + RI_ALPHA + RI_UPPER);
            } else if (i == '_') {
                class_tab[i] = (short) (RI_WORD + RI_HEAD);
            } else {
                class_tab[i] = (short) 0;
            }
        }
        class_tab[' '] |= RI_WHITE;
        class_tab['\t'] |= RI_WHITE;
        init_class_tab_done = true;
    }

    int re_multiline(S_regprog prog) {
        return prog.regflags & RF_HASNL;
    }

    int get_coll_element(Ptr<BytePtr> pp) {
        int c = 0;
        int l = 0;
        BytePtr p = null;
        l = 1;
        p = pp.get();
        if (p.at(0) != NUL && p.at(1) == '.' && p.at(2) != NUL) {
            l = utfc_ptr2len(p.add(2));
            if (p.at(l + 2) == '.' && p.at(l + 3) == ']') {
                c = utf_ptr2char(p.add(2));
                pp.put(pp.get().add(l + 4));
                return c;
            }
        }
        return 0;
    }

    void get_cpo_flags() {
        reg_cpo_lit = vim_strchr(p_cpo[0], CPO_LITERAL) != null ? 1 : 0;
        reg_cpo_bsl = vim_strchr(p_cpo[0], CPO_BACKSL) != null ? 1 : 0;
    }

    BytePtr skip_anyof(BytePtr p_arg) {
        BytePtr[] p = new BytePtr[] {p_arg};
        int l = 0;
        if (p[0].get() == '^') {
            p[0] = p[0].add(1);
        }
        if (p[0].get() == ']' || p[0].get() == '-') {
            p[0] = p[0].add(1);
        }
        while (p[0].get() != NUL && p[0].get() != ']') {
            l = utfc_ptr2len(p[0]);
            if (l > 1) {
                p[0] = p[0].add(l);
            } else {
                if (p[0].get() == '-') {
                    p[0] = p[0].add(1);
                    if (p[0].get() != ']' && p[0].get() != NUL) {
                        p[0] = p[0].add(utfc_ptr2len(p[0]));
                    }
                } else if (p[0].get() == '\\' && reg_cpo_bsl == 0 && (vim_strchr(new BytePtr(REGEXP_INRANGE, 0), p[0].at(1) & 0xff) != null || (reg_cpo_lit == 0 && vim_strchr(new BytePtr(REGEXP_ABBR, 0), p[0].at(1) & 0xff) != null))) {
                    p[0] = p[0].add(2);
                } else if (p[0].get() == '[') {
                    if (get_char_class(new Ptr<BytePtr>(p, 0)) == CLASS_NONE && get_coll_element(new Ptr<BytePtr>(p, 0)) == 0 && p[0].get() != NUL) {
                        p[0] = p[0].add(1);
                    }
                } else {
                    p[0] = p[0].add(1);
                }
            }
        }
        return p[0];
    }

    BytePtr skip_regexp(BytePtr startp, int delim, int magic) {
        return skip_regexp_ex(startp, delim, magic, null, null, null);
    }

    BytePtr skip_regexp_ex(BytePtr startp, int dirc, int magic, Ptr<BytePtr> newp, IntPtr dropped, IntPtr magic_val) {
        int mymagic = 0;
        BytePtr p = null;
        long startplen = 0;
        p = startp;
        startplen = 0L;
        if (magic != 0) {
            mymagic = MAGIC_ON;
        } else {
            mymagic = MAGIC_OFF;
        }
        get_cpo_flags();
        for (; p.at(0) != NUL; p = p.add(utfc_ptr2len(p))) {
            if ((p.at(0) & 0xff) == dirc) {
                break;
            }
            if ((p.at(0) == '[' && mymagic >= MAGIC_ON) || (p.at(0) == '\\' && p.at(1) == '[' && mymagic <= MAGIC_OFF)) {
                p = skip_anyof(p.add(1));
                if (p.at(0) == NUL) {
                    break;
                }
            } else if (p.at(0) == '\\' && p.at(1) != NUL) {
                if (dirc == '?' && newp != null && p.at(1) == '?') {
                    if (startplen == 0L) {
                        startplen = musl_strlen(startp);
                    }
                    if (newp.get() == null) {
                        newp.put(vim_strnsave(startp, startplen));
                        if (newp.get() != null) {
                            p = newp.get().add((int) p.sub(startp));
                            startp = newp.get();
                        }
                    }
                    if (dropped != null) {
                        dropped.put(dropped.get() + 1);
                    }
                    if (newp.get() != null) {
                        Rt.memmove(p, p.add(1), startplen - p.add(1).sub(startp) + 1L);
                    } else {
                        p = p.add(1);
                    }
                } else {
                    p = p.add(1);
                }
                if (p.get() == 'v') {
                    mymagic = MAGIC_ALL;
                } else if (p.get() == 'V') {
                    mymagic = MAGIC_NONE;
                }
            }
        }
        if (magic_val != null) {
            magic_val.put(mymagic);
        }
        return p;
    }

    void initchr(BytePtr str) {
        regparse[0] = str;
        prevchr_len = 0;
        nextchr = -1;
        prevchr = nextchr;
        prevprevchr = prevchr;
        curchr = prevprevchr;
        at_start = TRUE;
        prev_at_start = FALSE;
    }

    int peekchr() {
        BytePtr p = null;
        boolean is_magic_all = false;
        int c = 0;
        if (curchr != -1) {
            return curchr;
        }
        curchr = regparse[0].at(0) & 0xff;
        switch (curchr) {
            case '.':
            case '[':
            case '~':
                if (reg_magic >= MAGIC_ON) {
                    curchr = curchr - 256;
                }
                break;
            case '(':
            case ')':
            case '{':
            case '%':
            case '+':
            case '=':
            case '?':
            case '@':
            case '!':
            case '&':
            case '|':
            case '<':
            case '>':
            case '#':
            case '"':
            case '\'':
            case ',':
            case '-':
            case ':':
            case ';':
            case '`':
            case '/':
                if (reg_magic == MAGIC_ALL) {
                    curchr = curchr - 256;
                }
                break;
            case '*':
                if (reg_magic >= MAGIC_ON && at_start == 0 && !(prev_at_start != 0 && prevchr == '^' - 256) && (peekchr_after_slash != 0 || (prevchr != '(' - 256 && prevchr != '&' - 256 && prevchr != '|' - 256))) {
                    curchr = '*' - 256;
                }
                break;
            case '^':
                if (reg_magic >= MAGIC_OFF && (at_start != 0 || reg_magic == MAGIC_ALL || prevchr == '(' - 256 || prevchr == '|' - 256 || prevchr == '&' - 256 || prevchr == 'n' - 256 || (no_Magic(prevchr) == '(' && prevprevchr == '%' - 256))) {
                    curchr = '^' - 256;
                    at_start = TRUE;
                    prev_at_start = FALSE;
                }
                break;
            case '$':
                if (reg_magic >= MAGIC_OFF) {
                    p = regparse[0].add(1);
                    is_magic_all = reg_magic == MAGIC_ALL;
                    while (p.at(0) == '\\' && (p.at(1) == 'c' || p.at(1) == 'C' || p.at(1) == 'm' || p.at(1) == 'M' || p.at(1) == 'v' || p.at(1) == 'V' || p.at(1) == 'Z')) {
                        if (p.at(1) == 'v') {
                            is_magic_all = true;
                        } else if (p.at(1) == 'm' || p.at(1) == 'M' || p.at(1) == 'V') {
                            is_magic_all = false;
                        }
                        p = p.add(2);
                    }
                    if (p.at(0) == NUL || (p.at(0) == '\\' && (p.at(1) == '|' || p.at(1) == '&' || p.at(1) == ')' || p.at(1) == 'n')) || (is_magic_all && (p.at(0) == '|' || p.at(0) == '&' || p.at(0) == ')')) || reg_magic == MAGIC_ALL) {
                        curchr = '$' - 256;
                    }
                }
                break;
            case '\\':
                c = regparse[0].at(1) & 0xff;
                if (c == NUL) {
                    curchr = '\\';
                } else if (c <= '~' && META_flags[c] != 0) {
                    curchr = -1;
                    prev_at_start = at_start;
                    at_start = FALSE;
                    regparse[0] = regparse[0].add(1);
                    peekchr_after_slash++;
                    peekchr();
                    regparse[0] = regparse[0].add(-1);
                    peekchr_after_slash--;
                    curchr = toggle_Magic(curchr);
                } else if (vim_strchr(new BytePtr(REGEXP_ABBR, 0), c) != null) {
                    curchr = backslash_trans(c);
                } else if (reg_magic == MAGIC_NONE && (c == '$' || c == '^')) {
                    curchr = toggle_Magic(c);
                } else {
                    if (c >= 128) {
                        curchr = utf_ptr2char(regparse[0].add(1));
                    } else {
                        curchr = c;
                    }
                }
                break;
            default:
                if (curchr >= 128) {
                    curchr = utf_ptr2char(regparse[0]);
                }
        }
        return curchr;
    }

    void skipchr() {
        if (regparse[0].get() == '\\') {
            prevchr_len = 1;
        } else {
            prevchr_len = 0;
        }
        if (regparse[0].at(prevchr_len) != NUL) {
            if ((regparse[0].at(prevchr_len) & 0xff) < 128) {
                prevchr_len++;
            } else {
                prevchr_len += utf_ptr2len(regparse[0].add(prevchr_len));
            }
        }
        regparse[0] = regparse[0].add(prevchr_len);
        prev_at_start = at_start;
        at_start = FALSE;
        prevprevchr = prevchr;
        prevchr = curchr;
        curchr = nextchr;
        nextchr = -1;
    }

    void skipchr_keepstart() {
        int as = 0;
        int pr = 0;
        int prpr = 0;
        as = prev_at_start;
        pr = prevchr;
        prpr = prevprevchr;
        skipchr();
        at_start = as;
        prevchr = pr;
        prevprevchr = prpr;
    }

    int getchr() {
        int chr = 0;
        chr = peekchr();
        skipchr();
        return chr;
    }

    void ungetchr() {
        nextchr = curchr;
        curchr = prevchr;
        prevchr = prevprevchr;
        at_start = prev_at_start;
        prev_at_start = FALSE;
        regparse[0] = regparse[0].add(-prevchr_len);
    }

    long gethexchrs(int maxinputlen) {
        long nr = 0;
        int c = 0;
        int i = 0;
        nr = 0L;
        i = 0;
        for (; i < maxinputlen; i++) {
            c = regparse[0].at(0) & 0xff;
            if (!vim_isxdigit(c)) {
                break;
            }
            nr <<= 4;
            nr |= (long) hex2nr(c);
            regparse[0] = regparse[0].add(1);
        }
        if (i == 0) {
            return -1L;
        }
        return nr;
    }

    long getdecchrs() {
        long nr = 0;
        int c = 0;
        int i = 0;
        nr = 0L;
        i = 0;
        for (; ; i++) {
            c = regparse[0].at(0) & 0xff;
            if (c < '0' || c > '9') {
                break;
            }
            nr *= 10L;
            nr += (long) (c - '0');
            regparse[0] = regparse[0].add(1);
            curchr = -1;
        }
        if (i == 0) {
            return -1L;
        }
        return nr;
    }

    long getoctchrs() {
        long nr = 0;
        int c = 0;
        int i = 0;
        nr = 0L;
        i = 0;
        for (; (i < 3) && Long.compareUnsigned(nr, 32L) < 0; i++) {
            c = regparse[0].at(0) & 0xff;
            if (c < '0' || c > '7') {
                break;
            }
            nr <<= 3;
            nr |= (long) hex2nr(c);
            regparse[0] = regparse[0].add(1);
        }
        if (i == 0) {
            return -1L;
        }
        return nr;
    }

    int read_limits(LongPtr minval, LongPtr maxval) {
        boolean reverse = false;
        BytePtr first_char = null;
        long tmp = 0;
        reverse = false;
        if (regparse[0].get() == '-') {
            regparse[0] = regparse[0].add(1);
            reverse = true;
        }
        first_char = regparse[0];
        minval.put(getdigits(new Ptr<BytePtr>(regparse, 0)));
        if (regparse[0].get() == ',') {
            regparse[0] = regparse[0].add(1);
            if (vim_isdigit(regparse[0].get() & 0xff)) {
                maxval.put(getdigits(new Ptr<BytePtr>(regparse, 0)));
            } else {
                maxval.put(2147418112L);
            }
        } else if (Integer.compareUnsigned((first_char.get() & 0xff) - '0', 10) < 0) {
            maxval.put(minval.get());
        } else {
            maxval.put(2147418112L);
        }
        if (regparse[0].get() == '\\') {
            regparse[0] = regparse[0].add(1);
        }
        if (regparse[0].get() != '}') {
            vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(new BytePtr(e_syntax_error_in_str_curlies, 0)), reg_magic == MAGIC_ALL ? BytePtr.lit("") : BytePtr.lit("\\"));
            emsg(iobuff_or(gettext_(new BytePtr(e_syntax_error_in_str_curlies, 0))));
            rc_did_emsg = TRUE;
            return FAIL;
        }
        if ((!reverse && minval.get() > maxval.get()) || (reverse && minval.get() < maxval.get())) {
            tmp = minval.get();
            minval.put(maxval.get());
            maxval.put(tmp);
        }
        skipchr();
        return OK;
    }

    boolean reg_iswordc(int c) {
        return vim_iswordc_buf(c, rex.reg_buf);
    }

    void reg_getline_common(long lnum, int flags, Ptr<BytePtr> line, IntPtr length) {
        int get_line = 0;
        int get_length = 0;
        long firstlnum = 0;
        long maxline = 0;
        get_line = flags & RGLF_LINE;
        get_length = flags & RGLF_LENGTH;
        firstlnum = rex.reg_firstlnum + lnum;
        maxline = rex.reg_maxline;
        if (firstlnum < 1L) {
            if (get_line != 0) {
                line.put(null);
            }
            if (get_length != 0) {
                length.put(0);
            }
            return;
        }
        if (lnum > maxline) {
            if (get_line != 0) {
                line.put(BytePtr.lit(""));
            }
            if (get_length != 0) {
                length.put(0);
            }
            return;
        }
        if (get_line != 0) {
            line.put(ml_get_buf(rex.reg_buf, firstlnum, false));
        }
        if (get_length != 0) {
            length.put(ml_get_buf_len(rex.reg_buf, firstlnum));
        }
    }

    BytePtr reg_getline(long lnum) {
        BytePtr[] line = new BytePtr[1];
        reg_getline_common(lnum, RGLF_LINE, new Ptr<BytePtr>(line, 0), null);
        return line[0];
    }

    int reg_getline_len(long lnum) {
        int[] length = new int[1];
        reg_getline_common(lnum, RGLF_LENGTH, null, new IntPtr(length, 0));
        return length[0];
    }

    int reg_prev_class() {
        if (rex.input.gt(rex.line)) {
            return mb_get_class_buf(rex.input.add(-1).add(-utf_head_off(rex.line, rex.input.add(-1))), rex.reg_buf);
        }
        return -1;
    }

    boolean reg_match_visual() {
        T_pos_T top = new T_pos_T();
        T_pos_T bot = new T_pos_T();
        long lnum = 0;
        int col = 0;
        S_window_S wp = null;
        int mode = 0;
        int[] start = new int[1];
        int[] end = new int[1];
        int[] start2 = new int[1];
        int[] end2 = new int[1];
        int cols = 0;
        int curswant = 0;
        wp = rex.reg_win == null ? curwin : rex.reg_win;
        if (!(rex.reg_buf == curbuf) || VIsual.lnum[0] == 0L || !(rex.reg_match == null)) {
            return false;
        }
        if (VIsual_active != 0) {
            if (VIsual.lnum[0] != wp.w_cursor.lnum[0] ? VIsual.lnum[0] < wp.w_cursor.lnum[0] : (VIsual.col[0] != wp.w_cursor.col[0] ? VIsual.col[0] < wp.w_cursor.col[0] : VIsual.coladd < wp.w_cursor.coladd)) {
                top.set(VIsual);
                bot.set(wp.w_cursor);
            } else {
                top.set(wp.w_cursor);
                bot.set(VIsual);
            }
            mode = VIsual_mode;
            curswant = wp.w_curswant;
        } else {
            if (curbuf.b_visual.vi_start.lnum[0] != curbuf.b_visual.vi_end.lnum[0] ? curbuf.b_visual.vi_start.lnum[0] < curbuf.b_visual.vi_end.lnum[0] : (curbuf.b_visual.vi_start.col[0] != curbuf.b_visual.vi_end.col[0] ? curbuf.b_visual.vi_start.col[0] < curbuf.b_visual.vi_end.col[0] : curbuf.b_visual.vi_start.coladd < curbuf.b_visual.vi_end.coladd)) {
                top.set(curbuf.b_visual.vi_start);
                bot.set(curbuf.b_visual.vi_end);
            } else {
                top.set(curbuf.b_visual.vi_end);
                bot.set(curbuf.b_visual.vi_start);
            }
            if (bot.lnum[0] > curbuf.b_ml.ml_line_count) {
                bot.lnum[0] = curbuf.b_ml.ml_line_count;
            }
            mode = curbuf.b_visual.vi_mode;
            curswant = curbuf.b_visual.vi_curswant;
        }
        lnum = rex.lnum + rex.reg_firstlnum;
        if (lnum < top.lnum[0] || lnum > bot.lnum[0]) {
            return false;
        }
        col = (int) rex.input.sub(rex.line);
        if (mode == 'v') {
            if ((lnum == top.lnum[0] && col < top.col[0]) || (lnum == bot.lnum[0] && col >= bot.col[0] + (p_sel[0].get() != 'e' ? 1 : 0))) {
                return false;
            }
        } else if (mode == Ctrl_V) {
            getvvcol(wp, top, new IntPtr(start, 0), null, new IntPtr(end, 0), 0);
            getvvcol(wp, bot, new IntPtr(start2, 0), null, new IntPtr(end2, 0), 0);
            if (start2[0] < start[0]) {
                start[0] = start2[0];
            }
            if (end2[0] > end[0]) {
                end[0] = end2[0];
            }
            if (top.col[0] == MAXCOL || bot.col[0] == MAXCOL || curswant == MAXCOL) {
                end[0] = MAXCOL;
            }
            rex.line = reg_getline(rex.lnum);
            rex.input = rex.line.add(col);
            cols = win_linetabsize(wp, rex.reg_firstlnum + rex.lnum, rex.line, col);
            if (cols < start[0] || cols > (end[0] - (p_sel[0].get() == 'e' ? 1 : 0))) {
                return false;
            }
        }
        return true;
    }

    boolean prog_magic_wrong() {
        S_regprog prog = null;
        prog = rex.reg_match == null ? rex.reg_mmatch.regprog : rex.reg_match.regprog;
        if ((prog.program.get() & 0xff) != REGMAGIC) {
            iemsg(new BytePtr(e_corrupted_regexp_program, 0));
            return true;
        }
        return false;
    }

    void cleanup_subexpr() {
        Ptr<T_lpos_T> t1 = null;
        int t2 = 0;
        Ptr<T_lpos_T> t3 = null;
        int t4 = 0;
        if (rex.need_clear_subexpr == 0) {
            return;
        }
        if (rex.reg_match == null) {
            t1 = rex.reg_startpos;
            for (t2 = 0; t2 < 10; t2++) {
                t1.at(t2).lnum = -1L;
                t1.at(t2).col = -1;
            }
            t3 = rex.reg_endpos;
            for (t4 = 0; t4 < 10; t4++) {
                t3.at(t4).lnum = -1L;
                t3.at(t4).col = -1;
            }
        } else {
            Rt.zero(rex.reg_startp, 10);
            Rt.zero(rex.reg_endp, 10);
        }
        rex.need_clear_subexpr = FALSE;
    }

    void reg_nextline() {
        rex.lnum++;
        rex.line = reg_getline(rex.lnum);
        rex.input = rex.line;
        fast_breakcheck();
    }

    int match_with_backref(long start_lnum, int start_col, long end_lnum, int end_col, IntPtr bytelen) {
        long clnum = 0;
        int ccol = 0;
        int[] len = new int[1];
        BytePtr p = null;
        clnum = start_lnum;
        ccol = start_col;
        if (bytelen != null) {
            bytelen.put(0);
        }
        for (;;) {
            if (!BytePtr.eq(rex.line, reg_tofree)) {
                len[0] = (int) musl_strlen(rex.line);
                if (reg_tofree == null || len[0] >= reg_tofreelen) {
                    len[0] += 50;
                    reg_tofree = BytePtr.alloc((long) len[0]);
                    reg_tofreelen = len[0];
                }
                musl_strcpy(reg_tofree, rex.line);
                rex.input = reg_tofree.add((int) rex.input.sub(rex.line));
                rex.line = reg_tofree;
            }
            p = reg_getline(clnum);
            if (clnum == end_lnum) {
                len[0] = end_col - ccol;
            } else {
                len[0] = reg_getline_len(clnum) - ccol;
            }
            if ((rex.reg_ic == 0 && cstrncmp(p.add(ccol), rex.input, new IntPtr(len, 0)) != 0) || (rex.reg_ic != 0 && mb_strnicmp(p.add(ccol), rex.input, (long) len[0]) != 0)) {
                return RA_NOMATCH;
            }
            if (bytelen != null) {
                bytelen.put(bytelen.get() + len[0]);
            }
            if (clnum == end_lnum) {
                break;
            }
            if (rex.lnum >= rex.reg_maxline) {
                return RA_NOMATCH;
            }
            reg_nextline();
            if (bytelen != null) {
                bytelen.put(0);
            }
            clnum++;
            ccol = 0;
            if (got_int != 0) {
                return RA_FAIL;
            }
        }
        return RA_MATCH;
    }

