    void free_screenlines() {
        int i = 0;
        ScreenLinesUC = null;
        i = 0;
        for (; i < Screen_mco; i++) {
            ScreenLinesC[i] = null;
        }
        ScreenLines2 = null;
        ScreenLines = null;
        ScreenAttrs = null;
        ScreenCols = null;
        LineOffset = null;
        LineWraps = null;
        TabPageIdxs = null;
    }

    boolean screenclear() {
        check_for_delay(false);
        screenalloc(false);
        return screenclear2(true);
    }

    void redraw_as_cleared() {
        screenclear2(false);
    }

    boolean screenclear2(boolean doclear) {
        int i = 0;
        boolean did_clear = false;
        did_clear = false;
        if (starting == NO_SCREEN || ScreenLines == null) {
            return false;
        }
        screen_attr = -1;
        screen_stop_highlight();
        i = 0;
        for (; ((long) i) < Rows[0]; i++) {
            lineclear(LineOffset.at(i), (int) Columns[0], 0);
            LineWraps.set(i, (byte) FALSE);
        }
        if (doclear && can_clear(term_strings[KS_CL])) {
            out_str(term_strings[KS_CL]);
            did_clear = true;
            clear_cmdline = FALSE;
            mode_displayed = FALSE;
        } else {
            i = 0;
            for (; ((long) i) < Rows[0]; i++) {
                lineinvalid(LineOffset.at(i), (int) Columns[0]);
            }
            clear_cmdline = TRUE;
        }
        screen_cleared = TRUE;
        win_rest_invalid(curwin);
        redraw_cmdline = TRUE;
        redraw_tabline = TRUE;
        if (must_redraw == UPD_CLEAR) {
            must_redraw = UPD_NOT_VALID;
        }
        msg_scrolled = 0;
        compute_cmdrow();
        msg_row = cmdline_row;
        msg_col = 0;
        screen_start();
        msg_didany = FALSE;
        msg_didout = FALSE;
        return did_clear;
    }

    void lineclear(int off, int width, int attr) {
        Rt.memset(ScreenLines.add(off), ' ', (long) width * 1L);
        Rt.fill(ScreenLinesUC.add(off), 0, (int) (long) width);
        Rt.fill(ScreenAttrs.add(off), (short) ((attr & 0xff) * 0x0101), (int) (long) width);
        Rt.fill(ScreenCols.add(off), -1, (int) (long) width);
    }

    void lineinvalid(int off, int width) {
        Rt.fill(ScreenAttrs.add(off), (short) -1, (int) (long) width);
        Rt.fill(ScreenCols.add(off), -1, (int) (long) width);
    }

    void linecopy(int to_, int from, S_window_S wp) {
        int off_to = 0;
        int off_from = 0;
        int i = 0;
        off_to = LineOffset.at(to_) + wp.w_wincol;
        off_from = LineOffset.at(from) + wp.w_wincol;
        Rt.memmove(ScreenLines.add(off_to), ScreenLines.add(off_from), (long) wp.w_width * 1L);
        Rt.memmove(ScreenLinesUC.add(off_to), ScreenLinesUC.add(off_from), wp.w_width);
        i = 0;
        for (; ((long) i) < p_mco[0]; i++) {
            Rt.memmove(ScreenLinesC[i].add(off_to), ScreenLinesC[i].add(off_from), wp.w_width);
        }
        Rt.memmove(ScreenAttrs.add(off_to), ScreenAttrs.add(off_from), wp.w_width);
        Rt.memmove(ScreenCols.add(off_to), ScreenCols.add(off_from), wp.w_width);
    }

    boolean can_clear(BytePtr p) {
        return p.get() != NUL && (t_colors <= 1 || cterm_normal_bg_color == 0 || term_strings[KS_UT].get() != NUL);
    }

    void screen_start() {
        screen_cur_col = 9999;
        screen_cur_row = screen_cur_col;
    }

    void windgoto(int row, int col) {
        ShortPtr p = null;
        int i = 0;
        int plan = 0;
        int cost = 0;
        int wouldbe_col = 0;
        int noinvcurs = 0;
        BytePtr bs = null;
        int goto_cost = 0;
        int attr = 0;
        ShortPtr t1 = null;
        boolean t2 = false;
        ShortPtr t3 = null;
        boolean t4 = false;
        int t5 = 0;
        int off = 0;
        int t6 = 0;
        if (ScreenLines == null) {
            return;
        }
        if (col == screen_cur_col && row == screen_cur_row) {
            return;
        }
        if (row < 0) {
            row = 0;
        }
        if (row >= screen_Rows) {
            row = screen_Rows - 1;
        }
        if (col >= screen_Columns) {
            col = screen_Columns - 1;
        }
        if (screen_attr != 0 && term_strings[KS_MS].get() == NUL) {
            noinvcurs = HIGHL_COST;
        } else {
            noinvcurs = 0;
        }
        goto_cost = GOTO_COST + noinvcurs;
        if (row >= screen_cur_row && (long) screen_cur_col < Columns[0]) {
            bs = null;
            attr = screen_attr;
            if (row == screen_cur_row && col < screen_cur_col) {
                if (term_strings[KS_LE].get() != 0) {
                    bs = term_strings[KS_LE];
                } else {
                    bs = term_strings[KS_BC];
                }
                if (bs.get() != 0) {
                    cost = (screen_cur_col - col) * (int) musl_strlen(bs);
                } else {
                    cost = 999;
                }
                if (col + 1 < cost) {
                    plan = PLAN_CR;
                    wouldbe_col = 0;
                    cost = 1;
                } else {
                    plan = PLAN_LE;
                    wouldbe_col = col;
                }
                if (noinvcurs != 0) {
                    cost += noinvcurs;
                    attr = 0;
                }
            } else if (row > screen_cur_row) {
                plan = PLAN_NL;
                wouldbe_col = 0;
                cost = (row - screen_cur_row) * 2;
                if (noinvcurs != 0) {
                    cost += noinvcurs;
                    attr = 0;
                }
            } else {
                plan = PLAN_WRITE;
                wouldbe_col = screen_cur_col;
                cost = 0;
            }
            i = col - wouldbe_col;
            if (i > 0) {
                cost += i;
            }
            if (cost < goto_cost && i > 0) {
                p = ScreenAttrs.add(LineOffset.at(row)).add(wouldbe_col);
                while (true) {
                    t2 = i != 0;
                    if (t2) {
                        t1 = p;
                        p = p.add(1);
                        t2 = (t1.get() & 0xffff) == attr;
                    }
                    if (!t2) {
                        break;
                    }
                    i--;
                }
                if (i != 0) {
                    p = p.add(-1);
                    if (p.get() == 0) {
                        cost += noinvcurs;
                        while (true) {
                            t4 = i != 0;
                            if (t4) {
                                t3 = p;
                                p = p.add(1);
                                t4 = t3.get() == 0;
                            }
                            if (!t4) {
                                break;
                            }
                            i--;
                        }
                    }
                    if (i != 0) {
                        cost = 999;
                    }
                }
                i = wouldbe_col;
                for (; i < col; i++) {
                    if (ScreenLinesUC.at(LineOffset.at(row) + i) != 0) {
                        cost = 999;
                        break;
                    }
                }
            }
            if (cost < goto_cost) {
                if (plan == PLAN_LE) {
                    if (noinvcurs != 0) {
                        screen_stop_highlight();
                    }
                    while (screen_cur_col > col) {
                        out_str(bs);
                        screen_cur_col--;
                    }
                } else if (plan == PLAN_CR) {
                    if (noinvcurs != 0) {
                        screen_stop_highlight();
                    }
                    out_char('\r');
                    screen_cur_col = 0;
                } else if (plan == PLAN_NL) {
                    if (noinvcurs != 0) {
                        screen_stop_highlight();
                    }
                    while (screen_cur_row < row) {
                        out_char('\n');
                        screen_cur_row++;
                    }
                    screen_cur_col = 0;
                }
                i = col - screen_cur_col;
                if (i > 0) {
                    if (term_strings[KS_ND].at(0) != NUL && term_strings[KS_ND].at(1) == NUL) {
                        while (true) {
                            t5 = i;
                            i--;
                            if (!(t5 > 0)) {
                                break;
                            }
                            out_char(term_strings[KS_ND].get() & 0xff);
                        }
                    } else {
                        off = LineOffset.at(row) + screen_cur_col;
                        while (true) {
                            t6 = i;
                            i--;
                            if (!(t6 > 0)) {
                                break;
                            }
                            if ((ScreenAttrs.at(off) & 0xffff) != screen_attr) {
                                screen_stop_highlight();
                            }
                            out_char(ScreenLines.at(off) & 0xff);
                            off++;
                        }
                    }
                }
            }
        } else {
            cost = 999;
        }
        if (cost >= goto_cost) {
            if (noinvcurs != 0) {
                screen_stop_highlight();
            }
            if (row == screen_cur_row && col > screen_cur_col && term_strings[KS_CRI].get() != NUL) {
                term_cursor_right(col - screen_cur_col);
            } else {
                term_windgoto(row, col);
            }
        }
        screen_cur_row = row;
        screen_cur_col = col;
    }

    void setcursor() {
        setcursor_mayforce(false);
    }

    void setcursor_mayforce(boolean force) {
        if (force || redrawing()) {
            validate_cursor();
            windgoto(curwin.w_winrow + curwin.w_wrow, curwin.w_wincol + curwin.w_wcol);
        }
    }

    int win_ins_lines(S_window_S wp, int row, int line_count, boolean invalid, boolean mayclear) {
        boolean did_delete = false;
        int nextrow = 0;
        int lastrow = 0;
        int retval = 0;
        if (invalid) {
            wp.w_lines_valid = 0;
        }
        if (wp.w_height < 5) {
            return FAIL;
        }
        if (line_count > (wp.w_height - row)) {
            line_count = wp.w_height - row;
        }
        retval = win_do_lines(wp, row, line_count, mayclear, false, 0);
        if (retval != MAYBE) {
            return retval;
        }
        did_delete = false;
        if (wp.w_status_height != 0) {
            if (screen_del_lines(0, wp.w_winrow + wp.w_height - line_count, line_count, (int) Rows[0], false, 0, null)) {
                did_delete = true;
            }
        }
        if (!did_delete) {
            wp.w_redr_status = true;
            redraw_cmdline = TRUE;
            nextrow = wp.w_winrow + wp.w_height + wp.w_status_height;
            lastrow = nextrow + line_count;
            if ((long) lastrow > Rows[0]) {
                lastrow = (int) Rows[0];
            }
            screen_fill(nextrow - line_count, lastrow - line_count, wp.w_wincol, wp.w_wincol + wp.w_width, ' ', ' ', 0);
        }
        if (!screen_ins_lines(0, wp.w_winrow + row, line_count, (int) Rows[0], 0, null)) {
            if (did_delete) {
                wp.w_redr_status = true;
            }
            return FAIL;
        }
        return OK;
    }

    int win_del_lines(S_window_S wp, int row, int line_count, boolean invalid, boolean mayclear, int clear_attr) {
        int retval = 0;
        if (invalid) {
            wp.w_lines_valid = 0;
        }
        if (line_count > (wp.w_height - row)) {
            line_count = wp.w_height - row;
        }
        retval = win_do_lines(wp, row, line_count, mayclear, true, clear_attr);
        if (retval != MAYBE) {
            return retval;
        }
        if (!screen_del_lines(0, wp.w_winrow + row, line_count, (int) Rows[0], false, clear_attr, null)) {
            return FAIL;
        }
        if (wp.w_status_height != 0 || (long) cmdline_row < Rows[0] - 1L) {
            if (!screen_ins_lines(0, wp.w_winrow + wp.w_height - line_count, line_count, (int) Rows[0], clear_attr, null)) {
                wp.w_redr_status = true;
            }
        } else {
            redraw_cmdline = TRUE;
        }
        return OK;
    }

    int win_do_lines(S_window_S wp, int row, int line_count, boolean mayclear, boolean del, int clear_attr) {
        boolean retval = false;
        if (!redrawing() || line_count <= 0) {
            return FAIL;
        }
        if (no_win_do_lines_ins != 0 && !del) {
            return FAIL;
        }
        if (mayclear && Rows[0] - (long) line_count < 5L && wp.w_width == topframe.fr_width) {
            if (no_win_do_lines_ins == 0) {
                redraw_as_cleared();
            }
            return FAIL;
        }
        if (row + line_count >= wp.w_height) {
            screen_fill(wp.w_winrow + row, wp.w_winrow + wp.w_height, wp.w_wincol, wp.w_wincol + wp.w_width, ' ', ' ', 0);
            return OK;
        }
        if (no_win_do_lines_ins == 0) {
            clear_cmdline = TRUE;
        }
        if (scroll_region != 0 || wp.w_width != topframe.fr_width) {
            if (scroll_region != 0 && (wp.w_width == topframe.fr_width || term_strings[KS_CSV].get() != NUL)) {
                scroll_region_set(wp, row);
            }
            if (del) {
                retval = screen_del_lines(wp.w_winrow + row, 0, line_count, wp.w_height - row, false, clear_attr, wp);
            } else {
                retval = screen_ins_lines(wp.w_winrow + row, 0, line_count, wp.w_height - row, clear_attr, wp);
            }
            if (scroll_region != 0 && (wp.w_width == topframe.fr_width || term_strings[KS_CSV].get() != NUL)) {
                scroll_region_reset();
            }
            return retval ? 1 : 0;
        }
        return MAYBE;
    }

    void win_rest_invalid(S_window_S wp) {
        redraw_win_later(wp, UPD_NOT_VALID);
        wp.w_redr_status = true;
        redraw_cmdline = TRUE;
    }

    boolean screen_ins_lines(int off, int row, int line_count, int end, int clear_attr, S_window_S wp) {
        int i = 0;
        int j = 0;
        int temp = 0;
        int cursor_row = 0;
        int cursor_col = 0;
        int type = 0;
        boolean result_empty = false;
        boolean can_ce = false;
        cursor_col = 0;
        can_ce = can_clear(term_strings[KS_CE]);
        if (!screen_valid(true) || line_count <= 0 || (long) line_count > p_ttyscroll[0] || (long) end > Rows[0]) {
            return false;
        }
        result_empty = row + line_count >= end;
        if (wp != null && wp.w_width != topframe.fr_width && term_strings[KS_CSV].get() == NUL) {
            if (line_count > 3) {
                return false;
            }
            type = USE_REDRAW;
        } else if (can_clear(term_strings[KS_CD]) && result_empty) {
            type = USE_T_CD;
        } else if (term_strings[KS_CAL].get() != NUL && (line_count > 1 || term_strings[KS_AL].get() == NUL)) {
            type = USE_T_CAL;
        } else if (term_strings[KS_CDL].get() != NUL && result_empty && (line_count > 1 || !can_ce)) {
            type = USE_T_CDL;
        } else if (term_strings[KS_AL].get() != NUL) {
            type = USE_T_AL;
        } else if (can_ce && result_empty) {
            type = USE_T_CE;
        } else if (term_strings[KS_DL].get() != NUL && result_empty) {
            type = USE_T_DL;
        } else if (term_strings[KS_SR].get() != NUL && row == 0 && (term_strings[KS_DA].get() == NUL || can_ce)) {
            type = USE_T_SR;
        } else {
            return false;
        }
        if (type == USE_T_CD || type == USE_T_CDL || type == USE_T_CE || type == USE_T_DL) {
            return screen_del_lines(off, row, line_count, end, false, 0, wp);
        }
        if (term_strings[KS_DB].get() != 0) {
            screen_del_lines(off, end - line_count, line_count, end, false, 0, wp);
        }
        if (wp != null && wp.w_wincol != 0 && term_strings[KS_CSV].get() != NUL && term_strings[KS_CCS].get() == NUL) {
            cursor_col = wp.w_wincol;
        }
        if (term_strings[KS_CCS].get() != NUL) {
            cursor_row = row;
        } else {
            cursor_row = row + off;
        }
        row += off;
        end += off;
        i = 0;
        for (; i < line_count; i++) {
            if (wp != null && wp.w_width != topframe.fr_width) {
                j = end - 1 - i;
                while (true) {
                    j -= line_count;
                    if (!(j >= row)) {
                        break;
                    }
                    linecopy(j + line_count, j, wp);
                }
                j += line_count;
                if (can_clear(BytePtr.lit(" "))) {
                    lineclear(LineOffset.at(j) + wp.w_wincol, wp.w_width, clear_attr);
                } else {
                    lineinvalid(LineOffset.at(j) + wp.w_wincol, wp.w_width);
                }
                LineWraps.set(j, (byte) FALSE);
            } else {
                j = end - 1 - i;
                temp = LineOffset.at(j);
                while (true) {
                    j -= line_count;
                    if (!(j >= row)) {
                        break;
                    }
                    LineOffset.set(j + line_count, LineOffset.at(j));
                    LineWraps.set(j + line_count, LineWraps.at(j));
                }
                LineOffset.set(j + line_count, temp);
                LineWraps.set(j + line_count, (byte) FALSE);
                if (can_clear(BytePtr.lit(" "))) {
                    lineclear(temp, (int) Columns[0], clear_attr);
                } else {
                    lineinvalid(temp, (int) Columns[0]);
                }
            }
        }
        screen_stop_highlight();
        windgoto(cursor_row, cursor_col);
        if (clear_attr != 0) {
            screen_start_highlight(clear_attr);
        }
        if (type == USE_REDRAW) {
            redraw_block(row, end, wp);
        } else if (type == USE_T_CAL) {
            term_append_lines(line_count);
            screen_start();
        } else {
            i = 0;
            for (; i < line_count; i++) {
                if (type == USE_T_AL) {
                    if (i != 0 && cursor_row != 0) {
                        windgoto(cursor_row, cursor_col);
                    }
                    out_str(term_strings[KS_AL]);
                } else {
                    out_str(term_strings[KS_SR]);
                }
                screen_start();
            }
        }
        if (type == USE_T_SR && term_strings[KS_DA].get() != 0) {
            i = 0;
            for (; i < line_count; i++) {
                windgoto(off + i, cursor_col);
                out_str(term_strings[KS_CE]);
                screen_start();
            }
        }
        return true;
    }

    boolean screen_del_lines(int off, int row, int line_count, int end, boolean force, int clear_attr, S_window_S wp) {
        int j = 0;
        int i = 0;
        int temp = 0;
        int cursor_row = 0;
        int cursor_col = 0;
        int cursor_end = 0;
        boolean result_empty = false;
        boolean can_delete = false;
        int type = 0;
        cursor_col = 0;
        if (!screen_valid(true) || line_count <= 0 || (!force && (long) line_count > p_ttyscroll[0]) || (long) end > Rows[0]) {
            return false;
        }
        result_empty = row + line_count >= end;
        can_delete = term_strings[KS_DB].get() == NUL || can_clear(term_strings[KS_CE]);
        if (wp != null && wp.w_width != topframe.fr_width && term_strings[KS_CSV].get() == NUL) {
            if (line_count > 3) {
                return false;
            }
            type = USE_REDRAW;
        } else if (can_clear(term_strings[KS_CD]) && result_empty) {
            type = USE_T_CD;
        } else if (row == 0 && (line_count == 1 || term_strings[KS_CDL].get() == NUL)) {
            type = USE_NL;
        } else if (term_strings[KS_CDL].get() != NUL && line_count > 1 && can_delete) {
            type = USE_T_CDL;
        } else if (can_clear(term_strings[KS_CE]) && result_empty && (wp == null || wp.w_width == topframe.fr_width)) {
            type = USE_T_CE;
        } else if (term_strings[KS_DL].get() != NUL && can_delete) {
            type = USE_T_DL;
        } else if (term_strings[KS_CDL].get() != NUL && can_delete) {
            type = USE_T_CDL;
        } else {
            return false;
        }
        if (wp != null && wp.w_wincol != 0 && term_strings[KS_CSV].get() != NUL && term_strings[KS_CCS].get() == NUL) {
            cursor_col = wp.w_wincol;
        }
        if (term_strings[KS_CCS].get() != NUL) {
            cursor_row = row;
            cursor_end = end;
        } else {
            cursor_row = row + off;
            cursor_end = end + off;
        }
        row += off;
        end += off;
        i = 0;
        for (; i < line_count; i++) {
            if (wp != null && wp.w_width != topframe.fr_width) {
                j = row + i;
                while (true) {
                    j += line_count;
                    if (!(j <= end - 1)) {
                        break;
                    }
                    linecopy(j - line_count, j, wp);
                }
                j -= line_count;
                if (can_clear(BytePtr.lit(" "))) {
                    lineclear(LineOffset.at(j) + wp.w_wincol, wp.w_width, clear_attr);
                } else {
                    lineinvalid(LineOffset.at(j) + wp.w_wincol, wp.w_width);
                }
                LineWraps.set(j, (byte) FALSE);
            } else {
                j = row + i;
                temp = LineOffset.at(j);
                while (true) {
                    j += line_count;
                    if (!(j <= end - 1)) {
                        break;
                    }
                    LineOffset.set(j - line_count, LineOffset.at(j));
                    LineWraps.set(j - line_count, LineWraps.at(j));
                }
                LineOffset.set(j - line_count, temp);
                LineWraps.set(j - line_count, (byte) FALSE);
                if (can_clear(BytePtr.lit(" "))) {
                    lineclear(temp, (int) Columns[0], clear_attr);
                } else {
                    lineinvalid(temp, (int) Columns[0]);
                }
            }
        }
        if (screen_attr != clear_attr) {
            screen_stop_highlight();
        }
        if (clear_attr != 0) {
            screen_start_highlight(clear_attr);
        }
        if (type == USE_REDRAW) {
            redraw_block(row, end, wp);
        } else if (type == USE_T_CD) {
            windgoto(cursor_row, cursor_col);
            out_str(term_strings[KS_CD]);
            screen_start();
        } else if (type == USE_T_CDL) {
            windgoto(cursor_row, cursor_col);
            term_delete_lines(line_count);
            screen_start();
        } else if (type == USE_NL) {
            windgoto(cursor_end - 1, cursor_col);
            i = line_count;
            for (;;) {
                i--;
                if (!(i >= 0)) {
                    break;
                }
                out_char('\n');
            }
        } else {
            i = line_count;
            for (;;) {
                i--;
                if (!(i >= 0)) {
                    break;
                }
                if (type == USE_T_DL) {
                    windgoto(cursor_row, cursor_col);
                    out_str(term_strings[KS_DL]);
                } else {
                    windgoto(cursor_row + i, cursor_col);
                    out_str(term_strings[KS_CE]);
                }
                screen_start();
            }
        }
        if (term_strings[KS_DB].get() != 0 && (type == USE_T_DL || type == USE_T_CDL)) {
            i = line_count;
            for (; i > 0; i--) {
                windgoto(cursor_end - i, cursor_col);
                out_str(term_strings[KS_CE]);
                screen_start();
            }
        }
        return true;
    }

    boolean skip_showmode() {
        if (global_busy != 0 || msg_silent != 0 || !redrawing() || ((!stuff_empty() || typebuf.tb_len > 0) && KeyTyped == 0)) {
            redraw_mode = TRUE;
            return true;
        }
        return false;
    }

    int showmode() {
        int need_clear = 0;
        int length = 0;
        boolean do_mode = false;
        int attr = 0;
        int nwr_save = 0;
        int sub_attr = 0;
        boolean show_ruler_with_pum = false;
        BytePtr p = null;
        length = 0;
        show_ruler_with_pum = false;
        do_mode = p_smd[0] != 0 && msg_silent == 0 && ((State & MODE_INSERT) != 0 || restart_edit != NUL || VIsual_active != 0);
        if (do_mode || reg_recording != 0) {
            if (skip_showmode()) {
                return 0;
            }
            nwr_save = need_wait_return;
            check_for_delay(false);
            need_clear = clear_cmdline;
            if (clear_cmdline != 0 && (long) cmdline_row < Rows[0] - 1L) {
                msg_clr_cmdline();
            }
            msg_pos_mode();
            cursor_off();
            attr = highlight_attr[HLF_CM];
            if (do_mode) {
                msg_puts_attr(BytePtr.lit("--"), attr);
                if (edit_submode != null && !shortmess(SHM_COMPLETIONMENU)) {
                    length = (int) ((Rows[0] - (long) msg_row) * (long) cmdline_width - 3L);
                    if (edit_submode_extra != null) {
                        length -= vim_strsize(edit_submode_extra);
                    }
                    if (length > 0) {
                        if (edit_submode_pre != null) {
                            length -= vim_strsize(edit_submode_pre);
                        }
                        if (length - vim_strsize(edit_submode) > 0) {
                            if (edit_submode_pre != null) {
                                msg_puts_attr(edit_submode_pre, attr);
                            }
                            msg_puts_attr(edit_submode, attr);
                        }
                        if (edit_submode_extra != null) {
                            msg_puts_attr(BytePtr.lit(" "), attr);
                            if (edit_submode_highl < HLF_COUNT) {
                                sub_attr = highlight_attr[edit_submode_highl];
                            } else {
                                sub_attr = attr;
                            }
                            msg_puts_attr(edit_submode_extra, sub_attr);
                        }
                    }
                } else {
                    if ((State & VREPLACE_FLAG) != 0) {
                        msg_puts_attr(gettext_(BytePtr.lit(" VREPLACE")), attr);
                    } else if ((State & REPLACE_FLAG) != 0) {
                        msg_puts_attr(gettext_(BytePtr.lit(" REPLACE")), attr);
                    } else if ((State & MODE_INSERT) != 0) {
                        msg_puts_attr(gettext_(BytePtr.lit(" INSERT")), attr);
                    } else if (restart_edit == 'I' || restart_edit == 'i' || restart_edit == 'a' || restart_edit == 'A') {
                        msg_puts_attr(gettext_(BytePtr.lit(" (insert)")), attr);
                    } else if (restart_edit == 'R') {
                        msg_puts_attr(gettext_(BytePtr.lit(" (replace)")), attr);
                    } else if (restart_edit == 'V') {
                        msg_puts_attr(gettext_(BytePtr.lit(" (vreplace)")), attr);
                    }
                    if ((State & MODE_INSERT) != 0 && p_paste[0] != 0) {
                        msg_puts_attr(gettext_(BytePtr.lit(" (paste)")), attr);
                    }
                    if (VIsual_active != 0) {
                        switch ((VIsual_select != 0 ? 4 : 0) + (VIsual_mode == Ctrl_V ? 1 : 0) * 2 + (VIsual_mode == 'V' ? 1 : 0)) {
                            case 0:
                                p = BytePtr.lit(" VISUAL");
                                break;
                            case 1:
                                p = BytePtr.lit(" VISUAL LINE");
                                break;
                            case 2:
                                p = BytePtr.lit(" VISUAL BLOCK");
                                break;
                            case 4:
                                p = BytePtr.lit(" SELECT");
                                break;
                            case 5:
                                p = BytePtr.lit(" SELECT LINE");
                                break;
                            default:
                                p = BytePtr.lit(" SELECT BLOCK");
                                break;
                        }
                        msg_puts_attr(gettext_(p), attr);
                    }
                    msg_puts_attr(BytePtr.lit(" --"), attr);
                    show_ruler_with_pum = true;
                }
                need_clear = TRUE;
            }
            if (reg_recording != 0 && edit_submode == null) {
                recording_mode(attr);
                need_clear = TRUE;
            }
            mode_displayed = TRUE;
            if (need_clear != 0 || clear_cmdline != 0 || redraw_mode != 0) {
                msg_clr_eos();
            }
            msg_didout = FALSE;
            length = msg_col;
            msg_col = 0;
            need_wait_return = nwr_save;
        } else if (clear_cmdline != 0 && msg_silent == 0) {
            msg_clr_cmdline();
        } else if (redraw_mode != 0) {
            msg_pos_mode();
            msg_clr_eos();
        }
        if (VIsual_active != 0) {
            clear_showcmd();
        }
        if (redrawing() && curwin.w_status_height == 0) {
            win_redr_ruler(curwin, true, show_ruler_with_pum);
        }
        redraw_cmdline = FALSE;
        redraw_mode = FALSE;
        clear_cmdline = FALSE;
        return length;
    }

    void msg_pos_mode() {
        msg_col = 0;
        msg_row = (int) (Rows[0] - 1L);
    }

    void unshowmode(boolean force) {
        if (!redrawing() || (!force && char_avail() && KeyTyped == 0)) {
            redraw_cmdline = TRUE;
        } else {
            clearmode();
        }
    }

    void clearmode() {
        int save_msg_row = 0;
        int save_msg_col = 0;
        save_msg_row = msg_row;
        save_msg_col = msg_col;
        msg_pos_mode();
        if (reg_recording != 0) {
            recording_mode(highlight_attr[HLF_CM]);
        }
        msg_clr_eos();
        msg_col = save_msg_col;
        msg_row = save_msg_row;
    }

    void recording_mode(int attr) {
        byte[] s = new byte[4];
        msg_puts_attr(gettext_(BytePtr.lit("recording")), attr);
        if (shortmess(SHM_RECORDING)) {
            return;
        }
        vim_snprintf(new BytePtr(s, 0), 4L, BytePtr.lit(" @%c"), reg_recording);
        msg_puts_attr(new BytePtr(s, 0), attr);
    }

    void draw_tabline() {
        redraw_tabline = FALSE;
    }

    void get_trans_bufname(S_file_buffer buf) {
        vim_strncpy(NameBuff, buf_spname(buf), PATH_MAX - 1);
        trans_characters(NameBuff, PATH_MAX);
    }

    int fillchar_status(IntPtr attr, S_window_S wp) {
        int fill = 0;
        boolean override_success = false;
        override_success = push_highlight_overrides(wp.w_hl, wp.w_hl_len);
        if (wp == curwin) {
            attr.put(highlight_attr[HLF_S]);
            fill = wp.w_fill_chars.stl[0];
        } else {
            attr.put(highlight_attr[HLF_SNC]);
            fill = wp.w_fill_chars.stlnc[0];
        }
        if (override_success) {
            pop_highlight_overrides();
        }
        return fill;
    }

    boolean vsep_row_is_curwin(S_window_S wp, int row) {
        if (wp == curwin) {
            return true;
        }
        if (curwin.w_wincol == wp.w_wincol + wp.w_width + wp.w_vsep_width && row >= curwin.w_winrow && row < curwin.w_winrow + curwin.w_height + curwin.w_status_height) {
            return true;
        }
        return false;
    }

    int fillchar_vsep(IntPtr attr, S_window_S wp, int row) {
        boolean override_success = false;
        override_success = push_highlight_overrides(wp.w_hl, wp.w_hl_len);
        if (vsep_row_is_curwin(wp, row)) {
            attr.put(highlight_attr[HLF_C]);
        } else {
            attr.put(highlight_attr[HLF_CNC]);
        }
        if (override_success) {
            pop_highlight_overrides();
        }
        if (attr.get() == 0 && wp.w_fill_chars.vert[0] == ' ') {
            return '|';
        } else {
            return wp.w_fill_chars.vert[0];
        }
    }

    boolean typed_ahead() {
        return char_avail();
    }

    boolean redrawing() {
        return RedrawingDisabled == 0 && !(p_lz[0] != 0 && typed_ahead() && KeyTyped == 0 && do_redraw == 0);
    }

    boolean messaging() {
        return !(p_lz[0] != 0 && typed_ahead() && KeyTyped == 0);
    }

    void comp_col() {
        boolean last_has_status = false;
        last_has_status = last_stl_height(false) > 0;
        sc_col = 0;
        ru_col = 0;
        if (p_ru[0] != 0) {
            ru_col = COL_RULER + 1;
            if (!last_has_status) {
                sc_col = ru_col;
            }
        }
        if (p_sc[0] != 0 && p_sloc[0].get() == 'l') {
            sc_col += SHOWCMD_COLS;
            if (p_ru[0] == 0 || last_has_status) {
                sc_col++;
            }
        }
        sc_col = cmdline_width - sc_col;
        ru_col = cmdline_width - ru_col;
        if (sc_col <= 0) {
            sc_col = 1;
        }
        if (ru_col <= 0) {
            ru_col = 1;
        }
    }

    int get_encoded_char_adv(Ptr<BytePtr> p) {
        BytePtr s = null;
        long num = 0;
        int bytes = 0;
        int n = 0;
        s = p.get();
        if (s.at(0) == '\\' && (s.at(1) == 'x' || s.at(1) == 'u' || s.at(1) == 'U')) {
            num = 0L;
            bytes = s.at(1) == 'x' ? 1 : (s.at(1) == 'u' ? 2 : 4);
            for (; bytes > 0; bytes--) {
                p.put(p.get().add(2));
                n = hexhex2nr(p.get());
                if (n < 0) {
                    return 0;
                }
                num = num * 256L + (long) n;
            }
            p.put(p.get().add(2));
            return (int) num;
        }
        return mb_ptr2char_adv(p);
    }

    BytePtr field_value_err(BytePtr errbuf, long errbuflen, BytePtr fmt, BytePtr field) {
        if (errbuf == null) {
            return BytePtr.lit("");
        }
        vim_snprintf(errbuf, errbuflen, gettext_(fmt), field);
        return errbuf;
    }

    BytePtr set_chars_option(S_window_S wp, BytePtr value, boolean is_listchars, boolean apply, BytePtr errbuf, long errbuflen) {
        int round = 0;
        int i = 0;
        int entries = 0;
        BytePtr p = null;
        BytePtr[] s = new BytePtr[1];
        int c1 = 0;
        int c2 = 0;
        int c3 = 0;
        BytePtr last_multispace = null;
        BytePtr last_lmultispace = null;
        int multispace_len = 0;
        int lead_multispace_len = 0;
        Ptr<S_charstab> tab = null;
        boolean has_tab = false;
        boolean has_leadtab = false;
        int multispace_pos = 0;
        int t1 = 0;
        int multispace_pos_2 = 0;
        int t2 = 0;
        c1 = 0;
        c2 = 0;
        c3 = 0;
        last_multispace = null;
        last_lmultispace = null;
        multispace_len = 0;
        lead_multispace_len = 0;
        if (is_listchars) {
            tab = new Ptr<S_charstab>(lcstab, 0);
            lcs_chars.zero();
            entries = 12;
            if (wp.w_onebuf_opt.wo_lcs[0].at(0) == NUL) {
                value = p_lcs[0];
            }
        } else {
            tab = new Ptr<S_charstab>(filltab, 0);
            entries = 13;
            if (wp.w_onebuf_opt.wo_fcs[0].at(0) == NUL) {
                value = p_fcs[0];
            }
        }
        round = 0;
        for (; round <= (apply ? 1 : 0); round++) {
            has_tab = false;
            has_leadtab = false;
            if (round > 0) {
                if (is_listchars) {
                    i = 0;
                    for (; i < entries; i++) {
                        if (tab.at(i).cp != null) {
                            tab.at(i).cp.put(NUL);
                        }
                    }
                    lcs_chars.tab1 = NUL;
                    lcs_chars.tab3 = NUL;
                    lcs_chars.leadtab1 = NUL;
                    lcs_chars.leadtab3 = NUL;
                    if (multispace_len > 0) {
                        lcs_chars.multispace = IntPtr.alloc(multispace_len + 1);
                        lcs_chars.multispace.set(multispace_len, NUL);
                    } else {
                        lcs_chars.multispace = null;
                    }
                    if (lead_multispace_len > 0) {
                        lcs_chars.leadmultispace = IntPtr.alloc(lead_multispace_len + 1);
                        lcs_chars.leadmultispace.set(lead_multispace_len, NUL);
                    } else {
                        lcs_chars.leadmultispace = null;
                    }
                } else {
                    fill_chars.stl[0] = ' ';
                    fill_chars.stlnc[0] = ' ';
                    fill_chars.vert[0] = '|';
                    fill_chars.fold[0] = '-';
                    fill_chars.foldopen[0] = '-';
                    fill_chars.foldclosed[0] = '+';
                    fill_chars.foldsep[0] = '|';
                    fill_chars.foldinner[0] = NUL;
                    fill_chars.diff[0] = '-';
                    fill_chars.eob[0] = '~';
                    fill_chars.lastline[0] = '@';
                    fill_chars.trunc[0] = '>';
                    fill_chars.truncrl[0] = '<';
                }
            }
            p = value;
            while (p.get() != 0) {
                i = 0;
                for (; i < entries; i++) {
                    if (!(musl_strncmp(p, tab.at(i).name.string[0], tab.at(i).name.length) == 0 && p.at((int) tab.at(i).name.length) == ':')) {
                        continue;
                    }
                    s[0] = p.add((int) tab.at(i).name.length).add(1);
                    if (is_listchars && musl_strcmp(tab.at(i).name.string[0], BytePtr.lit("multispace")) == 0) {
                        if (round == 0) {
                            last_multispace = p;
                            multispace_len = 0;
                            while (s[0].get() != NUL && s[0].get() != ',') {
                                c1 = get_encoded_char_adv(new Ptr<BytePtr>(s, 0));
                                if (char2cells(c1) > 1) {
                                    return field_value_err(errbuf, errbuflen, new BytePtr(e_wrong_character_width_for_field_str, 0), tab.at(i).name.string[0]);
                                }
                                multispace_len++;
                            }
                            if (multispace_len == 0) {
                                return field_value_err(errbuf, errbuflen, new BytePtr(e_wrong_number_of_characters_for_field_str, 0), tab.at(i).name.string[0]);
                            }
                        } else {
                            multispace_pos = 0;
                            while (s[0].get() != NUL && s[0].get() != ',') {
                                c1 = get_encoded_char_adv(new Ptr<BytePtr>(s, 0));
                                if (BytePtr.eq(p, last_multispace) && lcs_chars.multispace != null) {
                                    t1 = multispace_pos;
                                    multispace_pos++;
                                    lcs_chars.multispace.set(t1, c1);
                                }
                            }
                        }
                        p = s[0];
                        break;
                    }
                    if (is_listchars && musl_strcmp(tab.at(i).name.string[0], BytePtr.lit("leadmultispace")) == 0) {
                        if (round == 0) {
                            last_lmultispace = p;
                            lead_multispace_len = 0;
                            while (s[0].get() != NUL && s[0].get() != ',') {
                                c1 = get_encoded_char_adv(new Ptr<BytePtr>(s, 0));
                                if (char2cells(c1) > 1) {
                                    return field_value_err(errbuf, errbuflen, new BytePtr(e_wrong_character_width_for_field_str, 0), tab.at(i).name.string[0]);
                                }
                                lead_multispace_len++;
                            }
                            if (lead_multispace_len == 0) {
                                return field_value_err(errbuf, errbuflen, new BytePtr(e_wrong_number_of_characters_for_field_str, 0), tab.at(i).name.string[0]);
                            }
                        } else {
                            multispace_pos_2 = 0;
                            while (s[0].get() != NUL && s[0].get() != ',') {
                                c1 = get_encoded_char_adv(new Ptr<BytePtr>(s, 0));
                                if (BytePtr.eq(p, last_lmultispace) && lcs_chars.leadmultispace != null) {
                                    t2 = multispace_pos_2;
                                    multispace_pos_2++;
                                    lcs_chars.leadmultispace.set(t2, c1);
                                }
                            }
                        }
                        p = s[0];
                        break;
                    }
                    c3 = 0;
                    c2 = c3;
                    if (s[0].get() == NUL) {
                        return field_value_err(errbuf, errbuflen, new BytePtr(e_wrong_number_of_characters_for_field_str, 0), tab.at(i).name.string[0]);
                    }
                    c1 = get_encoded_char_adv(new Ptr<BytePtr>(s, 0));
                    if (char2cells(c1) > 1) {
                        return field_value_err(errbuf, errbuflen, new BytePtr(e_wrong_character_width_for_field_str, 0), tab.at(i).name.string[0]);
                    }
                    if (IntPtr.eq(tab.at(i).cp, new IntPtr(lcs_chars.tab2, 0)) || IntPtr.eq(tab.at(i).cp, new IntPtr(lcs_chars.leadtab2, 0))) {
                        if (s[0].get() == NUL) {
                            return field_value_err(errbuf, errbuflen, new BytePtr(e_wrong_number_of_characters_for_field_str, 0), tab.at(i).name.string[0]);
                        }
                        c2 = get_encoded_char_adv(new Ptr<BytePtr>(s, 0));
                        if (char2cells(c2) > 1) {
                            return field_value_err(errbuf, errbuflen, new BytePtr(e_wrong_character_width_for_field_str, 0), tab.at(i).name.string[0]);
                        }
                        if (!(s[0].get() == ',' || s[0].get() == NUL)) {
                            c3 = get_encoded_char_adv(new Ptr<BytePtr>(s, 0));
                            if (char2cells(c3) > 1) {
                                return field_value_err(errbuf, errbuflen, new BytePtr(e_wrong_character_width_for_field_str, 0), tab.at(i).name.string[0]);
                            }
                        }
                        if (IntPtr.eq(tab.at(i).cp, new IntPtr(lcs_chars.tab2, 0))) {
                            has_tab = true;
                        } else {
                            has_leadtab = true;
                        }
                    }
                    if (s[0].get() == ',' || s[0].get() == NUL) {
                        if (round > 0) {
                            if (IntPtr.eq(tab.at(i).cp, new IntPtr(lcs_chars.tab2, 0))) {
                                lcs_chars.tab1 = c1;
                                lcs_chars.tab2[0] = c2;
                                lcs_chars.tab3 = c3;
                            } else if (IntPtr.eq(tab.at(i).cp, new IntPtr(lcs_chars.leadtab2, 0))) {
                                lcs_chars.leadtab1 = c1;
                                lcs_chars.leadtab2[0] = c2;
                                lcs_chars.leadtab3 = c3;
                            } else if (tab.at(i).cp != null) {
                                tab.at(i).cp.put(c1);
                            }
                        }
                        p = s[0];
                        break;
                    } else {
                        return field_value_err(errbuf, errbuflen, new BytePtr(e_wrong_number_of_characters_for_field_str, 0), tab.at(i).name.string[0]);
                    }
                }
                if (i == entries) {
                    return new BytePtr(e_invalid_argument, 0);
                }
                if (p.get() == ',') {
                    p = p.add(1);
                }
            }
            if (is_listchars && has_leadtab && !has_tab) {
                return new BytePtr(e_leadtab_requires_tab, 0);
            }
        }
        if (apply) {
            if (is_listchars) {
                wp.w_lcs_chars.set(lcs_chars);
            } else {
                wp.w_fill_chars.set(fill_chars);
            }
        }
        return null;
    }

    BytePtr set_fillchars_option(S_window_S wp, BytePtr val, boolean apply, BytePtr errbuf, long errbuflen) {
        return set_chars_option(wp, val, false, apply, errbuf, errbuflen);
    }

    BytePtr set_listchars_option(S_window_S wp, BytePtr val, boolean apply, BytePtr errbuf, long errbuflen) {
        return set_chars_option(wp, val, true, apply, errbuf, errbuflen);
    }

    BytePtr check_chars_options() {
        S_window_S wp = null;
        if (set_listchars_option(curwin, p_lcs[0], false, null, 0L) != null) {
            return new BytePtr(e_conflicts_with_value_of_listchars, 0);
        }
        if (set_fillchars_option(curwin, p_fcs[0], false, null, 0L) != null) {
            return new BytePtr(e_conflicts_with_value_of_fillchars, 0);
        }
        wp = curwin;
        if (set_listchars_option(wp, wp.w_onebuf_opt.wo_lcs[0], false, null, 0L) != null) {
            return new BytePtr(e_conflicts_with_value_of_listchars, 0);
        }
        if (set_fillchars_option(wp, wp.w_onebuf_opt.wo_fcs[0], false, null, 0L) != null) {
            return new BytePtr(e_conflicts_with_value_of_fillchars, 0);
        }
        return null;
    }

    void estack_init() {
        T_estack_T entry = null;
        if (!ga_grow(exestack, 10)) {
            mch_exit(0);
        }
        entry = GA_Ptr_T_estack_T(exestack).at(exestack.ga_len);
        entry.es_type = ETYPE_TOP;
        entry.es_name = null;
        entry.es_lnum = 0L;
        exestack.ga_len++;
    }

    T_estack_T estack_push(int type, BytePtr name, long lnum) {
        T_estack_T entry = null;
        if (!ga_grow(exestack, 1)) {
            return null;
        }
        entry = GA_Ptr_T_estack_T(exestack).at(exestack.ga_len);
        entry.es_type = type;
        entry.es_name = name;
        entry.es_lnum = lnum;
        exestack.ga_len++;
        return entry;
    }

    T_estack_T estack_pop() {
        if (exestack.ga_len == 0) {
            return null;
        }
        exestack.ga_len--;
        return GA_Ptr_T_estack_T(exestack).at(exestack.ga_len);
    }

    BytePtr estack_sfile(int which) {
        T_estack_T entry = null;
        entry = GA_Ptr_T_estack_T(exestack).add(exestack.ga_len).at(-1);
        if (entry.es_name == null) {
            return null;
        }
        return vim_strsave(entry.es_name);
    }

    boolean search_regcomp(BytePtr pat, long patlen, Ptr<BytePtr> used_pat, int pat_save, int pat_use, int options, T_regmmatch_T regmatch) {
        int magic = 0;
        int i = 0;
        rc_did_emsg = FALSE;
        magic = magic_isset();
        if (pat == null || pat.get() == NUL) {
            if (pat_use == RE_LAST) {
                i = last_idx;
            } else {
                i = pat_use;
            }
            if (spats[i].pat == null) {
                if (pat_use == RE_SUBST) {
                    emsg(gettext_(new BytePtr(e_no_previous_substitute_regular_expression, 0)));
                } else {
                    emsg(gettext_(new BytePtr(e_no_previous_regular_expression, 0)));
                }
                rc_did_emsg = TRUE;
                return false;
            }
            pat = spats[i].pat;
            patlen = spats[i].patlen;
            magic = spats[i].magic;
            no_smartcase = spats[i].no_scs;
        } else if ((options & SEARCH_HIS) != 0) {
            add_to_history(HIST_SEARCH, pat, patlen, true, NUL);
        }
        if (used_pat != null) {
            used_pat.put(pat);
        }
        mr_pattern = vim_strnsave(pat, patlen);
        if ((options & SEARCH_KEEP) == 0 && (cmdmod.cmod_flags & CMOD_KEEPPATTERNS) == 0) {
            if (pat_save == RE_SEARCH || pat_save == RE_BOTH) {
                save_re_pat(RE_SEARCH, pat, patlen, magic);
            }
            if (pat_save == RE_SUBST || pat_save == RE_BOTH) {
                save_re_pat(RE_SUBST, pat, patlen, magic);
            }
        }
        regmatch.rmm_ic = ignorecase(pat);
        regmatch.rmm_maxcol = 0;
        regmatch.regprog = vim_regcomp(pat, magic != 0 ? RE_MAGIC : 0);
        if (regmatch.regprog == null) {
            return false;
        }
        return true;
    }

    BytePtr get_search_pat() {
        return mr_pattern;
    }

    void save_re_pat(int idx, BytePtr pat, long patlen, int magic) {
        if (BytePtr.eq(spats[idx].pat, pat)) {
            return;
        }
        spats[idx].pat = vim_strnsave(pat, patlen);
        spats[idx].patlen = patlen;
        spats[idx].magic = magic;
        spats[idx].no_scs = no_smartcase;
        last_idx = idx;
        if (p_hls[0] != 0) {
            redraw_all_later(UPD_SOME_VALID);
        }
        set_no_hlsearch(FALSE);
    }

    void save_last_search_pattern() {
        did_save_last_search_spat++;
        if (did_save_last_search_spat != 1) {
            return;
        }
        saved_last_search_spat.set(spats[RE_SEARCH]);
        if (spats[RE_SEARCH].pat != null) {
            saved_last_search_spat.pat = vim_strnsave(spats[RE_SEARCH].pat, spats[RE_SEARCH].patlen);
            saved_last_search_spat.patlen = spats[RE_SEARCH].patlen;
        }
        saved_last_idx = last_idx;
        saved_no_hlsearch = no_hlsearch;
    }

    void restore_last_search_pattern() {
        did_save_last_search_spat--;
        if (did_save_last_search_spat > 0) {
            return;
        }
        if (did_save_last_search_spat != 0) {
            iemsg(BytePtr.lit("restore_last_search_pattern() called more often than save_last_search_pattern()"));
            return;
        }
        spats[RE_SEARCH].set(saved_last_search_spat);
        saved_last_search_spat.pat = null;
        saved_last_search_spat.patlen = 0L;
        last_idx = saved_last_idx;
        set_no_hlsearch(saved_no_hlsearch);
    }

    int ignorecase(BytePtr pat) {
        return ignorecase_opt(pat, p_ic[0], p_scs[0]);
    }

    int ignorecase_opt(BytePtr pat, int ic_in, int scs) {
        int ic = 0;
        ic = ic_in;
        if (ic != 0 && no_smartcase == 0 && scs != 0) {
            ic = !pat_has_uppercase(pat) ? 1 : 0;
        }
        no_smartcase = FALSE;
        return ic;
    }

    boolean pat_has_uppercase(BytePtr pat) {
        BytePtr p = null;
        int[] magic_val = new int[1];
        int l = 0;
        p = pat;
        magic_val[0] = MAGIC_ON;
        skip_regexp_ex(pat, NUL, magic_isset(), null, null, new IntPtr(magic_val, 0));
        while (p.get() != NUL) {
            l = utfc_ptr2len(p);
            if (l > 1) {
                if (utf_isupper(utf_ptr2char(p))) {
                    return true;
                }
                p = p.add(l);
            } else if (p.get() == '\\' && magic_val[0] <= MAGIC_ON) {
                if (p.at(1) == '_' && p.at(2) != NUL) {
                    p = p.add(3);
                } else if (p.at(1) == '%' && p.at(2) != NUL) {
                    p = p.add(3);
                } else if (p.at(1) != NUL) {
                    p = p.add(2);
                } else {
                    p = p.add(1);
                }
            } else if ((p.get() == '%' || p.get() == '_') && magic_val[0] == MAGIC_ALL) {
                if (p.at(1) != NUL) {
                    p = p.add(2);
                } else {
                    p = p.add(1);
                }
            } else if (vim_isupper(p.get() & 0xff)) {
                return true;
            } else {
                p = p.add(1);
            }
        }
        return false;
    }

    void set_csearch_direction(int cdir) {
        lastcdir = cdir;
    }

    void set_csearch_until(int t_cmd) {
        last_t_cmd = t_cmd;
    }

    BytePtr last_search_pat() {
        return spats[last_idx].pat;
    }

    void last_pat_prog(T_regmmatch_T regmatch) {
        if (spats[last_idx].pat == null) {
            regmatch.regprog = null;
            return;
        }
        emsg_off++;
        search_regcomp(BytePtr.lit(""), 0L, null, 0, last_idx, SEARCH_KEEP, regmatch);
        emsg_off--;
    }

    int searchit(S_window_S win, S_file_buffer buf, T_pos_T pos, T_pos_T end_pos, int dir, BytePtr pat, long patlen, long count, int options, int pat_use, T_searchit_arg_T extra_arg) {
        int found = 0;
        long lnum = 0;
        int col = 0;
        T_regmmatch_T regmatch = new T_regmmatch_T();
        BytePtr ptr = null;
        int matchcol = 0;
        T_lpos_T endpos = new T_lpos_T();
        T_lpos_T matchpos = new T_lpos_T();
        int loop = 0;
        T_pos_T start_pos = new T_pos_T();
        boolean at_first_line = false;
        int extra_col = 0;
        int start_char_len = 0;
        boolean match_ok = false;
        long nmatched = 0;
        int submatch = 0;
        boolean first_match = false;
        int called_emsg_before = 0;
        boolean break_loop = false;
        long stop_lnum = 0;
        int[] unused_timeout_flag = new int[1];
        IntPtr timed_out = null;
        boolean search_from_match_end = false;
        boolean t1 = false;
        boolean t2 = false;
        submatch = 0;
        first_match = true;
        called_emsg_before = called_emsg;
        break_loop = false;
        stop_lnum = 0L;
        unused_timeout_flag[0] = FALSE;
        timed_out = new IntPtr(unused_timeout_flag, 0);
        if (!search_regcomp(pat, patlen, null, RE_SEARCH, pat_use, options & (SEARCH_HIS + SEARCH_KEEP), regmatch)) {
            if ((options & SEARCH_MSG) != 0 && rc_did_emsg == 0) {
                vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(new BytePtr(e_invalid_search_string_str, 0)), mr_pattern);
                emsg(iobuff_or(gettext_(new BytePtr(e_invalid_search_string_str, 0))));
            }
            return FAIL;
        }
        search_from_match_end = vim_strchr(p_cpo[0], CPO_SEARCH) != null;
        if (extra_arg != null) {
            stop_lnum = extra_arg.sa_stop_lnum;
        }
        do {
            if (pos.col[0] == MAXCOL) {
                start_char_len = 0;
            } else if (pos.lnum[0] >= 1L && pos.lnum[0] <= buf.b_ml.ml_line_count && pos.col[0] < MAXCOL - 2) {
                ptr = ml_get_buf(buf, pos.lnum[0], false);
                if (ml_get_buf_len(buf, pos.lnum[0]) <= pos.col[0]) {
                    start_char_len = 1;
                } else {
                    start_char_len = utfc_ptr2len(ptr.add(pos.col[0]));
                }
            } else {
                start_char_len = 1;
            }
            if (dir == FORWARD) {
                if ((options & SEARCH_START) != 0) {
                    extra_col = 0;
                } else {
                    extra_col = start_char_len;
                }
            } else {
                if ((options & SEARCH_START) != 0) {
                    extra_col = start_char_len;
                } else {
                    extra_col = 0;
                }
            }
            start_pos.set(pos);
            found = 0;
            at_first_line = true;
            if (pos.lnum[0] == 0L) {
                pos.lnum[0] = 1L;
                pos.col[0] = 0;
                at_first_line = false;
            }
            if (dir == -1 && start_pos.col[0] == 0 && (options & SEARCH_START) == 0) {
                lnum = pos.lnum[0] - 1L;
                at_first_line = false;
            } else {
                lnum = pos.lnum[0];
            }
            loop = 0;
            for (; loop <= 1; loop++) {
                for (; (lnum > 0L) && lnum <= buf.b_ml.ml_line_count; lnum += (long) dir, at_first_line = false) {
                    if (stop_lnum != 0L && (dir == FORWARD ? lnum > stop_lnum : lnum < stop_lnum)) {
                        break;
                    }
                    if (timed_out.get() != 0) {
                        break;
                    }
                    col = at_first_line && (options & SEARCH_COL) != 0 ? pos.col[0] : 0;
                    nmatched = vim_regexec_multi(regmatch, win, buf, lnum, col, timed_out);
                    if (regmatch.regprog == null) {
                        break;
                    }
                    if (called_emsg > called_emsg_before || timed_out.get() != 0) {
                        break;
                    }
                    if (nmatched > 0L) {
                        matchpos.set(regmatch.startpos[0]);
                        endpos.set(regmatch.endpos[0]);
                        if (lnum + matchpos.lnum > buf.b_ml.ml_line_count) {
                            ptr = BytePtr.lit("");
                        } else {
                            ptr = ml_get_buf(buf, lnum + matchpos.lnum, false);
                        }
                        if (dir == FORWARD && at_first_line) {
                            match_ok = true;
                            while (matchpos.lnum == 0L && ((options & SEARCH_END) != 0 && first_match ? nmatched == 1L && endpos.col - 1 < start_pos.col[0] + extra_col : matchpos.col - (ptr.at(matchpos.col) == NUL ? 1 : 0) < start_pos.col[0] + extra_col)) {
                                if (search_from_match_end) {
                                    if (nmatched > 1L) {
                                        match_ok = false;
                                        break;
                                    }
                                    matchcol = endpos.col;
                                    if (matchcol == matchpos.col && ptr.at(matchcol) != NUL) {
                                        matchcol += utfc_ptr2len(ptr.add(matchcol));
                                    }
                                } else {
                                    matchcol = regmatch.rmm_matchcol;
                                    if (ptr.at(matchcol) != NUL) {
                                        matchcol += utfc_ptr2len(ptr.add(matchcol));
                                    }
                                }
                                if (matchcol == 0 && (options & SEARCH_START) != 0) {
                                    break;
                                }
                                t1 = ptr.at(matchcol) == NUL;
                                if (!t1) {
                                    nmatched = vim_regexec_multi(regmatch, win, buf, lnum + matchpos.lnum, matchcol, timed_out);
                                    t1 = nmatched == 0L;
                                }
                                if (t1) {
                                    match_ok = false;
                                    break;
                                }
                                if (regmatch.regprog == null) {
                                    break;
                                }
                                matchpos.set(regmatch.startpos[0]);
                                endpos.set(regmatch.endpos[0]);
                                ptr = ml_get_buf(buf, lnum + matchpos.lnum, false);
                            }
                            if (!match_ok) {
                                continue;
                            }
                        }
                        if (dir == -1) {
                            match_ok = false;
                            for (;;) {
                                if (loop != 0 || ((options & SEARCH_END) != 0 ? lnum + regmatch.endpos[0].lnum < start_pos.lnum[0] || (lnum + regmatch.endpos[0].lnum == start_pos.lnum[0] && regmatch.endpos[0].col - 1 < start_pos.col[0] + extra_col) : lnum + regmatch.startpos[0].lnum < start_pos.lnum[0] || (lnum + regmatch.startpos[0].lnum == start_pos.lnum[0] && regmatch.startpos[0].col < start_pos.col[0] + extra_col))) {
                                    match_ok = true;
                                    matchpos.set(regmatch.startpos[0]);
                                    endpos.set(regmatch.endpos[0]);
                                } else {
                                    break;
                                }
                                if (search_from_match_end) {
                                    if (nmatched > 1L) {
                                        break;
                                    }
                                    matchcol = endpos.col;
                                    if (matchcol == matchpos.col && ptr.at(matchcol) != NUL) {
                                        matchcol += utfc_ptr2len(ptr.add(matchcol));
                                    }
                                } else {
                                    if (matchpos.lnum > 0L) {
                                        break;
                                    }
                                    matchcol = matchpos.col;
                                    if (ptr.at(matchcol) != NUL) {
                                        matchcol += utfc_ptr2len(ptr.add(matchcol));
                                    }
                                }
                                t2 = ptr.at(matchcol) == NUL;
                                if (!t2) {
                                    nmatched = vim_regexec_multi(regmatch, win, buf, lnum + matchpos.lnum, matchcol, timed_out);
                                    t2 = nmatched == 0L;
                                }
                                if (t2) {
                                    if (timed_out.get() != 0) {
                                        match_ok = false;
                                    }
                                    break;
                                }
                                if (regmatch.regprog == null) {
                                    break;
                                }
                                ptr = ml_get_buf(buf, lnum + matchpos.lnum, false);
                            }
                            if (!match_ok) {
                                continue;
                            }
                        }
                        if ((options & SEARCH_END) != 0 && (options & SEARCH_NOOF) == 0 && !(matchpos.lnum == endpos.lnum && matchpos.col == endpos.col)) {
                            pos.lnum[0] = lnum + endpos.lnum;
                            pos.col[0] = endpos.col;
                            if (endpos.col == 0) {
                                if (pos.lnum[0] > 1L) {
                                    pos.lnum[0]--;
                                    pos.col[0] = ml_get_buf_len(buf, pos.lnum[0]);
                                }
                            } else {
                                pos.col[0]--;
                                if (pos.lnum[0] <= buf.b_ml.ml_line_count) {
                                    ptr = ml_get_buf(buf, pos.lnum[0], false);
                                    pos.col[0] -= utf_head_off(ptr, ptr.add(pos.col[0]));
                                }
                            }
                            if (end_pos != null) {
                                end_pos.lnum[0] = lnum + matchpos.lnum;
                                end_pos.col[0] = matchpos.col;
                            }
                        } else {
                            pos.lnum[0] = lnum + matchpos.lnum;
                            pos.col[0] = matchpos.col;
                            if (end_pos != null) {
                                end_pos.lnum[0] = lnum + endpos.lnum;
                                end_pos.col[0] = endpos.col;
                            }
                        }
                        pos.coladd = 0;
                        if (end_pos != null) {
                            end_pos.coladd = 0;
                        }
                        found = 1;
                        first_match = false;
                        search_match_lines = endpos.lnum - matchpos.lnum;
                        search_match_endcol = endpos.col;
                        break;
                    }
                    line_breakcheck();
                    if (got_int != 0) {
                        break;
                    }
                    if ((options & SEARCH_PEEK) != 0 && ((lnum - pos.lnum[0]) & 63L) == 0L && char_avail()) {
                        break_loop = true;
                        break;
                    }
                    if (loop != 0 && lnum == start_pos.lnum[0]) {
                        break;
                    }
                }
                at_first_line = false;
                if (regmatch.regprog == null) {
                    break;
                }
                if (p_ws[0] == 0 || stop_lnum != 0L || got_int != 0 || called_emsg > called_emsg_before || timed_out.get() != 0 || break_loop || found != 0 || loop != 0) {
                    break;
                }
                if (dir == -1) {
                    lnum = buf.b_ml.ml_line_count;
                } else {
                    lnum = 1L;
                }
                if (!shortmess(SHM_SEARCH) && shortmess(SHM_SEARCHCOUNT) && (options & SEARCH_MSG) != 0) {
                    give_warning(gettext_(dir == -1 ? new BytePtr(top_bot_msg, 0) : new BytePtr(bot_top_msg, 0)), true);
                }
                if (extra_arg != null) {
                    extra_arg.sa_wrapped = true;
                }
            }
            if (got_int != 0 || called_emsg > called_emsg_before || timed_out.get() != 0 || break_loop) {
                break;
            }
            count--;
        } while (count > 0L && found != 0);
        vim_regfree(regmatch.regprog);
        if (found == 0) {
            if (got_int != 0) {
                emsg(gettext_(new BytePtr(e_interrupted, 0)));
            } else if ((options & SEARCH_MSG) == SEARCH_MSG) {
                if (p_ws[0] != 0) {
                    vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(new BytePtr(e_pattern_not_found_str, 0)), mr_pattern);
                    emsg(iobuff_or(gettext_(new BytePtr(e_pattern_not_found_str, 0))));
                } else if (lnum == 0L) {
                    vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(new BytePtr(e_search_hit_top_without_match_for_str, 0)), mr_pattern);
                    emsg(iobuff_or(gettext_(new BytePtr(e_search_hit_top_without_match_for_str, 0))));
                } else {
                    vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(new BytePtr(e_search_hit_bottom_without_match_for_str, 0)), mr_pattern);
                    emsg(iobuff_or(gettext_(new BytePtr(e_search_hit_bottom_without_match_for_str, 0))));
                }
            }
            return FAIL;
        }
        if (pos.lnum[0] > buf.b_ml.ml_line_count) {
            pos.lnum[0] = buf.b_ml.ml_line_count;
            pos.col[0] = ml_get_buf_len(buf, pos.lnum[0]);
            if (pos.col[0] > 0) {
                pos.col[0]--;
            }
        }
        return submatch + 1;
    }

    int parse_search_pattern_offset(Ptr<BytePtr> pat, LongPtr patlen, int search_delim, int options, Ptr<BytePtr> strcopy, Ptr<BytePtr> searchstr, LongPtr searchstrlen, Ptr<BytePtr> dircp, S_soffset offset) {
        int cmdlen = 0;
        BytePtr p = null;
        BytePtr ps = null;
        long len = 0;
        BytePtr t1 = null;
        cmdlen = 0;
        if (pat.get() == null || pat.get().get() == NUL) {
            return 0;
        }
        ps = strcopy.get();
        searchstr.put(pat.get());
        searchstrlen.put(patlen.get());
        dircp.put(null);
        p = skip_regexp_ex(pat.get(), search_delim, magic_isset(), strcopy, null, null);
        if (!BytePtr.eq(strcopy.get(), ps)) {
            len = musl_strlen(strcopy.get());
            cmdlen += (int) (patlen.get() - len);
            pat.put(strcopy.get());
            patlen.put(len);
            searchstr.put(strcopy.get());
            searchstrlen.put(len);
        }
        if ((p.get() & 0xff) == search_delim) {
            searchstrlen.put(p.sub(pat.get()));
            dircp.put(p);
            t1 = p;
            p = p.add(1);
            t1.put((byte) NUL);
        }
        offset.line = FALSE;
        offset.end = FALSE;
        offset.off = 0L;
        if (p.get() == '+' || p.get() == '-' || Integer.compareUnsigned((p.get() & 0xff) - '0', 10) < 0) {
            offset.line = TRUE;
        } else if ((options & SEARCH_OPT) != 0 && (p.get() == 'e' || p.get() == 's' || p.get() == 'b')) {
            if (p.get() == 'e') {
                offset.end = SEARCH_END;
            }
            p = p.add(1);
        }
        if (Integer.compareUnsigned((p.get() & 0xff) - '0', 10) < 0 || p.get() == '+' || p.get() == '-') {
            if (Integer.compareUnsigned((p.get() & 0xff) - '0', 10) < 0 || Integer.compareUnsigned((p.add(1).get() & 0xff) - '0', 10) < 0) {
                offset.off = musl_atol(p);
            } else if (p.get() == '-') {
                offset.off = -1L;
            } else {
                offset.off = 1L;
            }
            p = p.add(1);
            while (Integer.compareUnsigned((p.get() & 0xff) - '0', 10) < 0) {
                p = p.add(1);
            }
        }
        cmdlen += (int) p.sub(pat.get());
        patlen.put(patlen.get() - p.sub(pat.get()));
        pat.put(p);
        return cmdlen;
    }

    int do_search(S_oparg_S oap, int dirc, int search_delim, BytePtr pat_arg, long patlen_arg, long count, int options, T_searchit_arg_T sia) {
        BytePtr[] pat = new BytePtr[] {pat_arg};
        long[] patlen = new long[] {patlen_arg};
        T_pos_T pos = new T_pos_T();
        BytePtr[] searchstr = new BytePtr[1];
        long[] searchstrlen = new long[1];
        S_soffset old_off = new S_soffset();
        int retval = 0;
        BytePtr p = null;
        long c = 0;
        BytePtr[] dircp = new BytePtr[1];
        BytePtr[] strcopy = new BytePtr[1];
        boolean show_search_stats = false;
        BytePtr msgbuf = null;
        long msgbuflen = 0;
        boolean has_offset = false;
        boolean show_top_bot_msg = false;
        byte[] off_buf = new byte[40];
        long off_len = 0;
        long plen = 0;
        long msgbufsize = 0;
        long t1 = 0;
        long t2 = 0;
        long t3 = 0;
        BytePtr trunc = null;
        T_pos_T org_pos = new T_pos_T();
        long t4 = 0;
        long t5 = 0;
        strcopy[0] = null;
        msgbuf = null;
        msgbuflen = 0L;
        has_offset = false;
        searchcmdlen = 0;
        if (spats[0].off.line != 0 && vim_strchr(p_cpo[0], CPO_LINEOFF) != null) {
            spats[0].off.line = FALSE;
            spats[0].off.off = 0L;
        }
        old_off.set(spats[0].off);
        pos.set(curwin.w_cursor);
        if (dirc == 0) {
            dirc = spats[0].off.dir;
        } else {
            spats[0].off.dir = dirc;
        }
        if ((options & SEARCH_REV) != 0) {
            if (dirc == '/') {
                dirc = '?';
            } else {
                dirc = '/';
            }
        }
        if (no_hlsearch != 0 && (options & SEARCH_KEEP) == 0) {
            redraw_all_later(UPD_SOME_VALID);
            set_no_hlsearch(FALSE);
        }
        L_end_do_search: {
            for (;;) {
                show_top_bot_msg = false;
                searchstr[0] = pat[0];
                searchstrlen[0] = patlen[0];
                dircp[0] = null;
                if (pat[0] == null || pat[0].get() == NUL || (pat[0].get() & 0xff) == search_delim) {
                    if (spats[RE_SEARCH].pat == null) {
                        if (spats[RE_SUBST].pat == null) {
                            emsg(gettext_(new BytePtr(e_no_previous_regular_expression, 0)));
                            retval = 0;
                            break L_end_do_search;
                        }
                        searchstr[0] = spats[RE_SUBST].pat;
                        searchstrlen[0] = spats[RE_SUBST].patlen;
                    } else {
                        searchstr[0] = BytePtr.lit("");
                        searchstrlen[0] = 0L;
                    }
                }
                if (pat[0] != null && pat[0].get() != NUL) {
                    searchcmdlen += parse_search_pattern_offset(new Ptr<BytePtr>(pat, 0), new LongPtr(patlen, 0), search_delim, options, new Ptr<BytePtr>(strcopy, 0), new Ptr<BytePtr>(searchstr, 0), new LongPtr(searchstrlen, 0), new Ptr<BytePtr>(dircp, 0), spats[0].off);
                }
                show_search_stats = false;
                if ((options & SEARCH_ECHO) != 0 && messaging() && msg_silent == 0 && (cmd_silent == 0 || !shortmess(SHM_SEARCHCOUNT))) {
                    off_len = 0L;
                    msg_start();
                    if (cmd_silent == 0 && (spats[0].off.line != 0 || spats[0].off.end != 0 || spats[0].off.off != 0)) {
                        t1 = off_len;
                        off_len++;
                        off_buf[(int) t1] = (byte) dirc;
                        if (spats[0].off.end != 0) {
                            t2 = off_len;
                            off_len++;
                            off_buf[(int) t2] = (byte) 'e';
                        } else if (spats[0].off.line == 0) {
                            t3 = off_len;
                            off_len++;
                            off_buf[(int) t3] = (byte) 's';
                        }
                        off_buf[(int) off_len] = (byte) NUL;
                        if (spats[0].off.off != 0L || spats[0].off.line != 0) {
                            off_len += (long) vim_snprintf(new BytePtr(off_buf, 0).add((int) off_len), 40L - off_len, BytePtr.lit("%+ld"), spats[0].off.off);
                        }
                    }
                    if (searchstr[0].get() == NUL) {
                        p = spats[0].pat;
                        plen = spats[0].patlen;
                    } else {
                        p = searchstr[0];
                        plen = searchstrlen[0];
                    }
                    if (!shortmess(SHM_SEARCHCOUNT) || cmd_silent != 0) {
                        if (msg_scrolled != 0 && cmd_silent == 0) {
                            msgbufsize = (long) ((int) (Rows[0] - (long) msg_row) * cmdline_width - 1);
                        } else {
                            msgbufsize = (long) ((int) (Rows[0] - (long) msg_row - 1L) * cmdline_width + sc_col - 1);
                        }
                        if (Long.compareUnsigned(msgbufsize, plen + off_len + SEARCH_STAT_BUF_LEN + 3L) < 0) {
                            msgbufsize = plen + off_len + SEARCH_STAT_BUF_LEN + 3L;
                        }
                    } else {
                        msgbufsize = plen + off_len + 3L;
                    }
                    msgbuf = BytePtr.alloc(msgbufsize);
                    Rt.memset(msgbuf, ' ', msgbufsize);
                    msgbuflen = msgbufsize - 1L;
                    msgbuf.set((int) msgbuflen, (byte) NUL);
                    if (cmd_silent == 0) {
                        msgbuf.set(0, (byte) dirc);
                        if (utf_iscomposing(utf_ptr2char(p))) {
                            msgbuf.set(1, (byte) ' ');
                            Rt.memmove(msgbuf.add(2), p, plen);
                        } else {
                            Rt.memmove(msgbuf.add(1), p, plen);
                        }
                        if (Long.compareUnsigned(off_len, 0L) > 0) {
                            Rt.memmove(msgbuf.add((int) plen).add(1), new BytePtr(off_buf, 0), off_len);
                        }
                        trunc = msg_strtrunc(msgbuf, true);
                        if (trunc != null) {
                            msgbuf = trunc;
                            msgbuflen = musl_strlen(msgbuf);
                        }
                        msg_outtrans(msgbuf);
                        msg_clr_eos();
                        msg_check();
                        gotocmdline(false);
                        out_flush();
                        msg_nowait = TRUE;
                    }
                    if (!shortmess(SHM_SEARCHCOUNT)) {
                        show_search_stats = true;
                    }
                }
                if (spats[0].off.line == 0 && spats[0].off.off != 0 && pos.col[0] < MAXCOL - 2) {
                    if (spats[0].off.off > 0L) {
                        c = spats[0].off.off;
                        for (; c != 0; c--) {
                            if (decl(pos) == -1) {
                                break;
                            }
                        }
                        if (c != 0) {
                            pos.lnum[0] = 0L;
                            pos.col[0] = MAXCOL;
                        }
                    } else {
                        c = spats[0].off.off;
                        for (; c != 0; c++) {
                            if (incl(pos) == -1) {
                                break;
                            }
                        }
                        if (c != 0) {
                            pos.lnum[0] = curbuf.b_ml.ml_line_count + 1L;
                            pos.col[0] = 0;
                        }
                    }
                }
                c = (long) searchit(curwin, curbuf, pos, null, dirc == '/' ? FORWARD : -1, searchstr[0], searchstrlen[0], count, spats[0].off.end + (options & (SEARCH_KEEP + SEARCH_PEEK + SEARCH_HIS + SEARCH_MSG + SEARCH_START + (pat[0] != null && pat[0].get() == ';' ? 0 : SEARCH_NOOF))), RE_LAST, sia);
                if (dircp[0] != null) {
                    dircp[0].put((byte) search_delim);
                }
                if (!shortmess(SHM_SEARCH) && sia != null && sia.sa_wrapped) {
                    show_top_bot_msg = true;
                }
                if (c == FAIL) {
                    retval = 0;
                    break L_end_do_search;
                }
                if (spats[0].off.end != 0 && oap != null) {
                    oap.inclusive = TRUE;
                }
                retval = 1;
                if ((options & SEARCH_NOOF) == 0 || (pat[0] != null && pat[0].get() == ';')) {
                    org_pos.set(pos);
                    if (spats[0].off.line != 0) {
                        c = pos.lnum[0] + spats[0].off.off;
                        if (c < 1L) {
                            pos.lnum[0] = 1L;
                        } else if (c > curbuf.b_ml.ml_line_count) {
                            pos.lnum[0] = curbuf.b_ml.ml_line_count;
                        } else {
                            pos.lnum[0] = c;
                        }
                        pos.col[0] = 0;
                        retval = 2;
                    } else if (pos.col[0] < MAXCOL - 2) {
                        c = spats[0].off.off;
                        if (c > 0L) {
                            while (true) {
                                t4 = c;
                                c--;
                                if (!(t4 > 0L)) {
                                    break;
                                }
                                if (incl(pos) == -1) {
                                    break;
                                }
                            }
                        } else {
                            while (true) {
                                t5 = c;
                                c++;
                                if (!(t5 < 0L)) {
                                    break;
                                }
                                if (decl(pos) == -1) {
                                    break;
                                }
                            }
                        }
                    }
                    if (!(pos.lnum[0] == org_pos.lnum[0] && pos.col[0] == org_pos.col[0] && pos.coladd == org_pos.coladd)) {
                        has_offset = true;
                    }
                }
                if (show_search_stats) {
                    cmdline_search_stat(dirc, pos, curwin.w_cursor, show_top_bot_msg, msgbuf, msgbuflen, count != 1L || has_offset, (int) p_msc[0], SEARCH_STAT_DEF_TIMEOUT);
                }
                if ((options & SEARCH_OPT) == 0 || pat[0] == null || pat[0].get() != ';') {
                    break;
                }
                pat[0] = pat[0].add(1);
                dirc = pat[0].get() & 0xff;
                search_delim = dirc;
                if (dirc != '?' && dirc != '/') {
                    retval = 0;
                    emsg(gettext_(new BytePtr(e_expected_question_or_slash_after_semicolon, 0)));
                    break L_end_do_search;
                }
                pat[0] = pat[0].add(1);
                patlen[0]--;
            }
            if ((options & SEARCH_MARK) != 0) {
                setpcmark();
            }
            curwin.w_cursor.set(pos);
            curwin.w_set_curswant = true;
        }
        if ((options & SEARCH_KEEP) != 0 || (cmdmod.cmod_flags & CMOD_KEEPPATTERNS) != 0) {
            spats[0].off.set(old_off);
        }
        return retval;
    }

    boolean searchc(S_cmdarg_S cap, int t_cmd) {
        int c = 0;
        int dir = 0;
        long count = 0;
        int col = 0;
        BytePtr p = null;
        int len = 0;
        boolean stop = false;
        long t1 = 0;
        c = cap.nchar[0];
        dir = cap.arg;
        count = cap.count1;
        stop = true;
        if (c != NUL) {
            if (KeyStuffed == 0) {
                lastc[0] = (byte) c;
                set_csearch_direction(dir);
                set_csearch_until(t_cmd);
                lastc_bytelen = utf_char2bytes(c, new BytePtr(lastc_bytes, 0));
                if (cap.ncharC1 != 0) {
                    lastc_bytelen += utf_char2bytes(cap.ncharC1, new BytePtr(lastc_bytes, 0).add(lastc_bytelen));
                    if (cap.ncharC2 != 0) {
                        lastc_bytelen += utf_char2bytes(cap.ncharC2, new BytePtr(lastc_bytes, 0).add(lastc_bytelen));
                    }
                }
            }
        } else {
            if (lastc[0] == NUL && lastc_bytelen <= 1) {
                return false;
            }
            if (dir != 0) {
                dir = -lastcdir;
            } else {
                dir = lastcdir;
            }
            t_cmd = last_t_cmd;
            c = lastc[0] & 0xff;
            if (vim_strchr(p_cpo[0], CPO_SCOLON) == null && count == 1L && t_cmd != 0) {
                stop = false;
            }
        }
        if (dir == -1) {
            cap.oap.inclusive = FALSE;
        } else {
            cap.oap.inclusive = TRUE;
        }
        p = ml_get_curline();
        col = curwin.w_cursor.col[0];
        len = ml_get_curline_len();
        while (true) {
            t1 = count;
            count--;
            if (!(t1 != 0)) {
                break;
            }
            for (;;) {
                if (dir > 0) {
                    col += utfc_ptr2len(p.add(col));
                    if (col >= len) {
                        return false;
                    }
                } else {
                    if (col == 0) {
                        return false;
                    }
                    col -= utf_head_off(p, p.add(col).add(-1)) + 1;
                }
                if (lastc_bytelen <= 1) {
                    if ((p.at(col) & 0xff) == c && stop) {
                        break;
                    }
                } else if (musl_strncmp(p.add(col), new BytePtr(lastc_bytes, 0), (long) lastc_bytelen) == 0 && stop) {
                    break;
                }
                stop = true;
            }
        }
        if (t_cmd != 0) {
            col -= dir;
            if (dir < 0) {
                col += lastc_bytelen - 1;
            } else {
                col -= utf_head_off(p, p.add(col));
            }
        }
        curwin.w_cursor.col[0] = col;
        return true;
    }

    T_pos_T findmatch(S_oparg_S oap, int initc) {
        return findmatchlimit(oap, initc, 0, 0);
    }

    boolean check_prevcol(BytePtr linep, int col, int ch, IntPtr prevcol) {
        col--;
        if (col > 0) {
            col -= utf_head_off(linep, linep.add(col));
        }
        if (prevcol != null) {
            prevcol.put(col);
        }
        return (col >= 0 && (linep.at(col) & 0xff) == ch ? TRUE : FALSE) != 0;
    }

    boolean find_rawstring_end(BytePtr linep, T_pos_T startpos, T_pos_T endpos) {
        BytePtr p = null;
        BytePtr delim_copy = null;
        long delim_len = 0;
        long lnum = 0;
        boolean found = false;
        BytePtr line = null;
        found = false;
        p = linep.add(startpos.col[0]).add(1);
        for (; (p.get() != 0) && p.get() != '('; p = p.add(1)) {
        }
        delim_len = p.sub(linep) - (long) startpos.col[0] - 1L;
        delim_copy = vim_strnsave(linep.add(startpos.col[0]).add(1), delim_len);
        lnum = startpos.lnum[0];
        for (; lnum <= endpos.lnum[0]; lnum++) {
            line = ml_get(lnum);
            p = line.add(lnum == startpos.lnum[0] ? startpos.col[0] + 1 : 0);
            for (; p.get() != 0; p = p.add(1)) {
                if (lnum == endpos.lnum[0] && (int) p.sub(line) >= endpos.col[0]) {
                    break;
                }
                if (p.get() == ')' && musl_strncmp(delim_copy, p.add(1), delim_len) == 0 && p.at((int) (delim_len + 1L)) == '"') {
                    found = true;
                    break;
                }
            }
            if (found) {
                break;
            }
        }
        return found;
    }

    void find_mps_values(IntPtr initc, IntPtr findc, IntPtr backwards, boolean switchit) {
        BytePtr ptr = null;
        BytePtr prev = null;
        ptr = curbuf.b_p_mps[0];
        while (ptr.get() != NUL) {
            if (utf_ptr2char(ptr) == initc.get()) {
                if (switchit) {
                    findc.put(initc.get());
                    initc.put(utf_ptr2char(ptr.add(utfc_ptr2len(ptr)).add(1)));
                    backwards.put(TRUE);
                } else {
                    findc.put(utf_ptr2char(ptr.add(utfc_ptr2len(ptr)).add(1)));
                    backwards.put(FALSE);
                }
                return;
            }
            prev = ptr;
            ptr = ptr.add(utfc_ptr2len(ptr) + 1);
            if (utf_ptr2char(ptr) == initc.get()) {
                if (switchit) {
                    findc.put(initc.get());
                    initc.put(utf_ptr2char(prev));
                    backwards.put(FALSE);
                } else {
                    findc.put(utf_ptr2char(prev));
                    backwards.put(TRUE);
                }
                return;
            }
            ptr = ptr.add(utfc_ptr2len(ptr));
            if (ptr.get() == ',') {
                ptr = ptr.add(1);
            }
        }
    }

    T_pos_T findmatchlimit(S_oparg_S oap, int initc_arg, int flags, int maxtravel) {
        int[] initc = new int[] {initc_arg};
        int[] findc = new int[1];
        int c = 0;
        int count = 0;
        int[] backwards = new int[1];
        boolean raw_string = false;
        int inquote = 0;
        BytePtr linep = null;
        BytePtr ptr = null;
        int do_quotes = 0;
        int at_start = 0;
        int hash_dir = 0;
        int comment_dir = 0;
        T_pos_T match_pos = new T_pos_T();
        int start_in_quotes = 0;
        int traveled = 0;
        boolean ignore_cend = false;
        boolean cpo_match = false;
        boolean cpo_bsl = false;
        int match_escaped = 0;
        int dir = 0;
        int comment_col = 0;
        boolean skip_comments = false;
        boolean in_block_comment = false;
        int[] col = new int[1];
        int bslcnt = 0;
        boolean t1 = false;
        int t2 = 0;
        boolean t3 = false;
        int col_2 = 0;
        int[] col_3 = new int[1];
        int bslcnt_2 = 0;
        findc[0] = 0;
        count = 0;
        backwards[0] = FALSE;
        raw_string = false;
        inquote = FALSE;
        hash_dir = 0;
        comment_dir = 0;
        traveled = 0;
        ignore_cend = false;
        match_escaped = 0;
        comment_col = MAXCOL;
        skip_comments = (flags & FM_SKIPCOMM) != 0;
        in_block_comment = false;
        findmatchlimit_pos.set(curwin.w_cursor);
        findmatchlimit_pos.coladd = 0;
        linep = ml_get(findmatchlimit_pos.lnum[0]);
        cpo_match = vim_strchr(p_cpo[0], CPO_MATCH) != null;
        cpo_bsl = vim_strchr(p_cpo[0], CPO_MATCHBSL) != null;
        if ((flags & FM_BACKWARD) != 0) {
            dir = -1;
        } else if ((flags & FM_FORWARD) != 0) {
            dir = FORWARD;
        } else {
            dir = 0;
        }
        if (initc[0] == '/' || initc[0] == '*' || initc[0] == 'R') {
            comment_dir = dir;
            if (initc[0] == '/') {
                ignore_cend = true;
            }
            backwards[0] = dir == FORWARD ? FALSE : TRUE;
            raw_string = initc[0] == 'R';
            initc[0] = NUL;
        } else if (initc[0] != '#' && initc[0] != NUL) {
            find_mps_values(new IntPtr(initc, 0), new IntPtr(findc, 0), new IntPtr(backwards, 0), true);
            if (dir != 0) {
                backwards[0] = dir == FORWARD ? FALSE : TRUE;
            }
            if (findc[0] == NUL) {
                return null;
            }
        } else {
            if (initc[0] == '#') {
                hash_dir = dir;
            } else {
                if (!cpo_match) {
                    ptr = skipwhite(linep);
                    if (ptr.get() == '#' && findmatchlimit_pos.col[0] <= (int) ptr.sub(linep)) {
                        ptr = skipwhite(ptr.add(1));
                        if (musl_strncmp(ptr, BytePtr.lit("if"), 2L) == 0 || musl_strncmp(ptr, BytePtr.lit("endif"), 5L) == 0 || musl_strncmp(ptr, BytePtr.lit("el"), 2L) == 0) {
                            hash_dir = 1;
                        }
                    } else if (linep.at(findmatchlimit_pos.col[0]) == '/') {
                        if (linep.at(findmatchlimit_pos.col[0] + 1) == '*') {
                            comment_dir = FORWARD;
                            backwards[0] = FALSE;
                            findmatchlimit_pos.col[0]++;
                        } else if (findmatchlimit_pos.col[0] > 0 && linep.at(findmatchlimit_pos.col[0] - 1) == '*') {
                            comment_dir = -1;
                            backwards[0] = TRUE;
                            findmatchlimit_pos.col[0]--;
                        }
                    } else if (linep.at(findmatchlimit_pos.col[0]) == '*') {
                        if (linep.at(findmatchlimit_pos.col[0] + 1) == '/') {
                            comment_dir = -1;
                            backwards[0] = TRUE;
                        } else if (findmatchlimit_pos.col[0] > 0 && linep.at(findmatchlimit_pos.col[0] - 1) == '/') {
                            comment_dir = FORWARD;
                            backwards[0] = FALSE;
                        }
                    }
                }
                if (hash_dir == 0 && comment_dir == 0) {
                    if (linep.at(findmatchlimit_pos.col[0]) == NUL && findmatchlimit_pos.col[0] != 0) {
                        findmatchlimit_pos.col[0]--;
                    }
                    for (;;) {
                        initc[0] = utf_ptr2char(linep.add(findmatchlimit_pos.col[0]));
                        if (initc[0] == NUL) {
                            break;
                        }
                        find_mps_values(new IntPtr(initc, 0), new IntPtr(findc, 0), new IntPtr(backwards, 0), false);
                        if (findc[0] != 0) {
                            break;
                        }
                        findmatchlimit_pos.col[0] += utfc_ptr2len(linep.add(findmatchlimit_pos.col[0]));
                    }
                    if (findc[0] == 0) {
                        if (!cpo_match && skipwhite(linep).get() == '#') {
                            hash_dir = 1;
                        } else {
                            return null;
                        }
                    } else if (!cpo_bsl) {
                        bslcnt = 0;
                        col[0] = findmatchlimit_pos.col[0];
                        for (; check_prevcol(linep, col[0], '\\', new IntPtr(col, 0)); ) {
                            bslcnt++;
                        }
                        match_escaped = bslcnt & 1;
                    }
                }
            }
            if (hash_dir != 0) {
                if (oap != null) {
                    oap.motion_type = MLINE;
                }
                if (initc[0] != '#') {
                    ptr = skipwhite(skipwhite(linep).add(1));
                    if (musl_strncmp(ptr, BytePtr.lit("if"), 2L) == 0 || musl_strncmp(ptr, BytePtr.lit("el"), 2L) == 0) {
                        hash_dir = 1;
                    } else if (musl_strncmp(ptr, BytePtr.lit("endif"), 5L) == 0) {
                        hash_dir = -1;
                    } else {
                        return null;
                    }
                }
                findmatchlimit_pos.col[0] = 0;
                while (got_int == 0) {
                    if (hash_dir > 0) {
                        if (findmatchlimit_pos.lnum[0] == curbuf.b_ml.ml_line_count) {
                            break;
                        }
                    } else if (findmatchlimit_pos.lnum[0] == 1L) {
                        break;
                    }
                    findmatchlimit_pos.lnum[0] += (long) hash_dir;
                    linep = ml_get(findmatchlimit_pos.lnum[0]);
                    line_breakcheck();
                    ptr = skipwhite(linep);
                    if (ptr.get() != '#') {
                        continue;
                    }
                    findmatchlimit_pos.col[0] = (int) ptr.sub(linep);
                    ptr = skipwhite(ptr.add(1));
                    if (hash_dir > 0) {
                        if (musl_strncmp(ptr, BytePtr.lit("if"), 2L) == 0) {
                            count++;
                        } else if (musl_strncmp(ptr, BytePtr.lit("el"), 2L) == 0) {
                            if (count == 0) {
                                return findmatchlimit_pos;
                            }
                        } else if (musl_strncmp(ptr, BytePtr.lit("endif"), 5L) == 0) {
                            if (count == 0) {
                                return findmatchlimit_pos;
                            }
                            count--;
                        }
                    } else {
                        if (musl_strncmp(ptr, BytePtr.lit("if"), 2L) == 0) {
                            if (count == 0) {
                                return findmatchlimit_pos;
                            }
                            count--;
                        } else if (initc[0] == '#' && musl_strncmp(ptr, BytePtr.lit("el"), 2L) == 0) {
                            if (count == 0) {
                                return findmatchlimit_pos;
                            }
                        } else if (musl_strncmp(ptr, BytePtr.lit("endif"), 5L) == 0) {
                            count++;
                        }
                    }
                }
                return null;
            }
        }
        do_quotes = -1;
        start_in_quotes = MAYBE;
        match_pos.lnum[0] = 0L;
        match_pos.col[0] = 0;
        match_pos.coladd = 0;
        if ((backwards[0] != 0 && comment_dir != 0) || skip_comments) {
            comment_col = check_linecomment(linep);
        }
        if (skip_comments && !in_block_comment && comment_col != MAXCOL && backwards[0] != 0 && findmatchlimit_pos.col[0] > comment_col) {
            findmatchlimit_pos.col[0] = comment_col;
        }
        while (got_int == 0) {
            if (backwards[0] != 0) {
                if (findmatchlimit_pos.col[0] == 0) {
                    if (findmatchlimit_pos.lnum[0] == 1L) {
                        break;
                    }
                    findmatchlimit_pos.lnum[0]--;
                    t1 = maxtravel > 0;
                    if (t1) {
                        traveled++;
                        t1 = traveled > maxtravel;
                    }
                    if (t1) {
                        break;
                    }
                    linep = ml_get(findmatchlimit_pos.lnum[0]);
                    findmatchlimit_pos.col[0] = ml_get_len(findmatchlimit_pos.lnum[0]);
                    do_quotes = -1;
                    line_breakcheck();
                    if (comment_dir != 0 || skip_comments) {
                        comment_col = check_linecomment(linep);
                    }
                    if (skip_comments && !in_block_comment && comment_col != MAXCOL && findmatchlimit_pos.col[0] > comment_col) {
                        findmatchlimit_pos.col[0] = comment_col;
                    }
                } else {
                    findmatchlimit_pos.col[0]--;
                    findmatchlimit_pos.col[0] -= utf_head_off(linep, linep.add(findmatchlimit_pos.col[0]));
                }
            } else {
                if (linep.at(findmatchlimit_pos.col[0]) == NUL) {
                    if (findmatchlimit_pos.lnum[0] == curbuf.b_ml.ml_line_count) {
                        break;
                    }
                    findmatchlimit_pos.lnum[0]++;
                    t3 = maxtravel != 0;
                    if (t3) {
                        t2 = traveled;
                        traveled++;
                        t3 = t2 > maxtravel;
                    }
                    if (t3) {
                        break;
                    }
                    linep = ml_get(findmatchlimit_pos.lnum[0]);
                    findmatchlimit_pos.col[0] = 0;
                    do_quotes = -1;
                    line_breakcheck();
                    if (skip_comments) {
                        comment_col = check_linecomment(linep);
                    }
                } else {
                    findmatchlimit_pos.col[0] += utfc_ptr2len(linep.add(findmatchlimit_pos.col[0]));
                }
            }
            if (skip_comments && comment_dir == 0 && inquote == 0) {
                if (backwards[0] != 0) {
                    if (!in_block_comment && findmatchlimit_pos.col[0] > 0 && linep.at(findmatchlimit_pos.col[0] - 1) == '*' && linep.at(findmatchlimit_pos.col[0]) == '/' && (comment_col == MAXCOL || findmatchlimit_pos.col[0] < comment_col)) {
                        in_block_comment = true;
                    } else if (in_block_comment && findmatchlimit_pos.col[0] > 0 && linep.at(findmatchlimit_pos.col[0] - 1) == '/' && linep.at(findmatchlimit_pos.col[0]) == '*') {
                        in_block_comment = false;
                    }
                } else {
                    if (!in_block_comment && linep.at(findmatchlimit_pos.col[0]) == '/' && linep.at(findmatchlimit_pos.col[0] + 1) == '*' && (comment_col == MAXCOL || findmatchlimit_pos.col[0] < comment_col)) {
                        in_block_comment = true;
                    } else if (in_block_comment && findmatchlimit_pos.col[0] > 0 && linep.at(findmatchlimit_pos.col[0] - 1) == '*' && linep.at(findmatchlimit_pos.col[0]) == '/') {
                        in_block_comment = false;
                    }
                }
            }
            if (findmatchlimit_pos.col[0] == 0 && (flags & FM_BLOCKSTOP) != 0 && (linep.at(0) == '{' || linep.at(0) == '}')) {
                if ((linep.at(0) & 0xff) == findc[0] && count == 0) {
                    return findmatchlimit_pos;
                }
                break;
            }
            if (comment_dir != 0) {
                if (comment_dir == FORWARD) {
                    if (linep.at(findmatchlimit_pos.col[0]) == '*' && linep.at(findmatchlimit_pos.col[0] + 1) == '/') {
                        findmatchlimit_pos.col[0]++;
                        return findmatchlimit_pos;
                    }
                } else {
                    if (findmatchlimit_pos.col[0] == 0) {
                        continue;
                    } else if (raw_string) {
                        if (linep.at(findmatchlimit_pos.col[0] - 1) == 'R' && linep.at(findmatchlimit_pos.col[0]) == '"' && vim_strchr(linep.add(findmatchlimit_pos.col[0]).add(1), '(') != null) {
                            if (!find_rawstring_end(linep, findmatchlimit_pos, count > 0 ? match_pos : curwin.w_cursor)) {
                                count++;
                                match_pos.set(findmatchlimit_pos);
                                match_pos.col[0]--;
                            }
                            linep = ml_get(findmatchlimit_pos.lnum[0]);
                        }
                    } else if (linep.at(findmatchlimit_pos.col[0] - 1) == '/' && linep.at(findmatchlimit_pos.col[0]) == '*' && (findmatchlimit_pos.col[0] == 1 || linep.at(findmatchlimit_pos.col[0] - 2) != '*') && findmatchlimit_pos.col[0] < comment_col) {
                        count++;
                        match_pos.set(findmatchlimit_pos);
                        match_pos.col[0]--;
                    } else if (linep.at(findmatchlimit_pos.col[0] - 1) == '*' && linep.at(findmatchlimit_pos.col[0]) == '/') {
                        if (count > 0) {
                            findmatchlimit_pos.set(match_pos);
                        } else if (findmatchlimit_pos.col[0] > 1 && linep.at(findmatchlimit_pos.col[0] - 2) == '/' && findmatchlimit_pos.col[0] <= comment_col) {
                            findmatchlimit_pos.col[0] -= 2;
                        } else if (ignore_cend) {
                            continue;
                        } else {
                            return null;
                        }
                        return findmatchlimit_pos;
                    }
                }
                continue;
            }
            if (cpo_match) {
                do_quotes = 0;
            } else if (do_quotes == -1) {
                at_start = do_quotes;
                ptr = linep;
                for (; ptr.get() != 0; ptr = ptr.add(1)) {
                    if (BytePtr.eq(ptr, linep.add(findmatchlimit_pos.col[0]).add(backwards[0]))) {
                        at_start = do_quotes & 1;
                    }
                    if (ptr.get() == '"' && (BytePtr.eq(ptr, linep) || ptr.at(-1) != '\'' || ptr.at(1) != '\'')) {
                        do_quotes++;
                    }
                    if (ptr.get() == '\\' && ptr.at(1) != NUL) {
                        ptr = ptr.add(1);
                    }
                }
                do_quotes &= 1;
                if (do_quotes == 0) {
                    inquote = FALSE;
                    if (ptr.at(-1) == '\\') {
                        do_quotes = 1;
                        if (start_in_quotes == MAYBE) {
                            inquote = at_start;
                            if (inquote != 0) {
                                start_in_quotes = TRUE;
                            }
                        } else if (backwards[0] != 0) {
                            inquote = TRUE;
                        }
                    }
                    if (findmatchlimit_pos.lnum[0] > 1L) {
                        ptr = ml_get(findmatchlimit_pos.lnum[0] - 1L);
                        if (ptr.get() != 0 && ptr.add(ml_get_len(findmatchlimit_pos.lnum[0] - 1L)).add(-1).get() == '\\') {
                            do_quotes = 1;
                            if (start_in_quotes == MAYBE) {
                                inquote = at_start;
                                if (inquote != 0) {
                                    start_in_quotes = TRUE;
                                }
                            } else if (backwards[0] == 0) {
                                inquote = TRUE;
                            }
                        }
                        linep = ml_get(findmatchlimit_pos.lnum[0]);
                    }
                }
            }
            if (start_in_quotes == MAYBE) {
                start_in_quotes = FALSE;
            }
            c = utf_ptr2char(linep.add(findmatchlimit_pos.col[0]));
            switch (c) {
                case NUL:
                    if (findmatchlimit_pos.col[0] == 0 || linep.at(findmatchlimit_pos.col[0] - 1) != '\\') {
                        inquote = FALSE;
                        start_in_quotes = FALSE;
                    }
                    break;
                case '"':
                    if (do_quotes != 0) {
                        col_2 = findmatchlimit_pos.col[0] - 1;
                        for (; col_2 >= 0; col_2--) {
                            if (linep.at(col_2) != '\\') {
                                break;
                            }
                        }
                        if (((findmatchlimit_pos.col[0] - 1 - col_2) & 1) == 0) {
                            inquote = inquote == 0 ? 1 : 0;
                            start_in_quotes = FALSE;
                        }
                    }
                    break;
                case '\'':
                    if (!cpo_match && initc[0] != '\'' && findc[0] != '\'') {
                        if (backwards[0] != 0) {
                            if (findmatchlimit_pos.col[0] > 1) {
                                if (linep.at(findmatchlimit_pos.col[0] - 2) == '\'') {
                                    findmatchlimit_pos.col[0] -= 2;
                                    break;
                                } else if (linep.at(findmatchlimit_pos.col[0] - 2) == '\\' && findmatchlimit_pos.col[0] > 2 && linep.at(findmatchlimit_pos.col[0] - 3) == '\'') {
                                    findmatchlimit_pos.col[0] -= 3;
                                    break;
                                }
                            }
                        } else if (linep.at(findmatchlimit_pos.col[0] + 1) != 0) {
                            if (linep.at(findmatchlimit_pos.col[0] + 1) == '\\' && linep.at(findmatchlimit_pos.col[0] + 2) != 0 && linep.at(findmatchlimit_pos.col[0] + 3) == '\'') {
                                findmatchlimit_pos.col[0] += 3;
                                break;
                            } else if (linep.at(findmatchlimit_pos.col[0] + 2) == '\'') {
                                findmatchlimit_pos.col[0] += 2;
                                break;
                            }
                        }
                    }
                default:
                    if (skip_comments && (in_block_comment || (comment_col != MAXCOL && findmatchlimit_pos.col[0] >= comment_col))) {
                        break;
                    }
                    if ((inquote == 0 || start_in_quotes == TRUE) && (c == initc[0] || c == findc[0])) {
                        bslcnt_2 = 0;
                        if (!cpo_bsl) {
                            col_3[0] = findmatchlimit_pos.col[0];
                            for (; check_prevcol(linep, col_3[0], '\\', new IntPtr(col_3, 0)); ) {
                                bslcnt_2++;
                            }
                        }
                        if (cpo_bsl || (bslcnt_2 & 1) == match_escaped) {
                            if (c == initc[0]) {
                                count++;
                            } else {
                                if (count == 0) {
                                    return findmatchlimit_pos;
                                }
                                count--;
                            }
                        }
                    }
            }
        }
        if (comment_dir == -1 && count > 0) {
            findmatchlimit_pos.set(match_pos);
            return findmatchlimit_pos;
        }
        return null;
    }

    void showmatch(int c) {
        T_pos_T lpos = null;
        T_pos_T save_cursor = new T_pos_T();
        T_pos_T mpos = new T_pos_T();
        int[] vcol = new int[1];
        long save_so = 0;
        long save_siso = 0;
        int save_dollar_vcol = 0;
        BytePtr p = null;
        LongPtr so = null;
        LongPtr siso = null;
        boolean col_visible = false;
        so = curwin.w_onebuf_opt.wo_so[0] >= 0L ? new LongPtr(curwin.w_onebuf_opt.wo_so, 0) : new LongPtr(p_so, 0);
        siso = curwin.w_onebuf_opt.wo_siso[0] >= 0L ? new LongPtr(curwin.w_onebuf_opt.wo_siso, 0) : new LongPtr(p_siso, 0);
        p = curbuf.b_p_mps[0];
        for (; p.get() != NUL; p = p.add(1)) {
            p = p.add(utfc_ptr2len(p) + 1);
            if (utf_ptr2char(p) == c) {
                break;
            }
            p = p.add(utfc_ptr2len(p));
            if (p.get() == NUL) {
                return;
            }
        }
        if (p.get() == NUL) {
            return;
        }
        lpos = findmatch(null, NUL);
        if (lpos == null) {
            vim_beep(BO_MATCH);
            return;
        }
        if (lpos.lnum[0] < curwin.w_topline || lpos.lnum[0] >= curwin.w_botline) {
            return;
        }
        if (curwin.w_onebuf_opt.wo_wrap[0] == 0) {
            getvcol(curwin, lpos, null, new IntPtr(vcol, 0), null, 0);
        }
        col_visible = curwin.w_onebuf_opt.wo_wrap[0] != 0 || (vcol[0] >= curwin.w_leftcol && vcol[0] < curwin.w_leftcol + curwin.w_width);
        if (!col_visible) {
            return;
        }
        mpos.set(lpos);
        save_cursor.set(curwin.w_cursor);
        save_so = so.get();
        save_siso = siso.get();
        if (dollar_vcol >= 0 && dollar_vcol == curwin.w_virtcol[0]) {
            dollar_vcol = -1;
        }
        curwin.w_virtcol[0]++;
        update_screen(UPD_VALID);
        save_dollar_vcol = dollar_vcol;
        curwin.w_cursor.set(mpos);
        so.put(0L);
        siso.put(0L);
        showruler(false);
        setcursor();
        cursor_on();
        out_flush_cursor(true, false);
        dollar_vcol = save_dollar_vcol;
        if (vim_strchr(p_cpo[0], CPO_SHOWMATCH) != null) {
            ui_delay(p_mat[0] * 100L + 8L, true);
        } else if (!char_avail()) {
            ui_delay(p_mat[0] * 100L + 9L, false);
        }
        curwin.w_cursor.set(save_cursor);
        so.put(save_so);
        siso.put(save_siso);
    }

    int is_zero_width(BytePtr pattern, long patternlen, boolean move, T_pos_T cur, int direction) {
        T_regmmatch_T regmatch = new T_regmmatch_T();
        int nmatched = 0;
        int result = 0;
        T_pos_T pos = new T_pos_T();
        int called_emsg_before = 0;
        int flag = 0;
        nmatched = 0;
        result = -1;
        called_emsg_before = called_emsg;
        flag = 0;
        if (pattern == null) {
            pattern = spats[last_idx].pat;
            patternlen = spats[last_idx].patlen;
        }
        if (!search_regcomp(pattern, patternlen, null, RE_SEARCH, RE_SEARCH, SEARCH_KEEP, regmatch)) {
            return -1;
        }
        regmatch.startpos[0].col = -1;
        if (move) {
            pos.lnum[0] = 0L;
            pos.col[0] = 0;
            pos.coladd = 0;
        } else {
            pos.set(cur);
            flag = SEARCH_START;
        }
        if (searchit(curwin, curbuf, pos, null, direction, pattern, patternlen, 1L, SEARCH_KEEP + flag, RE_SEARCH, null) != FAIL) {
            do {
                regmatch.startpos[0].col++;
                nmatched = (int) vim_regexec_multi(regmatch, curwin, curbuf, pos.lnum[0], regmatch.startpos[0].col, null);
                if (nmatched != 0) {
                    break;
                }
            } while (regmatch.regprog != null && (direction == FORWARD ? regmatch.startpos[0].col < pos.col[0] : regmatch.startpos[0].col > pos.col[0]));
            if (called_emsg == called_emsg_before) {
                result = nmatched != 0 && regmatch.startpos[0].lnum == regmatch.endpos[0].lnum && regmatch.startpos[0].col == regmatch.endpos[0].col ? 1 : 0;
            }
        }
        vim_regfree(regmatch.regprog);
        return result;
    }

    boolean current_search(long count, boolean forward) {
        T_pos_T start_pos = new T_pos_T();
        T_pos_T end_pos = new T_pos_T();
        T_pos_T orig_pos = new T_pos_T();
        T_pos_T pos = new T_pos_T();
        int i = 0;
        int dir = 0;
        int result = 0;
        byte old_p_ws = 0;
        int flags = 0;
        T_pos_T save_VIsual = new T_pos_T();
        int zero_width = 0;
        boolean skip_first_backward = false;
        old_p_ws = (byte) p_ws[0];
        flags = 0;
        save_VIsual.set(VIsual);
        if (VIsual_active != 0 && p_sel[0].get() == 'e' && (VIsual.lnum[0] != curwin.w_cursor.lnum[0] ? VIsual.lnum[0] < curwin.w_cursor.lnum[0] : (VIsual.col[0] != curwin.w_cursor.col[0] ? VIsual.col[0] < curwin.w_cursor.col[0] : VIsual.coladd < curwin.w_cursor.coladd))) {
            dec_cursor();
        }
        skip_first_backward = forward && VIsual_active != 0 && (curwin.w_cursor.lnum[0] != VIsual.lnum[0] ? curwin.w_cursor.lnum[0] < VIsual.lnum[0] : (curwin.w_cursor.col[0] != VIsual.col[0] ? curwin.w_cursor.col[0] < VIsual.col[0] : curwin.w_cursor.coladd < VIsual.coladd));
        pos.set(curwin.w_cursor);
        orig_pos.set(pos);
        if (VIsual_active != 0) {
            if (forward) {
                incl(pos);
            } else {
                decl(pos);
            }
        }
        zero_width = is_zero_width(spats[last_idx].pat, spats[last_idx].patlen, true, curwin.w_cursor, FORWARD);
        if (zero_width == -1) {
            return false;
        }
        i = 0;
        for (; i < 2; i++) {
            if (forward) {
                if (i == 0 && skip_first_backward) {
                    continue;
                }
                dir = i;
            } else {
                dir = i == 0 ? 1 : 0;
            }
            flags = 0;
            if (dir == 0 && zero_width == 0) {
                flags = SEARCH_END;
            }
            end_pos.set(pos);
            if (i == 0) {
                p_ws[0] = FALSE;
            }
            result = searchit(curwin, curbuf, pos, end_pos, dir != 0 ? FORWARD : -1, spats[last_idx].pat, spats[last_idx].patlen, i != 0 ? count : 1L, SEARCH_KEEP | flags, RE_SEARCH, null);
            p_ws[0] = old_p_ws & 0xff;
            if (i == 1 && result == 0) {
                curwin.w_cursor.set(orig_pos);
                if (VIsual_active != 0) {
                    VIsual.set(save_VIsual);
                }
                return false;
            } else if (i == 0 && result == 0) {
                if (forward) {
                    pos.lnum[0] = 0L;
                    pos.col[0] = 0;
                    pos.coladd = 0;
                } else {
                    pos.lnum[0] = curwin.w_buffer.b_ml.ml_line_count;
                    pos.col[0] = ml_get_len(curwin.w_buffer.b_ml.ml_line_count);
                }
            }
        }
        start_pos.set(pos);
        if (VIsual_active == 0) {
            VIsual.set(start_pos);
        }
        curwin.w_cursor.set(end_pos);
        if ((VIsual.lnum[0] != end_pos.lnum[0] ? VIsual.lnum[0] < end_pos.lnum[0] : (VIsual.col[0] != end_pos.col[0] ? VIsual.col[0] < end_pos.col[0] : VIsual.coladd < end_pos.coladd)) && forward) {
            if (skip_first_backward) {
                curwin.w_cursor.set(pos);
            } else {
                dec_cursor();
            }
        } else if (VIsual_active != 0 && (curwin.w_cursor.lnum[0] != VIsual.lnum[0] ? curwin.w_cursor.lnum[0] < VIsual.lnum[0] : (curwin.w_cursor.col[0] != VIsual.col[0] ? curwin.w_cursor.col[0] < VIsual.col[0] : curwin.w_cursor.coladd < VIsual.coladd)) && forward) {
            curwin.w_cursor.set(pos);
        }
        VIsual_active = TRUE;
        VIsual_mode = 'v';
        if (p_sel[0].get() == 'e') {
            if (forward && ((VIsual.lnum[0] != curwin.w_cursor.lnum[0] ? VIsual.lnum[0] < curwin.w_cursor.lnum[0] : (VIsual.col[0] != curwin.w_cursor.col[0] ? VIsual.col[0] < curwin.w_cursor.col[0] : VIsual.coladd < curwin.w_cursor.coladd)) || (VIsual.lnum[0] == curwin.w_cursor.lnum[0] && VIsual.col[0] == curwin.w_cursor.col[0] && VIsual.coladd == curwin.w_cursor.coladd))) {
                inc_cursor();
            } else if (!forward && ((curwin.w_cursor.lnum[0] != VIsual.lnum[0] ? curwin.w_cursor.lnum[0] < VIsual.lnum[0] : (curwin.w_cursor.col[0] != VIsual.col[0] ? curwin.w_cursor.col[0] < VIsual.col[0] : curwin.w_cursor.coladd < VIsual.coladd)) || (curwin.w_cursor.lnum[0] == VIsual.lnum[0] && curwin.w_cursor.col[0] == VIsual.col[0] && curwin.w_cursor.coladd == VIsual.coladd))) {
                inc(VIsual);
            }
        }
        may_start_select('c');
        redraw_curbuf_later(UPD_INVERTED);
        showmode();
        return true;
    }

    void cmdline_search_stat(int dirc, T_pos_T pos, T_pos_T cursor_pos, boolean show_top_bot_msg, BytePtr msgbuf, long msgbuflen, boolean recompute, int maxcount, long timeout) {
        S_searchstat stat = new S_searchstat();
        byte[] t = new byte[16];
        long len = 0;
        update_search_stat(dirc, pos, cursor_pos, stat, recompute, maxcount, timeout);
        if (stat.cur <= 0) {
            return;
        }
        if (stat.incomplete == 1) {
            len = (long) vim_snprintf(new BytePtr(t, 0), SEARCH_STAT_BUF_LEN, BytePtr.lit("[?/??]"));
        } else if (stat.cnt > maxcount && stat.cur > maxcount) {
            len = (long) vim_snprintf(new BytePtr(t, 0), SEARCH_STAT_BUF_LEN, BytePtr.lit("[>%d/>%d]"), maxcount, maxcount);
        } else if (stat.cnt > maxcount) {
            len = (long) vim_snprintf(new BytePtr(t, 0), SEARCH_STAT_BUF_LEN, BytePtr.lit("[%d/>%d]"), stat.cur, maxcount);
        } else {
            len = (long) vim_snprintf(new BytePtr(t, 0), SEARCH_STAT_BUF_LEN, BytePtr.lit("[%d/%d]"), stat.cur, stat.cnt);
        }
        if (show_top_bot_msg && Long.compareUnsigned(len + 2L, SEARCH_STAT_BUF_LEN) < 0) {
            Rt.memmove(new BytePtr(t, 0).add(2), new BytePtr(t, 0), len);
            t[0] = (byte) 'W';
            t[1] = (byte) ' ';
            len += 2L;
        }
        if (Long.compareUnsigned(len, msgbuflen) > 0) {
            len = msgbuflen;
        }
        Rt.memmove(msgbuf.add((int) msgbuflen).add(-((int) len)), new BytePtr(t, 0), len);
        if (dirc == '?' && stat.cur == maxcount + 1) {
            stat.cur = -1;
        }
        msg_hist_off = TRUE;
        give_warning(msgbuf, false);
        msg_hist_off = FALSE;
    }

    void update_search_stat(int dirc, T_pos_T pos, T_pos_T cursor_pos, S_searchstat stat, boolean recompute, int maxcount, long timeout) {
        int save_ws = 0;
        boolean wraparound = false;
        T_pos_T p = new T_pos_T();
        boolean done_search = false;
        T_pos_T endpos = new T_pos_T();
        save_ws = p_ws[0];
        wraparound = false;
        p.set(pos);
        stat.zero();
        if (dirc == 0 && !recompute && !(update_search_stat_lastpos.lnum[0] == 0L && update_search_stat_lastpos.col[0] == 0 && update_search_stat_lastpos.coladd == 0)) {
            stat.cur = update_search_stat_cur;
            stat.cnt = update_search_stat_cnt;
            stat.exact_match = update_search_stat_exact_match;
            stat.incomplete = update_search_stat_incomplete;
            stat.last_maxcount = update_search_stat_last_maxcount;
            return;
        }
        update_search_stat_last_maxcount = maxcount;
        wraparound = (dirc == '?' && (update_search_stat_lastpos.lnum[0] != p.lnum[0] ? update_search_stat_lastpos.lnum[0] < p.lnum[0] : (update_search_stat_lastpos.col[0] != p.col[0] ? update_search_stat_lastpos.col[0] < p.col[0] : update_search_stat_lastpos.coladd < p.coladd))) || (dirc == '/' && (p.lnum[0] != update_search_stat_lastpos.lnum[0] ? p.lnum[0] < update_search_stat_lastpos.lnum[0] : (p.col[0] != update_search_stat_lastpos.col[0] ? p.col[0] < update_search_stat_lastpos.col[0] : p.coladd < update_search_stat_lastpos.coladd)));
        if (!((long) update_search_stat_chgtick == curbuf.b_changedtick && (update_search_stat_lastpat != null && musl_strncmp(update_search_stat_lastpat, spats[last_idx].pat, update_search_stat_lastpatlen) == 0 && update_search_stat_lastpatlen == spats[last_idx].patlen) && (update_search_stat_lastpos.lnum[0] == cursor_pos.lnum[0] && update_search_stat_lastpos.col[0] == cursor_pos.col[0] && update_search_stat_lastpos.coladd == cursor_pos.coladd) && update_search_stat_lbuf == curbuf) || wraparound || update_search_stat_cur < 0 || (maxcount > 0 && update_search_stat_cur > maxcount) || recompute) {
            update_search_stat_cur = 0;
            update_search_stat_cnt = 0;
            update_search_stat_exact_match = false;
            update_search_stat_incomplete = 0;
            update_search_stat_lastpos.lnum[0] = 0L;
            update_search_stat_lastpos.col[0] = 0;
            update_search_stat_lastpos.coladd = 0;
            update_search_stat_lbuf = curbuf;
        }
        if (update_search_stat_lastpos.lnum[0] == cursor_pos.lnum[0] && update_search_stat_lastpos.col[0] == cursor_pos.col[0] && update_search_stat_lastpos.coladd == cursor_pos.coladd && !wraparound && (dirc == 0 || dirc == '/' ? update_search_stat_cur < update_search_stat_cnt : update_search_stat_cur > 1)) {
            update_search_stat_cur += dirc == 0 ? 0 : (dirc == '/' ? 1 : -1);
        } else {
            done_search = false;
            endpos = new T_pos_T();
            p_ws[0] = FALSE;
            while (got_int == 0 && searchit(curwin, curbuf, update_search_stat_lastpos, endpos, FORWARD, null, 0L, 1L, SEARCH_KEEP, RE_LAST, null) != FAIL) {
                done_search = true;
                update_search_stat_cnt++;
                if ((update_search_stat_lastpos.lnum[0] != p.lnum[0] ? update_search_stat_lastpos.lnum[0] < p.lnum[0] : (update_search_stat_lastpos.col[0] != p.col[0] ? update_search_stat_lastpos.col[0] < p.col[0] : update_search_stat_lastpos.coladd < p.coladd)) || (update_search_stat_lastpos.lnum[0] == p.lnum[0] && update_search_stat_lastpos.col[0] == p.col[0] && update_search_stat_lastpos.coladd == p.coladd)) {
                    update_search_stat_cur = update_search_stat_cnt;
                    if (p.lnum[0] != endpos.lnum[0] ? p.lnum[0] < endpos.lnum[0] : (p.col[0] != endpos.col[0] ? p.col[0] < endpos.col[0] : p.coladd < endpos.coladd)) {
                        update_search_stat_exact_match = true;
                    }
                }
                fast_breakcheck();
                if (maxcount > 0 && update_search_stat_cnt > maxcount) {
                    update_search_stat_incomplete = 2;
                    break;
                }
            }
            if (got_int != 0) {
                update_search_stat_cur = -1;
            }
            if (done_search) {
                update_search_stat_lastpat = vim_strnsave(spats[last_idx].pat, spats[last_idx].patlen);
                update_search_stat_lastpatlen = spats[last_idx].patlen;
                update_search_stat_chgtick = (int) curbuf.b_changedtick;
                update_search_stat_lbuf = curbuf;
                update_search_stat_lastpos.set(p);
            }
        }
        stat.cur = update_search_stat_cur;
        stat.cnt = update_search_stat_cnt;
        stat.exact_match = update_search_stat_exact_match;
        stat.incomplete = update_search_stat_incomplete;
        stat.last_maxcount = update_search_stat_last_maxcount;
        p_ws[0] = save_ws;
    }

    BytePtr vim_strsave(BytePtr string) {
        BytePtr p = null;
        long len = 0;
        len = musl_strlen(string) + 1L;
        p = BytePtr.alloc(len);
        Rt.memmove(p, string, len);
        return p;
    }

    BytePtr vim_strnsave(BytePtr string, long len) {
        BytePtr p = null;
        p = BytePtr.alloc(len + 1L);
        musl_strncpy(p, string, len);
        p.set((int) len, (byte) NUL);
        return p;
    }

    BytePtr vim_strsave_escaped(BytePtr string, BytePtr esc_chars) {
        return vim_strsave_escaped_ext(string, esc_chars, '\\', false);
    }

    BytePtr vim_strsave_escaped_ext(BytePtr string, BytePtr esc_chars, int cc, boolean bsl) {
        BytePtr p = null;
        BytePtr p2 = null;
        BytePtr escaped_string = null;
        int length = 0;
        int l = 0;
        BytePtr t1 = null;
        BytePtr t2 = null;
        length = 1;
        p = string;
        for (; p.get() != 0; p = p.add(1)) {
            l = utfc_ptr2len(p);
            if (l > 1) {
                length += l;
                p = p.add(l - 1);
                continue;
            }
            if (vim_strchr(esc_chars, p.get() & 0xff) != null || (bsl && rem_backslash(p))) {
                length++;
            }
            length++;
        }
        escaped_string = BytePtr.alloc(Integer.toUnsignedLong(length));
        p2 = escaped_string;
        p = string;
        for (; p.get() != 0; p = p.add(1)) {
            l = utfc_ptr2len(p);
            if (l > 1) {
                Rt.memmove(p2, p, (long) l);
                p2 = p2.add(l);
                p = p.add(l - 1);
                continue;
            }
            if (vim_strchr(esc_chars, p.get() & 0xff) != null || (bsl && rem_backslash(p))) {
                t1 = p2;
                p2 = p2.add(1);
                t1.put((byte) cc);
            }
            t2 = p2;
            p2 = p2.add(1);
            t2.put(p.get());
        }
        p2.put((byte) NUL);
        return escaped_string;
    }

    BytePtr vim_strnsave_up(BytePtr string, long len) {
        BytePtr p1 = null;
        p1 = vim_strnsave(string, len);
        vim_strup(p1);
        return p1;
    }

    void vim_strup(BytePtr p) {
        BytePtr p2 = null;
        int c = 0;
        BytePtr t1 = null;
        if (p == null) {
            return;
        }
        p2 = p;
        while (true) {
            c = p2.get() & 0xff;
            if (!(c != NUL)) {
                break;
            }
            t1 = p2;
            p2 = p2.add(1);
            t1.put((byte) (c < 'a' || c > 'z' ? c : c - 32));
        }
    }

    void del_trailing_spaces(BytePtr ptr) {
        BytePtr q = null;
        q = ptr.add((int) musl_strlen(ptr));
        while (true) {
            q = q.add(-1);
            if (!(q.gt(ptr) && (q.at(0) == ' ' || q.at(0) == '\t') && q.at(-1) != '\\' && q.at(-1) != Ctrl_V)) {
                break;
            }
            q.put((byte) NUL);
        }
    }

    void vim_strncpy(BytePtr to_, BytePtr from, long len) {
        musl_strncpy(to_, from, len);
        to_.set((int) len, (byte) NUL);
    }

    void vim_strcat(BytePtr to_, BytePtr from, long tosize) {
        long tolen = 0;
        long fromlen = 0;
        tolen = musl_strlen(to_);
        fromlen = musl_strlen(from);
        if (Long.compareUnsigned(tolen + fromlen + 1L, tosize) > 0) {
            Rt.memmove(to_.add((int) tolen), from, tosize - tolen - 1L);
            to_.set((int) (tosize - 1L), (byte) NUL);
        } else {
            Rt.memmove(to_.add((int) tolen), from, fromlen + 1L);
        }
    }

    int vim_strnicmp_asc(BytePtr s1, BytePtr s2, long len) {
        int i = 0;
        i = 0;
        while (Long.compareUnsigned(len, 0L) > 0) {
            i = ((int) s1.get() < 'A' || (int) s1.get() > 'Z' ? (int) s1.get() : (int) s1.get() + ('a' - 'A')) - ((int) s2.get() < 'A' || (int) s2.get() > 'Z' ? (int) s2.get() : (int) s2.get() + ('a' - 'A'));
            if (i != 0) {
                break;
            }
            if ((int) s1.get() == NUL) {
                break;
            }
            s1 = s1.add(1);
            s2 = s2.add(1);
            len--;
        }
        return i;
    }

    BytePtr vim_strchr(BytePtr string, int c) {
        BytePtr p = null;
        int b = 0;
        int l = 0;
        p = string;
        if (c > 0 && c < 128) {
            return vim_strbyte(string, c);
        }
        if (c >= 128) {
            while (p.get() != NUL) {
                l = utfc_ptr2len(p);
                if (utf_ptr2char(p) == c && l > 1) {
                    return p;
                }
                p = p.add(l);
            }
            return null;
        }
        while (true) {
            b = p.get() & 0xff;
            if (!(b != NUL)) {
                break;
            }
            if (b == c) {
                return p;
            }
            p = p.add(utfc_ptr2len(p));
        }
        return null;
    }

    BytePtr vim_strbyte(BytePtr string, int c) {
        if (c <= 0 || c > 255) {
            return null;
        }
        return musl_strchr(string, c);
    }

    void sort_strings(Ptr<BytePtr> files, int count) {
        int i = 0;
        int j = 0;
        BytePtr s = null;
        i = 1;
        for (; i < count; i++) {
            s = files.at(i);
            j = i;
            for (; (j > 0) && musl_strcmp(files.at(j - 1), s) > 0; j--) {
                files.set(j, files.at(j - 1));
            }
            files.set(j, s);
        }
    }

    BytePtr concat_str(BytePtr str1, BytePtr str2) {
        BytePtr dest = null;
        long l = 0;
        l = str1 == null ? 0L : musl_strlen(str1);
        dest = BytePtr.alloc(l + (str2 == null ? 0L : musl_strlen(str2)) + 1L);
        if (str1 == null) {
            dest.put((byte) NUL);
        } else {
            musl_strcpy(dest, str1);
        }
        if (str2 != null) {
            musl_strcpy(dest.add((int) l), str2);
        }
        return dest;
    }

    void set_rgb_term_prop() {
        term_props[TPR_RGB].tpr_status = t_colors == 16777216 ? TPR_YES : TPR_UNKNOWN;
    }

    void init_term_props(boolean all) {
        int i = 0;
        term_props[TPR_CURSOR_STYLE].tpr_name = BytePtr.lit("cursor_style");
        term_props[TPR_CURSOR_STYLE].tpr_set_by_termresponse = false;
        term_props[TPR_CURSOR_BLINK].tpr_name = BytePtr.lit("cursor_blink_mode");
        term_props[TPR_CURSOR_BLINK].tpr_set_by_termresponse = false;
        term_props[TPR_UNDERLINE_RGB].tpr_name = BytePtr.lit("underline_rgb");
        term_props[TPR_UNDERLINE_RGB].tpr_set_by_termresponse = true;
        term_props[TPR_MOUSE].tpr_name = BytePtr.lit("mouse");
        term_props[TPR_MOUSE].tpr_set_by_termresponse = true;
        term_props[TPR_KITTY].tpr_name = BytePtr.lit("kitty");
        term_props[TPR_KITTY].tpr_set_by_termresponse = false;
        term_props[TPR_DECRQM].tpr_name = BytePtr.lit("decrqm");
        term_props[TPR_DECRQM].tpr_set_by_termresponse = true;
        term_props[TPR_RGB].tpr_name = BytePtr.lit("rgb");
        term_props[TPR_RGB].tpr_set_by_termresponse = false;
        i = 0;
        for (; i < TPR_COUNT; i++) {
            if (all || term_props[i].tpr_set_by_termresponse) {
                term_props[i].tpr_status = TPR_UNKNOWN;
            }
        }
        set_rgb_term_prop();
    }

    Ptr<T_tcap_entry_T> find_builtin_term(BytePtr term) {
        int i = 0;
        BytePtr name = null;
        i = 0;
        for (; ; i++) {
            name = builtin_terminals[i].bitc_name;
            if (name == null) {
                break;
            }
            if (musl_strcmp(term, name) == 0) {
                return builtin_terminals[i].bitc_table;
            }
        }
        return null;
    }

    void apply_builtin_tcap(BytePtr term, Ptr<T_tcap_entry_T> entries, boolean overwrite) {
        boolean term_8bit = false;
        Ptr<T_tcap_entry_T> p = null;
        BytePtr s = null;
        BytePtr t = null;
        byte[] name = new byte[2];
        term_8bit = term_is_8bit(term);
        p = entries;
        for (; (p.get().bt_entry != KS_NAME) && p.get().bt_entry != BT_EXTRA_KEYS; p = p.add(1)) {
            if (p.get().bt_entry >= 0) {
                if (term_strings[p.get().bt_entry] == null || BytePtr.eq(term_strings[p.get().bt_entry], empty_option) || overwrite) {
                    if (term_8bit && term_7to8bit(p.get().bt_string) != 0) {
                        s = vim_strsave(p.get().bt_string);
                        t = s;
                        for (; t.get() != 0; t = t.add(1)) {
                            if (term_7to8bit(t) != 0) {
                                t.put((byte) term_7to8bit(t));
                                Rt.memmove(t.add(1), t.add(2), musl_strlen(t.add(2)) + 1L);
                            }
                        }
                        term_strings[p.get().bt_entry] = s;
                        set_term_option_alloced(new Ptr<BytePtr>(term_strings, p.get().bt_entry));
                    } else {
                        term_strings[p.get().bt_entry] = p.get().bt_string;
                    }
                }
            } else {
                name[0] = (byte) (-p.get().bt_entry & 255);
                name[1] = (byte) ((-p.get().bt_entry >>> 8) & 255);
                if (find_termcode(new BytePtr(name, 0)) == null || overwrite) {
                    add_termcode(new BytePtr(name, 0), p.get().bt_string, term_8bit ? 1 : 0);
                }
            }
        }
    }

    void apply_keyprotocol(BytePtr term, int prot) {
        if (prot == KEYPROTOCOL_KITTY) {
            apply_builtin_tcap(term, new Ptr<T_tcap_entry_T>(builtin_kitty, 0), true);
        }
        if (prot == KEYPROTOCOL_MOK2) {
            apply_builtin_tcap(term, new Ptr<T_tcap_entry_T>(builtin_mok2, 0), true);
        }
        if (prot != KEYPROTOCOL_NONE) {
            accept_modifiers_for_function_keys();
        }
    }

    void parse_builtin_tcap(BytePtr term) {
        Ptr<T_tcap_entry_T> entries = null;
        entries = find_builtin_term(term);
        if (entries != null) {
            apply_builtin_tcap(term, entries, false);
        }
    }

    void set_color_count(int nr) {
        byte[] nr_colors = new byte[20];
        t_colors = nr;
        if (t_colors > 1) {
            vim_snprintf(new BytePtr(nr_colors, 0), 20L, BytePtr.lit("%d"), t_colors);
        } else {
            nr_colors[0] = (byte) NUL;
        }
        set_string_option_direct(BytePtr.lit("t_Co"), -1, new BytePtr(nr_colors, 0), OPT_FREE, 0);
    }

    void may_adjust_color_count(int val) {
        if (val == t_colors) {
            return;
        }
        set_keep_msg_from_hist();
        set_color_count(val);
        init_highlight(true, false);
        redraw_asap(UPD_CLEAR);
    }

    boolean term_strings_not_set(int idx) {
        return term_strings[idx] == null || BytePtr.eq(term_strings[idx], empty_option);
    }

    void report_term_error(BytePtr error_msg, BytePtr term) {
        byte[] buf = new byte[1024];
        if (error_msg != null) {
            vim_snprintf(new BytePtr(buf, 0), 1024L, BytePtr.lit("\015\n%s\015\n'%s%s\015\n"), error_msg, term, gettext_(BytePtr.lit("' not known")));
        } else {
            vim_snprintf(new BytePtr(buf, 0), 1024L, BytePtr.lit("\015\n'%s%s\015\n"), term, gettext_(BytePtr.lit("' not known")));
        }
        host_message(new BytePtr(buf, 0), -1, TRUE);
    }

    int match_keyprotocol(BytePtr term) {
        int len = 0;
        BytePtr buf = null;
        int ret = 0;
        BytePtr[] p = new BytePtr[1];
        BytePtr colon = null;
        int prot = 0;
        T_regmatch_T regmatch = new T_regmatch_T();
        boolean match = false;
        len = (int) musl_strlen(p_kpc[0]) + 1;
        buf = BytePtr.alloc((long) len);
        ret = KEYPROTOCOL_FAIL;
        p[0] = p_kpc[0];
        while (p[0].get() != NUL) {
            copy_option_part(new Ptr<BytePtr>(p, 0), buf, len, BytePtr.lit(","));
            colon = vim_strchr(buf, ':');
            if (colon == null || BytePtr.eq(colon, buf) || colon.at(1) == NUL) {
                return ret;
            }
            colon.put((byte) NUL);
            if (musl_strcmp(colon.add(1), BytePtr.lit("none")) == 0) {
                prot = KEYPROTOCOL_NONE;
            } else if (musl_strcmp(colon.add(1), BytePtr.lit("mok2")) == 0) {
                prot = KEYPROTOCOL_MOK2;
            } else if (musl_strcmp(colon.add(1), BytePtr.lit("kitty")) == 0) {
                prot = KEYPROTOCOL_KITTY;
            } else {
                return ret;
            }
            regmatch.zero();
            regmatch.rm_ic = true;
            regmatch.regprog = vim_regcomp(buf, RE_MAGIC);
            if (regmatch.regprog == null) {
                return ret;
            }
            match = term != null && vim_regexec(regmatch, term, 0);
            vim_regfree(regmatch.regprog);
            if (match) {
                ret = prot;
                return ret;
            }
        }
        ret = KEYPROTOCOL_NONE;
        return ret;
    }

    boolean set_termname(BytePtr term) {
        int width = 0;
        int height = 0;
        BytePtr error_msg = null;
        BytePtr bs_p = null;
        BytePtr del_p = null;
        Ptr<T_tcap_entry_T> termp = null;
        int kpc = 0;
        byte[] name = new byte[3];
        width = 0;
        height = 0;
        error_msg = null;
        detected_8bit = FALSE;
        if (term_is_builtin(term)) {
            term = term.add(8);
        }
        termp = find_builtin_term(term);
        if (termp == null) {
            report_term_error(error_msg, term);
            screen_start();
            wait_return(TRUE);
            return false;
        }
        out_flush();
        clear_termoptions();
        parse_builtin_tcap(term);
        if (musl_strstr(term, BytePtr.lit("256color")) != null && (term_strings_not_set(KS_CCO) || musl_atoi(term_strings[KS_CCO]) < 256)) {
            apply_builtin_tcap(term, new Ptr<T_tcap_entry_T>(builtin_256colors, 0), true);
        }
        kpc = match_keyprotocol(term);
        apply_keyprotocol(term, kpc);
        if (musl_strcmp(term, BytePtr.lit("pcterm")) == 0) {
            term_strings[KS_CCS] = BytePtr.lit("yes");
        } else {
            term_strings[KS_CCS] = empty_option;
        }
        if (musl_strstr(term, BytePtr.lit("kitty")) != null && (term_strings[KS_CRV] == null || term_strings[KS_CRV].get() == NUL)) {
            term_strings[KS_CRV] = BytePtr.lit("\033[>c");
        }
        get_stty();
        bs_p = find_termcode(BytePtr.lit("kb"));
        del_p = find_termcode(BytePtr.lit("kD"));
        if (bs_p == null || bs_p.get() == NUL) {
            bs_p = BytePtr.lit("\010");
            add_termcode(BytePtr.lit("kb"), bs_p, FALSE);
        }
        if ((del_p == null || del_p.get() == NUL) && (bs_p == null || bs_p.get() != DEL)) {
            add_termcode(BytePtr.lit("kD"), BytePtr.lit("\177"), FALSE);
        }
        term_is_xterm = vim_is_xterm(term) ? 1 : 0;
        name[0] = (byte) KS_EXTRA;
        name[1] = (byte) KE_FOCUSGAINED;
        name[2] = (byte) NUL;
        add_termcode(new BytePtr(name, 0), BytePtr.lit("\033[I"), FALSE);
        name[1] = (byte) KE_FOCUSLOST;
        add_termcode(new BytePtr(name, 0), BytePtr.lit("\033[O"), FALSE);
        need_gather = TRUE;
        focus_state = MAYBE;
        ttest(true);
        full_screen = TRUE;
        set_term_defaults();
        if (starting != NO_SCREEN) {
            starttermcap();
        }
        if (width <= 0 || height <= 0) {
            width = 80;
            height = 24;
        }
        set_shellsize(width, height, FALSE);
        if (starting != NO_SCREEN) {
            if (scroll_region != 0) {
                scroll_region_reset();
            }
            check_map_keycodes();
        }
        return true;
    }

    boolean add_termcap_entry(BytePtr name, boolean force) {
        BytePtr term = null;
        int key = 0;
        Ptr<T_tcap_entry_T> termp = null;
        if (!force && find_termcode(name) != null) {
            return true;
        }
        term = term_strings[KS_NAME];
        if (term == null || term.get() == NUL) {
            return false;
        }
        if (term_is_builtin(term)) {
            term = term.add(8);
        }
        termp = find_builtin_term(term);
        if (termp != null) {
            key = -((name.at(0) & 0xff) + ((name.at(1) & 0xff) << 8));
            termp = termp.add(1);
            while (termp.get().bt_entry != KS_NAME) {
                if (termp.get().bt_entry == key) {
                    add_termcode(name, termp.get().bt_string, term_is_8bit(term) ? 1 : 0);
                    return true;
                }
                termp = termp.add(1);
            }
        }
        if (GA_Ptr_T_estack_T(exestack).at(exestack.ga_len - 1).es_name == null) {
            vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(new BytePtr(e_no_str_entry_in_termcap, 0)), name);
            emsg(iobuff_or(gettext_(new BytePtr(e_no_str_entry_in_termcap, 0))));
        }
        return false;
    }

    boolean term_is_builtin(BytePtr name) {
        return musl_strncmp(name, BytePtr.lit("builtin_"), 8L) == 0;
    }

    boolean term_is_8bit(BytePtr name) {
        return detected_8bit != 0 || musl_strstr(name, BytePtr.lit("8bit")) != null;
    }

    int term_7to8bit(BytePtr p) {
        if (p.get() != ESC) {
            return 0;
        }
        if (p.at(1) == '[') {
            return CSI;
        } else if (p.at(1) == ']') {
            return OSC;
        } else if (p.at(1) == 'O') {
            return 143;
        }
        return 0;
    }

    BytePtr tltoa(long i) {
        BytePtr p = null;
        p = new BytePtr(tltoa_buf, 0).add(15);
        p.put((byte) '\0');
        do {
            p = p.add(-1);
            p.put((byte) (Long.remainderUnsigned(i, 10L) + '0'));
            i = Long.divideUnsigned(i, 10L);
        } while (Long.compareUnsigned(i, 0L) > 0 && p.gt(new BytePtr(tltoa_buf, 0)));
        return p;
    }

    BytePtr tgoto(BytePtr cm, int x, int y) {
        BytePtr p = null;
        BytePtr s = null;
        BytePtr e = null;
        BytePtr t1 = null;
        BytePtr t2 = null;
        BytePtr t3 = null;
        BytePtr t4 = null;
        BytePtr t5 = null;
        if (cm == null) {
            return BytePtr.lit("OOPS");
        }
        e = new BytePtr(tgoto_buf, 0).add(29);
        s = new BytePtr(tgoto_buf, 0);
        for (; s.lt(e) && cm.get() != 0; cm = cm.add(1)) {
            if ((int) cm.get() != '%') {
                t1 = s;
                s = s.add(1);
                t1.put(cm.get());
                continue;
            }
            cm = cm.add(1);
            switch ((int) cm.get()) {
                case 'd':
                    p = tltoa((long) y);
                    y = x;
                    while (p.get() != 0) {
                        t2 = s;
                        s = s.add(1);
                        t3 = p;
                        p = p.add(1);
                        t2.put(t3.get());
                    }
                    break;
                case 'i':
                    x++;
                    y++;
                    break;
                case '+':
                    t4 = s;
                    s = s.add(1);
                    cm = cm.add(1);
                    t4.put((byte) ((int) cm.get() + y));
                    y = x;
                    break;
                case '%':
                    t5 = s;
                    s = s.add(1);
                    t5.put(cm.get());
                    break;
                default:
                    return BytePtr.lit("OOPS");
            }
        }
        s.put((byte) '\0');
        return new BytePtr(tgoto_buf, 0);
    }

    void termcapinit() {
        BytePtr term = null;
        term = BytePtr.lit("xterm-256color");
        set_string_option_direct(BytePtr.lit("term"), -1, term, OPT_FREE, 0);
        set_string_default(BytePtr.lit("term"), term);
        set_string_default(BytePtr.lit("ttytype"), term);
        set_termname(term_strings[KS_NAME] != null ? term_strings[KS_NAME] : term);
    }

    void out_flush() {
        int len = 0;
        if (out_pos == 0) {
            return;
        }
        len = out_pos;
        out_pos = 0;
        ui_write(new BytePtr(out_buf, 0), len);
    }

    void out_flush_cursor(boolean force, boolean clear_selection) {
        out_flush();
    }

    void out_char(int c) {
        int t1 = 0;
        if (c == '\n') {
            out_char('\r');
        }
        t1 = out_pos;
        out_pos++;
        out_buf[t1] = (byte) c;
        if (out_pos >= OUT_SIZE || p_wd[0] != 0) {
            out_flush();
        }
    }

    int out_char_nf(int c) {
        int t1 = 0;
        t1 = out_pos;
        out_pos++;
        out_buf[t1] = (byte) c;
        if (out_pos >= OUT_SIZE) {
            out_flush();
        }
        return c;
    }

    void out_str_nf(BytePtr s) {
        BytePtr p = null;
        if (out_pos > (OUT_SIZE - MAX_ESC_SEQ_LEN)) {
            out_flush();
        }
        p = s;
        for (; p.get() != NUL; p = p.add(1)) {
            out_char_nf(p.get() & 0xff);
        }
        if (p_wd[0] != 0) {
            out_flush();
        }
    }

    void out_str_cf(BytePtr s) {
        BytePtr t1 = null;
        if (s == null || s.get() == NUL) {
            return;
        }
        if (out_pos > (OUT_SIZE - MAX_ESC_SEQ_LEN)) {
            out_flush();
        }
        while (s.get() != 0) {
            t1 = s;
            s = s.add(1);
            out_char_nf(t1.get() & 0xff);
        }
        if (p_wd[0] != 0) {
            out_flush();
        }
    }

    void out_str(BytePtr s) {
        BytePtr t1 = null;
        if (s == null || s.get() == NUL) {
            return;
        }
        if (out_pos > (OUT_SIZE - MAX_ESC_SEQ_LEN)) {
            out_flush();
        }
        while (s.get() != 0) {
            t1 = s;
            s = s.add(1);
            out_char_nf(t1.get() & 0xff);
        }
        if (p_wd[0] != 0) {
            out_flush();
        }
    }

