    void term_font(int n) {
        byte[] buf = new byte[20];
        if (term_strings[KS_CF].get() != 0) {
            vim_snprintf(new BytePtr(buf, 0), 20L, term_strings[KS_CF], 9 + n);
            out_str(new BytePtr(buf, 0));
        }
    }

    void term_color(BytePtr s, int n) {
        byte[] buf = new byte[20];
        int i = 0;
        boolean t1 = false;
        boolean t2 = false;
        boolean t3 = false;
        BytePtr format = null;
        BytePtr lead = null;
        BytePtr tail = null;
        i = (s.get() & 0xff) == CSI ? 1 : 2;
        t3 = n >= 8 && t_colors >= 16;
        if (t3) {
            t2 = s.at(0) == ESC && s.at(1) == '[';
            if (!t2) {
                t1 = (s.at(0) & 0xff) == CSI;
                if (t1) {
                    i = 1;
                    t1 = i == 1;
                }
                t2 = t1;
            }
            t3 = t2;
        }
        if (t3 && s.at(i) != NUL && (musl_strcmp(s.add(i).add(1), BytePtr.lit("%p1%dm")) == 0 || musl_strcmp(s.add(i).add(1), BytePtr.lit("%dm")) == 0) && (s.at(i) == '3' || s.at(i) == '4')) {
            format = BytePtr.lit("%s%s%%dm");
            lead = i == 2 ? BytePtr.lit("\033[") : BytePtr.lit("\233");
            tail = s.at(i) == '3' ? (n >= 16 ? BytePtr.lit("38;5;") : BytePtr.lit("9")) : (n >= 16 ? BytePtr.lit("48;5;") : BytePtr.lit("10"));
            vim_snprintf(new BytePtr(buf, 0), 20L, format, lead, tail);
            out_str(tgoto(new BytePtr(buf, 0), 0, n >= 16 ? n : n - 8));
        } else {
            out_str(tgoto(s, 0, n));
        }
    }

    void term_fg_color(int n) {
        if (term_strings[KS_CAF].get() != 0) {
            term_color(term_strings[KS_CAF], n);
        } else if (term_strings[KS_CSF].get() != 0) {
            term_color(term_strings[KS_CSF], n);
        }
    }

    void term_bg_color(int n) {
        if (term_strings[KS_CAB].get() != 0) {
            term_color(term_strings[KS_CAB], n);
        } else if (term_strings[KS_CSB].get() != 0) {
            term_color(term_strings[KS_CSB], n);
        }
    }

    void term_ul_color(int n) {
        if (term_strings[KS_CAU].get() != 0) {
            term_color(term_strings[KS_CAU], n);
        }
    }

    BytePtr term_bg_default() {
        if (musl_strcmp(term_strings[KS_NAME], BytePtr.lit("linux")) == 0 || musl_strcmp(term_strings[KS_NAME], BytePtr.lit("screen.linux")) == 0 || musl_strncmp(term_strings[KS_NAME], BytePtr.lit("cygwin"), 6L) == 0 || musl_strncmp(term_strings[KS_NAME], BytePtr.lit("putty"), 5L) == 0) {
            return BytePtr.lit("dark");
        }
        return BytePtr.lit("light");
    }

    void ttest(boolean pairs) {
        check_options();
        if (term_strings[KS_CM].get() == NUL) {
            emsg(gettext_(new BytePtr(e_terminal_capability_cm_required, 0)));
        }
        if (term_strings[KS_CS].get() != NUL) {
            scroll_region = TRUE;
        } else {
            scroll_region = FALSE;
        }
        if (pairs) {
            if (term_strings[KS_ME].get() == NUL) {
                term_strings[KS_MB] = empty_option;
                term_strings[KS_MD] = term_strings[KS_MB];
                term_strings[KS_MR] = term_strings[KS_MD];
                term_strings[KS_ME] = term_strings[KS_MR];
            }
            if (term_strings[KS_SO].get() == NUL || term_strings[KS_SE].get() == NUL) {
                term_strings[KS_SE] = empty_option;
                term_strings[KS_SO] = term_strings[KS_SE];
            }
            if (term_strings[KS_US].get() == NUL || term_strings[KS_UE].get() == NUL) {
                term_strings[KS_UE] = empty_option;
                term_strings[KS_US] = term_strings[KS_UE];
            }
            if (term_strings[KS_CZH].get() == NUL || term_strings[KS_CZR].get() == NUL) {
                term_strings[KS_CZR] = empty_option;
                term_strings[KS_CZH] = term_strings[KS_CZR];
            }
            if (term_strings[KS_VE].get() == NUL) {
                term_strings[KS_VI] = empty_option;
            }
            if (term_strings[KS_ME].get() == NUL) {
                term_strings[KS_ME] = term_strings[KS_SE];
                term_strings[KS_MR] = term_strings[KS_SO];
                term_strings[KS_MD] = term_strings[KS_SO];
            }
            if (term_strings[KS_SO].get() == NUL) {
                term_strings[KS_SE] = term_strings[KS_ME];
                if (term_strings[KS_MR].get() == NUL) {
                    term_strings[KS_SO] = term_strings[KS_MD];
                } else {
                    term_strings[KS_SO] = term_strings[KS_MR];
                }
            }
            if (term_strings[KS_CZH].get() == NUL) {
                term_strings[KS_CZR] = term_strings[KS_ME];
                if (term_strings[KS_MR].get() == NUL) {
                    term_strings[KS_CZH] = term_strings[KS_MD];
                } else {
                    term_strings[KS_CZH] = term_strings[KS_MR];
                }
            }
            if (term_strings[KS_CSB].get() == NUL || term_strings[KS_CSF].get() == NUL) {
                term_strings[KS_CSB] = empty_option;
                term_strings[KS_CSF] = empty_option;
            }
            if (term_strings[KS_CAB].get() == NUL || term_strings[KS_CAF].get() == NUL) {
                term_strings[KS_CAB] = empty_option;
                term_strings[KS_CAF] = empty_option;
            }
            p_wiv[0] = term_strings[KS_XS].get() != NUL ? 1 : 0;
        }
        need_gather = TRUE;
        t_colors = musl_atoi(term_strings[KS_CCO]);
        set_rgb_term_prop();
    }

    void check_shellsize() {
        if (Rows[0] < (long) min_rows_for_all_tabpages()) {
            Rows[0] = (long) min_rows_for_all_tabpages();
        }
        limit_screen_size();
        if ((long) cmdline_row >= Rows[0]) {
            cmdline_row = (int) (Rows[0] - 1L);
        }
        if ((long) msg_row >= Rows[0]) {
            msg_row = (int) (Rows[0] - 1L);
        }
    }

    void limit_screen_size() {
        if (Columns[0] < MIN_COLUMNS) {
            Columns[0] = MIN_COLUMNS;
        } else if (Columns[0] > 10000L) {
            Columns[0] = 10000L;
        }
        if (Rows[0] > 1000L) {
            Rows[0] = 1000L;
        }
    }

    void win_new_shellsize() {
        if ((long) win_new_shellsize_old_Rows != Rows[0] || (long) win_new_shellsize_old_Columns != Columns[0] || win_new_shellsize_old_coloff != 0) {
            ui_new_shellsize();
        }
        if ((long) win_new_shellsize_old_Columns != Columns[0] || win_new_shellsize_old_coloff != 0) {
            win_new_shellsize_old_Columns = (int) Columns[0];
            win_new_shellsize_old_coloff = 0;
            shell_new_columns();
        }
        if ((long) win_new_shellsize_old_Rows != Rows[0]) {
            if (p_window[0] == (long) (win_new_shellsize_old_Rows - 1) || (win_new_shellsize_old_Rows == 0 && !option_was_set(BytePtr.lit("window")))) {
                p_window[0] = Rows[0] - 1L;
            }
            win_new_shellsize_old_Rows = (int) Rows[0];
            shell_new_rows();
        }
    }

    void shell_resized() {
        set_shellsize(0, 0, FALSE);
    }

    void set_shellsize_inner(int width, int height, int mustset) {
        if (updating_screen != 0) {
            return;
        }
        if (curwin.w_buffer == null || curwin.w_lines == null) {
            return;
        }
        if (mustset != 0 || (!ui_get_shellsize() && height != 0)) {
            Rows[0] = (long) height;
            Columns[0] = (long) width;
            check_shellsize();
            ui_set_shellsize(mustset);
        } else {
            check_shellsize();
        }
        if (State != MODE_ASKMORE && State != MODE_EXTERNCMD && State != MODE_CONFIRM) {
            screenclear();
        } else {
            screen_start();
        }
        if (starting != NO_SCREEN) {
            changed_line_abv_curs();
            invalidate_botline();
            if (State == MODE_ASKMORE || State == MODE_EXTERNCMD || State == MODE_CONFIRM) {
                screenalloc(false);
                repeat_message();
            } else {
                if ((State & MODE_CMDLINE) != 0) {
                    update_screen(UPD_NOT_VALID);
                    redrawcmdline();
                } else {
                    update_topline();
                    update_screen(UPD_NOT_VALID);
                    if (redrawing()) {
                        setcursor();
                    }
                }
            }
            cursor_on();
        }
        out_flush();
    }

    void set_shellsize(int width, int height, int mustset) {
        if (width < 0 || height < 0) {
            return;
        }
        if (State == (8192 | MODE_NORMAL) || State == MODE_SETWSIZE) {
            State = MODE_SETWSIZE;
            return;
        }
        set_shellsize_do_run = true;
        if (set_shellsize_busy) {
            return;
        }
        while (set_shellsize_do_run) {
            set_shellsize_do_run = false;
            set_shellsize_busy = true;
            set_shellsize_inner(width, height, mustset);
            set_shellsize_busy = false;
        }
    }

    void out_str_t_TE() {
        out_str(term_strings[KS_CTE]);
        if (modify_otherkeys_state == MOKS_ENABLED || modify_otherkeys_state == MOKS_DISABLED) {
            modify_otherkeys_state = MOKS_DISABLED;
        } else if (modify_otherkeys_state != MOKS_INITIAL) {
            modify_otherkeys_state = MOKS_AFTER_T_TE;
        }
        if (kitty_protocol_state == KKPS_ENABLED || kitty_protocol_state == KKPS_DISABLED) {
            kitty_protocol_state = KKPS_DISABLED;
        } else {
            kitty_protocol_state = KKPS_AFTER_T_TE;
        }
    }

    void out_str_t_TI() {
        out_str(term_strings[KS_CTI]);
        send_t_RK = TRUE;
    }

    void out_str_t_BE() {
        BytePtr p = null;
        boolean t1 = false;
        boolean t2 = false;
        t1 = term_strings[KS_CBE] == null || term_strings[KS_CBE].get() == NUL;
        if (!t1) {
            p = find_termcode(BytePtr.lit("PS"));
            t1 = p == null;
        }
        t2 = t1 || p.get() == NUL;
        if (!t2) {
            p = find_termcode(BytePtr.lit("PE"));
            t2 = p == null;
        }
        if (t2 || p.get() == NUL) {
            return;
        }
        out_str(term_strings[KS_CBE]);
    }

    void may_send_t_RK() {
        if (send_t_RK != 0 && !work_pending() && ex_normal_busy == 0 && exiting == 0) {
            send_t_RK = FALSE;
            out_str(term_strings[KS_CRK]);
            out_flush();
        }
    }

    void term_enter() {
        if (full_screen == 0 || term_entered != 0) {
            return;
        }
        if (termcap_active != 0) {
            out_str_t_BE();
            out_str_t_TI();
        }
        out_flush();
        musl_term_start();
        term_entered = TRUE;
        out_flush();
    }

    void term_leave() {
        if (full_screen == 0 || term_entered == 0) {
            return;
        }
        if (termcap_active != 0) {
            out_str(term_strings[KS_CBD]);
            out_str_t_TE();
        }
        out_flush();
        musl_term_stop();
        term_entered = FALSE;
        out_flush();
    }

    void starttermcap() {
        if (full_screen == 0 || termcap_active != 0) {
            return;
        }
        out_str(term_strings[KS_TI]);
        out_str_t_TI();
        out_str(term_strings[KS_KS]);
        out_str_t_BE();
        if (p_ek[0] != 0 && term_strings[KS_FE].get() != NUL) {
            out_str(term_strings[KS_FE]);
        }
        out_flush();
        termcap_active = TRUE;
        screen_start();
    }

    void stoptermcap() {
        screen_stop_highlight();
        reset_cterm_colors();
        if (termcap_active == 0) {
            return;
        }
        if (p_ek[0] != 0 && term_strings[KS_FD].get() != NUL) {
            out_str(term_strings[KS_FD]);
        }
        out_str(term_strings[KS_CBD]);
        out_str(term_strings[KS_KE]);
        out_flush();
        termcap_active = FALSE;
        if (term_strings[KS_TE].get() != NUL && (kitty_protocol_state == KKPS_ENABLED || kitty_protocol_state == KKPS_DISABLED)) {
            out_str_t_TE();
        }
        out_str(term_strings[KS_TE]);
        cursor_on();
        out_str_t_TE();
        screen_start();
        out_flush();
    }

    boolean swapping_screen() {
        return full_screen != 0 && term_strings[KS_TI].get() != NUL;
    }

    void scroll_start() {
        if (term_strings[KS_VS].get() == NUL || term_strings[KS_CVS].get() == NUL) {
            return;
        }
        out_str(term_strings[KS_VS]);
        out_str(term_strings[KS_CVS]);
        screen_start();
    }

    void cursor_on_force() {
        out_str(term_strings[KS_VE]);
        cursor_is_off = FALSE;
        cursor_is_asleep = FALSE;
    }

    void cursor_on() {
        if (cursor_is_off != 0 && cursor_is_asleep == 0) {
            cursor_on_force();
        }
    }

    void cursor_off() {
        if (full_screen != 0 && cursor_is_off == 0) {
            out_str(term_strings[KS_VI]);
            cursor_is_off = TRUE;
        }
    }

    void cursor_sleep() {
        cursor_is_asleep = TRUE;
        cursor_off();
    }

    void cursor_unsleep() {
        cursor_is_asleep = FALSE;
        cursor_on();
    }

    void scroll_region_set(S_window_S wp, int off) {
        out_str(tgoto(term_strings[KS_CS], wp.w_winrow + wp.w_height - 1, wp.w_winrow + off));
        if (term_strings[KS_CSV].get() != NUL && (long) wp.w_width != Columns[0]) {
            out_str(tgoto(term_strings[KS_CSV], wp.w_wincol + wp.w_width - 1, wp.w_wincol));
        }
        screen_start();
    }

    void scroll_region_reset() {
        out_str(tgoto(term_strings[KS_CS], (int) Rows[0] - 1, 0));
        if (term_strings[KS_CSV].get() != NUL) {
            out_str(tgoto(term_strings[KS_CSV], (int) Columns[0] - 1, 0));
        }
        screen_start();
    }

    void clear_termcodes() {
        while (tc_len > 0) {
            tc_len--;
        }
        termcodes = null;
        tc_max_len = 0;
        need_gather = TRUE;
    }

    void adjust_modlen(int idx) {
        int j = 0;
        termcodes.at(idx).modlen = 0;
        j = termcode_star(termcodes.at(idx).code, termcodes.at(idx).len);
        if (j <= 0) {
            return;
        }
        termcodes.at(idx).modlen = termcodes.at(idx).len - 1 - j;
        if (termcodes.at(idx).code.at(termcodes.at(idx).modlen - 1) == '@') {
            termcodes.at(idx).modlen--;
        }
    }

    void add_termcode(BytePtr name, BytePtr string, int flags) {
        Ptr<S_termcode> new_tc = null;
        int i = 0;
        int j = 0;
        BytePtr s = null;
        int len = 0;
        boolean t1 = false;
        if (string == null || string.get() == NUL) {
            del_termcode(name);
            return;
        }
        s = vim_strsave(string);
        if (flags != 0 && flags != ATC_FROM_TERM && term_7to8bit(string) != 0) {
            Rt.memmove(s, s.add(1), musl_strlen(s.add(1)) + 1L);
            s.set(0, (byte) term_7to8bit(string));
        }
        len = (int) musl_strlen(s);
        need_gather = TRUE;
        if (tc_len == tc_max_len) {
            tc_max_len += 20;
            new_tc = new Ptr<S_termcode>(S_termcode.array(tc_max_len), 0);
            i = 0;
            for (; i < tc_len; i++) {
                new_tc.at(i).set(termcodes.at(i));
            }
            termcodes = new_tc;
        }
        i = 0;
        for (; i < tc_len; i++) {
            if ((termcodes.at(i).name[0] & 0xff) < (name.at(0) & 0xff)) {
                continue;
            }
            if ((termcodes.at(i).name[0] & 0xff) == (name.at(0) & 0xff)) {
                if ((termcodes.at(i).name[1] & 0xff) < (name.at(1) & 0xff)) {
                    continue;
                }
                if ((termcodes.at(i).name[1] & 0xff) == (name.at(1) & 0xff)) {
                    t1 = flags == ATC_FROM_TERM;
                    if (t1) {
                        j = termcode_star(termcodes.at(i).code, termcodes.at(i).len);
                        t1 = j > 0;
                    }
                    if (t1) {
                        if (len == termcodes.at(i).len - j && musl_strncmp(s, termcodes.at(i).code, (long) (len - 1)) == 0 && (s.at(len - 1) & 0xff) == (termcodes.at(i).code.at(termcodes.at(i).len - 1) & 0xff)) {
                            return;
                        }
                    } else {
                        tc_len--;
                        break;
                    }
                }
            }
            j = tc_len;
            for (; j > i; j--) {
                termcodes.at(j).set(termcodes.at(j - 1));
            }
            break;
        }
        termcodes.at(i).name[0] = name.at(0);
        termcodes.at(i).name[1] = name.at(1);
        termcodes.at(i).code = s;
        termcodes.at(i).len = len;
        adjust_modlen(i);
        tc_len++;
    }

    void accept_modifiers_for_function_keys() {
        T_regmatch_T regmatch = new T_regmatch_T();
        int i = 0;
        BytePtr s = null;
        long len = 0;
        BytePtr ns = null;
        regmatch.zero();
        regmatch.rm_ic = true;
        regmatch.regprog = vim_regcomp(BytePtr.lit("^\033[\\d\\+\\~$"), RE_MAGIC);
        i = 0;
        for (; i < tc_len; i++) {
            if (regmatch.regprog == null) {
                return;
            }
            if (termcodes.at(i).name[0] == 'P' && (termcodes.at(i).name[1] == 'S' || termcodes.at(i).name[1] == 'E')) {
                continue;
            }
            s = termcodes.at(i).code;
            if (s != null && vim_regexec(regmatch, s, 0)) {
                len = musl_strlen(s);
                ns = BytePtr.alloc(len + 3L);
                Rt.memmove(ns, s, len - 1L);
                Rt.memmove(ns.add((int) len).add(-1), BytePtr.lit(";*~"), 4L);
                termcodes.at(i).code = ns;
                termcodes.at(i).len += 2;
                adjust_modlen(i);
            }
        }
        vim_regfree(regmatch.regprog);
    }

    int termcode_star(BytePtr code, int len) {
        if (len >= 3 && code.at(len - 2) == '*') {
            if (len >= 5 && code.at(len - 3) == ';') {
                return 2;
            } else {
                return 1;
            }
        }
        return 0;
    }

    BytePtr find_termcode(BytePtr name) {
        int i = 0;
        i = 0;
        for (; i < tc_len; i++) {
            if ((termcodes.at(i).name[0] & 0xff) == (name.at(0) & 0xff) && (termcodes.at(i).name[1] & 0xff) == (name.at(1) & 0xff)) {
                return termcodes.at(i).code;
            }
        }
        return null;
    }

    void del_termcode(BytePtr name) {
        int i = 0;
        if (termcodes == null) {
            return;
        }
        need_gather = TRUE;
        i = 0;
        for (; i < tc_len; i++) {
            if ((termcodes.at(i).name[0] & 0xff) == (name.at(0) & 0xff) && (termcodes.at(i).name[1] & 0xff) == (name.at(1) & 0xff)) {
                del_termcode_idx(i);
                return;
            }
        }
    }

    void del_termcode_idx(int idx) {
        int i = 0;
        tc_len--;
        i = idx;
        for (; i < tc_len; i++) {
            termcodes.at(i).set(termcodes.at(i + 1));
        }
    }

    void switch_to_8bit() {
        int i = 0;
        int c = 0;
        if (!term_is_8bit(term_strings[KS_NAME])) {
            i = 0;
            for (; i < tc_len; i++) {
                c = term_7to8bit(termcodes.at(i).code);
                if (c != 0) {
                    Rt.memmove(termcodes.at(i).code.add(1), termcodes.at(i).code.add(2), musl_strlen(termcodes.at(i).code.add(2)) + 1L);
                    termcodes.at(i).code.set(0, (byte) c);
                }
            }
            need_gather = TRUE;
        }
        detected_8bit = TRUE;
    }

    boolean put_string_in_typebuf(int offset, int slen, BytePtr string, int new_slen, BytePtr buf, int bufsize, IntPtr buflen) {
        int extra = 0;
        extra = new_slen - slen;
        string.set(new_slen, (byte) NUL);
        if (buf == null) {
            if (extra < 0) {
                del_typebuf(-extra, offset);
            } else if (extra > 0) {
                if (!ins_typebuf(string.add(slen), REMAP_YES, offset, false, FALSE)) {
                    return false;
                }
            }
            Rt.memmove(typebuf.tb_buf.add(typebuf.tb_off).add(offset), string, (long) new_slen);
        } else {
            if (extra < 0) {
                Rt.memmove(buf.add(offset), buf.add(offset).add(-extra), (long) (buflen.get() + offset + extra));
            } else if (extra > 0) {
                if (buflen.get() + extra + new_slen >= bufsize) {
                    return false;
                }
                Rt.memmove(buf.add(offset).add(extra), buf.add(offset), (long) (buflen.get() - offset));
            }
            Rt.memmove(buf.add(offset), string, (long) new_slen);
            buflen.put(buflen.get() + extra + new_slen);
        }
        return true;
    }

    int decode_modifiers(int n) {
        int code = 0;
        int modifiers = 0;
        code = n - 1;
        modifiers = 0;
        if ((code & 1) != 0) {
            modifiers |= MOD_MASK_SHIFT;
        }
        if ((code & 2) != 0) {
            modifiers |= MOD_MASK_ALT;
        }
        if ((code & 4) != 0) {
            modifiers |= MOD_MASK_CTRL;
        }
        if ((code & 8) != 0) {
            modifiers |= MOD_MASK_META;
        }
        return modifiers;
    }

    int modifiers2keycode(int modifiers_arg, IntPtr key, BytePtr string) {
        int[] modifiers = new int[] {modifiers_arg};
        int new_slen = 0;
        int t1 = 0;
        int t2 = 0;
        int t3 = 0;
        new_slen = 0;
        if (modifiers[0] == 0) {
            return 0;
        }
        key.put(simplify_key(key.get(), new IntPtr(modifiers, 0)));
        if (modifiers[0] != 0) {
            t1 = new_slen;
            new_slen++;
            string.set(t1, (byte) -128);
            t2 = new_slen;
            new_slen++;
            string.set(t2, (byte) KS_MODIFIER);
            t3 = new_slen;
            new_slen++;
            string.set(t3, (byte) modifiers[0]);
        }
        return new_slen;
    }

    void handle_u7_response(IntPtr arg, BytePtr tp, int csi_len) {
        BytePtr aw = null;
        int value = 0;
        if (arg.at(0) == 2 && arg.at(1) >= 2) {
            aw = null;
            u7_status.tr_progress = STATUS_GOT;
            did_cursorhold = TRUE;
            if (arg.at(1) == 2) {
                aw = BytePtr.lit("single");
            } else if (arg.at(1) == 3) {
                aw = BytePtr.lit("double");
            }
            if (aw != null && musl_strcmp(aw, p_ambw[0]) != 0) {
                set_option_value_give_err(BytePtr.lit("ambw"), 0L, aw, 0);
                redraw_asap(UPD_CLEAR);
            }
        } else if (arg.at(0) == 3) {
            xcc_status.tr_progress = STATUS_GOT;
            value = arg.at(1) == 1 ? TPR_YES : TPR_NO;
            term_props[TPR_CURSOR_STYLE].tpr_status = value;
            term_props[TPR_CURSOR_BLINK].tpr_status = value;
        }
    }

    void handle_version_response(int first, IntPtr arg, int argc, BytePtr tp) {
        int version = 0;
        version = arg.at(1);
        crv_status.tr_progress = STATUS_GOT;
        did_cursorhold = TRUE;
        init_term_props(false);
        if ((tp.at(0) & 0xff) == CSI) {
            switch_to_8bit();
        }
        if (version > 20000) {
            version = 0;
        }
        if (first == '>' && argc == 3) {
            if (arg.at(0) == 77) {
                term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR;
            }
            if ((version == 100 || version == 115) && arg.at(0) == 0 && arg.at(2) == 0) {
                may_adjust_color_count(256);
                term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR;
            }
            if (version == 95) {
                if (arg.at(0) == 1 && arg.at(2) == 0) {
                    term_props[TPR_UNDERLINE_RGB].tpr_status = TPR_YES;
                    term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR;
                    term_props[TPR_DECRQM].tpr_status = TPR_NO;
                } else if (arg.at(0) == 0 && arg.at(2) == 0) {
                    term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR;
                    term_props[TPR_DECRQM].tpr_status = TPR_YES;
                } else if (arg.at(0) == 0 && arg.at(2) == -1) {
                    term_props[TPR_UNDERLINE_RGB].tpr_status = TPR_YES;
                }
            }
            if (arg.at(0) == 83) {
                if (arg.at(1) >= 40700) {
                    term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR;
                } else {
                    term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_XTERM;
                }
            }
            if (term_props[TPR_MOUSE].tpr_status == TPR_UNKNOWN) {
                if (version >= 277) {
                    term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR;
                } else if (version >= 95) {
                    term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_XTERM2;
                }
            }
            if (arg.at(1) >= 2500) {
                term_props[TPR_UNDERLINE_RGB].tpr_status = TPR_YES;
            } else if (version == 136 && arg.at(2) == 0) {
                term_props[TPR_UNDERLINE_RGB].tpr_status = TPR_YES;
                if (arg.at(0) == 0) {
                    term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR;
                }
            }
            if (arg.at(0) == 1 && arg.at(1) >= 4000 && arg.at(1) <= 4009) {
                term_props[TPR_KITTY].tpr_status = TPR_YES;
                term_props[TPR_KITTY].tpr_set_by_termresponse = true;
                term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR;
                term_props[TPR_DECRQM].tpr_status = TPR_YES;
            }
            if (arg.at(0) == 1 && version == 12700 && arg.at(2) == 0) {
                term_props[TPR_MOUSE].tpr_status = TPR_MOUSE_SGR;
                term_props[TPR_DECRQM].tpr_status = TPR_YES;
            }
            if (arg.at(0) == 83 && arg.at(1) >= 30600) {
                term_props[TPR_CURSOR_STYLE].tpr_status = TPR_NO;
                term_props[TPR_CURSOR_BLINK].tpr_status = TPR_NO;
                term_props[TPR_DECRQM].tpr_status = TPR_NO;
            }
            if (version < 95) {
                term_props[TPR_UNDERLINE_RGB].tpr_status = TPR_YES;
            }
            if (version < 279) {
                term_props[TPR_CURSOR_STYLE].tpr_status = TPR_NO;
            }
            if (term_props[TPR_UNDERLINE_RGB].tpr_status != TPR_YES && term_strings[KS_8U].get() != NUL && !option_was_set(BytePtr.lit("t_8u"))) {
                set_string_option_direct(BytePtr.lit("t_8u"), -1, BytePtr.lit(""), OPT_FREE, 0);
            }
        }
    }

    int add_key_to_buf(int key, BytePtr buf) {
        int idx = 0;
        int t1 = 0;
        int t2 = 0;
        int t3 = 0;
        idx = 0;
        if (key < 0) {
            t1 = idx;
            idx++;
            buf.set(t1, (byte) -128);
            t2 = idx;
            idx++;
            buf.set(t2, (byte) (-key & 255));
            t3 = idx;
            idx++;
            buf.set(t3, (byte) ((-key >>> 8) & 255));
        } else {
            idx += utf_char2bytes(key, buf.add(idx));
        }
        return idx;
    }

    int put_key_modifiers_in_typebuf(int key_arg, int modifiers_arg, int csi_len, int offset, BytePtr buf, int bufsize, IntPtr buflen) {
        int[] key = new int[1];
        int modifiers = 0;
        byte[] string = new byte[8];
        int new_slen = 0;
        key[0] = key_arg;
        modifiers = modifiers_arg;
        key[0] = may_adjust_key_for_ctrl(modifiers, key[0]);
        modifiers = may_remove_shift_modifier(modifiers, key[0]);
        new_slen = modifiers2keycode(modifiers, new IntPtr(key, 0), new BytePtr(string, 0));
        if (key[0] > 1114111) {
            return -1;
        }
        new_slen += add_key_to_buf(key[0], new BytePtr(string, 0).add(new_slen));
        string[new_slen] = (byte) NUL;
        if (!put_string_in_typebuf(offset, csi_len, new BytePtr(string, 0), new_slen, buf, bufsize, buflen)) {
            return -1;
        }
        return new_slen - csi_len + offset;
    }

    int parse_csi_f_keys(int arg) {
        byte[] key_name = new byte[2];
        key_name = new byte[2];
        switch (arg) {
            case 11:
                key_name[0] = (byte) 'k';
                key_name[1] = (byte) '1';
                break;
            case 12:
                key_name[0] = (byte) 'k';
                key_name[1] = (byte) '2';
                break;
            case 13:
                key_name[0] = (byte) 'k';
                key_name[1] = (byte) '3';
                break;
            case 14:
                key_name[0] = (byte) 'k';
                key_name[1] = (byte) '4';
                break;
            case 15:
                key_name[0] = (byte) 'k';
                key_name[1] = (byte) '5';
                break;
            case 17:
                key_name[0] = (byte) 'k';
                key_name[1] = (byte) '6';
                break;
            case 18:
                key_name[0] = (byte) 'k';
                key_name[1] = (byte) '7';
                break;
            case 19:
                key_name[0] = (byte) 'k';
                key_name[1] = (byte) '8';
                break;
            case 20:
                key_name[0] = (byte) 'k';
                key_name[1] = (byte) '9';
                break;
            case 21:
                key_name[0] = (byte) 'F';
                key_name[1] = (byte) ';';
                break;
            case 23:
                key_name[0] = (byte) 'F';
                key_name[1] = (byte) '1';
                break;
            case 24:
                key_name[0] = (byte) 'F';
                key_name[1] = (byte) '2';
                break;
        }
        if (key_name[0] != 0) {
            return -((key_name[0] & 0xff) + ((key_name[1] & 0xff) << 8));
        }
        return arg;
    }

    int handle_key_with_modifier(IntPtr arg, int csi_len, int offset, BytePtr buf, int bufsize, IntPtr buflen, boolean iskitty, int trail) {
        int key = 0;
        int modifiers = 0;
        if (!iskitty && (kitty_protocol_state == KKPS_INITIAL || kitty_protocol_state == KKPS_OFF || kitty_protocol_state == KKPS_AFTER_T_TE) && term_props[TPR_KITTY].tpr_status != TPR_YES) {
            seenModifyOtherKeys = TRUE;
        }
        key = iskitty ? arg.at(0) : arg.at(2);
        modifiers = decode_modifiers(arg.at(1));
        if ((modifiers & MOD_MASK_SHIFT) != 0 && key >= 'a' && key <= 'z') {
            key += 'A' - 'a';
        }
        if (key == ESC) {
            key = K_ESC;
        } else if (arg.at(0) >= 11 && arg.at(0) <= 24 && trail == '~') {
            key = parse_csi_f_keys(arg.at(0));
        }
        return put_key_modifiers_in_typebuf(key, modifiers, csi_len, offset, buf, bufsize, buflen);
    }

    int handle_key_without_modifier(IntPtr arg, int csi_len, int offset, BytePtr buf, int bufsize, IntPtr buflen, int trail) {
        byte[] string = new byte[7];
        int new_slen = 0;
        int key = 0;
        if (arg.at(0) == ESC) {
            string[0] = (byte) -128;
            string[1] = (byte) KS_EXTRA;
            string[2] = (byte) KE_ESC;
            new_slen = 3;
        } else if (arg.at(0) >= 11 && arg.at(0) <= 24 && trail == '~') {
            key = parse_csi_f_keys(arg.at(0));
            string[0] = (byte) -128;
            string[1] = (byte) (-key & 255);
            string[2] = (byte) ((-key >>> 8) & 255);
            new_slen = 3;
        } else {
            new_slen = add_key_to_buf(arg.at(0), new BytePtr(string, 0));
        }
        if (!put_string_in_typebuf(offset, csi_len, new BytePtr(string, 0), new_slen, buf, bufsize, buflen)) {
            return -1;
        }
        return new_slen - csi_len + offset;
    }

    int handle_csi_function_key(int argc, IntPtr arg, int trail, int csi_len, BytePtr key_name, int offset, BytePtr buf, int bufsize, IntPtr buflen) {
        int key = 0;
        int modifiers = 0;
        key_name.set(0, (byte) 'k');
        switch (trail) {
            case 'A':
                key_name.set(1, (byte) 'u');
                break;
            case 'B':
                key_name.set(1, (byte) 'd');
                break;
            case 'C':
                key_name.set(1, (byte) 'r');
                break;
            case 'D':
                key_name.set(1, (byte) 'l');
                break;
            case 'F':
                key_name.set(0, (byte) '@');
                key_name.set(1, (byte) '7');
                break;
            case 'H':
                key_name.set(1, (byte) 'h');
                break;
            case 'P':
                key_name.set(1, (byte) '1');
                break;
            case 'Q':
                key_name.set(1, (byte) '2');
                break;
            case 'R':
                key_name.set(1, (byte) '3');
                break;
            case 'S':
                key_name.set(1, (byte) '4');
                break;
            default:
                return 0;
        }
        key = -((key_name.at(0) & 0xff) + ((key_name.at(1) & 0xff) << 8));
        modifiers = argc == 2 ? decode_modifiers(arg.at(1)) : 0;
        put_key_modifiers_in_typebuf(key, modifiers, csi_len, offset, buf, bufsize, buflen);
        return csi_len;
    }

    int handle_csi(BytePtr tp, int len, BytePtr argp, int offset, BytePtr buf, int bufsize, IntPtr buflen, BytePtr key_name, IntPtr slen) {
        int first = 0;
        int trail = 0;
        int[] arg = new int[3];
        int argc = 0;
        BytePtr ap = null;
        int csi_len = 0;
        BytePtr t1 = null;
        int t2 = 0;
        int res = 0;
        int setting = 0;
        int height = 0;
        int width = 0;
        boolean iskitty = false;
        first = -1;
        arg = new int[3];
        arg[0] = -1;
        arg[1] = -1;
        arg[2] = -1;
        argc = 0;
        ap = argp;
        if (!(Integer.compareUnsigned((ap.get() & 0xff) - '0', 10) < 0)) {
            t1 = ap;
            ap = ap.add(1);
            first = t1.get() & 0xff;
        }
        if (first >= 'A' && first <= 'Z') {
            trail = first;
            first = -1;
            ap = ap.add(-1);
        } else {
            argc = 0;
            for (; argc < 3; ) {
                if (ap.ge(tp.add(len))) {
                    return -1;
                }
                if (ap.get() == ';') {
                    t2 = argc;
                    argc++;
                    arg[t2] = -1;
                } else if (Integer.compareUnsigned((ap.get() & 0xff) - '0', 10) < 0) {
                    arg[argc] = 0;
                    for (;;) {
                        if (ap.ge(tp.add(len))) {
                            return -1;
                        }
                        if (!(Integer.compareUnsigned((ap.get() & 0xff) - '0', 10) < 0)) {
                            break;
                        }
                        if (arg[argc] <= (INT_MAX - 9) / 10) {
                            arg[argc] = arg[argc] * 10 + ((ap.get() & 0xff) - '0');
                        }
                        ap = ap.add(1);
                    }
                    argc++;
                }
                if (ap.get() == ';') {
                    ap = ap.add(1);
                } else {
                    break;
                }
            }
            while (ap.lt(tp.add(len)) && !((ap.get() & 0xff) >= '{' && (ap.get() & 0xff) <= '~') && !(Integer.compareUnsigned((ap.get() & 0xff) - 'A', 26) < 0 || Integer.compareUnsigned((ap.get() & 0xff) - 'a', 26) < 0)) {
                ap = ap.add(1);
            }
            if (ap.ge(tp.add(len))) {
                return -1;
            }
            trail = ap.get() & 0xff;
        }
        csi_len = (int) ap.sub(tp) + 1;
        if (first == '>' && (argc == 1 || argc == 2) && trail == 'm') {
            if (arg[0] == 4 && argc == 2) {
                modify_otherkeys_state = arg[1] == 2 ? MOKS_ENABLED : MOKS_OFF;
            }
            key_name.set(0, (byte) KS_EXTRA);
            key_name.set(1, (byte) KE_IGNORE);
            slen.put(csi_len);
        } else if (first == -1 && Integer.compareUnsigned(trail - 'A', 26) < 0 && (argc == 0 || (argc == 2 && arg[0] == 1))) {
            res = handle_csi_function_key(argc, new IntPtr(arg, 0), trail, csi_len, key_name, offset, buf, bufsize, buflen);
            return res <= 0 ? res : len + res;
        } else if (first == -1 && argc == 2 && trail == 'R') {
            handle_u7_response(new IntPtr(arg, 0), tp, csi_len);
            key_name.set(0, (byte) KS_EXTRA);
            key_name.set(1, (byte) KE_IGNORE);
            slen.put(csi_len);
        } else if (first == '?' && trail == 'c') {
            slen.put(csi_len);
            key_name.set(0, (byte) KS_EXTRA);
            key_name.set(1, (byte) KE_IGNORE);
        } else if (first == '?' && trail == 'y' && argc == 2 && arg[0] == 2026) {
            setting = arg[1];
            slen.put(csi_len);
            key_name.set(0, (byte) KS_EXTRA);
            key_name.set(1, (byte) KE_IGNORE);
            if (setting >= 0 && setting <= 4) {
                switch (arg[0]) {
                    case 2026:
                        sync_output_setting = setting;
                        set_option_value_give_err(BytePtr.lit("termsync"), (long) (setting == 1 || setting == 2 ? 1 : 0), null, 0);
                        break;
                }
            }
        } else if (first == '?' && argc == 1 && arg[0] == 1 && trail == 'z') {
            slen.put(csi_len);
            key_name.set(0, (byte) KS_EXTRA);
            key_name.set(1, (byte) KE_IGNORE);
            do_cmdline_cmd(BytePtr.lit("stop"));
        } else if (argc >= 3 && arg[0] == 48) {
            height = arg[1];
            width = arg[2];
            slen.put(csi_len);
            key_name.set(0, (byte) KS_EXTRA);
            key_name.set(1, (byte) KE_IGNORE);
            set_shellsize(width, height, 1);
        } else if (term_strings[KS_CRV].get() != NUL && ap.gt(argp.add(1)) && trail == 'c') {
            handle_version_response(first, new IntPtr(arg, 0), argc, tp);
            slen.put(csi_len);
            key_name.set(0, (byte) KS_EXTRA);
            key_name.set(1, (byte) KE_IGNORE);
        } else if (first == '?' && argc == 1 && trail == 'u') {
            if (arg[0] == '0') {
                kitty_protocol_state = KKPS_OFF;
            } else {
                kitty_protocol_state = KKPS_ENABLED;
                seenModifyOtherKeys = FALSE;
            }
            key_name.set(0, (byte) KS_EXTRA);
            key_name.set(1, (byte) KE_IGNORE);
            slen.put(csi_len);
        } else if ((arg[0] == 27 && argc == 3 && trail == '~') || (argc == 2 && (trail == 'u' || trail == '~'))) {
            iskitty = argc == 2 && (trail == 'u' || trail == '~');
            return len + handle_key_with_modifier(new IntPtr(arg, 0), csi_len, offset, buf, bufsize, buflen, iskitty, trail);
        } else if (argc == 1 && (trail == 'u' || trail == '~')) {
            return len + handle_key_without_modifier(new IntPtr(arg, 0), csi_len, offset, buf, bufsize, buflen, trail);
        }
        return 0;
    }

    void check_for_color_response(BytePtr resp, int len) {
        int i = 0;
        int j = 0;
        BytePtr argp = null;
        boolean is_bg = false;
        boolean is_4digit = false;
        BytePtr tp_r = null;
        BytePtr tp_g = null;
        BytePtr tp_b = null;
        BytePtr new_bg_val = null;
        j = 1 + (resp.at(0) == ESC ? 1 : 0);
        argp = resp.add(j);
        if (len >= j + 3 && (argp.at(0) != '1' || (argp.at(1) != '1' && argp.at(1) != '0') || argp.at(2) != ';')) {
            i = 0;
        } else {
            i = j;
            for (; i < len; i++) {
                if (resp.at(i) == '\7' || ((resp.at(0) & 0xff) == OSC ? (resp.at(i) & 0xff) == STERM : resp.at(i) == ESC && i + 1 < len && resp.at(i + 1) == '\\')) {
                    is_bg = argp.at(1) == '1';
                    is_4digit = i - j >= 21 && resp.at(j + 11) == '/' && resp.at(j + 16) == '/';
                    if (i - j >= 15 && musl_strncmp(resp.add(j).add(3), BytePtr.lit("rgb:"), 4L) == 0 && (is_4digit || (resp.at(j + 9) == '/' && resp.at(j + 12) == '/'))) {
                        tp_r = resp.add(j).add(7);
                        tp_g = resp.add(j).add(is_4digit ? 12 : 10);
                        tp_b = resp.add(j).add(is_4digit ? 17 : 13);
                        if (is_bg) {
                            new_bg_val = 3 * '6' < (tp_r.get() & 0xff) + (tp_g.get() & 0xff) + (tp_b.get() & 0xff) ? BytePtr.lit("light") : BytePtr.lit("dark");
                            if (!option_was_set(BytePtr.lit("bg")) && musl_strcmp(p_bg[0], new_bg_val) != 0) {
                                set_option_value_give_err(BytePtr.lit("bg"), 0L, new_bg_val, 0);
                                reset_option_was_set(BytePtr.lit("bg"));
                                redraw_asap(UPD_CLEAR);
                            }
                        }
                    }
                    break;
                }
            }
        }
    }

    boolean in_osc_sequence() {
        return osc_state.processing;
    }

    boolean handle_osc(BytePtr tp, int len, BytePtr key_name, IntPtr slen) {
        byte last_char = 0;
        int cur = 0;
        int i = 0;
        byte savebg = 0;
        if (!osc_state.processing) {
            cur = 1 + (tp.at(0) == ESC ? 1 : 0);
            if (len < cur + 1 + ((tp.at(0) & 0xff) != OSC ? 1 : 0)) {
                return false;
            }
            ga_init2(osc_state.buf, 1L, 1024);
            osc_state.start_tv = musl_now_ms();
            osc_state.processing = true;
            osc_state.start_char = tp.at(0);
            last_char = (byte) 0;
        } else {
            last_char = GA_BytePtr(osc_state.buf).at(osc_state.buf.ga_len - 1);
        }
        key_name.set(0, (byte) KS_EXTRA);
        i = 0;
        for (; i < len; i++) {
            if (tp.at(i) == '\7' || ((osc_state.start_char & 0xff) == OSC ? (tp.at(i) & 0xff) == STERM : (tp.at(i) == ESC && i + 1 < len && tp.at(i + 1) == '\\') || (i == 0 && tp.at(i) == '\\' && last_char == ESC))) {
                osc_state.processing = false;
                key_name.set(1, (byte) KE_OSC);
                ga_concat_len(osc_state.buf, tp, (long) (i + 1 + (tp.at(i) == ESC ? 1 : 0)));
                ga_append(osc_state.buf, NUL);
                slen.put(i + 1 + (tp.at(i) == ESC ? 1 : 0));
                check_for_color_response(GA_BytePtr(osc_state.buf), osc_state.buf.ga_len - 1);
                savebg = p_bg[0].get();
                if ((p_bg[0].get() & 0xff) != (savebg & 0xff)) {
                    redraw_asap(UPD_CLEAR);
                }
                return true;
            }
        }
        key_name.set(1, (byte) KE_IGNORE);
        if (musl_now_ms() - osc_state.start_tv >= p_ost[0]) {
            vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(new BytePtr(e_osc_response_timed_out, 0)), osc_state.buf.ga_len, osc_state.buf.ga_data);
            emsg(iobuff_or(gettext_(new BytePtr(e_osc_response_timed_out, 0))));
            ga_clear(osc_state.buf);
            osc_state.processing = false;
            return false;
        }
        ga_concat(osc_state.buf, tp);
        slen.put(len);
        return true;
    }

    boolean handle_dcs(BytePtr tp, BytePtr argp, int len, BytePtr key_name, IntPtr slen) {
        int i = 0;
        int j = 0;
        j = 1 + (tp.at(0) == ESC ? 1 : 0);
        if (len < j + 3) {
            i = len;
        } else if ((argp.at(1) != '+' && argp.at(1) != '$') || (argp.at(2) != 'r' && argp.at(2) != 'R')) {
            i = 0;
        } else if (argp.at(1) == '+') {
            i = j;
            for (; i < len; i++) {
                if ((tp.at(i) == ESC && i + 1 < len && tp.at(i + 1) == '\\') || (tp.at(i) & 0xff) == STERM) {
                    key_name.set(0, (byte) KS_EXTRA);
                    key_name.set(1, (byte) KE_IGNORE);
                    slen.put(i + 1 + (tp.at(i) == ESC ? 1 : 0));
                    break;
                }
            }
        } else {
            i = j + 3;
            for (; i < len; i++) {
                if (i - j == 3 && !musl_isdigit(tp.at(i) & 0xff)) {
                    break;
                }
                if (i - j == 4 && tp.at(i) != ' ') {
                    break;
                }
                if (i - j == 5 && tp.at(i) != 'q') {
                    break;
                }
                if (i - j == 6 && tp.at(i) != ESC && (tp.at(i) & 0xff) != STERM) {
                    break;
                }
                if ((i - j == 6 && (tp.at(i) & 0xff) == STERM) || (i - j == 7 && tp.at(i) == '\\')) {
                    key_name.set(0, (byte) KS_EXTRA);
                    key_name.set(1, (byte) KE_IGNORE);
                    slen.put(i + 1);
                    break;
                }
            }
        }
        if (i == len) {
            return false;
        }
        return true;
    }

    int check_termcode(int max_offset, BytePtr buf, int bufsize, IntPtr buflen) {
        BytePtr tp = null;
        BytePtr p = null;
        int[] slen = new int[1];
        int modslen = 0;
        int len = 0;
        int retval = 0;
        int offset = 0;
        byte[] key_name = new byte[2];
        int modifiers = 0;
        BytePtr modifiers_start = null;
        int[] key = new int[1];
        int new_slen = 0;
        byte[] string = new byte[7];
        int i = 0;
        int j = 0;
        int idx = 0;
        boolean cpo_koffset = false;
        int keypad_index_found = 0;
        int keypad_slen_found = 0;
        boolean is_keypad = false;
        int n = 0;
        BytePtr argp = null;
        int resp = 0;
        int t1 = 0;
        int t2 = 0;
        int t3 = 0;
        slen[0] = 0;
        retval = 0;
        modifiers_start = null;
        idx = 0;
        cpo_koffset = vim_strchr(p_cpo[0], CPO_KOFFSET) != null;
        if (need_gather != 0) {
            gather_termleader();
        }
        offset = 0;
        for (; offset < max_offset; offset++) {
            if (buf == null) {
                if (offset >= typebuf.tb_len) {
                    break;
                }
                tp = typebuf.tb_buf.add(typebuf.tb_off).add(offset);
                len = typebuf.tb_len - offset;
            } else {
                if (offset >= buflen.get()) {
                    break;
                }
                tp = buf.add(offset);
                len = buflen.get() - offset;
            }
            if ((tp.get() & 0xff) == 128) {
                offset += 2;
                continue;
            }
            if (osc_state.processing) {
                tp.set(len, (byte) NUL);
                key_name[0] = (byte) NUL;
                key_name[1] = (byte) NUL;
                modifiers = 0;
                if (!handle_osc(tp, len, new BytePtr(key_name, 0), new IntPtr(slen, 0))) {
                    return -1;
                }
            } else {
                i = tp.get() & 0xff;
                p = new BytePtr(termleader, 0);
                for (; (p.get() != 0) && (p.get() & 0xff) != i; p = p.add(1)) {
                }
                if (p.get() == NUL) {
                    continue;
                }
                if (tp.get() == ESC && p_ek[0] == 0 && (State & MODE_INSERT) != 0) {
                    continue;
                }
                tp.set(len, (byte) NUL);
                key_name[0] = (byte) NUL;
                key_name[1] = (byte) NUL;
                modifiers = 0;
                keypad_index_found = -1;
                keypad_slen_found = 0;
                idx = 0;
                for (; idx < tc_len; idx++) {
                    is_keypad = false;
                    slen[0] = termcodes.at(idx).len;
                    modifiers_start = null;
                    if (cpo_koffset && offset != 0 && len < slen[0]) {
                        continue;
                    }
                    if (musl_strncmp(termcodes.at(idx).code, tp, (long) (slen[0] > len ? len : slen[0])) == 0) {
                        if (len < slen[0]) {
                            return -1;
                        }
                        if (termcodes.at(idx).name[0] == 'K' && (Integer.compareUnsigned((termcodes.at(idx).name[1] & 0xff) - '0', 10) < 0 || Integer.compareUnsigned((termcodes.at(idx).name[1] & 0xff) - 'A', 26) < 0)) {
                            is_keypad = true;
                            if (keypad_index_found < 0) {
                                keypad_index_found = idx;
                                keypad_slen_found = slen[0];
                            }
                        }
                        if (!is_keypad) {
                            key_name[0] = termcodes.at(idx).name[0];
                            key_name[1] = termcodes.at(idx).name[1];
                            break;
                        }
                    }
                    if (termcodes.at(idx).modlen > 0) {
                        modslen = termcodes.at(idx).modlen;
                        if (cpo_koffset && offset != 0 && len < modslen) {
                            continue;
                        }
                        if (musl_strncmp(termcodes.at(idx).code, tp, (long) (modslen > len ? len : modslen)) == 0) {
                            if (len <= modslen) {
                                return -1;
                            }
                            if ((tp.at(modslen) & 0xff) == (termcodes.at(idx).code.at(slen[0] - 1) & 0xff)) {
                                slen[0] = modslen + 1;
                            } else if (tp.at(modslen) != ';' && modslen == slen[0] - 3) {
                                continue;
                            } else if (termcodes.at(idx).code.at(modslen) == '@' && (tp.at(modslen) != '1' || tp.at(modslen + 1) != ';')) {
                                continue;
                            } else {
                                j = slen[0] - 2;
                                for (; (j < len) && (musl_isdigit(tp.at(j) & 0xff) || tp.at(j) == '-' || tp.at(j) == ';'); j++) {
                                }
                                j++;
                                if (len < j) {
                                    return -1;
                                }
                                if ((tp.at(j - 1) & 0xff) != (termcodes.at(idx).code.at(slen[0] - 1) & 0xff)) {
                                    continue;
                                }
                                modifiers_start = tp.add(slen[0]).add(-2);
                                n = musl_atoi(modifiers_start);
                                modifiers |= decode_modifiers(n);
                                slen[0] = j;
                            }
                            if (termcodes.at(idx).name[0] == 'K' && (Integer.compareUnsigned((termcodes.at(idx).name[1] & 0xff) - '0', 10) < 0 || Integer.compareUnsigned((termcodes.at(idx).name[1] & 0xff) - 'A', 26) < 0)) {
                                is_keypad = true;
                                if (keypad_index_found < 0) {
                                    keypad_index_found = idx;
                                    keypad_slen_found = slen[0];
                                }
                            }
                            if (!is_keypad) {
                                key_name[0] = termcodes.at(idx).name[0];
                                key_name[1] = termcodes.at(idx).name[1];
                                break;
                            }
                        }
                    }
                }
                if (idx == tc_len && keypad_index_found >= 0) {
                    key_name[0] = termcodes.at(keypad_index_found).name[0];
                    key_name[1] = termcodes.at(keypad_index_found).name[1];
                    slen[0] = keypad_slen_found;
                }
                if (key_name[0] == NUL) {
                    argp = tp.at(0) == ESC ? tp.add(2) : tp.add(1);
                    if (((tp.at(0) == ESC && len >= 3 && tp.at(1) == '[') || ((tp.at(0) & 0xff) == CSI && len >= 2)) && vim_strchr(BytePtr.lit("0123456789>?ABCDEFHPQRS"), argp.get() & 0xff) != null) {
                        resp = handle_csi(tp, len, argp, offset, buf, bufsize, buflen, new BytePtr(key_name, 0), new IntPtr(slen, 0));
                        if (resp != 0) {
                            return resp;
                        }
                    } else if ((tp.at(0) == ESC && len >= 2 && tp.at(1) == ']') || (tp.at(0) & 0xff) == OSC) {
                        if (!handle_osc(tp, len, new BytePtr(key_name, 0), new IntPtr(slen, 0))) {
                            return -1;
                        }
                    } else if ((tp.at(0) == ESC && len >= 2 && tp.at(1) == 'P') || (tp.at(0) & 0xff) == DCS) {
                        if (!handle_dcs(tp, argp, len, new BytePtr(key_name, 0), new IntPtr(slen, 0))) {
                            return -1;
                        }
                    }
                }
            }
            if (key_name[0] == NUL) {
                continue;
            }
            if ((key_name[0] & 0xff) == KS_EXTRA) {
                if (key_name[1] == KE_FOCUSGAINED) {
                    if (focus_state == 0) {
                        ui_focus_change(true);
                        did_cursorhold = TRUE;
                        focus_state = TRUE;
                    }
                    key_name[1] = (byte) KE_IGNORE;
                } else if (key_name[1] == KE_FOCUSLOST) {
                    if (focus_state != 0) {
                        ui_focus_change(false);
                        did_cursorhold = TRUE;
                        focus_state = FALSE;
                    }
                    key_name[1] = (byte) KE_IGNORE;
                }
            }
            key[0] = handle_x_keys(-((key_name[0] & 0xff) + ((key_name[1] & 0xff) << 8)));
            new_slen = modifiers2keycode(modifiers, new IntPtr(key, 0), new BytePtr(string, 0));
            key_name[0] = (byte) (-key[0] & 255);
            key_name[1] = (byte) ((-key[0] >>> 8) & 255);
            if ((key_name[0] & 0xff) == KS_KEY) {
                new_slen += utf_char2bytes(key_name[1] & 0xff, new BytePtr(string, 0).add(new_slen));
            } else if (osc_state.processing || (new_slen == 0 && (key_name[0] & 0xff) == KS_EXTRA && key_name[1] == KE_IGNORE)) {
                retval = KEYLEN_REMOVED;
            } else {
                t1 = new_slen;
                new_slen++;
                string[t1] = (byte) -128;
                t2 = new_slen;
                new_slen++;
                string[t2] = key_name[0];
                t3 = new_slen;
                new_slen++;
                string[t3] = key_name[1];
            }
            if (!put_string_in_typebuf(offset, slen[0], new BytePtr(string, 0), new_slen, buf, bufsize, buflen)) {
                return -1;
            }
            return retval == 0 ? len + new_slen - slen[0] + offset : retval;
        }
        return 0;
    }

    BytePtr replace_termcodes(BytePtr from, Ptr<BytePtr> bufp, int sid_arg, int flags, IntPtr did_simplify) {
        int i = 0;
        int slen = 0;
        int key = 0;
        long dlen = 0;
        BytePtr[] src = new BytePtr[1];
        boolean do_backslash = false;
        boolean do_special = false;
        boolean do_key_code = false;
        BytePtr result = null;
        S_growarray ga = new S_growarray();
        long t1 = 0;
        long t2 = 0;
        long t3 = 0;
        long t4 = 0;
        int fsk_flags = 0;
        int[] len = new int[1];
        long t5 = 0;
        long t6 = 0;
        long t7 = 0;
        long t8 = 0;
        long t9 = 0;
        long t10 = 0;
        long t11 = 0;
        long t12 = 0;
        dlen = 0L;
        do_backslash = vim_strchr(p_cpo[0], CPO_BSLASH) == null;
        do_special = vim_strchr(p_cpo[0], CPO_SPECI) == null || (flags & REPTERM_SPECIAL) != 0;
        do_key_code = vim_strchr(p_cpo[0], CPO_KEYCODE) == null;
        src[0] = from;
        ga_init2(ga, 1L, 100);
        if (!ga_grow(ga, (int) (musl_strlen(src[0]) * 6L + 1L))) {
            bufp.put(null);
            return from;
        }
        result = GA_BytePtr(ga);
        if ((flags & REPTERM_FROM_PART) != 0 && src[0].at(0) == '#' && Integer.compareUnsigned((src[0].at(1) & 0xff) - '0', 10) < 0) {
            t1 = dlen;
            dlen++;
            result.set((int) t1, (byte) -128);
            t2 = dlen;
            dlen++;
            result.set((int) t2, (byte) 'k');
            if (src[0].at(1) == '0') {
                t3 = dlen;
                dlen++;
                result.set((int) t3, (byte) ';');
            } else {
                t4 = dlen;
                dlen++;
                result.set((int) t4, src[0].at(1));
            }
            src[0] = src[0].add(2);
        }
        while (src[0].get() != NUL) {
            if (do_special && ((flags & REPTERM_DO_LT) != 0 || musl_strncmp(src[0], BytePtr.lit("<lt>"), 4L) != 0)) {
                fsk_flags = FSK_KEYCODE | ((flags & REPTERM_NO_SIMPLIFY) != 0 ? 0 : FSK_SIMPLIFY) | ((flags & REPTERM_FROM_PART) != 0 ? FSK_FROM_PART : 0);
                slen = trans_special(new Ptr<BytePtr>(src, 0), result.add((int) dlen), fsk_flags, true, did_simplify);
                if (slen > 0) {
                    dlen += (long) slen;
                    continue;
                }
            }
            if (do_key_code) {
                i = find_term_bykeys(src[0], new IntPtr(len, 0));
                if (i >= 0) {
                    t5 = dlen;
                    dlen++;
                    result.set((int) t5, (byte) -128);
                    t6 = dlen;
                    dlen++;
                    result.set((int) t6, termcodes.at(i).name[0]);
                    t7 = dlen;
                    dlen++;
                    result.set((int) t7, termcodes.at(i).name[1]);
                    src[0] = src[0].add(len[0]);
                    continue;
                }
            }
            key = src[0].get() & 0xff;
            if (key == Ctrl_V || (do_backslash && key == '\\')) {
                src[0] = src[0].add(1);
                if (src[0].get() == NUL) {
                    if ((flags & REPTERM_FROM_PART) != 0) {
                        t8 = dlen;
                        dlen++;
                        result.set((int) t8, (byte) key);
                    }
                    break;
                }
            }
            i = utfc_ptr2len(src[0]);
            for (; i > 0; i--) {
                if ((src[0].get() & 0xff) == 128) {
                    t9 = dlen;
                    dlen++;
                    result.set((int) t9, (byte) -128);
                    t10 = dlen;
                    dlen++;
                    result.set((int) t10, (byte) KS_SPECIAL);
                    t11 = dlen;
                    dlen++;
                    result.set((int) t11, (byte) 'X');
                } else {
                    t12 = dlen;
                    dlen++;
                    result.set((int) t12, src[0].get());
                }
                src[0] = src[0].add(1);
            }
        }
        result.set((int) dlen, (byte) NUL);
        bufp.put(vim_strsave(result));
        if (bufp.get() != null) {
            from = bufp.get();
        }
        return from;
    }

    int find_term_bykeys(BytePtr src, IntPtr matchlen) {
        int i = 0;
        int j = 0;
        int len = 0;
        int found = 0;
        int foundlen = 0;
        int slen = 0;
        int modslen = 0;
        int thislen = 0;
        len = (int) musl_strlen(src);
        found = -1;
        foundlen = 1;
        if (need_gather != 0) {
            gather_termleader();
        }
        if (src.get() == NUL || vim_strchr(new BytePtr(termleader, 0), src.get() & 0xff) == null) {
            return -1;
        }
        i = 0;
        for (; i < tc_len; i++) {
            slen = termcodes.at(i).len;
            modslen = termcodes.at(i).modlen;
            if (modslen > 0) {
                if (len > modslen && musl_strncmp(termcodes.at(i).code, src, (long) modslen) == 0) {
                    thislen = 0;
                    if ((src.at(modslen) & 0xff) == (termcodes.at(i).code.at(slen - 1) & 0xff)) {
                        thislen = modslen + 1;
                    } else if (src.at(modslen) != ';' && modslen == slen - 3) {
                        continue;
                    } else if (termcodes.at(i).code.at(modslen) == '@' && (src.at(modslen) != '1' || src.at(modslen + 1) != ';')) {
                        continue;
                    } else {
                        j = slen - 2;
                        for (; (j < len) && (musl_isdigit(src.at(j) & 0xff) || src.at(j) == '-' || src.at(j) == ';'); j++) {
                        }
                        j++;
                        if (len < j) {
                            continue;
                        }
                        if ((src.at(j - 1) & 0xff) != (termcodes.at(i).code.at(slen - 1) & 0xff)) {
                            continue;
                        }
                        thislen = j;
                    }
                    if (thislen > foundlen) {
                        found = i;
                        foundlen = thislen;
                    }
                }
            } else {
                if (slen > foundlen && len >= slen && musl_strncmp(termcodes.at(i).code, src, (long) slen) == 0) {
                    found = i;
                    foundlen = slen;
                }
            }
        }
        if (matchlen != null && found >= 0) {
            matchlen.put(foundlen);
        }
        return found;
    }

    void gather_termleader() {
        int i = 0;
        int len = 0;
        int t1 = 0;
        len = 0;
        termleader[len] = (byte) NUL;
        i = 0;
        for (; i < tc_len; i++) {
            if (vim_strchr(new BytePtr(termleader, 0), termcodes.at(i).code.at(0) & 0xff) == null) {
                t1 = len;
                len++;
                termleader[t1] = termcodes.at(i).code.at(0);
                termleader[len] = (byte) NUL;
            }
        }
        need_gather = FALSE;
    }

    void show_termcodes(int flags) {
        int col = 0;
        IntPtr items = null;
        int item_count = 0;
        int run = 0;
        int row = 0;
        int rows = 0;
        int cols = 0;
        int i = 0;
        int len = 0;
        int t1 = 0;
        if (tc_len == 0) {
            return;
        }
        items = IntPtr.alloc(tc_len);
        msg_puts_title(gettext_(BytePtr.lit("\n--- Terminal keys ---")));
        run = (flags & OPT_ONECOLUMN) != 0 ? 3 : 1;
        for (; (run <= 3) && got_int == 0; run++) {
            item_count = 0;
            i = 0;
            for (; i < tc_len; i++) {
                len = show_one_termcode(new BytePtr(termcodes.at(i).name, 0), termcodes.at(i).code, false);
                if ((flags & OPT_ONECOLUMN) != 0 || (len <= INC3 - TERMCODE_GAP ? run == 1 : (len <= INC2 - TERMCODE_GAP ? run == 2 : run == 3))) {
                    t1 = item_count;
                    item_count++;
                    items.set(t1, i);
                }
            }
            if (run <= 2) {
                cols = (int) ((Columns[0] + TERMCODE_GAP) / (long) (run == 1 ? INC3 : INC2));
                if (cols == 0) {
                    cols = 1;
                }
                rows = (item_count + cols - 1) / cols;
            } else {
                rows = item_count;
            }
            row = 0;
            for (; (row < rows) && got_int == 0; row++) {
                msg_putchar('\n');
                if (got_int != 0) {
                    break;
                }
                col = 0;
                i = row;
                for (; i < item_count; i += rows) {
                    msg_col = col;
                    show_one_termcode(new BytePtr(termcodes.at(items.at(i)).name, 0), termcodes.at(items.at(i)).code, true);
                    if (run == 2) {
                        col += INC2;
                    } else {
                        col += INC3;
                    }
                }
                out_flush();
                ui_breakcheck();
            }
        }
    }

    int show_one_termcode(BytePtr name, BytePtr code, boolean printit) {
        BytePtr p = null;
        int len = 0;
        int t1 = 0;
        if ((name.at(0) & 0xff) > '~') {
            IObuff.set(0, (byte) ' ');
            IObuff.set(1, (byte) ' ');
            IObuff.set(2, (byte) ' ');
            IObuff.set(3, (byte) ' ');
        } else {
            IObuff.set(0, (byte) 't');
            IObuff.set(1, (byte) '_');
            IObuff.set(2, name.at(0));
            IObuff.set(3, name.at(1));
        }
        IObuff.set(4, (byte) ' ');
        p = get_special_key_name(-((name.at(0) & 0xff) + ((name.at(1) & 0xff) << 8)), 0);
        if (p.at(1) != 't') {
            musl_strcpy(IObuff.add(5), p);
        } else {
            IObuff.set(5, (byte) NUL);
        }
        len = (int) musl_strlen(IObuff);
        do {
            t1 = len;
            len++;
            IObuff.set(t1, (byte) ' ');
        } while (len < 17);
        IObuff.set(len, (byte) NUL);
        if (code == null) {
            len += 4;
        } else {
            len += vim_strsize(code);
        }
        if (printit) {
            msg_puts(IObuff);
            if (code == null) {
                msg_puts(BytePtr.lit("NULL"));
            } else {
                msg_outtrans(code);
            }
        }
        return len;
    }

    void term_disable_dec() {
        term_set_sync_output(TERM_SYNC_OUTPUT_OFF);
        out_flush();
    }

    boolean sync_output_active() {
        return p_tsy[0] != 0 && (sync_output_setting == 1 || sync_output_setting == 2) && term_strings[KS_BSU].get() != NUL && term_strings[KS_ESU].get() != NUL;
    }

    void term_set_sync_output(int flags) {
        boolean allowed = false;
        boolean in_gui = false;
        int t1 = 0;
        boolean t2 = false;
        in_gui = false;
        allowed = p_tsy[0] != 0 && (sync_output_setting == 1 || sync_output_setting == 2);
        if ((flags & TERM_SYNC_OUTPUT_FLUSH) != 0) {
            if (allowed && !in_gui && sync_output_state > 0 && term_strings[KS_ESU].get() != NUL && term_strings[KS_BSU].get() != NUL) {
                out_str_nf(term_strings[KS_ESU]);
                out_str_nf(term_strings[KS_BSU]);
                out_flush();
            }
            return;
        }
        if ((flags & TERM_SYNC_OUTPUT_OFF) != 0) {
            if (sync_output_state > 0 && term_strings[KS_ESU].get() != NUL) {
                out_str_nf(term_strings[KS_ESU]);
                out_flush();
                sync_output_state = 0;
            }
            return;
        }
        if (!allowed || in_gui || term_strings[KS_BSU].get() == NUL || term_strings[KS_ESU].get() == NUL) {
            return;
        }
        if ((flags & TERM_SYNC_OUTPUT_ENABLE) != 0) {
            t1 = sync_output_state;
            sync_output_state++;
            if (t1 > 0) {
                return;
            }
            out_str_nf(term_strings[KS_BSU]);
        } else if ((flags & TERM_SYNC_OUTPUT_DISABLE) != 0) {
            t2 = sync_output_state == 0;
            if (!t2) {
                sync_output_state--;
                t2 = sync_output_state > 0;
            }
            if (t2) {
                return;
            }
            out_str_nf(term_strings[KS_ESU]);
            out_flush();
        } else {
            vim_snprintf(IObuff, emsg_iobuff_room(), BytePtr.lit("Unknown sync output value %d"), flags);
            iemsg(iobuff_or(BytePtr.lit("Unknown sync output value %d")));
            return;
        }
    }

    void internal_format(int textwidth, int second_indent, int flags, boolean format_only, int c) {
        int cc = 0;
        int save_char = 0;
        boolean haveto_redraw = false;
        int safe_tw = 0;
        int startcol = 0;
        int wantcol = 0;
        int foundcol = 0;
        int end_foundcol = 0;
        int len = 0;
        int virtcol = 0;
        int orig_col = 0;
        BytePtr saved_text = null;
        int end_col = 0;
        boolean first_pass = false;
        int len_2 = 0;
        save_char = NUL;
        haveto_redraw = false;
        safe_tw = trim_to_int(8L * (long) textwidth);
        if (curbuf.b_p_ai[0] == 0 && (State & VREPLACE_FLAG) == 0) {
            cc = gchar_cursor();
            if (cc == ' ' || cc == '\t') {
                save_char = cc;
                pchar_cursor('x');
            }
        }
        while (got_int == 0) {
            end_foundcol = 0;
            orig_col = 0;
            saved_text = null;
            if (curwin.w_cursor.col[0] < safe_tw) {
                virtcol = get_nolist_virtcol() + char2cells(c != NUL ? c : gchar_cursor());
                if (virtcol <= textwidth) {
                    break;
                }
            }
            if (p_paste[0] != 0) {
                break;
            }
            startcol = curwin.w_cursor.col[0];
            if (startcol == 0) {
                break;
            }
            coladvance(textwidth);
            wantcol = curwin.w_cursor.col[0];
            curwin.w_cursor.col[0] = startcol < safe_tw ? startcol : safe_tw;
            foundcol = 0;
            first_pass = true;
            for (;;) {
                if (first_pass && c != NUL) {
                    cc = c;
                    first_pass = false;
                } else {
                    cc = gchar_cursor();
                }
                if ((cc == ' ' || cc == '\t') && !utf_iscomposing(utf_ptr2char(ml_get_cursor().add(1)))) {
                    end_col = curwin.w_cursor.col[0];
                    while (curwin.w_cursor.col[0] > 0 && ((cc == ' ' || cc == '\t') && !utf_iscomposing(utf_ptr2char(ml_get_cursor().add(1))))) {
                        dec_cursor();
                        cc = gchar_cursor();
                    }
                    if (curwin.w_cursor.col[0] == 0 && ((cc == ' ' || cc == '\t') && !utf_iscomposing(utf_ptr2char(ml_get_cursor().add(1))))) {
                        break;
                    }
                    inc_cursor();
                    end_foundcol = end_col + 1;
                    foundcol = curwin.w_cursor.col[0];
                    if (curwin.w_cursor.col[0] <= wantcol) {
                        break;
                    }
                }
                if (curwin.w_cursor.col[0] == 0) {
                    break;
                }
                dec_cursor();
            }
            if (foundcol == 0) {
                curwin.w_cursor.col[0] = startcol;
                break;
            }
            undisplay_dollar();
            if ((State & VREPLACE_FLAG) != 0) {
                orig_col = startcol;
            } else {
                replace_offset = startcol - end_foundcol;
            }
            curwin.w_cursor.col[0] = foundcol;
            while (true) {
                cc = gchar_cursor();
                if (!((cc == ' ' || cc == '\t') && !utf_iscomposing(utf_ptr2char(ml_get_cursor().add(1))))) {
                    break;
                }
                inc_cursor();
            }
            startcol -= curwin.w_cursor.col[0];
            if (startcol < 0) {
                startcol = 0;
            }
            if ((State & VREPLACE_FLAG) != 0) {
                len_2 = ml_get_cursor_len();
                saved_text = vim_strnsave(ml_get_cursor(), (long) len_2);
                curwin.w_cursor.col[0] = orig_col;
                if (saved_text == null) {
                    break;
                }
                saved_text.set(startcol, (byte) NUL);
                backspace_until_column(foundcol);
            } else {
                curwin.w_cursor.col[0] = foundcol;
            }
            open_line(FORWARD, OPENLINE_DELSPACES + OPENLINE_MARKFIX, old_indent, null);
            old_indent = 0;
            replace_offset = 0;
            if ((State & VREPLACE_FLAG) != 0) {
                ins_bytes(saved_text);
            } else {
                curwin.w_cursor.col[0] += startcol;
                len = ml_get_curline_len();
                if (curwin.w_cursor.col[0] > len) {
                    curwin.w_cursor.col[0] = len;
                }
            }
            haveto_redraw = true;
            did_ai = FALSE;
            did_si = FALSE;
            can_si = FALSE;
            can_si_back = FALSE;
            line_breakcheck();
        }
        if (save_char != NUL) {
            pchar_cursor(save_char);
        }
        if (haveto_redraw) {
            update_topline();
            redraw_curbuf_later(UPD_VALID);
        }
    }

    int comp_textwidth() {
        int textwidth = 0;
        textwidth = (int) curbuf.b_p_tw[0];
        if (textwidth == 0 && curbuf.b_p_wm[0] != 0) {
            textwidth = (int) ((long) curwin.w_width - curbuf.b_p_wm[0]);
            if (curwin.w_onebuf_opt.wo_nu[0] != 0 || curwin.w_onebuf_opt.wo_rnu[0] != 0) {
                textwidth -= 8;
            }
        }
        if (textwidth < 0) {
            textwidth = 0;
        }
        return textwidth;
    }

    int cls() {
        int c = 0;
        c = gchar_cursor();
        if (c == ' ' || c == '\t' || c == NUL) {
            return 0;
        }
        c = utf_class(c);
        if (c != 0 && cls_bigword != 0) {
            return 1;
        }
        return c;
    }

    boolean fwd_word(long count, int bigword, int eol) {
        int sclass = 0;
        int i = 0;
        boolean last_line = false;
        curwin.w_cursor.coladd = 0;
        cls_bigword = bigword;
        while (true) {
            count--;
            if (!(count >= 0L)) {
                break;
            }
            sclass = cls();
            last_line = curwin.w_cursor.lnum[0] == curbuf.b_ml.ml_line_count;
            i = inc_cursor();
            if (i == -1 || (i >= 1 && last_line)) {
                return false;
            }
            if (i >= 1 && eol != 0 && count == 0L) {
                return true;
            }
            if (sclass != 0) {
                while (cls() == sclass) {
                    i = inc_cursor();
                    if (i == -1 || (i >= 1 && eol != 0 && count == 0L)) {
                        return true;
                    }
                }
            }
            while (cls() == 0) {
                if (curwin.w_cursor.col[0] == 0 && ml_get_curline().get() == NUL) {
                    break;
                }
                i = inc_cursor();
                if (i == -1 || (i >= 1 && eol != 0 && count == 0L)) {
                    return true;
                }
            }
        }
        return true;
    }

    boolean bck_word(long count, int bigword, boolean stop) {
        int sclass = 0;
        curwin.w_cursor.coladd = 0;
        cls_bigword = bigword;
        while (true) {
            count--;
            if (!(count >= 0L)) {
                break;
            }
            sclass = cls();
            if (dec_cursor() == -1) {
                return false;
            }
            L_finished: {
                if (!stop || sclass == cls() || sclass == 0) {
                    while (cls() == 0) {
                        if (curwin.w_cursor.col[0] == 0 && ml_get(curwin.w_cursor.lnum[0]).get() == NUL) {
                            break L_finished;
                        }
                        if (dec_cursor() == -1) {
                            return true;
                        }
                    }
                    if (skip_chars(cls(), -1)) {
                        return true;
                    }
                }
                inc_cursor();
            }
            stop = false;
        }
        adjust_skipcol();
        return true;
    }

    boolean end_word(long count, int bigword, boolean stop, boolean empty) {
        int sclass = 0;
        curwin.w_cursor.coladd = 0;
        cls_bigword = bigword;
        if (p_sel[0].get() == 'e' && VIsual_active != 0 && VIsual_mode == 'v' && VIsual_select_exclu_adj != 0) {
            unadjust_for_sel();
        }
        while (true) {
            count--;
            if (!(count >= 0L)) {
                break;
            }
            sclass = cls();
            if (inc_cursor() == -1) {
                return false;
            }
            L_finished: {
                if (cls() == sclass && sclass != 0) {
                    if (skip_chars(sclass, FORWARD)) {
                        return false;
                    }
                } else if (!stop || sclass == 0) {
                    while (cls() == 0) {
                        if (empty && curwin.w_cursor.col[0] == 0 && ml_get(curwin.w_cursor.lnum[0]).get() == NUL) {
                            break L_finished;
                        }
                        if (inc_cursor() == -1) {
                            return false;
                        }
                    }
                    if (skip_chars(cls(), FORWARD)) {
                        return false;
                    }
                }
                dec_cursor();
            }
            stop = false;
        }
        return true;
    }

    boolean bckend_word(long count, boolean bigword, boolean eol) {
        int sclass = 0;
        int i = 0;
        curwin.w_cursor.coladd = 0;
        cls_bigword = bigword ? 1 : 0;
        while (true) {
            count--;
            if (!(count >= 0L)) {
                break;
            }
            sclass = cls();
            i = dec_cursor();
            if (i == -1) {
                return false;
            }
            if (eol && i == 1) {
                return true;
            }
            if (sclass != 0) {
                while (cls() == sclass) {
                    i = dec_cursor();
                    if (i == -1 || (eol && i == 1)) {
                        return true;
                    }
                }
            }
            while (cls() == 0) {
                if (curwin.w_cursor.col[0] == 0 && ml_get(curwin.w_cursor.lnum[0]).get() == NUL) {
                    break;
                }
                i = dec_cursor();
                if (i == -1 || (eol && i == 1)) {
                    return true;
                }
            }
        }
        adjust_skipcol();
        return true;
    }

    boolean skip_chars(int cclass, int dir) {
        while (cls() == cclass) {
            if ((dir == FORWARD ? inc_cursor() : dec_cursor()) == -1) {
                return true;
            }
        }
        return false;
    }

    void back_in_line() {
        int sclass = 0;
        sclass = cls();
        for (;;) {
            if (curwin.w_cursor.col[0] == 0) {
                break;
            }
            dec_cursor();
            if (cls() != sclass) {
                inc_cursor();
                break;
            }
        }
    }

    boolean current_word(S_oparg_S oap, long count, boolean include, boolean bigword) {
        T_pos_T start_pos = new T_pos_T();
        T_pos_T pos = new T_pos_T();
        boolean inclusive = false;
        boolean include_white = false;
        inclusive = true;
        include_white = false;
        cls_bigword = bigword ? 1 : 0;
        start_pos.lnum[0] = 0L;
        start_pos.col[0] = 0;
        start_pos.coladd = 0;
        if (VIsual_active != 0 && p_sel[0].get() == 'e' && (VIsual.lnum[0] != curwin.w_cursor.lnum[0] ? VIsual.lnum[0] < curwin.w_cursor.lnum[0] : (VIsual.col[0] != curwin.w_cursor.col[0] ? VIsual.col[0] < curwin.w_cursor.col[0] : VIsual.coladd < curwin.w_cursor.coladd))) {
            dec_cursor();
        }
        if (VIsual_active == 0 || (curwin.w_cursor.lnum[0] == VIsual.lnum[0] && curwin.w_cursor.col[0] == VIsual.col[0] && curwin.w_cursor.coladd == VIsual.coladd)) {
            back_in_line();
            start_pos.set(curwin.w_cursor);
            if ((cls() == 0 ? 1 : 0) == (include ? 1 : 0)) {
                if (!end_word(1L, bigword ? 1 : 0, true, true)) {
                    return false;
                }
            } else {
                fwd_word(1L, bigword ? 1 : 0, TRUE);
                if (curwin.w_cursor.col[0] == 0) {
                    decl(curwin.w_cursor);
                } else {
                    oneleft();
                }
                if (include) {
                    include_white = true;
                }
            }
            if (VIsual_active != 0) {
                VIsual.set(start_pos);
                redraw_curbuf_later(UPD_INVERTED);
            } else {
                oap.start.set(start_pos);
                oap.motion_type = MCHAR;
            }
            count--;
        }
        while (count > 0L) {
            inclusive = true;
            if (VIsual_active != 0 && (curwin.w_cursor.lnum[0] != VIsual.lnum[0] ? curwin.w_cursor.lnum[0] < VIsual.lnum[0] : (curwin.w_cursor.col[0] != VIsual.col[0] ? curwin.w_cursor.col[0] < VIsual.col[0] : curwin.w_cursor.coladd < VIsual.coladd))) {
                if (decl(curwin.w_cursor) == -1) {
                    return false;
                }
                if ((include ? 1 : 0) != (cls() != 0 ? 1 : 0)) {
                    if (!bck_word(1L, bigword ? 1 : 0, true)) {
                        return false;
                    }
                } else {
                    if (!bckend_word(1L, bigword, true)) {
                        return false;
                    }
                    incl(curwin.w_cursor);
                }
            } else {
                if (incl(curwin.w_cursor) == -1) {
                    return false;
                }
                if ((include ? 1 : 0) != (cls() == 0 ? 1 : 0)) {
                    if (!fwd_word(1L, bigword ? 1 : 0, TRUE) && count > 1L) {
                        return false;
                    }
                    if (!oneleft()) {
                        inclusive = false;
                    }
                } else {
                    if (!end_word(1L, bigword ? 1 : 0, true, true)) {
                        return false;
                    }
                }
            }
            count--;
        }
        if (include_white && (cls() != 0 || (curwin.w_cursor.col[0] == 0 && !inclusive))) {
            pos.set(curwin.w_cursor);
            curwin.w_cursor.set(start_pos);
            if (oneleft()) {
                back_in_line();
                if (cls() == 0 && curwin.w_cursor.col[0] > 0) {
                    if (VIsual_active != 0) {
                        VIsual.set(curwin.w_cursor);
                    } else {
                        oap.start.set(curwin.w_cursor);
                    }
                }
            }
            curwin.w_cursor.set(pos);
        }
        if (VIsual_active != 0) {
            if (p_sel[0].get() == 'e' && inclusive && ((VIsual.lnum[0] != curwin.w_cursor.lnum[0] ? VIsual.lnum[0] < curwin.w_cursor.lnum[0] : (VIsual.col[0] != curwin.w_cursor.col[0] ? VIsual.col[0] < curwin.w_cursor.col[0] : VIsual.coladd < curwin.w_cursor.coladd)) || (VIsual.lnum[0] == curwin.w_cursor.lnum[0] && VIsual.col[0] == curwin.w_cursor.col[0] && VIsual.coladd == curwin.w_cursor.coladd))) {
                inc_cursor();
            }
            if (VIsual_mode == 'V') {
                VIsual_mode = 'v';
                redraw_cmdline = TRUE;
            }
        } else {
            oap.inclusive = inclusive ? 1 : 0;
        }
        return true;
    }

    boolean current_block(S_oparg_S oap, long count, boolean include, int what, int other) {
        T_pos_T old_pos = new T_pos_T();
        T_pos_T pos = null;
        T_pos_T start_pos = new T_pos_T();
        T_pos_T end_pos = null;
        T_pos_T old_start = new T_pos_T();
        T_pos_T old_end = new T_pos_T();
        BytePtr save_cpo = null;
        boolean sol = false;
        long t1 = 0;
        long t2 = 0;
        boolean t3 = false;
        pos = null;
        sol = false;
        old_pos.set(curwin.w_cursor);
        old_end.set(curwin.w_cursor);
        old_start.set(old_end);
        if (VIsual_active == 0 || (VIsual.lnum[0] == curwin.w_cursor.lnum[0] && VIsual.col[0] == curwin.w_cursor.col[0] && VIsual.coladd == curwin.w_cursor.coladd)) {
            setpcmark();
            if (what == '{') {
                while (inindent(1)) {
                    if (inc_cursor() != 0) {
                        break;
                    }
                }
            }
            if (gchar_cursor() == what) {
                curwin.w_cursor.col[0]++;
            }
        } else if (VIsual.lnum[0] != curwin.w_cursor.lnum[0] ? VIsual.lnum[0] < curwin.w_cursor.lnum[0] : (VIsual.col[0] != curwin.w_cursor.col[0] ? VIsual.col[0] < curwin.w_cursor.col[0] : VIsual.coladd < curwin.w_cursor.coladd)) {
            old_start.set(VIsual);
            curwin.w_cursor.set(VIsual);
        } else {
            old_end.set(VIsual);
        }
        save_cpo = p_cpo[0];
        p_cpo[0] = vim_strchr(p_cpo[0], CPO_MATCHBSL) != null ? BytePtr.lit("%M") : BytePtr.lit("%");
        pos = findmatch(null, what);
        if (pos != null) {
            while (true) {
                t1 = count;
                count--;
                if (!(t1 > 0L)) {
                    break;
                }
                pos = findmatch(null, what);
                if (pos == null) {
                    break;
                }
                curwin.w_cursor.set(pos);
                start_pos.set(pos);
            }
        } else {
            while (true) {
                t2 = count;
                count--;
                if (!(t2 > 0L)) {
                    break;
                }
                pos = findmatchlimit(null, what, FM_FORWARD, 0);
                if (pos == null) {
                    break;
                }
                curwin.w_cursor.set(pos);
                start_pos.set(pos);
            }
        }
        p_cpo[0] = save_cpo;
        t3 = pos == null;
        if (!t3) {
            end_pos = findmatch(null, other);
            t3 = end_pos == null;
        }
        if (t3) {
            curwin.w_cursor.set(old_pos);
            return false;
        }
        curwin.w_cursor.set(end_pos);
        while (!include) {
            incl(start_pos);
            sol = curwin.w_cursor.col[0] == 0;
            decl(curwin.w_cursor);
            while (inindent(1)) {
                sol = true;
                if (decl(curwin.w_cursor) != 0) {
                    break;
                }
            }
            if (start_pos.lnum[0] == end_pos.lnum[0] && start_pos.col[0] == end_pos.col[0] && start_pos.coladd == end_pos.coladd && VIsual_active != 0) {
                curwin.w_cursor.set(old_pos);
                return false;
            }
            if (!(start_pos.lnum[0] != old_start.lnum[0] ? start_pos.lnum[0] < old_start.lnum[0] : (start_pos.col[0] != old_start.col[0] ? start_pos.col[0] < old_start.col[0] : start_pos.coladd < old_start.coladd)) && !(old_end.lnum[0] != curwin.w_cursor.lnum[0] ? old_end.lnum[0] < curwin.w_cursor.lnum[0] : (old_end.col[0] != curwin.w_cursor.col[0] ? old_end.col[0] < curwin.w_cursor.col[0] : old_end.coladd < curwin.w_cursor.coladd)) && !(start_pos.lnum[0] == curwin.w_cursor.lnum[0] && start_pos.col[0] == curwin.w_cursor.col[0] && start_pos.coladd == curwin.w_cursor.coladd) && VIsual_active != 0) {
                curwin.w_cursor.set(old_start);
                decl(curwin.w_cursor);
                pos = findmatch(null, what);
                if (pos == null) {
                    curwin.w_cursor.set(old_pos);
                    return false;
                }
                start_pos.set(pos);
                curwin.w_cursor.set(pos);
                end_pos = findmatch(null, other);
                if (end_pos == null) {
                    curwin.w_cursor.set(old_pos);
                    return false;
                }
                curwin.w_cursor.set(end_pos);
            } else {
                break;
            }
        }
        if (VIsual_active != 0) {
            if (p_sel[0].get() == 'e') {
                inc(curwin.w_cursor);
            }
            if (sol && gchar_cursor() != NUL) {
                inc(curwin.w_cursor);
            }
            VIsual.set(start_pos);
            VIsual_mode = 'v';
            redraw_curbuf_later(UPD_INVERTED);
            showmode();
        } else {
            oap.start.set(start_pos);
            oap.motion_type = MCHAR;
            oap.inclusive = FALSE;
            if (sol) {
                incl(curwin.w_cursor);
            } else if ((start_pos.lnum[0] != curwin.w_cursor.lnum[0] ? start_pos.lnum[0] < curwin.w_cursor.lnum[0] : (start_pos.col[0] != curwin.w_cursor.col[0] ? start_pos.col[0] < curwin.w_cursor.col[0] : start_pos.coladd < curwin.w_cursor.coladd)) || (start_pos.lnum[0] == curwin.w_cursor.lnum[0] && start_pos.col[0] == curwin.w_cursor.col[0] && start_pos.coladd == curwin.w_cursor.coladd)) {
                oap.inclusive = TRUE;
            } else {
                curwin.w_cursor.set(start_pos);
            }
        }
        return true;
    }

    int find_next_quote(BytePtr line, int col, int quotechar, BytePtr escape) {
        int c = 0;
        for (;;) {
            c = line.at(col) & 0xff;
            if (c == NUL) {
                return -1;
            } else if (escape != null && vim_strchr(escape, c) != null) {
                col++;
                if (line.at(col) == NUL) {
                    return -1;
                }
            } else if (c == quotechar) {
                break;
            }
            col += utfc_ptr2len(line.add(col));
        }
        return col;
    }

    int find_prev_quote(BytePtr line, int col_start, int quotechar, BytePtr escape) {
        int n = 0;
        while (col_start > 0) {
            col_start--;
            col_start -= utf_head_off(line, line.add(col_start));
            n = 0;
            if (escape != null) {
                while (col_start - n > 0 && vim_strchr(escape, line.at(col_start - n - 1) & 0xff) != null) {
                    n++;
                }
            }
            if ((n & 1) != 0) {
                col_start -= n;
            } else if ((line.at(col_start) & 0xff) == quotechar) {
                break;
            }
        }
        return col_start;
    }

    boolean current_quote(S_oparg_S oap, long count, boolean include, int quotechar) {
        BytePtr line = null;
        int col_end = 0;
        int col_start = 0;
        boolean inclusive = false;
        boolean vis_empty = false;
        boolean vis_bef_curs = false;
        boolean did_exclusive_adj = false;
        boolean inside_quotes = false;
        boolean selected_quote = false;
        int i = 0;
        boolean restore_vis_bef = false;
        T_pos_T t = new T_pos_T();
        int t1 = 0;
        int first_col = 0;
        T_pos_T t_2 = new T_pos_T();
        line = ml_get_curline();
        col_start = curwin.w_cursor.col[0];
        inclusive = false;
        vis_empty = true;
        vis_bef_curs = false;
        did_exclusive_adj = false;
        inside_quotes = false;
        selected_quote = false;
        restore_vis_bef = false;
        if (VIsual_active != 0) {
            if (VIsual.lnum[0] != curwin.w_cursor.lnum[0]) {
                return false;
            }
            vis_bef_curs = VIsual.lnum[0] != curwin.w_cursor.lnum[0] ? VIsual.lnum[0] < curwin.w_cursor.lnum[0] : (VIsual.col[0] != curwin.w_cursor.col[0] ? VIsual.col[0] < curwin.w_cursor.col[0] : VIsual.coladd < curwin.w_cursor.coladd);
            vis_empty = VIsual.lnum[0] == curwin.w_cursor.lnum[0] && VIsual.col[0] == curwin.w_cursor.col[0] && VIsual.coladd == curwin.w_cursor.coladd;
            if (p_sel[0].get() == 'e') {
                if (vis_bef_curs) {
                    dec_cursor();
                    did_exclusive_adj = true;
                } else if (!vis_empty) {
                    dec(VIsual);
                    did_exclusive_adj = true;
                }
                vis_empty = VIsual.lnum[0] == curwin.w_cursor.lnum[0] && VIsual.col[0] == curwin.w_cursor.col[0] && VIsual.coladd == curwin.w_cursor.coladd;
                if (!vis_bef_curs && !vis_empty) {
                    t.set(curwin.w_cursor);
                    curwin.w_cursor.set(VIsual);
                    VIsual.set(t);
                    vis_bef_curs = true;
                    restore_vis_bef = true;
                }
            }
        }
        if (!vis_empty) {
            if (vis_bef_curs) {
                inside_quotes = VIsual.col[0] > 0 && (line.at(VIsual.col[0] - 1) & 0xff) == quotechar && line.at(curwin.w_cursor.col[0]) != NUL && (line.at(curwin.w_cursor.col[0] + 1) & 0xff) == quotechar;
                i = VIsual.col[0];
                col_end = curwin.w_cursor.col[0];
            } else {
                inside_quotes = curwin.w_cursor.col[0] > 0 && (line.at(curwin.w_cursor.col[0] - 1) & 0xff) == quotechar && line.at(VIsual.col[0]) != NUL && (line.at(VIsual.col[0] + 1) & 0xff) == quotechar;
                i = curwin.w_cursor.col[0];
                col_end = VIsual.col[0];
            }
            while (i <= col_end) {
                if (line.at(i) == NUL) {
                    break;
                }
                t1 = i;
                i++;
                if ((line.at(t1) & 0xff) == quotechar) {
                    selected_quote = true;
                    break;
                }
            }
        }
        L_abort_search: {
            if (!vis_empty && (line.at(col_start) & 0xff) == quotechar) {
                if (vis_bef_curs) {
                    col_start = find_next_quote(line, col_start + 1, quotechar, null);
                    if (col_start < 0) {
                        break L_abort_search;
                    }
                    col_end = find_next_quote(line, col_start + 1, quotechar, curbuf.b_p_qe[0]);
                    if (col_end < 0) {
                        col_end = col_start;
                        col_start = curwin.w_cursor.col[0];
                    }
                } else {
                    col_end = find_prev_quote(line, col_start, quotechar, null);
                    if ((line.at(col_end) & 0xff) != quotechar) {
                        break L_abort_search;
                    }
                    col_start = find_prev_quote(line, col_end, quotechar, curbuf.b_p_qe[0]);
                    if ((line.at(col_start) & 0xff) != quotechar) {
                        col_start = col_end;
                        col_end = curwin.w_cursor.col[0];
                    }
                }
            } else {
                if ((line.at(col_start) & 0xff) == quotechar || !vis_empty) {
                    first_col = col_start;
                    if (!vis_empty) {
                        if (vis_bef_curs) {
                            first_col = find_next_quote(line, col_start, quotechar, null);
                        } else {
                            first_col = find_prev_quote(line, col_start, quotechar, null);
                        }
                    }
                    col_start = 0;
                    for (;;) {
                        col_start = find_next_quote(line, col_start, quotechar, null);
                        if (col_start < 0 || col_start > first_col) {
                            break L_abort_search;
                        }
                        col_end = find_next_quote(line, col_start + 1, quotechar, curbuf.b_p_qe[0]);
                        if (col_end < 0) {
                            break L_abort_search;
                        }
                        if (col_start <= first_col && first_col <= col_end) {
                            break;
                        }
                        col_start = col_end + 1;
                    }
                } else {
                    col_start = find_prev_quote(line, col_start, quotechar, curbuf.b_p_qe[0]);
                    if ((line.at(col_start) & 0xff) != quotechar) {
                        col_start = find_next_quote(line, col_start, quotechar, null);
                        if (col_start < 0) {
                            break L_abort_search;
                        }
                    }
                    col_end = find_next_quote(line, col_start + 1, quotechar, curbuf.b_p_qe[0]);
                    if (col_end < 0) {
                        break L_abort_search;
                    }
                }
            }
            if (include) {
                if (line.at(col_end + 1) == ' ' || line.at(col_end + 1) == '\t') {
                    while (line.at(col_end + 1) == ' ' || line.at(col_end + 1) == '\t') {
                        col_end++;
                    }
                } else {
                    while (col_start > 0 && (line.at(col_start - 1) == ' ' || line.at(col_start - 1) == '\t')) {
                        col_start--;
                    }
                }
            }
            if (!include && count < 2L && (vis_empty || !inside_quotes)) {
                col_start++;
            }
            curwin.w_cursor.col[0] = col_start;
            if (VIsual_active != 0) {
                if (vis_empty || (vis_bef_curs && !selected_quote && (inside_quotes || ((line.at(VIsual.col[0]) & 0xff) != quotechar && (VIsual.col[0] == 0 || (line.at(VIsual.col[0] - 1) & 0xff) != quotechar))))) {
                    VIsual.set(curwin.w_cursor);
                    redraw_curbuf_later(UPD_INVERTED);
                }
            } else {
                oap.start.set(curwin.w_cursor);
                oap.motion_type = MCHAR;
            }
            curwin.w_cursor.col[0] = col_end;
            if ((include || count > 1L || (!vis_empty && inside_quotes)) && inc_cursor() == 2) {
                inclusive = true;
            }
            if (VIsual_active != 0) {
                if (vis_empty || vis_bef_curs) {
                    if (p_sel[0].get() != 'e') {
                        dec_cursor();
                    }
                } else {
                    if (inside_quotes || (!selected_quote && (line.at(VIsual.col[0]) & 0xff) != quotechar && (line.at(VIsual.col[0]) == NUL || (line.at(VIsual.col[0] + 1) & 0xff) != quotechar))) {
                        dec_cursor();
                        VIsual.set(curwin.w_cursor);
                    }
                    curwin.w_cursor.col[0] = col_start;
                }
                if (VIsual_mode == 'V') {
                    VIsual_mode = 'v';
                    redraw_cmdline = TRUE;
                }
            } else {
                oap.inclusive = inclusive ? 1 : 0;
            }
            return true;
        }
        if (VIsual_active != 0 && p_sel[0].get() == 'e') {
            if (did_exclusive_adj) {
                inc_cursor();
            }
            if (restore_vis_bef) {
                t_2.set(curwin.w_cursor);
                curwin.w_cursor.set(VIsual);
                VIsual.set(t_2);
            }
        }
        return false;
    }

