    void ui_breakcheck_force(boolean force) {
        int save_updating_screen = 0;
        save_updating_screen = updating_screen;
        if (ui_breakcheck_force_recursive) {
            return;
        }
        ui_breakcheck_force_recursive = true;
        updating_screen++;
        mch_breakcheck(force);
        if (save_updating_screen != 0) {
            updating_screen = TRUE;
        } else {
            after_updating_screen(false);
        }
        ui_breakcheck_force_recursive = false;
    }

    boolean vim_is_input_buf_full() {
        return inbufcount >= INBUFLEN;
    }

    boolean vim_is_input_buf_empty() {
        return inbufcount == 0;
    }

    S_growarray get_input_buf() {
        S_growarray gap = null;
        gap = new S_growarray();
        gap.ga_data = BytePtr.alloc((long) (inbufcount + 1));
        Rt.memmove(GA_BytePtr(gap), new BytePtr(inbuf, 0), (long) inbufcount);
        gap.ga_len = inbufcount;
        trash_input_buf();
        return gap;
    }

    void set_input_buf(S_growarray gap, boolean overwrite) {
        if (gap == null) {
            return;
        }
        if (gap.ga_data != null) {
            if (overwrite || inbufcount + gap.ga_len >= INBUFLEN) {
                Rt.memmove(new BytePtr(inbuf, 0), GA_BytePtr(gap), (long) gap.ga_len);
                inbufcount = gap.ga_len;
            } else {
                Rt.memmove(new BytePtr(inbuf, 0).add(gap.ga_len), new BytePtr(inbuf, 0), (long) inbufcount);
                Rt.memmove(new BytePtr(inbuf, 0), GA_BytePtr(gap), (long) gap.ga_len);
                inbufcount += gap.ga_len;
            }
        }
    }

    void trash_input_buf() {
        inbufcount = 0;
    }

    int read_from_input_buf(BytePtr buf, long maxlen) {
        if (inbufcount == 0) {
            fill_input_buf(true);
        }
        if (maxlen > ((long) inbufcount)) {
            maxlen = (long) inbufcount;
        }
        Rt.memmove(buf, new BytePtr(inbuf, 0), maxlen);
        inbufcount -= maxlen;
        if (inbufcount > 0 && maxlen > 0L) {
            Rt.memmove(new BytePtr(inbuf, 0), new BytePtr(inbuf, 0).add((int) maxlen), (long) inbufcount);
        }
        return (int) maxlen;
    }

    void fill_input_buf(boolean exit_on_error) {
        int len = 0;
        int try_ = 0;
        long readlen = 0;
        if (vim_is_input_buf_full()) {
            return;
        }
        len = 0;
        try_ = 0;
        for (; try_ < 100; try_++) {
            readlen = (long) (INBUFLEN - inbufcount);
            len = musl_read_input(new BytePtr(inbuf, 0).add(inbufcount), (int) readlen);
            if (len > 0 || got_int != 0) {
                break;
            }
            if (!exit_on_error) {
                return;
            }
        }
        if (len <= 0 && got_int == 0) {
            read_error_exit();
        }
        if (got_int != 0) {
            inbuf[0] = (byte) 3;
            inbufcount = 1;
        } else {
            while (len > 0) {
                if (ctrl_c_interrupts != 0 && ((inbuf[inbufcount] == Ctrl_C && !key_protocol_enabled()) || (len >= 10 && musl_strncmp(new BytePtr(inbuf, 0).add(inbufcount), BytePtr.lit("\033[27;5;99~"), 10L) == 0) || (len >= 10 && musl_strncmp(new BytePtr(inbuf, 0).add(inbufcount), BytePtr.lit("\033[27;5;67~"), 10L) == 0) || (len >= 7 && musl_strncmp(new BytePtr(inbuf, 0).add(inbufcount), BytePtr.lit("\033[99;5u"), 7L) == 0) || (len >= 7 && musl_strncmp(new BytePtr(inbuf, 0).add(inbufcount), BytePtr.lit("\033[67;5u"), 7L) == 0))) {
                    Rt.memmove(new BytePtr(inbuf, 0), new BytePtr(inbuf, 0).add(inbufcount), (long) len);
                    inbufcount = 0;
                    got_int = TRUE;
                }
                len--;
                inbufcount++;
            }
        }
    }

    void read_error_exit() {
        musl_strcpy(IObuff, gettext_(BytePtr.lit("Vim: Error reading input, exiting...\n")));
        preserve_exit();
    }

    int check_col(int col) {
        if (col < 0) {
            return 0;
        }
        if (col >= screen_Columns) {
            return screen_Columns - 1;
        }
        return col;
    }

    int check_row(int row) {
        if (row < 0) {
            return 0;
        }
        if (row >= screen_Rows) {
            return screen_Rows - 1;
        }
        return row;
    }

    void ui_focus_change(boolean in_focus) {
        if (in_focus && ui_focus_change_last_time + 2L < host_time()) {
            ui_focus_change_last_time = host_time();
        }
    }

    boolean u_save_cursor() {
        return u_save(curwin.w_cursor.lnum[0] - 1L, curwin.w_cursor.lnum[0] + 1L);
    }

    boolean u_save(long top, long bot) {
        if (undo_off != 0) {
            return true;
        }
        if (top >= bot || bot > (curbuf.b_ml.ml_line_count + 1L)) {
            return false;
        }
        if (top + 2L == bot) {
            u_saveline(top + 1L);
        }
        return u_savecommon(top, bot, 0L, false);
    }

    boolean u_savesub(long lnum) {
        if (undo_off != 0) {
            return true;
        }
        return u_savecommon(lnum - 1L, lnum + 1L, lnum + 1L, false);
    }

    boolean u_inssub(long lnum) {
        if (undo_off != 0) {
            return true;
        }
        return u_savecommon(lnum - 1L, lnum, lnum + 1L, false);
    }

    boolean u_savedel(long lnum, long nlines) {
        if (undo_off != 0) {
            return true;
        }
        return u_savecommon(lnum - 1L, lnum + nlines, nlines == curbuf.b_ml.ml_line_count ? 2L : lnum, false);
    }

    boolean undo_allowed() {
        if (curbuf.b_p_ma[0] == 0) {
            emsg(gettext_(new BytePtr(e_cannot_make_changes_modifiable_is_off, 0)));
            return false;
        }
        if (textlock != 0) {
            emsg(gettext_(new BytePtr(e_not_allowed_to_change_text_or_change_window, 0)));
            return false;
        }
        return true;
    }

    long get_undolevel() {
        if (curbuf.b_p_ul[0] == -123456L) {
            return p_ul[0];
        }
        return curbuf.b_p_ul[0];
    }

    boolean u_save_line(T_undoline_T ul, long lnum) {
        BytePtr line = null;
        line = ml_get(lnum);
        ul.ul_textlen = ml_get_len(lnum);
        if (curbuf.b_ml.ml_line_len == 0) {
            ul.ul_len = 1L;
            ul.ul_line = vim_strsave(BytePtr.lit(""));
        } else {
            ul.ul_len = (long) curbuf.b_ml.ml_line_len;
            ul.ul_line = vim_memsave(line, ul.ul_len);
        }
        return (ul.ul_line == null ? FAIL : OK) != 0;
    }

    boolean u_savecommon(long top, long bot, long newbot, boolean reload) {
        long lnum = 0;
        long i = 0;
        S_u_header uhp = null;
        S_u_header[] old_curhead = new S_u_header[1];
        S_u_entry uep = null;
        S_u_entry prev_uep = null;
        long size = 0;
        S_u_header uhfree = null;
        long t1 = 0;
        if (!reload) {
            if (!undo_allowed()) {
                return false;
            }
            if (bot > (curbuf.b_ml.ml_line_count + 1L)) {
                emsg(gettext_(new BytePtr(e_line_count_changed_unexpectedly, 0)));
                return false;
            }
        }
        size = bot - top - 1L;
        if (curbuf.b_u_synced) {
            curbuf.b_new_change = true;
            if (get_undolevel() >= 0L) {
                uhp = new S_u_header();
            } else {
                uhp = null;
            }
            old_curhead[0] = curbuf.b_u_curhead;
            if (old_curhead[0] != null) {
                curbuf.b_u_newhead = old_curhead[0].uh_next;
                curbuf.b_u_curhead = null;
            }
            while ((long) curbuf.b_u_numhead > get_undolevel() && curbuf.b_u_oldhead != null) {
                uhfree = curbuf.b_u_oldhead;
                if (uhfree == old_curhead[0]) {
                    u_freebranch(curbuf, uhfree, new Ptr<S_u_header>(old_curhead, 0));
                } else if (uhfree.uh_alt_next == null) {
                    u_freeheader(curbuf, uhfree, new Ptr<S_u_header>(old_curhead, 0));
                } else {
                    while (uhfree.uh_alt_next != null) {
                        uhfree = uhfree.uh_alt_next;
                    }
                    u_freebranch(curbuf, uhfree, new Ptr<S_u_header>(old_curhead, 0));
                }
            }
            if (uhp == null) {
                if (old_curhead[0] != null) {
                    u_freebranch(curbuf, old_curhead[0], null);
                }
                curbuf.b_u_synced = false;
                return true;
            }
            uhp.uh_prev = null;
            uhp.uh_next = curbuf.b_u_newhead;
            uhp.uh_alt_next = old_curhead[0];
            if (old_curhead[0] != null) {
                uhp.uh_alt_prev = old_curhead[0].uh_alt_prev;
                if (uhp.uh_alt_prev != null) {
                    uhp.uh_alt_prev.uh_alt_next = uhp;
                }
                old_curhead[0].uh_alt_prev = uhp;
                if (curbuf.b_u_oldhead == old_curhead[0]) {
                    curbuf.b_u_oldhead = uhp;
                }
            } else {
                uhp.uh_alt_prev = null;
            }
            if (curbuf.b_u_newhead != null) {
                curbuf.b_u_newhead.uh_prev = uhp;
            }
            curbuf.b_u_seq_last++;
            uhp.uh_seq = curbuf.b_u_seq_last;
            curbuf.b_u_seq_cur = uhp.uh_seq;
            uhp.uh_time = host_time();
            uhp.uh_save_nr = 0L;
            curbuf.b_u_time_cur = uhp.uh_time + 1L;
            uhp.uh_walk = 0;
            uhp.uh_entry = null;
            uhp.uh_getbot_entry = null;
            uhp.uh_cursor.set(curwin.w_cursor);
            if (virtual_active() != 0 && curwin.w_cursor.coladd > 0) {
                uhp.uh_cursor_vcol = (long) getviscol();
            } else {
                uhp.uh_cursor_vcol = -1L;
            }
            uhp.uh_flags = (curbuf.b_changed[0] != 0 ? UH_CHANGED : 0) + ((curbuf.b_ml.ml_flags & ML_EMPTY) != 0 ? UH_EMPTYBUF : 0);
            Rt.moveStructs(new Ptr<T_pos_T>(uhp.uh_namedm, 0), new Ptr<T_pos_T>(curbuf.b_namedm, 0), 26);
            uhp.uh_visual.set(curbuf.b_visual);
            curbuf.b_u_newhead = uhp;
            if (curbuf.b_u_oldhead == null) {
                curbuf.b_u_oldhead = uhp;
            }
            curbuf.b_u_numhead++;
        } else {
            if (get_undolevel() < 0L) {
                return true;
            }
            if (size == 1L) {
                uep = u_get_headentry();
                prev_uep = null;
                i = 0L;
                for (; i < 10L; i++) {
                    if (uep == null) {
                        break;
                    }
                    if ((!(curbuf.b_u_newhead.uh_getbot_entry == uep) ? uep.ue_top + uep.ue_size + 1L != (uep.ue_bot == 0L ? curbuf.b_ml.ml_line_count + 1L : uep.ue_bot) : uep.ue_lcount != curbuf.b_ml.ml_line_count) || (uep.ue_size > 1L && top >= uep.ue_top && top + 2L <= uep.ue_top + uep.ue_size + 1L)) {
                        break;
                    }
                    if (uep.ue_size == 1L && uep.ue_top == top) {
                        if (i > 0L) {
                            u_getbot();
                            curbuf.b_u_synced = false;
                            prev_uep.ue_next = uep.ue_next;
                            uep.ue_next = curbuf.b_u_newhead.uh_entry;
                            curbuf.b_u_newhead.uh_entry = uep;
                        }
                        if (newbot != 0L) {
                            uep.ue_bot = newbot;
                        } else if (bot > curbuf.b_ml.ml_line_count) {
                            uep.ue_bot = 0L;
                        } else {
                            uep.ue_lcount = curbuf.b_ml.ml_line_count;
                            curbuf.b_u_newhead.uh_getbot_entry = uep;
                        }
                        return true;
                    }
                    prev_uep = uep;
                    uep = uep.ue_next;
                }
            }
            u_getbot();
        }
        uep = new S_u_entry();
        uep.zero();
        uep.ue_size = size;
        uep.ue_top = top;
        if (newbot != 0L) {
            uep.ue_bot = newbot;
        } else if (bot > curbuf.b_ml.ml_line_count) {
            uep.ue_bot = 0L;
        } else {
            uep.ue_lcount = curbuf.b_ml.ml_line_count;
            curbuf.b_u_newhead.uh_getbot_entry = uep;
        }
        L_nomem: {
            if (size > 0L) {
                uep.ue_array = new Ptr<T_undoline_T>(T_undoline_T.array((int) size), 0);
                i = 0L;
                lnum = top + 1L;
                for (; i < size; i++) {
                    fast_breakcheck();
                    if (got_int != 0) {
                        u_freeentry(uep, i);
                        return false;
                    }
                    t1 = lnum;
                    lnum++;
                    if (!u_save_line(uep.ue_array.at((int) i), t1)) {
                        u_freeentry(uep, i);
                        break L_nomem;
                    }
                }
            } else {
                uep.ue_array = null;
            }
            uep.ue_next = curbuf.b_u_newhead.uh_entry;
            curbuf.b_u_newhead.uh_entry = uep;
            curbuf.b_u_synced = false;
            undo_undoes = FALSE;
            return true;
        }
        msg_silent = 0;
        if (ask_yesno(gettext_(BytePtr.lit("No undo possible; continue anyway")), true) == 'y') {
            undo_off = TRUE;
            return true;
        }
        do_outofmem_msg(0L);
        return false;
    }

    void u_undo(int count) {
        if (!curbuf.b_u_synced) {
            u_sync(true);
            count = 1;
        }
        if (vim_strchr(p_cpo[0], CPO_UNDO) == null) {
            undo_undoes = TRUE;
        } else {
            undo_undoes = undo_undoes == 0 ? 1 : 0;
        }
        u_doit(count);
    }

    void u_redo(int count) {
        if (vim_strchr(p_cpo[0], CPO_UNDO) == null) {
            undo_undoes = FALSE;
        }
        u_doit(count);
    }

    void u_doit(int startcount) {
        int count = 0;
        int t1 = 0;
        count = startcount;
        if (!undo_allowed()) {
            return;
        }
        u_newcount = 0L;
        u_oldcount = 0L;
        if ((curbuf.b_ml.ml_flags & ML_EMPTY) != 0) {
            u_oldcount = -1L;
        }
        while (true) {
            t1 = count;
            count--;
            if (!(t1 != 0)) {
                break;
            }
            if (undo_undoes != 0) {
                if (curbuf.b_u_curhead == null) {
                    curbuf.b_u_curhead = curbuf.b_u_newhead;
                } else if (get_undolevel() > 0L) {
                    curbuf.b_u_curhead = curbuf.b_u_curhead.uh_next;
                }
                if (curbuf.b_u_numhead == 0 || curbuf.b_u_curhead == null) {
                    curbuf.b_u_curhead = curbuf.b_u_oldhead;
                    beep_flush();
                    if (count == startcount - 1) {
                        if (!shortmess(SHM_UNDO)) {
                            msg(gettext_(BytePtr.lit("Already at oldest change")));
                        }
                        return;
                    }
                    break;
                }
                u_undoredo(true);
            } else {
                if (curbuf.b_u_curhead == null || get_undolevel() <= 0L) {
                    beep_flush();
                    if (count == startcount - 1) {
                        if (!shortmess(SHM_UNDO)) {
                            msg(gettext_(BytePtr.lit("Already at newest change")));
                        }
                        return;
                    }
                    break;
                }
                u_undoredo(false);
                if (curbuf.b_u_curhead.uh_prev == null) {
                    curbuf.b_u_newhead = curbuf.b_u_curhead;
                }
                curbuf.b_u_curhead = curbuf.b_u_curhead.uh_prev;
            }
        }
        u_undo_end(undo_undoes, false);
    }

    void undo_time(long step, boolean sec, boolean file, boolean absolute) {
        long target = 0;
        long closest = 0;
        long closest_start = 0;
        long closest_seq = 0;
        long val = 0;
        S_u_header uhp = null;
        S_u_header last = null;
        int mark = 0;
        int nomark = 0;
        int round = 0;
        boolean dosec = false;
        boolean dofile = false;
        boolean above = false;
        boolean did_undo = false;
        closest_seq = 0L;
        uhp = null;
        nomark = 0;
        dosec = sec;
        dofile = file;
        above = false;
        did_undo = true;
        if (text_locked()) {
            text_locked_msg();
            return;
        }
        if (!curbuf.b_u_synced) {
            u_sync(true);
        }
        u_newcount = 0L;
        u_oldcount = 0L;
        if ((curbuf.b_ml.ml_flags & ML_EMPTY) != 0) {
            u_oldcount = -1L;
        }
        if (absolute) {
            target = step;
            closest = -1L;
        } else {
            if (dosec) {
                target = curbuf.b_u_time_cur + step;
            } else if (dofile) {
                if (step < 0L) {
                    uhp = curbuf.b_u_curhead;
                    if (uhp != null) {
                        uhp = uhp.uh_next;
                    } else {
                        uhp = curbuf.b_u_newhead;
                    }
                    if (uhp != null && uhp.uh_save_nr != 0L) {
                        target = curbuf.b_u_save_nr_cur + step;
                    } else {
                        target = curbuf.b_u_save_nr_cur + step + 1L;
                    }
                    if (target <= 0L) {
                        dofile = false;
                    }
                } else {
                    target = curbuf.b_u_save_nr_cur + step;
                    if (target > curbuf.b_u_save_nr_last) {
                        target = curbuf.b_u_seq_last + 1L;
                        dofile = false;
                    }
                }
            } else {
                target = curbuf.b_u_seq_cur + step;
            }
            if (step < 0L) {
                if (target < 0L) {
                    target = 0L;
                }
                closest = -1L;
            } else {
                if (dosec) {
                    closest = host_time() + 1L;
                } else if (dofile) {
                    closest = curbuf.b_u_save_nr_last + 2L;
                } else {
                    closest = curbuf.b_u_seq_last + 2L;
                }
                if (target >= closest) {
                    target = closest - 1L;
                }
            }
        }
        closest_start = closest;
        closest_seq = curbuf.b_u_seq_cur;
        do {
            if (target == 0L) {
                mark = lastmark;
                break;
            }
            round = 1;
            for (; round <= 2; round++) {
                lastmark++;
                mark = lastmark;
                lastmark++;
                nomark = lastmark;
                if (curbuf.b_u_curhead == null) {
                    uhp = curbuf.b_u_newhead;
                } else {
                    uhp = curbuf.b_u_curhead;
                }
                while (uhp != null) {
                    uhp.uh_walk = mark;
                    if (dosec) {
                        val = uhp.uh_time;
                    } else if (dofile) {
                        val = uhp.uh_save_nr;
                    } else {
                        val = uhp.uh_seq;
                    }
                    if (round == 1 && !(dofile && val == 0L)) {
                        if ((step < 0L ? uhp.uh_seq <= curbuf.b_u_seq_cur : uhp.uh_seq > curbuf.b_u_seq_cur) && (dosec && val == closest ? (step < 0L ? uhp.uh_seq < closest_seq : uhp.uh_seq > closest_seq) : closest == closest_start || (val > target ? (closest > target ? val - target <= closest - target : val - target <= target - closest) : (closest > target ? target - val <= closest - target : target - val <= target - closest)))) {
                            closest = val;
                            closest_seq = uhp.uh_seq;
                        }
                    }
                    if (target == val && !dosec) {
                        target = uhp.uh_seq;
                        break;
                    }
                    if (uhp.uh_prev != null && uhp.uh_prev.uh_walk != nomark && uhp.uh_prev.uh_walk != mark) {
                        uhp = uhp.uh_prev;
                    } else if (uhp.uh_alt_next != null && uhp.uh_alt_next.uh_walk != nomark && uhp.uh_alt_next.uh_walk != mark) {
                        uhp = uhp.uh_alt_next;
                    } else if (uhp.uh_next != null && uhp.uh_alt_prev == null && uhp.uh_next.uh_walk != nomark && uhp.uh_next.uh_walk != mark) {
                        if (uhp == curbuf.b_u_curhead) {
                            uhp.uh_walk = nomark;
                        }
                        uhp = uhp.uh_next;
                    } else {
                        uhp.uh_walk = nomark;
                        if (uhp.uh_alt_prev != null) {
                            uhp = uhp.uh_alt_prev;
                        } else {
                            uhp = uhp.uh_next;
                        }
                    }
                }
                if (uhp != null) {
                    break;
                }
                if (absolute) {
                    vim_snprintf(IObuff, emsg_iobuff_room(), gettext_(new BytePtr(e_undo_number_nr_not_found, 0)), step);
                    emsg(iobuff_or(gettext_(new BytePtr(e_undo_number_nr_not_found, 0))));
                    return;
                }
                if (closest == closest_start) {
                    if (!shortmess(SHM_UNDO)) {
                        if (step < 0L) {
                            msg(gettext_(BytePtr.lit("Already at oldest change")));
                        } else {
                            msg(gettext_(BytePtr.lit("Already at newest change")));
                        }
                    }
                    return;
                }
                target = closest_seq;
                dosec = false;
                dofile = false;
                if (step < 0L) {
                    above = true;
                }
            }
        } while (false);
        if (uhp != null || target == 0L) {
            while (got_int == 0) {
                uhp = curbuf.b_u_curhead;
                if (uhp == null) {
                    uhp = curbuf.b_u_newhead;
                } else {
                    uhp = uhp.uh_next;
                }
                if (uhp == null || (target > 0L && uhp.uh_walk != mark) || (uhp.uh_seq == target && !above)) {
                    break;
                }
                curbuf.b_u_curhead = uhp;
                u_undoredo(true);
                if (target > 0L) {
                    uhp.uh_walk = nomark;
                }
            }
            if (target > 0L) {
                while (got_int == 0) {
                    uhp = curbuf.b_u_curhead;
                    if (uhp == null) {
                        break;
                    }
                    while (uhp.uh_alt_prev != null && uhp.uh_alt_prev.uh_walk == mark) {
                        uhp = uhp.uh_alt_prev;
                    }
                    last = uhp;
                    while (last.uh_alt_next != null && last.uh_alt_next.uh_walk == mark) {
                        last = last.uh_alt_next;
                    }
                    if (!(last == uhp)) {
                        while (uhp.uh_alt_prev != null) {
                            uhp = uhp.uh_alt_prev;
                        }
                        if (last.uh_alt_next != null) {
                            last.uh_alt_next.uh_alt_prev = last.uh_alt_prev;
                        }
                        last.uh_alt_prev.uh_alt_next = last.uh_alt_next;
                        last.uh_alt_prev = null;
                        last.uh_alt_next = uhp;
                        uhp.uh_alt_prev = last;
                        if (curbuf.b_u_oldhead == uhp) {
                            curbuf.b_u_oldhead = last;
                        }
                        uhp = last;
                        if (uhp.uh_next != null) {
                            uhp.uh_next.uh_prev = uhp;
                        }
                    }
                    curbuf.b_u_curhead = uhp;
                    if (uhp.uh_walk != mark) {
                        break;
                    }
                    if (uhp.uh_seq == target && above) {
                        curbuf.b_u_seq_cur = target - 1L;
                        break;
                    }
                    u_undoredo(false);
                    if (uhp.uh_prev == null) {
                        curbuf.b_u_newhead = uhp;
                    }
                    curbuf.b_u_curhead = uhp.uh_prev;
                    did_undo = false;
                    if (uhp.uh_seq == target) {
                        break;
                    }
                    uhp = uhp.uh_prev;
                    if (uhp == null || uhp.uh_walk != mark) {
                        internal_error(BytePtr.lit("undo_time()"));
                        break;
                    }
                }
            }
        }
        u_undo_end(did_undo ? 1 : 0, absolute);
    }

    void u_undoredo(boolean undo) {
        Ptr<T_undoline_T> newarray = null;
        long oldsize = 0;
        long newsize = 0;
        long top = 0;
        long bot = 0;
        long lnum = 0;
        long newlnum = 0;
        T_pos_T new_curpos = new T_pos_T();
        long i = 0;
        S_u_entry uep = null;
        S_u_entry nuep = null;
        S_u_entry newlist = null;
        int old_flags = 0;
        int new_flags = 0;
        T_pos_T[] namedm = T_pos_T.array(26);
        T_visualinfo_T visualinfo = new T_visualinfo_T();
        boolean empty_buffer = false;
        S_u_header curhead = null;
        BytePtr p = null;
        newarray = null;
        newlnum = LONG_MAX;
        new_curpos.set(curwin.w_cursor);
        newlist = null;
        curhead = curbuf.b_u_curhead;
        block_autocmds();
        old_flags = curhead.uh_flags;
        new_flags = (curbuf.b_changed[0] != 0 ? UH_CHANGED : 0) + ((curbuf.b_ml.ml_flags & ML_EMPTY) != 0 ? UH_EMPTYBUF : 0);
        setpcmark();
        Rt.moveStructs(new Ptr<T_pos_T>(namedm, 0), new Ptr<T_pos_T>(curbuf.b_namedm, 0), 26);
        visualinfo.set(curbuf.b_visual);
        curbuf.b_op_start.lnum[0] = curbuf.b_ml.ml_line_count;
        curbuf.b_op_start.col[0] = 0;
        curbuf.b_op_end.lnum[0] = 0L;
        curbuf.b_op_end.col[0] = 0;
        uep = curhead.uh_entry;
        for (; uep != null; uep = nuep) {
            top = uep.ue_top;
            bot = uep.ue_bot;
            if (bot == 0L) {
                bot = curbuf.b_ml.ml_line_count + 1L;
            }
            if (top > curbuf.b_ml.ml_line_count || top >= bot || bot > (curbuf.b_ml.ml_line_count + 1L)) {
                unblock_autocmds();
                iemsg(new BytePtr(e_u_undo_line_numbers_wrong, 0));
                changed();
                return;
            }
            oldsize = bot - top - 1L;
            newsize = uep.ue_size;
            lnum = curhead.uh_cursor.lnum[0];
            if (lnum >= top && lnum <= top + newsize + 1L) {
                new_curpos.set(curhead.uh_cursor);
                newlnum = -1L;
            } else if (top < newlnum) {
                i = 0L;
                for (; (i < newsize) && i < oldsize; i++) {
                    p = ml_get(top + 1L + i);
                    if ((long) curbuf.b_ml.ml_line_len != uep.ue_array.at((int) i).ul_len || Rt.memcmp(uep.ue_array.at((int) i).ul_line, p, (long) curbuf.b_ml.ml_line_len) != 0) {
                        break;
                    }
                }
                if (i == newsize && newlnum == LONG_MAX && uep.ue_next == null) {
                    newlnum = top;
                    new_curpos.lnum[0] = newlnum + 1L;
                } else if (i < newsize) {
                    newlnum = top + i;
                    new_curpos.lnum[0] = newlnum + 1L;
                }
            }
            empty_buffer = false;
            if (oldsize > 0L) {
                newarray = new Ptr<T_undoline_T>(T_undoline_T.array((int) oldsize), 0);
                lnum = bot - 1L;
                i = oldsize;
                for (;;) {
                    i--;
                    if (!(i >= 0L)) {
                        break;
                    }
                    if (!u_save_line(newarray.at((int) i), lnum)) {
                        do_outofmem_msg(0L);
                    }
                    if (curbuf.b_ml.ml_line_count == 1L) {
                        empty_buffer = true;
                    }
                    ml_delete_flags(lnum, ML_DEL_UNDO);
                    lnum--;
                }
            } else {
                newarray = null;
            }
            check_cursor_lnum();
            if (newsize != 0) {
                lnum = top;
                i = 0L;
                for (; i < newsize; i++, lnum++) {
                    if (empty_buffer && lnum == 0L) {
                        ml_replace_len(1L, uep.ue_array.at((int) i).ul_line, (int) uep.ue_array.at((int) i).ul_len, true, true);
                    } else {
                        ml_append_flags(lnum, uep.ue_array.at((int) i).ul_line, (int) uep.ue_array.at((int) i).ul_len, ML_APPEND_UNDO);
                    }
                }
            }
            if (oldsize != newsize) {
                mark_adjust(top + 1L, top + oldsize, LONG_MAX, newsize - oldsize);
                if (curbuf.b_op_start.lnum[0] > (top + oldsize)) {
                    curbuf.b_op_start.lnum[0] += newsize - oldsize;
                }
                if (curbuf.b_op_end.lnum[0] > (top + oldsize)) {
                    curbuf.b_op_end.lnum[0] += newsize - oldsize;
                }
            }
            if (oldsize > 0L || newsize > 0L) {
                changed_lines(top + 1L, 0, bot, newsize - oldsize);
            }
            if (top + 1L < curbuf.b_op_start.lnum[0]) {
                curbuf.b_op_start.lnum[0] = top + 1L;
            }
            if (newsize == 0L && top + 1L > curbuf.b_op_end.lnum[0]) {
                curbuf.b_op_end.lnum[0] = top + 1L;
            } else if (top + newsize > curbuf.b_op_end.lnum[0]) {
                curbuf.b_op_end.lnum[0] = top + newsize;
            }
            u_newcount += newsize;
            u_oldcount += oldsize;
            uep.ue_size = oldsize;
            uep.ue_array = newarray;
            uep.ue_bot = top + newsize + 1L;
            nuep = uep.ue_next;
            uep.ue_next = newlist;
            newlist = uep;
        }
        if (curbuf.b_op_start.lnum[0] > curbuf.b_ml.ml_line_count) {
            curbuf.b_op_start.lnum[0] = curbuf.b_ml.ml_line_count;
        }
        if (curbuf.b_op_end.lnum[0] > curbuf.b_ml.ml_line_count) {
            curbuf.b_op_end.lnum[0] = curbuf.b_ml.ml_line_count;
        }
        curwin.w_cursor.set(new_curpos);
        check_cursor_lnum();
        curhead.uh_entry = newlist;
        curhead.uh_flags = new_flags;
        if ((old_flags & UH_EMPTYBUF) != 0 && (curbuf.b_ml.ml_line_count == 1L && ml_get(1L).get() == NUL)) {
            curbuf.b_ml.ml_flags |= ML_EMPTY;
        }
        if ((old_flags & UH_CHANGED) != 0) {
            changed();
        } else {
            unchanged(curbuf, false, true);
        }
        i = 0L;
        for (; i < 'z' - 'a' + 1; i++) {
            if (curhead.uh_namedm[(int) i].lnum[0] != 0L) {
                curbuf.b_namedm[(int) i].set(curhead.uh_namedm[(int) i]);
            }
            if (namedm[(int) i].lnum[0] != 0L) {
                curhead.uh_namedm[(int) i].set(namedm[(int) i]);
            } else {
                curhead.uh_namedm[(int) i].lnum[0] = 0L;
            }
        }
        if (curhead.uh_visual.vi_start.lnum[0] != 0L) {
            curbuf.b_visual.set(curhead.uh_visual);
            curhead.uh_visual.set(visualinfo);
        }
        if (curhead.uh_cursor.lnum[0] + 1L == curwin.w_cursor.lnum[0] && curwin.w_cursor.lnum[0] > 1L) {
            curwin.w_cursor.lnum[0]--;
        }
        if (curwin.w_cursor.lnum[0] <= curbuf.b_ml.ml_line_count) {
            if (curhead.uh_cursor.lnum[0] == curwin.w_cursor.lnum[0]) {
                curwin.w_cursor.col[0] = curhead.uh_cursor.col[0];
                if (virtual_active() != 0 && curhead.uh_cursor_vcol >= 0L) {
                    coladvance((int) curhead.uh_cursor_vcol);
                } else {
                    curwin.w_cursor.coladd = 0;
                }
            } else {
                beginline(BL_SOL | BL_FIX);
            }
        } else {
            curwin.w_cursor.col[0] = 0;
            curwin.w_cursor.coladd = 0;
        }
        check_cursor();
        curbuf.b_u_seq_cur = curhead.uh_seq;
        if (undo) {
            if (curhead.uh_next != null) {
                curbuf.b_u_seq_cur = curhead.uh_next.uh_seq;
            } else {
                curbuf.b_u_seq_cur = 0L;
            }
        }
        if (curhead.uh_save_nr != 0L) {
            if (undo) {
                curbuf.b_u_save_nr_cur = curhead.uh_save_nr - 1L;
            } else {
                curbuf.b_u_save_nr_cur = curhead.uh_save_nr;
            }
        }
        curbuf.b_u_time_cur = curhead.uh_time;
        unblock_autocmds();
    }

    void u_undo_end(int did_undo, boolean absolute) {
        BytePtr msgstr = null;
        S_u_header uhp = null;
        byte[] msgbuf = new byte[80];
        if (global_busy != 0 || !messaging() || shortmess(SHM_UNDO)) {
            return;
        }
        if ((curbuf.b_ml.ml_flags & ML_EMPTY) != 0) {
            u_newcount--;
        }
        u_oldcount -= u_newcount;
        if (u_oldcount == -1L) {
            msgstr = BytePtr.lit("more line");
        } else if (u_oldcount < 0L) {
            msgstr = BytePtr.lit("more lines");
        } else if (u_oldcount == 1L) {
            msgstr = BytePtr.lit("line less");
        } else if (u_oldcount > 1L) {
            msgstr = BytePtr.lit("fewer lines");
        } else {
            u_oldcount = u_newcount;
            if (u_newcount == 1L) {
                msgstr = BytePtr.lit("change");
            } else {
                msgstr = BytePtr.lit("changes");
            }
        }
        if (curbuf.b_u_curhead != null) {
            if (absolute && curbuf.b_u_curhead.uh_next != null) {
                uhp = curbuf.b_u_curhead.uh_next;
                did_undo = FALSE;
            } else if (did_undo != 0) {
                uhp = curbuf.b_u_curhead;
            } else {
                uhp = curbuf.b_u_curhead.uh_next;
            }
        } else {
            uhp = curbuf.b_u_newhead;
        }
        if (uhp == null) {
            msgbuf[0] = (byte) NUL;
        } else {
            add_time(new BytePtr(msgbuf, 0), 80L, uhp.uh_time);
        }
        if (VIsual_active != 0) {
            check_pos(curbuf, VIsual);
        }
        vim_snprintf(IObuff, iobuff_room(), gettext_(BytePtr.lit("%ld %s; %s #%ld  %s")), u_oldcount < 0L ? -u_oldcount : u_oldcount, gettext_(msgstr), did_undo != 0 ? gettext_(BytePtr.lit("before")) : gettext_(BytePtr.lit("after")), uhp == null ? 0L : uhp.uh_seq, new BytePtr(msgbuf, 0));
        msg_attr_keep(iobuff_or(gettext_(BytePtr.lit("%ld %s; %s #%ld  %s"))), 0, true);
    }

    void u_sync(boolean force) {
        if (curbuf.b_u_synced || (!force && no_u_sync > 0)) {
            return;
        }
        if (get_undolevel() < 0L) {
            curbuf.b_u_synced = true;
        } else {
            u_getbot();
            curbuf.b_u_curhead = null;
        }
    }

    void ex_undolist(S_exarg eap) {
        S_growarray ga = new S_growarray();
        S_u_header uhp = null;
        int mark = 0;
        int nomark = 0;
        int changes = 0;
        int len = 0;
        int n = 0;
        int t1 = 0;
        int i = 0;
        changes = 1;
        lastmark++;
        mark = lastmark;
        lastmark++;
        nomark = lastmark;
        ga_init2(ga, 8L, 20);
        uhp = curbuf.b_u_oldhead;
        while (uhp != null) {
            if (uhp.uh_prev == null && uhp.uh_walk != nomark && uhp.uh_walk != mark) {
                if (!ga_grow(ga, 1)) {
                    break;
                }
                len = vim_snprintf(IObuff, 1025L, BytePtr.lit("%6ld %7d  "), uhp.uh_seq, changes);
                add_time(IObuff.add(len), (long) (1025 - len), uhp.uh_time);
                len += (int) musl_strlen(IObuff.add(len));
                if (uhp.uh_save_nr > 0L) {
                    n = len >= 33 ? 0 : 33 - len;
                    len += vim_snprintf(IObuff.add(len), (long) (1025 - len), BytePtr.lit("%*.*s  %3ld"), n, n, BytePtr.lit(" "), uhp.uh_save_nr);
                }
                t1 = ga.ga_len;
                ga.ga_len++;
                GA_Ptr_BytePtr(ga).set(t1, vim_strnsave(IObuff, (long) len));
            }
            uhp.uh_walk = mark;
            if (uhp.uh_prev != null && uhp.uh_prev.uh_walk != nomark && uhp.uh_prev.uh_walk != mark) {
                uhp = uhp.uh_prev;
                changes++;
            } else if (uhp.uh_alt_next != null && uhp.uh_alt_next.uh_walk != nomark && uhp.uh_alt_next.uh_walk != mark) {
                uhp = uhp.uh_alt_next;
            } else if (uhp.uh_next != null && uhp.uh_alt_prev == null && uhp.uh_next.uh_walk != nomark && uhp.uh_next.uh_walk != mark) {
                uhp = uhp.uh_next;
                changes--;
            } else {
                uhp.uh_walk = nomark;
                if (uhp.uh_alt_prev != null) {
                    uhp = uhp.uh_alt_prev;
                } else {
                    uhp = uhp.uh_next;
                    changes--;
                }
            }
        }
        if (ga.ga_len == 0) {
            msg(gettext_(BytePtr.lit("Nothing to undo")));
        } else {
            sort_strings(GA_Ptr_BytePtr(ga), ga.ga_len);
            msg_start();
            msg_puts_attr(gettext_(BytePtr.lit("number changes  when               saved")), highlight_attr[HLF_T]);
            i = 0;
            for (; (i < ga.ga_len) && got_int == 0; i++) {
                msg_putchar('\n');
                if (got_int != 0) {
                    break;
                }
                msg_puts(GA_Ptr_BytePtr(ga).at(i));
            }
            msg_end();
            ga_clear_strings(ga);
        }
    }

    void ex_undojoin(S_exarg eap) {
        if (curbuf.b_u_newhead == null) {
            return;
        }
        if (curbuf.b_u_curhead != null) {
            emsg(gettext_(new BytePtr(e_undojoin_is_not_allowed_after_undo, 0)));
            return;
        }
        if (!curbuf.b_u_synced) {
            return;
        }
        if (get_undolevel() < 0L) {
            return;
        } else {
            curbuf.b_u_synced = false;
        }
    }

    S_u_entry u_get_headentry() {
        if (curbuf.b_u_newhead == null || curbuf.b_u_newhead.uh_entry == null) {
            iemsg(new BytePtr(e_undo_list_corrupt, 0));
            return null;
        }
        return curbuf.b_u_newhead.uh_entry;
    }

    void u_getbot() {
        S_u_entry uep = null;
        long extra = 0;
        uep = u_get_headentry();
        if (uep == null) {
            return;
        }
        uep = curbuf.b_u_newhead.uh_getbot_entry;
        if (uep != null) {
            extra = curbuf.b_ml.ml_line_count - uep.ue_lcount;
            uep.ue_bot = uep.ue_top + uep.ue_size + 1L + extra;
            if (uep.ue_bot < 1L || uep.ue_bot > curbuf.b_ml.ml_line_count) {
                iemsg(new BytePtr(e_undo_line_missing, 0));
                uep.ue_bot = uep.ue_top + 1L;
            }
            curbuf.b_u_newhead.uh_getbot_entry = null;
        }
        curbuf.b_u_synced = true;
    }

    void u_freeheader(S_file_buffer buf, S_u_header uhp, Ptr<S_u_header> uhpp) {
        S_u_header uhap = null;
        if (uhp.uh_alt_next != null) {
            u_freebranch(buf, uhp.uh_alt_next, uhpp);
        }
        if (uhp.uh_alt_prev != null) {
            uhp.uh_alt_prev.uh_alt_next = null;
        }
        if (uhp.uh_next == null) {
            buf.b_u_oldhead = uhp.uh_prev;
        } else {
            uhp.uh_next.uh_prev = uhp.uh_prev;
        }
        if (uhp.uh_prev == null) {
            buf.b_u_newhead = uhp.uh_next;
        } else {
            uhap = uhp.uh_prev;
            for (; uhap != null; uhap = uhap.uh_alt_next) {
                uhap.uh_next = uhp.uh_next;
            }
        }
        u_freeentries(buf, uhp, uhpp);
    }

    void u_freebranch(S_file_buffer buf, S_u_header uhp, Ptr<S_u_header> uhpp) {
        S_u_header tofree = null;
        S_u_header next = null;
        if (uhp == buf.b_u_oldhead) {
            while (buf.b_u_oldhead != null) {
                u_freeheader(buf, buf.b_u_oldhead, uhpp);
            }
            return;
        }
        if (uhp.uh_alt_prev != null) {
            uhp.uh_alt_prev.uh_alt_next = null;
        }
        next = uhp;
        while (next != null) {
            tofree = next;
            if (tofree.uh_alt_next != null) {
                u_freebranch(buf, tofree.uh_alt_next, uhpp);
            }
            next = tofree.uh_prev;
            u_freeentries(buf, tofree, uhpp);
        }
    }

    void u_freeentries(S_file_buffer buf, S_u_header uhp, Ptr<S_u_header> uhpp) {
        S_u_entry uep = null;
        S_u_entry nuep = null;
        if (buf.b_u_curhead == uhp) {
            buf.b_u_curhead = null;
        }
        if (buf.b_u_newhead == uhp) {
            buf.b_u_newhead = null;
        }
        if (uhpp != null && uhp == uhpp.get()) {
            uhpp.put(null);
        }
        uep = uhp.uh_entry;
        for (; uep != null; uep = nuep) {
            nuep = uep.ue_next;
            u_freeentry(uep, uep.ue_size);
        }
        buf.b_u_numhead--;
    }

    void u_freeentry(S_u_entry uep, long n) {
        while (n > 0L) {
            n--;
        }
    }

    void u_clearall(S_file_buffer buf) {
        buf.b_u_curhead = null;
        buf.b_u_oldhead = buf.b_u_curhead;
        buf.b_u_newhead = buf.b_u_oldhead;
        buf.b_u_synced = true;
        buf.b_u_numhead = 0;
        buf.b_u_line_ptr.ul_line = null;
        buf.b_u_line_ptr.ul_len = 0L;
        buf.b_u_line_ptr.ul_textlen = 0;
        buf.b_u_line_lnum = 0L;
    }

    void u_blockfree(S_file_buffer buf) {
        while (buf.b_u_oldhead != null) {
            u_freeheader(buf, buf.b_u_oldhead, null);
        }
    }

    void u_clearallandblockfree(S_file_buffer buf) {
        u_blockfree(buf);
        u_clearall(buf);
    }

    void u_saveline(long lnum) {
        if (lnum == curbuf.b_u_line_lnum) {
            return;
        }
        if (lnum < 1L || lnum > curbuf.b_ml.ml_line_count) {
            return;
        }
        u_clearline();
        curbuf.b_u_line_lnum = lnum;
        if (curwin.w_cursor.lnum[0] == lnum) {
            curbuf.b_u_line_colnr = curwin.w_cursor.col[0];
        } else {
            curbuf.b_u_line_colnr = 0;
        }
        if (!u_save_line(curbuf.b_u_line_ptr, lnum)) {
            do_outofmem_msg(0L);
        }
    }

    void u_clearline() {
        if (curbuf.b_u_line_ptr.ul_line == null) {
            return;
        }
        curbuf.b_u_line_ptr.ul_line = null;
        curbuf.b_u_line_ptr.ul_len = 0L;
        curbuf.b_u_line_ptr.ul_textlen = 0;
        curbuf.b_u_line_lnum = 0L;
    }

    void u_undoline() {
        int t = 0;
        T_undoline_T oldp = new T_undoline_T();
        if (undo_off != 0) {
            return;
        }
        if (curbuf.b_u_line_ptr.ul_line == null || curbuf.b_u_line_lnum > curbuf.b_ml.ml_line_count) {
            beep_flush();
            return;
        }
        if (!u_savecommon(curbuf.b_u_line_lnum - 1L, curbuf.b_u_line_lnum + 1L, 0L, false)) {
            return;
        }
        if (!u_save_line(oldp, curbuf.b_u_line_lnum)) {
            do_outofmem_msg(0L);
            return;
        }
        ml_replace_len(curbuf.b_u_line_lnum, curbuf.b_u_line_ptr.ul_line, (int) curbuf.b_u_line_ptr.ul_len, true, false);
        changed_bytes(curbuf.b_u_line_lnum, 0);
        curbuf.b_u_line_ptr.set(oldp);
        t = curbuf.b_u_line_colnr;
        if (curwin.w_cursor.lnum[0] == curbuf.b_u_line_lnum) {
            curbuf.b_u_line_colnr = curwin.w_cursor.col[0];
        }
        curwin.w_cursor.col[0] = t;
        curwin.w_cursor.lnum[0] = curbuf.b_u_line_lnum;
        check_cursor_col();
    }

    int bufIsChanged(S_file_buffer buf) {
        return bufIsChangedNotTerm(buf);
    }

    int anyBufIsChanged() {
        return bufIsChanged(curbuf);
    }

    int bufIsChangedNotTerm(S_file_buffer buf) {
        return buf.b_changed[0];
    }

    int curbufIsChanged() {
        return bufIsChanged(curbuf);
    }

    BytePtr uc_fun_cmd() {
        int i = 0;
        i = 0;
        for (; uc_fun_cmd_fcmd[i] != 0; i++) {
            IObuff.set(i, (byte) ((uc_fun_cmd_fcmd[i] & 0xff) - 64));
        }
        IObuff.set(i, (byte) NUL);
        return IObuff;
    }

    void init_longVersion() {
        BytePtr msg = null;
        long len = 0;
        if (longVersion != null) {
            return;
        }
        msg = gettext_(BytePtr.lit("%s (%s)"));
        len = musl_strlen(msg) + 22L - 1L + 12L - 1L;
        longVersion = BytePtr.alloc(len);
        vim_snprintf(longVersion, len, msg, new BytePtr(VIM_VERSION_LONG_ONLY, 0), new BytePtr(VIM_VERSION_DATE_ONLY, 0));
    }

    int win_valid(S_window_S win) {
        return win != null && win == curwin ? 1 : 0;
    }

    boolean win_valid_any_tab(S_window_S win) {
        return win != null && win == curwin;
    }

    void win_init_empty(S_window_S wp) {
        redraw_win_later(wp, UPD_NOT_VALID);
        wp.w_lines_valid = 0;
        wp.w_cursor.lnum[0] = 1L;
        wp.w_cursor.col[0] = 0;
        wp.w_curswant = wp.w_cursor.col[0];
        wp.w_cursor.coladd = 0;
        wp.w_pcmark.lnum[0] = 1L;
        wp.w_pcmark.col[0] = 0;
        wp.w_prev_pcmark.lnum[0] = 0L;
        wp.w_prev_pcmark.col[0] = 0;
        wp.w_topline = 1L;
        wp.w_botline = 2L;
        wp.w_valid = 0;
    }

    void curwin_init() {
        win_init_empty(curwin);
    }

    void snapshot_windows_scroll_size() {
        S_window_S wp = null;
        wp = curwin;
        wp.w_last_topline = wp.w_topline;
        wp.w_last_leftcol = wp.w_leftcol;
        wp.w_last_skipcol = wp.w_skipcol;
        wp.w_last_width = wp.w_width;
        wp.w_last_height = wp.w_height;
    }

    void may_make_initial_scroll_size_snapshot() {
        if (did_initial_scroll_size_snapshot == 0) {
            did_initial_scroll_size_snapshot = TRUE;
            snapshot_windows_scroll_size();
        }
    }

    void frame_new_height(S_frame_S topfrp, int height, boolean topfirst, boolean wfh, boolean set_ch) {
        int new_ch = 0;
        int save_ch = 0;
        if (set_ch) {
            new_ch = (int) ((long) min_set_ch > (p_ch[0] + (long) topfrp.fr_height - (long) height) ? (long) min_set_ch : p_ch[0] + (long) topfrp.fr_height - (long) height);
            save_ch = min_set_ch;
            if ((long) new_ch != p_ch[0]) {
                set_option_value(BytePtr.lit("cmdheight"), (long) new_ch, null, 0);
            }
            min_set_ch = save_ch;
            height = (int) ((long) height < Rows[0] - p_ch[0] ? (long) height : Rows[0] - p_ch[0]);
        }
        win_new_height(topfrp.fr_win, height - topfrp.fr_win.w_status_height - 0);
        topfrp.fr_height = height;
    }

