        new_wp.w_onebuf_opt.wo_sop[0] = -1L;
        new_wp.w_allbuf_opt.wo_sop[0] = new_wp.w_onebuf_opt.wo_sop[0];
        new_wp.w_onebuf_opt.wo_siso[0] = -1L;
