    void set_fraction(S_window_S wp) {
        if (wp.w_height > 1) {
            wp.w_fraction = (int) (((long) wp.w_wrow * FRACTION_MULT + FRACTION_MULT / 2) / (long) wp.w_height);
        }
    }

    void win_fix_scroll(int resize) {
        S_window_S wp = null;
        int diff = 0;
        T_pos_T cursor = new T_pos_T();
        long topline = 0;
        int skipcol = 0;
        if (p_spk.get() == 'c') {
            return;
        }
        skip_update_topline = TRUE;
        wp = curwin;
        if (wp.w_height != wp.w_prev_height) {
            wp.w_do_win_fix_cursor = true;
            if (p_spk.get() == 's' && wp.w_winrow != wp.w_prev_winrow && wp.w_botline - 1L <= wp.w_buffer.b_ml.ml_line_count) {
                diff = wp.w_winrow - wp.w_prev_winrow + (wp.w_height - wp.w_prev_height);
                cursor.set(wp.w_cursor);
                topline = wp.w_topline;
                skipcol = wp.w_skipcol;
                wp.w_cursor.lnum[0] = wp.w_botline - 1L;
                if (diff > 0) {
                    cursor_down_inner(wp, (long) diff);
                } else {
                    cursor_up_inner(wp, (long) -diff);
                }
                wp.w_fraction = FRACTION_MULT;
                scroll_to_fraction(wp, wp.w_prev_height);
                wp.w_cursor.set(cursor);
                if (wp.w_topline == topline) {
                    wp.w_skipcol = skipcol;
                }
                wp.w_valid &= ~VALID_WCOL;
            } else if (wp == curwin) {
                wp.w_valid &= ~VALID_CROW;
            }
            invalidate_botline_win(wp);
            validate_botline_win(wp);
        }
        wp.w_prev_height = wp.w_height;
        wp.w_prev_winrow = wp.w_winrow;
        skip_update_topline = FALSE;
        if ((get_real_state() & (MODE_NORMAL | MODE_CMDLINE | MODE_TERMINAL)) == 0) {
            win_fix_cursor(false);
        } else if (resize != 0) {
            win_fix_cursor(true);
        }
    }

    void win_fix_cursor(boolean normal) {
        S_window_S wp = null;
        long so = 0;
        long lnum = 0;
        long top = 0;
        long bot = 0;
        long nlnum = 0;
        wp = curwin;
        if (skip_win_fix_cursor != 0 || !wp.w_do_win_fix_cursor || wp.w_buffer.b_ml.ml_line_count < (long) wp.w_height) {
            return;
        }
        wp.w_do_win_fix_cursor = false;
        so = (long) (wp.w_height / 2) < get_scrolloff_value() ? (long) (wp.w_height / 2) : get_scrolloff_value();
        lnum = wp.w_cursor.lnum[0];
        wp.w_cursor.lnum[0] = wp.w_topline;
        cursor_down_inner(wp, so);
        top = wp.w_cursor.lnum[0];
        wp.w_cursor.lnum[0] = wp.w_botline - 1L;
        cursor_up_inner(wp, so);
        bot = wp.w_cursor.lnum[0];
        wp.w_cursor.lnum[0] = lnum;
        nlnum = 0L;
        if (lnum > bot && wp.w_botline - wp.w_buffer.b_ml.ml_line_count != 1L) {
            nlnum = bot;
        } else if (lnum < top && wp.w_topline != 1L) {
            nlnum = so == (long) (wp.w_height / 2) ? bot : top;
        }
        if (nlnum != 0L) {
            if (normal) {
                setmark('\'');
                wp.w_cursor.lnum[0] = nlnum;
            } else {
                wp.w_fraction = nlnum == bot ? FRACTION_MULT : 0;
                scroll_to_fraction(wp, wp.w_prev_height);
                validate_botline();
            }
        }
    }

    void win_new_height(S_window_S wp, int height) {
        int prev_height = 0;
        prev_height = wp.w_height;
        if (height < 0) {
            height = 0;
        }
        if (wp.w_height == height) {
            return;
        }
        if (wp.w_height > 0) {
            if (wp == curwin && p_spk.get() == 'c') {
                validate_cursor();
            }
            if (wp.w_height != prev_height) {
                return;
            }
            if (wp.w_wrow != wp.w_prev_fraction_row) {
                set_fraction(wp);
            }
        }
        wp.w_height = height;
        wp.w_redr_status = true;
        win_comp_scroll(wp);
        if (exiting == 0 && p_spk.get() == 'c') {
            if (wp.w_onebuf_opt.wo_sms[0] == 0) {
                wp.w_skipcol = 0;
            }
            scroll_to_fraction(wp, prev_height);
        }
    }

    void scroll_to_fraction(S_window_S wp, int prev_height) {
        long lnum = 0;
        int sline = 0;
        int line_size = 0;
        int height = 0;
        int rows = 0;
        int want_row = 0;
        int skipcol = 0;
        height = wp.w_height;
        if (height > 0 && ((long) height < wp.w_buffer.b_ml.ml_line_count || wp.w_topline > 1L)) {
            lnum = wp.w_cursor.lnum[0];
            if (lnum < 1L) {
                lnum = 1L;
            }
            wp.w_wrow = (int) (((long) wp.w_fraction * (long) height - 1L) / FRACTION_MULT);
            line_size = plines_win_col(wp, lnum, (long) wp.w_cursor.col[0]) - 1;
            sline = wp.w_wrow - line_size;
            if (sline >= 0) {
                rows = plines_win(wp, lnum, false);
                if (sline > (wp.w_height - rows)) {
                    sline = wp.w_height - rows;
                    wp.w_wrow -= rows - line_size;
                }
            }
            if (sline < 0) {
                want_row = wp.w_wrow;
                wp.w_wrow = line_size;
                if (wp.w_wrow >= wp.w_height && wp.w_width - win_col_off(wp) > 0) {
                    skipcol = wp.w_width - win_col_off(wp);
                    wp.w_wrow--;
                    while (wp.w_wrow > want_row) {
                        skipcol += wp.w_width - win_col_off(wp) + win_col_off2(wp);
                        wp.w_wrow--;
                    }
                    wp.w_skipcol = skipcol;
                }
            } else if (sline > 0) {
                while (sline > 0 && lnum > 1L) {
                    lnum--;
                    line_size = plines_win(wp, lnum, true);
                    sline -= line_size;
                }
                if (sline < 0) {
                    lnum++;
                    wp.w_wrow -= line_size + sline;
                } else if (sline > 0) {
                    lnum = 1L;
                    wp.w_wrow -= sline;
                }
            }
            set_topline(wp, lnum);
        }
        if (wp == curwin) {
            curs_columns(false);
        }
        if (prev_height > 0) {
            wp.w_prev_fraction_row = wp.w_wrow;
        }
        redraw_win_later(wp, UPD_SOME_VALID);
        invalidate_botline_win(wp);
    }

    void win_new_width(S_window_S wp, int width) {
        wp.w_width = width < 0 ? 0 : width;
        wp.w_lines_valid = 0;
        changed_line_abv_curs_win(wp);
        invalidate_botline_win(wp);
        if (wp == curwin && p_spk.get() == 'c') {
            curs_columns(true);
        }
        redraw_win_later(wp, UPD_NOT_VALID);
        wp.w_redr_status = true;
    }

    void win_comp_scroll(S_window_S wp) {
        wp.w_onebuf_opt.wo_scr[0] = Integer.toUnsignedLong(wp.w_height >>> 1);
        if (wp.w_onebuf_opt.wo_scr[0] == 0L) {
            wp.w_onebuf_opt.wo_scr[0] = 1L;
        }
    }

    void command_height() {
        int old_p_ch = 0;
        S_frame_S frp = null;
        int h = 0;
        old_p_ch = (int) curtab.tp_ch_used;
        frp = curwin.w_frame;
        if (p_ch[0] > ((long) old_p_ch) && command_frame_height != 0) {
            h = (int) (p_ch[0] - (long) old_p_ch < (long) (frp.fr_height - frame_minheight(frp, null)) ? p_ch[0] - (long) old_p_ch : (long) (frp.fr_height - frame_minheight(frp, null)));
            frame_add_height(frp, -h);
            old_p_ch += h;
        }
        if (p_ch[0] < (long) old_p_ch && command_frame_height != 0) {
            frame_add_height(frp, (int) ((long) old_p_ch - p_ch[0]));
        }
        win_comp_pos();
        win_fix_scroll(1);
        cmdline_row = (int) (Rows[0] - p_ch[0]);
        redraw_cmdline = TRUE;
        if (msg_scrolled == 0 && full_screen != 0) {
            screen_fill(cmdline_row, (int) Rows[0], 0, (int) Columns[0], ' ', ' ', 0);
            msg_row = cmdline_row;
        }
        curtab.tp_ch_used = p_ch[0];
        min_set_ch = (int) p_ch[0];
    }

    void frame_add_height(S_frame_S frp, int n) {
        frame_new_height(frp, frp.fr_height + n, false, false, false);
    }

    void last_status(boolean morewin) {
        last_status_rec(topframe, last_stl_height(morewin) > 0);
    }

    void last_status_rec(S_frame_S fr, boolean statusline) {
        S_window_S wp = null;
        wp = fr.fr_win;
        if (wp.w_status_height != 0 && !statusline) {
            win_new_height(wp, wp.w_height + wp.w_status_height);
            wp.w_status_height = 0;
            comp_col();
        } else if (wp.w_status_height == 0 && statusline) {
            if (fr.fr_height <= frame_minheight(fr, null)) {
                emsg(gettext_(new BytePtr(e_not_enough_room, 0)));
                return;
            }
            wp.w_status_height = statusline_height(wp);
            win_new_height(wp, wp.w_height - wp.w_status_height);
            comp_col();
            redraw_all_later(UPD_SOME_VALID);
        }
        if (musl_abs(wp.w_height - wp.w_prev_height) == 1) {
            wp.w_prev_height = wp.w_height;
        }
    }

    int statusline_height(S_window_S wp) {
        int stl_height = 0;
        stl_height = 1;
        return stl_height;
    }

    int last_stl_height(boolean morewin) {
        return p_ls[0] == 2L || (p_ls[0] == 1L && (morewin || false)) ? STATUS_HEIGHT : 0;
    }

    int min_rows() {
        if (curwin == null) {
            return MIN_LINES;
        }
        return frame_minheight(curtab.tp_topframe, null) + MIN_CMDHEIGHT;
    }

    int min_rows_for_all_tabpages() {
        int total = 0;
        S_tabpage_S tp = null;
        int n = 0;
        if (curwin == null) {
            return MIN_LINES;
        }
        total = 0;
        tp = curtab;
        n = frame_minheight(tp.tp_topframe, null);
        if (total < n) {
            total = n;
        }
        total += MIN_CMDHEIGHT;
        return total;
    }

